INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e1d3b895634b', 'en', 'US', 'Tom Yum Soup (Thai Soup)', 'Recipe video above! The famous Thai Soup, made at home, and it''s honestly the real deal!! See recipe notes for shortcut using frozen peeled prawns/shrimp. Also, CHOOSE from classic clear Tom Yum (Tom Yum Goong Nam Sa) or the creamy Tom Yum version (Tom Yum Goong Nam Khon)!', 'https://www.recipetineats.com/tachyon/2019/09/Tom-Yum-soup_2.jpg', 15, 20, 35, 2, '[{"id": "ing_shrimp", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_lemongrass", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_galangal", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_lime", "quantity": {"value": 5.0, "unit": "net of 500g"}}, {"id": "ing_chilli", "quantity": {"value": 2.0, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_oyster_mushrooms", "quantity": {"value": 0.8, "unit": "pack of 150g"}}, {"id": "ing_tomato", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 5.0, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 2.0, "unit": "pack of 100g"}}, {"id": "ing_milk", "quantity": {"value": 0.083, "unit": "L"}}]', '[{"ingredients":["300g / 10oz whole prawns / shrimp (with heads and shells on (Note 7))"]},{"ingredients":["3 cup (750 ml) water","1/2 cup (125 ml) chicken stock/broth (, low sodium)","2 stalks of lemongrass (, outer layers peeled(Note 1))","1.5 cm / 3/5\" piece of galangal (, cut into 4 slices (Note 2))","5 kaffir lime leaves (, torn roughly (Note 3))","2 Thai or birdseye chillies (Note 4)","3 garlic cloves"],"purpose":"Broth:"},{"ingredients":["120g / 4oz oyster mushrooms","1 roma tomato (, cut into wedges)","1/2 white onion ((medium sized), cut into wedges about 1 cm thick)","1 tsp sugar","3 tbsp fish sauce (Note 5)","3 tbsp lime juice","Coriander/cilantro (, for garnish)"],"purpose":"Soup Add Ins:"},{"ingredients":["1 1/2 tbsp Thai roasted chili sauce (Nam Prik Pa, Note 6)","1/3 cup (75 ml) evaporated milk"],"purpose":"Creamy Tom Yum Option:"}]', '[{"description":"Peel the prawns. Place heads and shell in pot, reserve meat.","images":[],"step":1},{"description":"Use a meat mallet or similar to bash the garlic, chilli and lemongrass so they burst open to release flavour. Add into pot.","images":[],"step":2},{"description":"Crush kaffir lime leaves with your hands. Add into pot.","images":[],"step":3},{"description":"Add galangal, stock and water. Bring to simmer on high heat, cover, then reduce to medium and simmer for 10 minutes.","duration":10,"images":[],"step":4},{"description":"Strain the broth, discard the prawn shells etc, then return broth into same pot over low heat.","images":[],"step":5},{"description":"Add onions and mushrooms, simmer 3 minutes. Add tomatoes, simmer for 1 minute.","duration":1,"images":[],"step":6},{"description":"Add prawns, simmer 2 minutes or until just cooked.","images":[],"step":7},{"description":"Stir in sugar and fish sauce, simmer for 1 minute.","duration":1,"images":[],"step":8},{"description":"Add lime juice, then taste. Adjust sweet (sugar), salt (fish sauce) and sour (lime) to your taste (trust me, you''ll know when you like it!).","images":[],"step":9},{"description":"Ladle into bowls and serve with fresh coriander and fresh chilli! This is the CLEAR version of Tom Yum.","images":[],"step":10},{"description":"Creamy Tom Yum:","images":[],"step":11},{"description":"When you add sugar, also add Thai Chilli Paste and evaporated milk.","images":[],"step":12},{"description":"Then continue with recipe!","images":[],"step":13},{"title":"Bonus","description":"Tom KHA!","images":[],"step":14},{"description":"Following Creamy Tom Yum steps but use coconut milk instead of evaporated milk.","images":[],"step":15}]', '["fish","milk","shellfish"]', '["gluten_free","high_protein","low_calorie"]', '{"mealType":["dinner","snack"],"cuisine":["Thai"],"categories":["asian-recipes","asian-soups","cuisines","dietary","iconic-dishes","low-calorie-recipes","soup-recipes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b8d7cd238ad5', 'en', 'US', 'Sticky Chinese Chicken Wings', 'Recipe video above. My family recipe for the ultimate Sticky Chinese Wings, perfected over years with many heated debates! Many of the ingredients can be substituted and you''ll still get a similar flavour - refer to the notes. Spiciness: A hint of spicy from the chilli sauce, can be omitted.', 'https://www.recipetineats.com/tachyon/2014/06/Sticky-Chinese-Chicken-Wings_5.jpg', 10, 50, 60, 6, '[{"id": "ing_chicken", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_ketchup", "quantity": {"value": 0.075, "unit": "bottle of 500g"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_five_spice_powder", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}]', '[{"ingredients":["1.5 kg /3 lb chicken wings (, cut into drumettes and wingettes (Note 1))"]},{"ingredients":["1/2 tsp sesame oil (, toasted )","2 tbsp lemon juice","2 tbsp Chinese cooking wine (Shaoxing wine, sub Mirin, dry sherry)","2 tbsp soy sauce (, light or all purpose)","2 tbsp brown sugar or honey","1 1/2 tbsp hoisin sauce","1 1/2 tbsp oyster sauce","1/4 cup ketchup (or Aussie tomato sauce)","1 tbsp chilli garlic sauce (or sambal oelek (adjust spiciness to taste))","4 cloves garlic (, minced)","1 tbsp ginger (, finely grated)","1/2 tsp five spice powder"],"purpose":"Chicken Wing Marinade (Note 2 for substitutions)"},{"ingredients":["Finely sliced shallots/scallions","Sesame seeds","Coriander/cilantro leaves","Finely sliced fresh chili"],"purpose":"Garnishes (optional)"}]', '[{"description":"Mix Marinade ingredients.","images":[],"step":1},{"description":"Place wings in large bowl, pour over Marinade and toss well. Set aside for 10 minutes - do not marinate for longer than 1 hour. (Note 3)","duration":10,"images":[],"step":2},{"description":"Preheat the oven to 180C/350F.","images":[],"step":3},{"description":"Line baking tray with foil then greaseproof paper (you''ll thank me later).","images":[],"step":4},{"description":"Shake excess marinade off wings (but reserve the marinade) and spread on baking tray - can be fairly snug but not super squished (use 2 trays if needed).","images":[],"step":5},{"title":"Bake 45","description":"50 minutes, basting with a brush at 25 minutes and 35 minutes, using the reserved marinade and juieces on the tray.","images":[],"step":6},{"description":"The meat should be able to be pulled off the bones quite easily, they should be just starting to char on the edges and a sticky, dark red/golden colour all over.","images":[],"step":7},{"title":"Sprinkle with garnishes","description":"coriander/cilantro leaves, sesame seeds, chilli, sliced shallots/scallions - then serve!","images":[],"step":8}]', '["gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["snack","dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","australia-day","chicken-recipes","chicken-wings","dinner-tonight","grilling-ideas-and-recipes","modern-asian","quick-and-easy","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_04b861d4f5dd', 'en', 'US', 'Tuna Poke Bowl', 'Recipe video above. The Dressing is what makes or breaks a Poke Bowl. This Ginger-Sesame one MAKES it!!! Mirin is the secret ingredient - it adds complexity and flavour that''s missing from usual Poke Bowl Dressings. It looks like a long list of ingredients and there are quite a few bits and pieces, but it''s actually a very leisurely recipe to make. (PS Dicing fish is great flavour carrier technique) GREAT HOT WEATHER FOOD!', 'https://www.recipetineats.com/tachyon/2019/08/Tuna-Poke-Bowls-main.jpg', 20, 15, 35, 4, '[{"id": "ing_rice", "quantity": {"value": 300.0, "unit": "pack"}}, {"id": "ing_water", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.25, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 3.0, "unit": "pack of 100g"}}, {"id": "ing_mirin", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_chilli", "quantity": {"value": 0.125, "unit": "pack of 100g"}}, {"id": "ing_ginger", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_sashimi_grade_tuna_0_7cm_1_4_dice", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_radishes", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_shelled_edamame", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["2 cups sushi rice (, rinsed (Note 1))","2 1/2 cups water"],"purpose":"Sushi Rice:"},{"ingredients":["1/4 cup rice vinegar (Note 2)","2 tsp sugar (, white)","1/4 tsp salt"],"purpose":"Sushi Rice Seasoning:"},{"ingredients":["1 1/2 tbsp light or all purpose soy sauce (Note 3)","2 tsp dark soy (Note 3)","2 1/2 tbsp toasted sesame oil (Note 4)","2 tbsp mirin (Note 5)","2 tbsp rice vinegar (Note 2)","2 1/2 tsp chilli paste or Sriracha","1 1/2 tsp grated ginger (, fresh)"],"purpose":"Ginger Marinade Dressing:"},{"ingredients":["350g / 12oz sashimi grade tuna (or salmon, trout or kingfish), diced 0.7cm / 1/4\" dice (Note 7)","1 small carrot (, finely julienned)","1 cucumber (, deseeded and finely diced (Note 7))","1 small avocado (, peeled and cut into 8 wedges (or dice))","6 red radish (, finely sliced)","1 cup shelled edamame (, boiled or steamed per packet (Note 8))","1 green onion (, finely sliced on the diagonal)","Black sesame seeds"],"purpose":"Poke Bowl:"}]', '[{"description":"Place water and rice in a large saucepan over medium high heat, no lid.","images":[],"step":1},{"description":"As soon as it comes to a boil (see video), lower heat to medium low, place lid on and leave for 18 - 20 minutes or until water is completely absorbed). DO NOT stir, DO NOT remove lid!","duration":19,"images":[],"step":2},{"description":"Remove from stove with lid still on and leave undisturbed for 15 minutes.","duration":15,"images":[],"step":3},{"description":"Sushi Rice Seasoning:","images":[],"step":4},{"description":"Mix Sushi Seasoning ingredients until sugar dissolves.","images":[],"step":5},{"description":"Spread rice out into large pan (23 x 33cm / 9 x 13\"), drizzle half Seasoning all over.","images":[],"step":6},{"description":"Using a rice paddle OR rubber spatula, cut through the rice and gently fold the rice over (see video!) to mix the Seasoning through.","images":[],"step":7},{"description":"After 1 minute of mixing, drizzle remaining Seasoning then cut/fold for 1 minute. Will look wet but will absorb in next step.","duration":1,"images":[],"step":8},{"description":"Leave rice to cool to warm or room temp (if you can stick it in front of a fan, that''s even better!) - about 20 minutes.","images":[],"step":9},{"description":"Poke Bowl Assembly:","images":[],"step":10},{"title":"Dressing","description":"Mix ingredients in a bowl.","images":[],"step":11},{"description":"Divide rice between bowls. Top with radish, carrot, edamame and avocado.","images":[],"step":12},{"description":"Place tuna in Dressing and toss (no need to marinate), then immediately transfer onto rice.","images":[],"step":13},{"description":"Sprinkle cucumber over the top (mainly on tuna), then green onion and sesame seeds.","images":[],"step":14},{"description":"Drizzle over remaining Dressing then serve!","images":[],"step":15}]', '["fish","gluten","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Hawaiian","Japanese(ish)","Western"],"categories":["asian-recipes","fish-recipes","rice-recipes","salad-recipes-main-course","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4264b86b0e37', 'en', 'US', 'Salmon Salad with Asian Ginger Sesame Dressing', 'Recipe video above. A mighty Salmon Salad that tastes even better than it looks! Vibrant flavours with a fabulous variety of textures - and the Asian Ginger Sesame Dressing gives this amazing flavours!', 'https://www.recipetineats.com/tachyon/2019/07/Salmon-Salad_1.jpg', 15, 10, 25, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_radishes", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_edamame", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.15, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["3 - 4 salmon fillets (, skinless)","3/4 tsp salt and pepper (, each)","1 tbsp oil","250g / 1.5 cups cherry tomatoes (, halved)","2 cucumber (, sliced (or 1 English/telegraph long cucumber))","1 large avocado (, cut into 1.5cm / 2/3\" pieces)","6 red radish (, sliced)","150g / 5 oz leafy crisp lettuce of choice (6 big handfuls)","1 cup edamame (, cooked per packet (Note 1))","1 green onion (, finely sliced on diagonal)","1/4 cup crispy fried shallots (Note 2)"]},{"ingredients":["2 tbsp soy sauce (light or all purpose)","2 1/2 tbsp rice vinegar (aka rice wine vinegar Note 3)","1 tbsp sesame oil (toasted, Note 4)","3 tbsp olive oil (or other neutral flavoured oil)","1.5 tsp sugar (, any type)","2 tsp fresh ginger (, grated)","1 garlic clove (, minced)","1/2 tsp black pepper"],"purpose":"Asian Ginger Sesame Dressing:"}]', '[{"description":"Place Dressing ingredients in a jar and shake well.","images":[],"step":1},{"description":"Sprinkle both sides of salmon with salt and pepper.","images":[],"step":2},{"description":"Heat oil in a non stick skillet over medium high heat.","images":[],"step":3},{"description":"Place salmon in upside down (ie skin side up), cook for 3 minutes or until deep golden.","duration":3,"images":[],"step":4},{"title":"Turn and cook for another 2","description":"3 minutes, or until cooked to your taste.","images":[],"step":5},{"description":"Remove onto plate and cool for 5 minutes.","duration":5,"images":[],"step":6},{"description":"Assemble Salad:","images":[],"step":7},{"description":"Place lettuce in a large bowl. Drizzle with a bit of dressing and toss.","images":[],"step":8},{"description":"Place lettuce in a large serving bowl (or individual plates). Top with salmon, then place tomato, cucumber, avocado, edamame and radish in piles around it.","images":[],"step":9},{"description":"Sprinkle with green onion and crispy shallots.","images":[],"step":10},{"description":"Just prior to serving, drizzle all over with remaining Dressing.","images":[],"step":11}]', '["fish","gluten","sesame","soy"]', '["high_protein"]', '{"mealType":["lunch","dinner"],"cuisine":["Asian influence"],"categories":["asian-recipes","fish-recipes","modern-asian","salad-recipes-main-course","salmon-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2252d8487ad7', 'en', 'US', 'Laksa Noodle Soup', 'Recipe video above. This is a recipe for a real Malaysian restaurant quality laksa made by sprucing up store bought laksa paste! You can''t just dump store bought laksa paste into coconut broth! The key is to freshen up the paste by sautéing it with garlic, ginger, chilli and lemongrass. Makes a world of difference! This makes 2 large bowls. Because large is the only way to go with Laksa!', 'https://www.recipetineats.com/tachyon/2016/09/Laksa.jpg', 15, 45, 60, 2, '[{"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_lemongrass", "quantity": {"value": 20.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_laksa_paste", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.1, "unit": "pack of 500g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.1, "unit": "pack of 500g"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 80.0, "unit": "bag of 250g"}}, {"id": "ing_tofu", "quantity": {"value": 0.267, "unit": "pack of 300g"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.03, "unit": "bottle of 250ml"}}, {"id": "ing_aksa_paste", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_sriracha", "quantity": {"value": 0.037, "unit": "bottle of 400ml"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}]', '[{"ingredients":["2 cups (500 ml) chicken stock / broth","1 cup (250 ml) water","3 chicken drumsticks (Note 1)"],"purpose":"Chicken Stock"},{"ingredients":["1 1/2 tbsp oil","2 garlic cloves (, minced)","2 cm / 4/5\" piece of ginger (, finely grated)","1 lemongrass (, white part grated, (Note 2))","2 birds eye chillis (, finely chopped (Note 3))","1/2 cup (135g) laksa paste (Note 4)","400ml can coconut milk (Note 5)","2 tsp fish sauce (sub soy)"],"purpose":"Laksa Broth"},{"ingredients":["50g / 1.5 oz vermicelli noodles (, dried)","100g / 3.5oz hokkien noodles (optional, Note 6)","80g / 2.5 oz bean sprouts","80g / 2.5 oz tofu puffs (, cut in half (Note 7))"],"purpose":"Noodles + Toppings"},{"ingredients":["1/2 tsp sugar (, white)","1 1/2 tsp soy sauce (, light or all purpose)","1/2 garlic clove (, minced)","1 1/2 tsp Laksa paste (Note 4)","1 tbsp Sriracha sauce (, or other chilli sauce)","1 tbsp chilli paste from jar (, or more Sriracha)","1 tbsp vegetable oil (any plain oil)"],"purpose":"Laksa Chilli Sauce (Note 8)"},{"ingredients":["Fresh coriander / cilantro (recommended)","Lime wedges (recommended)","Crispy fried shallots (, optional (Note 8))","Finely sliced red chilli (, optional )"],"purpose":"Garnishes"}]', '[{"description":"Place Chicken Stock ingredients in a medium saucepan over high heat. Bring to simmer, then reduce to medium high.","images":[],"step":1},{"description":"Cook for 25 minutes or until chicken flesh is falling off the bone and liquid reduces by about 1/3.","duration":25,"images":[],"step":2},{"description":"Discard skin, pull flesh off the bone and place in bowl, discard bone. Set broth aside.","images":[],"step":3},{"description":"Laksa Chilli Sauce","images":[],"step":4},{"description":"Mix ingredients together in a small bowl. Set aside for 20 minutes.","duration":20,"images":[],"step":5},{"description":"Heat oil in a large saucepan or small pot over medium low heat. Add garlic and ginger, sauté for 20 seconds, then add lemongrass and chillis. Cook for 1 minute.","duration":0.3333333333333333,"images":[],"step":6},{"description":"Add laksa paste. Turn heat up to medium and cook for 2 minutes, stirring constantly, or until fragrant.","duration":2,"images":[],"step":7},{"description":"Add chicken stock, coconut milk, fish sauce and 2 tsp of Laksa Chilli Sauce. Place lid on and simmer on for 10 minutes.","duration":10,"images":[],"step":8},{"description":"Adjust to taste using lime juice (for sour) and fish sauce (for saltiness). Add tofu puffs. Leave on turned off stove with lid on for 5 minutes.","duration":5,"images":[],"step":9},{"description":"Prepare noodles per packet directions.","images":[],"step":10},{"description":"Divide noodles between 2 bowls. Top with shredded chicken.","images":[],"step":11},{"description":"Pour broth over chicken. Top with beansprouts. Sprinkle with Garnishes you choose to use. Serve with Laksa Chilli Sauce on the side.","images":[],"step":12}]', '["fish","gluten","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Malaysian"],"categories":["asian-recipes","asian-soups","asian-takeout","chicken-breast-recipes","chicken-drumstick-recipes","chicken-recipes","curry-recipes","iconic-dishes","main-dishes","noodles","soup-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_daa08d39a60c', 'en', 'US', 'Nasi Goreng (Indonesian Fried Rice)', 'Recipe video above. A traditional Indonesian fried rice recipe which is often served with a fried egg for a protein boost to make it a meal, but I usually serve it as a side dish. The magic ingredient in this is kecap manis, a sweet soy sauce which is available in large supermarkets and of course in Asian stores. Feel free to swap out the chicken for other proteins! Shrimp/prawns, tofu, beef and pork are all great alternatives.', 'https://www.recipetineats.com/tachyon/2016/03/Nasi-Goreng_3-1.jpg', 10, 10, 20, 4, '[{"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.142, "unit": "kg"}}, {"id": "ing_kecap_mani", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_white_rice", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_shrimp", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 4.0, "unit": "carton of 12"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["1 tbsp oil","5 oz / 150g chicken breast (, thinly sliced (or other protein))","1 tbsp kecap manis (sweet soy sauce, Note 1)"],"purpose":"Chicken"},{"ingredients":["1.5 tbsp oil","2 garlic cloves (, finely chopped)","1 tsp red chilli (, finely chopped (Note 2))","1 onion (, small, diced)","3 cups cooked white rice (, day old, cold (Note 3))","2 tbsp kecap manis (sweet soy sauce, Note 1)","2 tsp shrimp paste (, optional (Note 4))"],"purpose":"Rice"},{"ingredients":["4 eggs (, fried to taste)","1 green onion (, sliced)","Tomatos and cucumbers, (cut into wedges/chunks)","Fried shallots (, store bought (optional) (Note 3))","Lime wedges"],"purpose":"Garnishes / side servings (optional)"}]', '[{"description":"Heat oil in a large skillet or wok over high heat.","images":[],"step":1},{"description":"Add chilli and garlic, stir for 10 seconds.","duration":0.16666666666666666,"images":[],"step":2},{"description":"Add onion, cook for 1 minute.","duration":1,"images":[],"step":3},{"description":"Add chicken, cook until it mostly turns white, then add 1 tbsp kecap manis and cook for a further 1 minute or until chicken is mostly cooked through and a bit caramelised.","images":[],"step":4},{"description":"Add rice, 2 tbsp kecap manis and shrimp paste, if using. Cook, stirring constantly, for 2 minutes until sauce reduces down and rice grains start to caramelise (key for flavour!).","duration":2,"images":[],"step":5},{"description":"Serve, garnished with garnishes of choice (green onions, red chilli, fried shallots).","images":[],"step":6},{"description":"Serve as a side for Asian main dishes or as part of a large spread, Asian or not! :) See in post for suggestions.","images":[],"step":7},{"title":"Make it a meal","description":"traditional Indonesian style!: Serve with a fried egg sunny side up (runny yolk!), tomato wedges and slices of cucumber on the side.","images":[],"step":8}]', '["egg","gluten","shellfish","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Indonesian"],"categories":["asian-recipes","asian-takeout","dietary","dinner-tonight","fried-rice","gluten-free-recipes","main-dishes","quick-and-easy","rice-recipes","rice-side-dishes","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_daa30431ea02', 'en', 'US', 'Bibimbap', 'Recipe VIDEO above. One of Korea''s most famous food exports! The key here is the Bibimbap Sauce - feel free to switch the veg and meat, whatever you use is going to be amazing once mixed up with that Sauce. There''s a lot of components here but there''s repeat ingredients and it''s an easy recipe - and it''s MEANT to be served at room temp so don''t rush!', 'https://www.recipetineats.com/tachyon/2019/05/Bibimbap_5.jpg', 40, 30, 70, 4, '[{"id": "ing_white_rice", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 4.0, "unit": "carton of 12"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_apples", "quantity": {"value": 0.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_honey", "quantity": {"value": 0.03, "unit": "jar of 500g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_spinach", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_shiitake_mushrooms", "quantity": {"value": 8.0, "unit": "pack of 150g"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 4.0, "unit": "bag of 250g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.04, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_gochujang_paste", "quantity": {"value": 60.0, "unit": "bottle"}}, {"id": "ing_mirin", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}]', '[{"ingredients":["4 cups cooked white rice (, preferably short grain (Note 1))","4 eggs","2 tsp sesame seeds"]},{"ingredients":["250 g/8oz beef tenderloin or thick steak (, very finely sliced (subs, Note 2))","1/4 green apple (, grated using box grater (Note 3))","3 garlic cloves (, minced)","1 tsp minced ginger","1 tbsp soy sauce (, light or all purpose (Note 4))","1 tbsp honey (or brown sugar)","2 tsp sesame oil (, toasted (Note 9))"],"purpose":"Korean Beef & Marinade:"},{"ingredients":["2 carrots (, large, cut into 5 x 0.5cm/2 x 1/5\" batons)","2 zucchini (, large, cut into 5 x 0.5cm/2 x 1/5\" batons)","1 bunch of spinach (, cut into 5cm/2\" lengths)","8 dried shiitake mushrooms (, large (Note 5))","4 cups bean sprouts","2 tsp garlic (, minced (3 cloves))","8 tsp vegetable oil (, separated)","1/2 tsp salt","1.5 tsp soy sauce (, light or all purpose (Note 4))","1/4 tsp fish sauce (sub soy)","1/4 tsp white sugar","Sesame oil (, toasted (Note 9))"],"purpose":"Vegetables:"},{"ingredients":["4 tbsp gochujang paste (Note 6)","2 tbsp mirin (Note 7)","2 tbsp rice vinegar (Note 8)","1.5 tsp soy sauce (Note 4)","3 tsp white sugar","1 garlic clove (, finely grated)","2.5 tsp sesame oil (, toasted (Note 9))"],"purpose":"Bibimbap Sauce:"}]', '[{"description":"Bibimbap Sauce:","images":[],"step":1},{"description":"Mix ingredients until sugar is dissolved.","images":[],"step":2},{"description":"Marinated Beef:","images":[],"step":3},{"description":"Mix the marinade in a bowl, then add beef. Marinate for 30 minutes to overnight.","duration":30,"images":[],"step":4},{"description":"Heat 2 tsp oil in a large skillet over high heat. Let excess marinade drip off then add beef. Cook for 3 - 4 minutes until cooked and there''s some caramelised bits, then remove from skillet.","duration":3.5,"images":[],"step":5},{"description":"Keep warm until required or reheat to warm.","images":[],"step":6},{"description":"Prepare Vegetables:","images":[],"step":7},{"title":"Shiitake","description":"Soak mushrooms in a large bowl of boiling water for 30 minutes, or until rehydrated. Drain, squeeze out excess water, then slice.","duration":30,"images":[],"step":8},{"title":"Carrot and Zucchini salting (optional, Note 10)","description":"Place carrot and zucchini in separate bowls, sprinkle each with 1/4 tsp salt, toss, leave for 20 minutes then drain excess liquid.","duration":20,"images":[],"step":9},{"description":"Cook Vegetables:","images":[],"step":10},{"description":"Get 2 skillets going if you can!","images":[],"step":11},{"title":"Shiitake","description":"Heat 2 tsp oil oil in a skillet over medium high heat. Cook mushrooms for 2 minutes. Add 1.5 tsp soy, 1/4 tsp sugar, 1/2 tsp of garlic. Stir for 1 minute, then remove.","duration":2,"images":[],"step":12},{"title":"Carrot","description":"Add 2 tsp oil into the skillet, cook carrot until just tender (5 to 8 minutes), then remove.","images":[],"step":13},{"title":"Zucchini","description":"Cook as with carrot for 4 minutes.","duration":4,"images":[],"step":14},{"title":"Spinach","description":"Heat 2 tsp veg with a splash of sesame oil. Saute until starting to wilt. Add 1/2 tsp garlic, and salt to taste, stir, then remove. When cool, squeeze to drain out excess liquid.","images":[],"step":15},{"title":"Beansprouts","description":"Simmer in water for 5 min or steam in microwave for 3 min until floppy. Drain under cold water, then cool. Squeeze out excess liquid with hands, place in bowl. Mix with 2 tsp sesame oil, 1 tsp garlic, 1/4 tsp fish sauce.","duration":5,"images":[],"step":16},{"description":"Vegetables can cool, they are meant to be at room temp or slightly warm.","images":[],"step":17},{"description":"Fry eggs in a skillet to your taste (I like mine with runny yolks).","images":[],"step":18},{"description":"Place warm rice in bowls.","images":[],"step":19},{"description":"Top with vegetables and beef, as pictured in post, then lastly, the egg.","images":[],"step":20},{"description":"Sprinkle with sesame seeds, drizzled with sesame oil. Serve with Bibimbap Sauce!","images":[],"step":21}]', '["egg","fish","gluten","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Korean"],"categories":["asian-recipes","asian-takeout","beef-recipes","iconic-dishes","korean-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a3bad777ed77', 'en', 'US', 'Asian Mushroom Ramen Noodles', 'Recipe video above. A quick Asian ramen noodle side dish with caramelised garlic mushrooms with a hint of sesame! Don''t let this 4 ingredient sauce fool you - once it hits the pan, it completely transforms. 4 as a side, 2 as a main (add more veggies!)', 'https://www.recipetineats.com/tachyon/2019/03/Mushroom-Ramen-Noodles_3.jpg', 5, 10, 15, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.004, "unit": "pack of 500g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_mushroom", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_water", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_mirin", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}]', '[{"ingredients":["2 packets ramen or other instant noodles (, uncooked, discard seasoning (Note 1))","1.5 tbsp vegetable oil (or other neutral flavoured oil)","400g / 14 oz mushrooms (, sliced (any type))","2 garlic cloves (, minced)","2 tsp sesame oil (or more oil) (Note 2)","5 green onion stems (shallots/scallions)","1 1/4 cups (315 ml) water, plus more as needed"]},{"ingredients":["1 tbsp dark soy sauce (Note 3)","1 tbsp Oyster sauce (or Hoisin, Note 4)","2 tsp Hoisin sauce (or more Oyster sauce)","1 tbsp mirin (Note 5)"],"purpose":"SAUCE:"}]', '[{"description":"Mix Sauce ingredients in a small bowl.","images":[],"step":1},{"description":"Cut green onion into 5cm/2\" lengths. Separate white/pale green part from green part.","images":[],"step":2},{"description":"Heat oil in a large skillet over high heat. Add mushrooms and cook for 3 minutes.","duration":3,"images":[],"step":3},{"description":"Add the garlic and sesame oil, cook until mushrooms and garlic are golden.","images":[],"step":4},{"description":"Add Sauce, give it a quick stir. Add white part of green onions. Cook 1 minute until mushrooms are caramelised.","images":[],"step":5},{"description":"Push mushrooms to the side to make a big well in the centre.","images":[],"step":6},{"description":"Add water then squidge noodle cakes in.","images":[],"step":7},{"description":"Cook 45 seconds, then flip. Cook 30 seconds then break up the noodles.","images":[],"step":8},{"description":"Add green part of green onions and toss well, adding more water if needed to make it saucy.","images":[],"step":9},{"description":"Serve immediately!","images":[],"step":10}]', '["gluten","sesame","soy"]', '["low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","dinner-tonight","emergency-recipes","mushroom-recipes","noodles","one-pot-recipes","quick-and-easy","side-dishes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3196c7ccbf7b', 'en', 'US', 'Thai Chicken Satay with Peanut Sauce', 'Recipe video above. Thai Chicken Satay Skewers are tasty enough to eat plain but we''d never skip Thai Peanut Sauce for dipping! The essential ingredient for a really great peanut sauce is natural peanut butter with no added sugar or oil. But normal peanut butter will work fine too.', 'https://www.recipetineats.com/tachyon/2019/03/Thai-Satay-Chicken_8.jpg', 15, 15, 30, 15, '[{"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_skewers", "quantity": {"value": 13.0, "unit": "pack of 50"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_red_curry_paste", "quantity": {"value": 0.05, "unit": "bottle"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.3, "unit": "jar of 375g"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_peanuts", "quantity": {"value": 0.075, "unit": "jar"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["400 g/14oz coconut milk ((1 can), full fat)","13-16 bamboo skewers (, 16cm / 6.5\" long (Note 1))"]},{"ingredients":["600 g / 1.2lb chicken thighs (, boneless skinless, cut into 2cm/4/5\" pieces (Note 2))","1 tbsp curry powder (Note 3)","1 tsp white sugar","2 tsp red curry paste (Note 4)","1 tsp cooking salt / kosher salt (sub 1/2 tsp table salt)"],"purpose":"Marinade:"},{"ingredients":["2 tbsp red curry paste (Note 4)","3/4 cup natural peanut butter, smooth (Note 5)","1/4 cup white sugar","2 tsp dark soy sauce (Note 6)","1 tsp cooking salt / kosher salt (sub 1/2 tsp table salt)","2 tbsp cider vinegar (Note 7)","3/4 cup water"],"purpose":"Thai Peanut Sauce:"},{"ingredients":["2 tbsp peanuts finely chopped","Lime wedges (optional)","Coriander / cilantro leaves and sliced red chilli (optional)"],"purpose":"Serving:"}]', '[{"description":"If cooking on a BBQ or over charcoal, soak skewers for 2 hours in water.","images":[],"step":1},{"description":"Thai Chicken Satay Skewers:","images":[],"step":2},{"description":"Mix together the chicken and Marinade with 1/4 cup of coconut milk, then set aside for at least 20 minutes, or overnight.","images":[],"step":3},{"title":"Thread onto skewers","description":"I do 4 to 5 pieces each.","images":[],"step":4},{"description":"Heat 1.5 tbsp oil in a large non stick pan over medium high heat.","images":[],"step":5},{"description":"Cook skewers in batches for 3 minutes on each side until golden.","duration":3,"images":[],"step":6},{"description":"Thai Peanut Sauce:","images":[],"step":7},{"description":"Place remaining coconut milk and Peanut Sauce ingredients in a saucepan over medium low heat.","images":[],"step":8},{"description":"Stir to combine then simmer, stirring every now and then, for 5 minutes.","duration":5,"images":[],"step":9},{"title":"Adjust consistency with water","description":"it should be a pourable but thickish sauce.","images":[],"step":10},{"description":"Cover with lid and keep warm while cooking skewers.","images":[],"step":11},{"description":"Pour some sauce into a bowl. Sprinkle with some peanuts - stir some through if you want.","images":[],"step":12},{"description":"Pile satay skewers onto a platter, sprinkle with remaining peanuts, coriander and chilli.","images":[],"step":13},{"description":"Serve with sauce on the side for dipping. Add a side of Jasmine Rice or Thai Fried Rice to complete the meal!","images":[],"step":14}]', '["gluten","peanuts","soy"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner","snack"],"cuisine":["Thai"],"categories":["asian-recipes","chicken-recipes","cuisines","iconic-dishes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b9bef2f0ca1d', 'en', 'US', 'Hot and Sour Soup', 'Recipe video above. A firm Chinese starter favourite! A glossy soup broth that''s savoury, sour and as spicy as you want it to be, filled with mushrooms, tofu and bamboo shoots. Skip the chicken to make it meat free, or add shrimp/prawns or fish pieces. Serves 6 - 8 as a starter, or 4 as a light meal.', 'https://www.recipetineats.com/tachyon/2019/02/Hot-and-Sour-Soup_1_6.jpg', 20, 20, 40, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.22, "unit": "kg"}}, {"id": "ing_shiitake_mushrooms", "quantity": {"value": 12.0, "unit": "pack of 150g"}}, {"id": "ing_mushroom", "quantity": {"value": 12.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_chicken", "quantity": {"value": 0.22, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_tofu", "quantity": {"value": 0.417, "unit": "pack of 300g"}}, {"id": "ing_bamboo_shoots", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.094, "unit": "pack of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["220 g / 7oz chicken breast","12 dried shiitake mushrooms (or 150g/5oz fresh) (Note 1)","1/2 cup wood ear mushrooms (, chopped 1.5cm/ 3/5\" pieces (Note 1))"]},{"ingredients":["1 tsp dried chilli / red pepper flakes (, adjust spice to taste (Note 2))","2 tsp dark soy sauce (Note 3)","1 tbsp light soy sauce (Note 3)","1 tsp ginger (, finely grated)","1/2 tsp white pepper (sub black)","6 cups (1.5L/1.5qt) chicken or veg stock/broth (, low sodium)","1 tsp sesame oil","1 tsp sugar","1/4 cup (65 ml) white vinegar (adjust to taste)"],"purpose":"Hot and sour soup broth:"},{"ingredients":["125 g / 4oz firm tofu (~ 1 cup) (, cut into 1.2cm / 0.5\" cubes (Note 4))","1/4 cup bamboo shoots (, thinly sliced (Note 5))","2 eggs (, whisked)","1/4 cup (40g) cornstarch/cornflour","1/4 cup (125 ml) water","Salt to taste","1 shallot/scallion (, finely sliced)"],"purpose":"Soup:"}]', '[{"description":"Cover shiitake mushrooms with plenty of boiling water. Stand 20 - 30 minutes until soft, drain, then slice thinly. (Discard or reserve liquid for other use)","images":[],"step":1},{"description":"Poached chicken:","images":[],"step":2},{"description":"Place chicken broth, ginger, soy sauces, chilli, sugar, pepper and sesame oil in a large pot over medium high heat.","images":[],"step":3},{"description":"Once simmering, add chicken, cover and reduce heat so it''s simmering.","images":[],"step":4},{"description":"Cook 10 minutes, remove chicken and shred.","images":[],"step":5},{"description":"Add vinegar, shiitake, wood ear mushrooms, bamboo shoots, tofu and shredded chicken into the soup.","images":[],"step":6},{"description":"Stir, simmer for 10 minutes.","duration":10,"images":[],"step":7},{"description":"Mix cornflour with water. While stirring soup at a medium pace, slowly pour the cornflour mixture in (ensures no lumps).","images":[],"step":8},{"description":"When it starts simmering again, stir constantly and slowly pour egg in a thin stream - this will create the signature \"egg ribbons\".","images":[],"step":9},{"title":"Taste","description":"add salt if desired, more chilli if you want.","images":[],"step":10},{"description":"Add shallots and serve!","images":[],"step":11}]', '["egg","gluten","sesame","soy"]', '["high_protein","low_calorie"]', '{"mealType":["dinner","snack"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-soups","asian-takeout","chinese-recipes","dietary","dinner-tonight","low-calorie-recipes","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7dc28d39aab0', 'en', 'US', 'How to Tenderise Chicken for Stir Fries (Chinese secret!)', 'Ever notice how the chicken in stir fries at your favourite Chinese restaurant is incredibly tender, and how it''s just never as good at home? It''s because the chicken breast is tenderised, a method called "velveting chicken". Use this for the juiciest chicken breast you''ll ever have in stir fries and noodles! SCALE recipe - click on servings and slide.', 'https://www.recipetineats.com/tachyon/2019/03/Tenderise-velvet-chicken-cover-photo-square.jpg', 5, 0, 5, 3, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.019, "unit": "tub of 200g"}}]', '[{"ingredients":["250 g / 8 oz chicken breast slices OR bite size pieces (not whole pieces, Note 1)","3/4 tsp baking soda (bi-carb/bi-carbonate)"]}]', '[{"description":"Place chicken in a bowl and sprinkle baking soda all over the surface.","images":[],"step":1},{"description":"Toss with fingers to coat as evenly as possible.","images":[],"step":2},{"description":"Refrigerate 20 minutes for slices, 30 minutes for bite size pieces.","images":[],"step":3},{"description":"Rinse well in colander to remove baking soda.","images":[],"step":4},{"description":"Shake off then pat away excess water (doesn''t need to be 100% dry).","images":[],"step":5},{"title":"Use as directed in chosen recipe","description":"stir fries and noodles (see in post for suggested recipes). Can be marinated, cooked on the stove, deep fried, simmered in broth.","images":[],"step":6}]', '[]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["American Chinese"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","chinese-recipes","good-to-know","stir-fries","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4fe0f880b8cf', 'en', 'US', 'How to tenderise beef (velveting beef)', 'Chinese restaurants tenderise economical cuts of beef so they are tender and juicy in stir fries. It''s also done for chicken. There''s a few methods - this baking soda way is the easiest, fastest and highly effective. Though I''m sharing this with beef stir fries in mind, don''t just limit yourself to Asian food. This beef can be used for any recipe calling for strips of beef to be cooked quickly, like Beef Stroganoff. Do not use this method for whole steaks (read Note 4).', 'https://www.recipetineats.com/tachyon/2015/03/How-to-Tenderise-Beef-Chinese-Method.jpg', 25, 0, 25, 2, '[{"id": "ing_beef", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.019, "unit": "tub of 200g"}}]', '[{"ingredients":["250 g / 8 oz stewing beef or other economical beef cuts (Note 1)","3/4 tsp baking soda / bi-carbonate soda (Note 2)"]}]', '[{"description":"Slice beef thinly against the grain. (Note 3)","images":[],"step":1},{"description":"Place in a bowl. Sprinkle over baking soda, toss with fingers to coat evenly.","images":[],"step":2},{"description":"Refrigerate for 30 to 40 minutes. (See Note 1 for different cuts)","duration":35,"images":[],"step":3},{"description":"Rinse beef well with tap water. Shake off excess water, then use paper towels to blot away excess water (doesn''t need to be 100% dry).","images":[],"step":4},{"description":"Proceed with recipe of choice. Beef can be marinated or seasoned before cooking, stir fried or deep fried, and it will be soft and tender, \"velvet\" like. Use for Stir Fries, Stir Fried Noodles, Beef Stroganoff and any other recipe calling for quick-cooked beef strips.","images":[],"step":5}]', '[]', '["gluten_free","high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["American Chinese","Chinese"],"categories":["asian-recipes","asian-takeout","beef-recipes","chinese-recipes","good-to-know","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2d254514e6f2', 'en', 'US', 'Egg Foo Young (Chinese omelette)', 'Recipe video above. This is how the Chinese do omelettes! Egg Foo Young was created as a recipe to use up leftovers, so make this your own using what you have - see Notes for the formula. Otherwise, use EITHER the prawn/shrimp or pork filling. Makes 4 small omelettes, serves 2 as meal with rice, or 4 as part of a banquet.', 'https://www.recipetineats.com/tachyon/2018/07/Egg-Foo-Yung-5.jpg', 10, 15, 25, 4, '[{"id": "ing_flour", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_egg", "quantity": {"value": 6.0, "unit": "carton of 12"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 4.0, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_one_filling_of_choice_below", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_shrimp", "quantity": {"value": 100.0, "unit": "kg"}}, {"id": "ing_pork", "quantity": {"value": 0.11, "unit": "kg"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 4.0, "unit": "bunch"}}]', '[{"ingredients":["4 tsp cornflour / corn starch","1 1/2 tbsp light soy sauce (, or all purpose (Note 2))","2 tsp Oyster Sauce","1 tbsp Chinese Cooking Wine (shaoxing wine) OR Mirin (Note 3)","1/2 tsp sesame oil","1 cup / 250 ml water","Dash of white pepper"],"purpose":"Sauce (Note 1 for Charlie option):"},{"ingredients":["6 eggs","2 cups bean sprouts (just eyeball it)","4 shallots/green onions (, white part only, sliced)","Salt and white pepper","2 tbsp vegetable oil","1 tsp sesame oil","1 garlic clove (, finely chopped)","ONE Filling of Choice, below (Prawn or Pork)"],"purpose":"Omelette:"},{"ingredients":["100 - 120g/3.5 - 4 oz chopped raw small prawns/shrimp (, peeled and deveined (Note 4))"],"purpose":"Option 1: For Prawn /Shrimp Egg Foo Young"},{"ingredients":["100 - 120g/3.5 - 4 oz ground/mince pork (or chicken, turkey, beef or veal)","1/2 tsp EACH soy sauce and Oyster Sauce","1/4 tsp sugar","Dash of sesame oil"],"purpose":"Option 2: For Pork Egg Foo Young :"},{"ingredients":["Sesame seeds, sliced green onion"],"purpose":"Garnish (optional):"}]', '[{"description":"Mix cornflour and soy sauce. Then add remaining ingredients.","images":[],"step":1},{"description":"Pour into a saucepan over medium heat. Bring to simmer, stirring constantly. Simmer for 1 minute until sauce thickens to thin syrup consistency. Remove from stove, set aside.","duration":1,"images":[],"step":2},{"title":"MICROWAVE option","description":"Microwave on high for 1 1/2 minutes. Stir very well, microwave for another 1 1/2 minutes until thickened. Mix well again.","images":[],"step":3},{"description":"Place pork in a bowl, add remaining ingredients. Use fork to mix through.","images":[],"step":4},{"description":"Whisk eggs in a bowl.","images":[],"step":5},{"description":"Add beansprouts, green onions, pork or prawns, salt and pepper. If using pork, crumble the raw pork in with fingers (see video). Mix through.","images":[],"step":6},{"description":"Heat 1/2 tbsp vegetable oil and drizzle of sesame oil in a non stick skillet over medium heat. Add a bit of garlic and quickly saute (10 seconds) and push into centre of skillet.","images":[],"step":7},{"description":"Ladle in 1/4 of batter. Use spatular to push edges in to form a round(ish) shape.","images":[],"step":8},{"description":"Cook until the underside is light golden (about 1 1/2 minutes) then flip and cook the other side for 1 minute. The raw meat will cook through in this time. Repeat with remaining egg to make 4 omelettes (use 2 pans if you can!).","duration":1,"images":[],"step":9},{"description":"Slide omelette onto plate. Pour over sauce. Sprinkle with sesame seeds and green onions, if using.","images":[],"step":10},{"description":"Serve with a side of rice and steamed vegetables of choice. Double the sauce if you want enough to pour over the rice and veggies! (Click on Servings to scale recipe up).","images":[],"step":11}]', '["egg","gluten","sesame","shellfish","soy"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["American Chinese"],"categories":["asian-recipes","chinese-recipes","dinner-tonight","egg-recipes","prawns-shrimp","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0a70c1e4ca66', 'en', 'US', 'Homemade Thai Green Curry Paste', 'Recipe video above. Usually, the main reason to make homemade curry paste is because you just can''t get the same intense, fresh flavour in a jar. And while that holds true for green curry paste, the other very big advantage is that you can control the spiciness without compromising flavour or the signature green colour.', 'https://www.recipetineats.com/tachyon/2019/02/Homemade-Thai-Green-Curry-Paste_3.jpg', 15, 0, 15, 5, '[{"id": "ing_cayenne_pepper", "quantity": {"value": 0.1, "unit": "jar of 40g"}}, {"id": "ing_chilli", "quantity": {"value": 6.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_lemongrass", "quantity": {"value": 40.0, "unit": "bunch"}}, {"id": "ing_galangal", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 8.333, "unit": "pack of 3 heads"}}, {"id": "ing_shrimp", "quantity": {"value": 0.013, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.08, "unit": "jar of 50g"}}, {"id": "ing_turmeric", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_water", "quantity": {"value": 2.0, "unit": "L"}}]', '[{"ingredients":["4 green cayenne pepper chilis (, deseeded and chopped (Note 1))","6 Thai green chilis (, chopped (Note 1))","2 red shallots / eschallots (, chopped)","2 lemongrass stems (, trimmed and finely chopped (about 2.5 - 3 tbsp) (Note 2))","2 tbsp galangal (, grated (Note 3))","5 cloves garlic (, chopped)","2.5 tsp dried shrimp paste (Belacan) (Note 4)","2 tsp lime zest (, grated)","1 tsp ground coriander","1 tsp ground cumin","1/4 tsp white pepper","1/4 tsp turmeric","2 tbsp chopped coriander/cilantro root and stem (Note 5)","1/4 cup coriander / cilantro leaves (, loosely packed)","2 - 3 tbsp water (, as needed)"]}]', '[{"description":"Combine all ingredients except water in a powerful blender or food processor. I use my Vitamix because it makes the paste smoother.","images":[],"step":1},{"description":"Blend to a fine paste, scraping down the sides as you go. Add the water as required to help it blend (you may not need any as the herbs and chilis have moisture).","images":[],"step":2},{"description":"Use to make Thai Green Curry!","images":[],"step":3},{"description":"Best to use immediately. Otherwise, refrigerate for up to 2 days, or freeze for 1 month.","images":[],"step":4}]', '["shellfish"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","cuisines","curry-recipes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1b144c63090f', 'en', 'US', 'Chinese Crispy Pork Belly', 'Recipe video above. This is Chinese pork belly, just like you get from the Chinese BBQ meat shops! The best crackling in the world, with the signature bubbles, super crispy and golden. If pricking the skin is too daunting for you, use the Foolproof Easy Method (Note 7)', 'https://www.recipetineats.com/tachyon/2017/01/Crispy-Chinese-Pork-Belly-1.jpg', 20, 90, 110, 8, '[{"id": "ing_pork", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.045, "unit": "bottle of 500ml"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}]', '[{"ingredients":["1 pork belly, skin on (800 - 1.2kg / 1.6 - 2.4 lb) (Note 1)","1 1/2 tbsp Chinese cooking wine (Shaoxing wine) (Note 2)","1 tsp Chinese five spice powder (Note 3)","1 tsp white pepper (sub black pepper)","1/2 tsp salt","1 tbsp white vinegar (helps conduct heat evenly)","200 g / 7 oz rock salt (Note 4)"]}]', '[{"description":"Prepare Pork Belly","images":[],"step":1},{"description":"Use an ice pick, sharp metal skewer or another tool to prick tons and tons of holes in the skin. Avoid piercing int o the fat as best you can, and really ensure you do not pierce the flesh (Note 5)","images":[],"step":2},{"description":"Turn the pork belly upside down. Rub the flesh (not skin) with Chinese cooking wine, dribbling it on gradually. Sprinkle over five spice powder, salt and pepper. Rub all over flesh, including sides (not on skin).","images":[],"step":3},{"description":"Turn skin side up and place in a container. Dab skin dry with paper towels. Refrigerate uncovered for 12 hours (max 24 hrs, min 3 hrs).","images":[],"step":4},{"description":"Cook:","images":[],"step":5},{"description":"Preheat oven to 180C/350F (all oven types).","images":[],"step":6},{"description":"Remove pork from fridge. Place onto a large sheet of foil. Fold up sides of foil around the pork to enclose it snugly (see photos in post or video) with a 1.5cm / 2/5\" rim above the pork skin (to hold salt in).","images":[],"step":7},{"description":"Transfer pork to baking tray. Dab skin with paper towels.","images":[],"step":8},{"description":"Brush skin with vinegar.","images":[],"step":9},{"description":"Spread rock salt on the skin (the foil edges will stop it from falling down the sides).","images":[],"step":10},{"description":"Roast for 60 minutes.","duration":60,"images":[],"step":11},{"description":"Remove pork from oven and transfer onto work surface.","images":[],"step":12},{"description":"Switch to grill/broiler on medium high. Move shelf so it is at least 25cm/10\" from the heat source.","images":[],"step":13},{"description":"Fold down foil and scrape all the salt off the top and sides. Return pork only (i.e. discard foil) to baking tray.","images":[],"step":14},{"title":"Place under grill/broiler for 20","description":"25 minutes, rotating tray once, until skin is golden, crispy and puffed. (Note 6)","duration":22.5,"images":[],"step":15},{"description":"To Serve","images":[],"step":16},{"title":"Remove pork onto cutting board. Slice into 1","description":"1.5cm / 2/5 - 3/5\" thick slices, then into smaller slices like pictured in post.","images":[],"step":17},{"title":"Serve with ordinary yellow mustard","description":"or Hot English Mustard if you like spicy like me! Not Dijon, just ordinary American or other yellow mustard (yes really!). Sometimes it is served with white sugar on the side too. Add some fresh raw vegetables (I use cucumber and radish).","images":[],"step":18}]', '[]', '["gluten_free","high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","dietary","gluten-free-recipes","iconic-dishes","main-dishes","modern-asian","pork-recipes","roasts","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_de3df7ab583a', 'en', 'US', 'Chinese Cashew Chicken', 'Recipe video above. The soft, creamy crunch of cashews is a perfect addition to this saucy chicken stir fry! Truly stacks up to your favourite take out - read the glowing reviews! If using breast, consider tenderising it the Chinese way ("Velveting Chicken")', 'https://www.recipetineats.com/tachyon/2015/10/Cashew-Chicken_6.jpg', 15, 6, 21, 4, '[{"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.045, "unit": "bottle of 500ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.09, "unit": "L"}}, {"id": "ing_roasted_cashews", "quantity": {"value": 112.5, "unit": "jar"}}]', '[{"ingredients":["1 tbsp cornstarch / cornflour","3 tbsp soy sauce (, all purpose or light (Note 1))","1 1/2 tbsp Chinese cooking wine or Mirin (Note 2)","3 tbsp oyster sauce","2 tsp sesame oil","Dash of white pepper (sub black)"],"purpose":"Sauce"},{"ingredients":["500g / 1 lb chicken thigh (, skinless boneless, cut into 2.5cm/1\" pieces (Note 3))","2 tbsp peanut oil (or vegetable oil)","2 garlic cloves (, minced)","1/2 onion (, chopped into 1.75 cm / 3/4\" pieces(yellow, brown or white))","1 green capsicum / bell pepper (, chopped into 2 cm / 0.8\" pieces)","6 tbsp water","3/4 cup roasted cashews (, unsalted)"],"purpose":"Stir Fry"}]', '[{"title":"Sauce","description":"Mix cornflour and soy sauce until there''s no lumps. Then add remaining Sauce ingredients and mix.","images":[],"step":1},{"title":"Marinate","description":"Transfer 2 tbsp Sauce to chicken, mix to coat. Set aside for 10 minutes+.","duration":10,"images":[],"step":2},{"title":"Cook","description":"Heat oil over high heat in a wok or heavy based skillet. Add the garlic and onion, cook for 1 minute.","duration":1,"images":[],"step":3},{"description":"Add chicken and cook for 2 minutes. Add capsicum and cook for 1 minute.","duration":2,"images":[],"step":4},{"description":"Add Sauce and water. Bring to simmer and cook, stirring, for 1 minute or until Sauce thickens.","duration":1,"images":[],"step":5},{"description":"Stir through cashews, remove from stove. Serve immediately with rice - or for a low carb, low cal option, try Cauliflower Rice!","images":[],"step":6}]', '["gluten","peanuts","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","chinese-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","most-popular","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3da0bdd640da', 'en', 'US', 'Chicken Vegetable Ramen Noodles', 'Recipe video above. A great quick Asian ramen noodle recipe that''s jam packed with a surprising amount of vegetables! Caramelise the chicken well - makes all the difference. Switch veg as desired. Also see the ground beef / mince version - Asian Beef Ramen Noodles.', 'https://www.recipetineats.com/tachyon/2019/01/Chicken-Ramen-Noodles_4.jpg', 10, 8, 18, 3, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.004, "unit": "pack of 500g"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cabbage", "quantity": {"value": 6.0, "unit": "head"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_mirin", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 packets ramen or other instant noodles (, discard seasoning (Note 1))","1 tbsp oil","2 garlic cloves (, minced)","1/2 onion (, sliced)","200g / 7oz chicken thighs, cut into bite size pieces (Note 2)","1 1/4 cups (315 ml) water, plus more as needed","1 carrot (, cut into matchsticks)","1 small red capsicum / bell pepper (, sliced )","2 cups cabbage (, finely sliced (any type))"]},{"ingredients":["1 tbsp dark soy sauce (Note 3)","1 tbsp Oyster sauce (or Hoisin, Note 4)","2 tsp Hoisin sauce (or more Oyster sauce)","1 tbsp Mirin (Note 5)"],"purpose":"Sauce:"},{"ingredients":["Finely sliced green onion / shallots"],"purpose":"Garnishes (optional):"}]', '[{"description":"Mix Sauce.","images":[],"step":1},{"description":"Heat oil in a large skillet over high heat. Add onion and garlic, cook for 1 1/2 minutes until starting to go golden.","images":[],"step":2},{"description":"Add chicken and cook just until the outside mostly changes from pink to white.","images":[],"step":3},{"description":"Add Sauce and cook for 1 minute until chicken is quite caramelised.","duration":1,"images":[],"step":4},{"description":"Add carrot and capsicum, cook for 1 minute (chicken should now be nicely caramelised, see video).","duration":1,"images":[],"step":5},{"description":"Push chicken and veg to the side to make enough space for the noodles. Add water, place noodles in water.","images":[],"step":6},{"description":"When the water starts simmering on the edges, leave noodles for 45 seconds then turn.","duration":0.75,"images":[],"step":7},{"description":"Leave for 30 seconds, then untangle the noodles, then toss through the chicken and veg.","duration":0.5,"images":[],"step":8},{"description":"Add cabbage, toss for 1 minute until sauce reduces to coat the noodles and the noodles are cooked. (Note 6)","duration":1,"images":[],"step":9},{"description":"Serve immediately, garnished with green onions.","images":[],"step":10}]', '["gluten","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","chicken","chicken-breast-recipes","chicken-recipes","dinner-tonight","emergency-recipes","main-dishes","mains","noodles","one-pot-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_037ee287ff80', 'en', 'US', 'Thai Coconut Soup', 'Recipe video above. This amazing quick & easy Thai Coconut Soup is made from scratch!! Tastes like a Thai coconut curry, a cross between Tom Yum and Laksa soups. This recipe is all about the soup broth, so put whatever you want into the soup! This is the noodle soup version of this Poached Salmon in Coconut Lime Sauce.', 'https://www.recipetineats.com/tachyon/2018/10/Coconut-Noodle-Soup_3.jpg', 8, 12, 20, 2, '[{"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_shrimp", "quantity": {"value": 10.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_lemongrass", "quantity": {"value": 20.0, "unit": "bunch"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.2, "unit": "jar of 50g"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_lime", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp vegetable oil","10 prawns/shrimp (, peeled and deveined (Note 1))","2 garlic cloves (, finely grated)","2 tsp ginger (, finely grated)","1 lemongrass (, peeled, finely grated (Note 2))","1 tbsp brown sugar","1 1/2 tbsp fish sauce (or soy sauce)","2 tsp curry powder (Note 3)","1 tsp coriander powder","2 tsp chilli garlic paste or other chilli paste (, adjust to taste (Note 4))","400 g/14oz coconut milk (Note 5)","2 cups /500ml chicken broth (or vegetable)","2 tsp lime zest (1 lime)","200 g / 7 oz fresh egg noodles, (prepared per packet (other noodles Note 6))","Big handful bean sprouts"]},{"ingredients":["Lime wedges","Fresh coriander/cilantro leaves","Sliced red onion (or sliced green onion), Fried Asian shallots (Note 7), sliced red chilli, more chilli paste (optional)"],"purpose":"Toppings / for serving:"}]', '[{"description":"Heat oil in a large saucepan over high heat. Add prawns and sear both sides until light golden (doesn''t need to cook inside). Remove onto plate.","images":[],"step":1},{"description":"Turn heat down to medium. If pot is looking dry, add a touch of extra oil.","images":[],"step":2},{"description":"Add garlic, ginger and lemongrass. Saute for 20 seconds until garlic is golden.","duration":0.3333333333333333,"images":[],"step":3},{"description":"Add sugar and fish sauce. Stir and cook for 30 seconds - it should look like caramel.","duration":0.5,"images":[],"step":4},{"description":"Add chilli paste, coriander and curry powder. Stir and cook for 30 seconds.","duration":0.5,"images":[],"step":5},{"description":"Add chicken broth and coconut milk. Stir and bring to simmer.","images":[],"step":6},{"description":"Simmer for 2 minutes, then add lime zest and return prawns into broth.","duration":2,"images":[],"step":7},{"description":"Cook for 2 minutes just to reheat and finish cooking the prawns.","duration":2,"images":[],"step":8},{"description":"Place noodles in bowl. Ladle over soup.","images":[],"step":9},{"description":"Top with bean sprouts and coriander, plus toppings of choice (chilli, red onion, Asian fried shallots).","images":[],"step":10},{"description":"Squeeze over lime juice to taste. Slurp and be happy!","images":[],"step":11}]', '["egg","fish","gluten","shellfish","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Asian","Thai"],"categories":["asian-recipes","asian-soups","cuisines","dinner-tonight","main-dishes","prawns-shrimp","quick-and-easy","soup-recipes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c22559ce5ce4', 'en', 'US', 'Kung Pao Chicken', 'Recipe video above. Kung Pao chicken - done right! The flavour of this sauce is very similar to proper restaurant versions, with a great balance of savoury-sweet and sour with the numbing tingle from Sichuan pepper. Use whole Sichuan peppercorns if you have them, otherwise ground is fine (which is what I use).', 'https://www.recipetineats.com/tachyon/2018/09/Kung-Pao-Chicken.jpg', 15, 10, 25, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_water", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 2.5, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 6.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.06, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_whole_peanuts", "quantity": {"value": 112.5, "unit": "jar"}}]', '[{"ingredients":["1 lb / 500g chicken thigh (, cut into bite size pieces)"],"purpose":"Chicken"},{"ingredients":["2 tsp cornflour / cornstarch","1 tbsp light soy sauce (Note 2)","1.5 tbsp dark soy sauce (Note 3)","2 tbsp Chinese black vinegar (Note 4)","1 tbsp Chinese cooking wine (Note 5)","3 tbsp sugar (, any)","1/2 tsp sesame oil","1/3 cup water"],"purpose":"Sauce"},{"ingredients":["2 tbsp peanut oil (or other cooking oil)","2 garlic cloves (, minced)","1 tsp ginger (, finely chopped)","6 - 10 dried chillies (adjust to taste), cut into 2cm/ 3/4\" pieces, most seeds discarded (Note 7)","3 green onions (, cut into 2cm/ 3/4\" pieces, white parts separated from green)","1.5 tsp ground sichuan peppercorns (, adjust to taste (Note 6))","3/4 cup whole peanuts (or 1/2 cup halved) (, roasted unsalted)"],"purpose":"Stir Fry"}]', '[{"description":"Sauce & Marinade Chicken:","images":[],"step":1},{"description":"Mix cornflour and soy sauce in a small bowl until cornflour is dissolved. Then mix in remaining Sauce ingredients EXCEPT water.","images":[],"step":2},{"description":"Pour 1.5 tbsp Sauce over chicken. Toss to coat, set aside for 10 - 20 minutes.","duration":15,"images":[],"step":3},{"description":"Add water into remaining Sauce.","images":[],"step":4},{"description":"Heat oil in wok over high heat. Add garlic, ginger and chillies. Cook for 30 seconds or until fragrant.","duration":0.5,"images":[],"step":5},{"description":"Add chicken, cook until it turns white, then add the white part of the green onions. Cook until chicken is cooked through - about 2 minutes.","images":[],"step":6},{"description":"Add Sauce and Sichuan pepper. Bring to simmer, mixing constantly, until almost all the sauce reduces to a thick syrup.","images":[],"step":7},{"description":"Just before the end, mix through peanuts and green part of the green onions. Also check spiciness - add more Sichuan pepper if you can handle the heat!","images":[],"step":8},{"title":"Serve immediately with rice","description":"or for a low carb, low cal option, try Cauliflower Rice!","images":[],"step":9}]', '["gluten","peanuts","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","chinese-recipes","dinner-tonight","main-dishes","modern-asian","most-popular","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e49ada168e82', 'en', 'US', 'One Pot Chinese Chicken and Rice', 'Recipe video above. It''s like fried rice and Chinese chicken made in one pot! If you can''t find Chinese broccoli, see notes for how to make with other vegetable options. A terrific quick and easy dinner!', 'https://www.recipetineats.com/tachyon/2018/09/One-Pot-Chinese-Chicken-and-Rice_3.jpg', 10, 20, 30, 4, '[{"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_broccoli", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_white_rice", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 tbsp oil","2 garlic cloves (, minced)","1 tsp ginger (, grated)","1 onion (, finely chopped)","500g (1 lb) chicken thighs (, skinless boneless, halved (Note 1))","1 big bunch Chinese Broccoli with thick stems (Note 2)"]},{"ingredients":["1 cup (180g) uncooked white rice ( (Note 3))","1 1/2 cups (375 ml) chicken broth (, low salt)"],"purpose":"Rice:"},{"ingredients":["2 cloves garlic (, small, chopped)","2 tbsp Chinese cooking wine (or Mirin (Note 4))","3 tbsp oyster sauce (or sub with Hoisin)","1 1/2 tbsp dark soy sauce (Note 5)","1/4 tsp white pepper (or black)"],"purpose":"Sauce:"},{"ingredients":["green onion (, sliced)","Sesame seeds"],"purpose":"Garnish:"}]', '[{"description":"Mix Sauce in a large bowl. Add chicken and set aside to marinate for 10 minutes to overnight.","duration":10,"images":[],"step":1},{"description":"Cut Chinese broccoli stems cut into 2.5 cm/1\" pieces, leafy part 5cm/2.5cm pieces.","images":[],"step":2},{"description":"Heat oil in a large pot over medium high heat. Remove chicken from marinade, shaking off excess marinade - RESERVE marinade!","images":[],"step":3},{"title":"Cook both sides until golden","description":"about 90 seconds on each side, don''t let them burn! Remove chicken onto plate.","images":[],"step":4},{"description":"Add a touch of oil if pot is dry. Add onion, garlic and ginger, cook for 2 minutes until tinged with gold.","duration":2,"images":[],"step":5},{"description":"Add rice, stir to coat grains in oil. Add broth, reserved Marinade and Chinese broccoli stems. Stir.","images":[],"step":6},{"description":"Place chicken across the top, pour in juices pooled on plate. Cover, bring to simmer then lower heat to medium.","images":[],"step":7},{"description":"Cook for 12 -15 minutes or until liquid is absorbed (tilt pot to check).","duration":13.5,"images":[],"step":8},{"description":"Remove from heat. Working quickly, scatter Chinese broccoli leaves across surface, clamp lid back on.","images":[],"step":9},{"description":"Rest for 10 minutes. Remove lid, toss rice and serve, garnished with sesame seeds and green onions. A dollop of your favourite chilli paste wouldn''t go astray either!","duration":10,"images":[],"step":10}]', '["gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","chicken","chicken-breast-recipes","chicken-recipes","chinese-recipes","dinner-tonight","main-dishes","mains","one-pot-recipes","quick-and-easy","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c69c2adb2b4d', 'en', 'US', 'Wonton Soup', 'Recipe VIDEO above. Homemade wontons are amazing! No fillers, just real ingredients in the filling. Terrific standby freezer meal!', 'https://www.recipetineats.com/tachyon/2016/09/Wontons_4.jpg', 20, 15, 35, 50, '[{"id": "ing_wonton_wrappers", "quantity": {"value": 50.0, "unit": "unit"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_shrimp", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_chicken", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_bok_choy", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 40.0, "unit": "pack of 500g"}}]', '[{"ingredients":["50 - 60 wonton wrappers (Note 1)"]},{"ingredients":["200 g / 7 oz lean pork mince (ground pork)","200 g / 7 oz peeled prawns / shrimp (, roughly chopped)","1 tbsp ginger (, finely grated (1.5\" / 3cm piece))","2 shallots / green onions (, finely chopped (5 tbsp))","1 tbsp light soy sauce (Note 2)","2 tbsp Chinese cooking wine (Shaoxing wine) (Note 3)","1/2 tsp salt","2 tbsp sesame oil, toasted (Note 4)"],"purpose":"Wonton Filling"},{"ingredients":["3 cups / 750 ml chicken broth (Note 5)","2 garlic cloves (, smashed (6))","⅓\" / 1 cm piece of ginger (, sliced (optional, but highly recommended))","1½ tbsp light soy sauce (Note 2)","2 tsp sugar (any)","1½ tbsp chinese cooking wine (Note 3)","¼ - ½ tsp sesame oil"],"purpose":"Broth (for 2 servings)"},{"ingredients":["Shallots / scallions (, finely chopped)","Bok choy (, quartered, or Chinese broccoli cut into 10cm /4\" lengths (optional))","40 - 50 g / 1.5 - 1.75 oz dried egg noodles per person (, (optional) (8))"],"purpose":"To Serve"}]', '[{"description":"Place Filling ingredients in a bowl. Use a potato masher to mash until fairly smooth - about 20 mashes. Don''t turn the prawn into a complete paste, small chunks are good.","images":[],"step":1},{"description":"Wrapping (See photos and video):","images":[],"step":2},{"description":"Use My Way (better Wonton Soup experience!) or the Asian Grocery Store Way (easier to pack for freezing).","images":[],"step":3},{"description":"Lay Wontons on work surface. Use 2 teaspoons to put the Filling on the wontons. Work in batches of 5 if starting out, up to 15 or 20 if confident. Brush 2 edges with water. Fold to seal, pressing out air. Brush water on one corner and bring corners together, pressing to seal.","images":[],"step":4},{"description":"Place wrapped wontons into a container with a lid as you work (so they don''t dry out).","images":[],"step":5},{"description":"Cooking/Freezing:","images":[],"step":6},{"title":"To cook","description":"bring a large pot of water to boil. Place wontons in water and cook for 4 minutes or until they float. Remove with slotted spoon straight into serving bowls. Ladle over broth.","duration":4,"images":[],"step":7},{"title":"To freeze","description":"Freeze uncooked in airtight containers. Cook from frozen for 6 to 8 minutes. IMPORTANT: Do not freeze if you made this with defrosted frozen prawns. (Note 11)","duration":7,"images":[],"step":8},{"description":"Place Broth ingredients in a saucepan over high heat. Add white ends of scallions/shallots if leftover from Wonton filling.","images":[],"step":9},{"description":"Place lid on, bring to simmer then reduce to medium high and simmer for 5 - 10 minutes to allow the flavours to infuse. Pick garlic and ginger out before using.","duration":7.5,"images":[],"step":10},{"description":"If using vegetables, blanch in the soup broth and place in serving bowl.","images":[],"step":11},{"description":"Prepare noodles according to packet directions (if using noodles). Place in serving bowl with cooked wontons and blanched vegetables.","images":[],"step":12},{"description":"Ladle over soup. Serve!","images":[],"step":13}]', '["egg","gluten","sesame","shellfish","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-soups","asian-takeout","chinese-recipes","dietary","dumplings","iconic-dishes","low-calorie-recipes","main-dishes","most-popular","noodles","soup-recipes","yum-cha-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2ae7b968998d', 'en', 'US', 'Poached Salmon in Coconut Lime Sauce', 'Recipe video above. Poached Salmon in a coconut lime sauce that tastes like a Thai coconut curry - except it''s super quick and easy to make! Even though the salmon is poached, it''s well worth searing lightly to brown for the extra flavour on both the salmon and in the sauce.', 'https://www.recipetineats.com/tachyon/2018/09/Poached-Salmon-in-Coconut-Lime-Sauce_2.jpg', 10, 15, 25, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_lemongrass", "quantity": {"value": 20.0, "unit": "bunch"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.01, "unit": "pack of 100g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_lime", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_steamed_asian_greens", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["4 salmon fillets (, 180g/6oz each preferably skinless (Note 1))","Salt and pepper","2 tbsp oil (, separated)","2 garlic cloves (, finely grated)","2 tsp ginger (, finely grated)","1 lemongrass (, peeled, finely grated (Note 2))","1 tbsp brown sugar","1 tsp chilli garlic paste (or other chilli paste, adjust to taste (Note 3))","400 g/14oz coconut milk (Note 2)","1 tbsp fish sauce (or soy sauce)","2 tsp lime zest (1 lime)","Lime juice (, to taste)"]},{"ingredients":["Fresh coriander/cilantro leaves (, finely chopped (recommended))","Finely sliced large red chillies (optional)","Vermicelli noodles OR (, soaked per packet, or rice)","Steamed jasmine rice","Steamed Asian greens"],"purpose":"Garnish/serving:"}]', '[{"description":"Sprinkle both sides of salmon with salt and pepper.","images":[],"step":1},{"description":"Heat 1 tbsp oil in a non stick pan or well seasoned skillet over medium high heat. Add salmon, skin side up, and sear for just 1 1/2 minutes until golden. Turn salmon and cook the other side just for 1 minute, then remove onto a plate (should still be raw inside).","duration":1,"images":[],"step":2},{"description":"Turn heat down to medium low and allow skillet to cool.","images":[],"step":3},{"description":"Heat remaining 1 tbsp oil. Add garlic, ginger and lemongrass. Cook until garlic is light golden ~ 1 minute.","images":[],"step":4},{"description":"Add sugar and cook for 20 seconds until it becomes a caramel (see video). Then stir in chilli paste.","duration":0.3333333333333333,"images":[],"step":5},{"description":"Add coconut milk and stir, scraping the bottom of the skillet to dissolve any bits stuck on the base into the sauce.","images":[],"step":6},{"description":"Stir in fish sauce, increase heat to medium. Simmer for 2 minutes.","duration":2,"images":[],"step":7},{"description":"Place salmon into the sauce, lower heat and simmer gently for 4 minutes, or until just cooked.","duration":4,"images":[],"step":8},{"description":"Remove salmon, stir in lime zest and juice to taste. Adjust salt to taste with fish sauce.","images":[],"step":9},{"description":"Serve salmon over noodles or rice. Spoon over sauce, garnish with coriander and chili if using.","images":[],"step":10}]', '["fish","gluten","soy"]', '["high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Thai-ish"],"categories":["asian-recipes","cuisines","dinner-tonight","fish-recipes","quick-and-easy","salmon-recipes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ac4a42795f42', 'en', 'US', 'Massaman Curry', 'Recipe video above. Not the fastest recipe in the world, but worth it! Rich and beautifully fragrant with the signature hint of smokiness, this mild curry is one of the most popular Thai curries ever. While many restaurants tend to tone down the spices and substantially increase the sugar, this recipe is based on authentic versions by Thai food authorities including David Thompson and Sujet Saenkham of Spice I Am. Super easy to adapt to other proteins - see notes! STORE BOUGHT CURRY PASTE version - see bottom of recipe', 'https://www.recipetineats.com/tachyon/2018/08/Massaman-Curry_3.jpg', 30, 120, 150, 4, '[{"id": "ing_lemongrass", "quantity": {"value": 20.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 6.0, "unit": "pack of 100g"}}, {"id": "ing_onion", "quantity": {"value": 4.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 8.333, "unit": "pack of 3 heads"}}, {"id": "ing_galangal", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_water", "quantity": {"value": 4.0, "unit": "L"}}, {"id": "ing_round_clove", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_cumin", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_round_nutmeg", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 0.075, "unit": "bunch"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cinnamon", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_beef", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_cinnamon_quill", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_star_anise", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_tamarind_paste_puree", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_peanuts", "quantity": {"value": 0.113, "unit": "jar"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 lemongrass (Note 1)","6 dried red Asian chillis (not Thai! Note 2)","4 eschallots (, peeled (Note 3))","5 cloves garlic (, unpeeled)","3 cm / 2.25\" galangal piece (, peeled, cut into 3/4 cm / 1/2\" slices (Note 4))","4 - 6 tbsp water"],"purpose":"Spice Paste:"},{"ingredients":["1/2 tsp ground cloves","3/4 tsp cumin","1/8 tsp ground nutmeg","3/4 tsp coriander","1/2 tsp cardamom","1/2 tsp cinnamon"],"purpose":"Spice Paste Dried Spices:"},{"ingredients":["700 g / 1.4lb beef chuck (, cut into 4cm / 2.5\" cubes (Note 5))","500 ml / 2 cups beef broth (, low sodium)","2 bay leaves"],"purpose":"Beef:"},{"ingredients":["1/4 cup / 65 ml vegetable oil","400 ml / 14 oz coconut milk (full fat, 1 can)","1 cinnamon quill","1 star anise","1 tsp tamarind paste/puree (Note 6)","1 tbsp fish sauce","1 tbsp white sugar","2 medium-small potatoes (, peeled and cut into 2.5cm / 1\" pieces)"],"purpose":"Curry Sauce:"},{"ingredients":["3 tbsp peanuts (, roughly chopped)","Finely sliced red chilli (optional)","Asian fried shallots (optional, Note 7)","Steamed jasmine rice"],"purpose":"Garnish & serving:"}]', '[{"description":"Lemongrass (see video):","images":[],"step":1},{"description":"Remove reedy outer layers and trim lemongrass per Note 1.","images":[],"step":2},{"description":"Reserve all the trimmings (for beef). Finely chop the white part (for paste.","images":[],"step":3},{"description":"Place Beef ingredients in a medium saucepan. Liquid should almost cover beef but not completely - if not, add water.","images":[],"step":4},{"description":"Add lemongrass trimmings.","images":[],"step":5},{"description":"Bring to boil over high heat, then reduce heat and simmer gently for 1.5 - 2 hours until beef is fork tender.","images":[],"step":6},{"description":"Remove beef. If there''s much more than 1.5 cups liquid, simmer to reduce. Set liquid aside.","images":[],"step":7},{"description":"Char Aromatics (char = flavour!):","images":[],"step":8},{"description":"Place heavy based skillet over high heat until smoking (no oil).","images":[],"step":9},{"description":"Add eschalot, garlic and galangal in skillet. Get a nice char on them, then remove (~1.5 minutes).","images":[],"step":10},{"description":"Add dried chillies into skillet, char 10 seconds or so on each side until charred, then remove.","images":[],"step":11},{"title":"Once cool enough to handle","description":"Grate galangal. Peel garlic. Break chillies in half, shake out seeds and discard.","images":[],"step":12},{"description":"Spice Paste Dried Spices:","images":[],"step":13},{"description":"Wipe the skillet used above or use a clean one. Heat on medium heat, add Spice Paste Dried Spices. Toast for 30 seconds or until they start to smell fragrant - do not let them burn. Immediately transfer into bowl.","duration":0.5,"images":[],"step":14},{"description":"Place chillies in food processor. (Note 8) Blitz until finely chopped.","images":[],"step":15},{"description":"Add galangal, finely chopped lemongrass, the toasted Spice Paste Dried Spices, and remaining Spice Paste ingredients, starting with 4 tbsp water. Blitz until smooth - add more water if required.","images":[],"step":16},{"description":"Place oil in a pot or large skillet over medium high heat. Add curry paste and cook for 3 minutes until the liquid has cooked out and it''s thick and fragrant.","duration":3,"images":[],"step":17},{"description":"Add coconut milk, stir to incorporate.","images":[],"step":18},{"description":"Add cinnamon, star anise and reserved beef braising liquid. Reduce heat to medium and simmer for 3 minutes.","duration":3,"images":[],"step":19},{"description":"Stir in fish sauce, tamarind and sugar, stir.","images":[],"step":20},{"description":"Add potatoes and cook for 7 minutes or until potatoes are tender, turning as required.","duration":7,"images":[],"step":21},{"description":"Add beef and simmer for 2 minutes or until sauce has reduced and thickened.","duration":2,"images":[],"step":22},{"title":"Adjust","description":"saltiness with fish sauce, sour with tamarind and sweet with sugar. The taste should be sweet, salty and sour, with more emphasis on the sweet and sour notes. Top up with a little water if the curry seems too thick","images":[],"step":23},{"description":"Serve over jasmine rice, garnished with peanuts (essential!) plus optional crispy Asian shallots and fresh chillies.","images":[],"step":24}]', '["fish"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","beef-recipes","cuisines","curry-recipes","iconic-dishes","main-dishes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8c05ae3b1308', 'en', 'US', 'Char Kway Teow', 'Recipe video above. Epic Malaysian street food favourite - made at home! Use the Base Recipe if you''re a capable cook with a powerful gas stove and a good cast iron wok or large heavy based skillet. Otherwise, I recommend using the Easier Method.', 'https://www.recipetineats.com/tachyon/2018/07/Char-Kway-Teow_6.jpg', 15, 5, 20, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_lard", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_shrimp", "quantity": {"value": 10.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_sausages", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 2.5, "unit": "bag of 250g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.1, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy", "quantity": {"value": 5.0, "unit": "unit"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.1, "unit": "bottle of 250ml"}}]', '[{"ingredients":["500 g / 1 lb fresh wide rice noodle (Note 1)","2 tbsp lard (, or vegetable oil (Note 2))","2 tbsp vegetable oil (, separated)","10 small prawns/shrimp (, shelled and deveined)","2 garlic cloves (, finely chopped)","1 Chinese sausage / Lup Chong Sausage (, sliced thinly on the diagonal (Note 3))","5 cm / 2\" piece of fried fish cake (, sliced thinly (Note 4))","20 stems garlic chives (, cut into 4 pieces (Note 5))","2 1/2 cups bean sprouts","2 eggs (, whisked)"]},{"ingredients":["5 tsp dark soy sauce (Note 6)","4 tsp light soy (Note 6)","2 tsp oyster sauce (Note 6)","4 tsp kecap manis / sweet soy sauce (Note 6)"],"purpose":"Sauce:"}]', '[{"description":"Mix Sauce together.","images":[],"step":1},{"description":"Do not attempt to pull noodles apart while cold and hard - they break.","images":[],"step":2},{"description":"Place whole packet in microwave, heat on high for 1 1/2 minutes - 2 minutes until warm and pliable, not hot, turning packet over as needed.","images":[],"step":3},{"description":"Handle carefully and measure out 500g/1 lb noodles into a heatproof bowl. Separate noodles stuck together.","images":[],"step":4},{"description":"If noodles become cold and brittle before cooking, cover with cling wrap and microwave for 30 seconds to make warm (not hot, just warm) to reduce breakage.","duration":0.5,"images":[],"step":5},{"description":"Cook using Base Recipe (capable cooks) or Easier Method.","images":[],"step":6},{"title":"Cooking","description":"BASE Recipe:","images":[],"step":7},{"description":"Heat lard and 1 tbsp oil in a wok or very large heavy based skillet over high heat. Swirl around the wok.","images":[],"step":8},{"description":"When it starts smoking, add prawns. Cook for 30 seconds.","duration":0.5,"images":[],"step":9},{"description":"Add garlic, stir for 10 seconds.","duration":0.16666666666666666,"images":[],"step":10},{"description":"Add noodles, then using both hands on the handle, toss 4 times until coated with oil (or gently fold using a spatula + wooden spoon, see video).","images":[],"step":11},{"description":"Add Chinese sausage and fish cake, toss or gently fold 4 times.","images":[],"step":12},{"description":"Add bean sprouts and garlic chives, toss or gently fold 6 times.","images":[],"step":13},{"description":"Push everything to one side, add remaining 1 tbsp oil. Add egg and cook, moving it around until mostly set - about 1 minute. Use wooden spoon to chop it up roughly.","images":[],"step":14},{"description":"Pour Sauce over noodles, then toss to disperse Sauce through the noodles. Pause between tosses to give the noodles a chance to caramelise on the edges.","images":[],"step":15},{"description":"Serve immediately!","images":[],"step":16},{"title":"Cooking","description":"EASIER Method:","images":[],"step":17},{"description":"Heat 1 tbsp oil in a large non stick skillet over high heat.","images":[],"step":18},{"description":"When heated, add shrimp and cook for 1 1/2 minutes until just cooked through, then remove into bowl","images":[],"step":19},{"description":"Add Chinese sausage and fish cake, and cook for 1 minute until sausage is caramelised, then add to bowl.","duration":1,"images":[],"step":20},{"description":"Add 1 tbsp oil then add egg and cook, pushing in the edges to make a thick omelette. Once set, chop it up roughly using a wooden spoon (see video), then add to bowl.","images":[],"step":21},{"description":"Add bean sprouts and cook for about 1 minute until just starting to wilt, then add to bowl.","images":[],"step":22},{"description":"Add lard. Once melted and starting to smoke, add garlic then immediately add noodles. Fold gently 4 times using a spatula + wooden spoon (see video) just to disperse oil through noodles.","images":[],"step":23},{"description":"Tip all the other ingredients back in plus the chives. Fold gently twice, then pour all the Sauce over.","images":[],"step":24},{"description":"Gently toss 4 to 6 times to disperse the sauce, pausing in between to allow the noodles to have a chance to caramelise on the edges a bit.","images":[],"step":25},{"description":"Remove from stove and serve immediately.","images":[],"step":26}]', '["egg","fish","gluten","shellfish","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Malaysian"],"categories":["asian-recipes","asian-takeout","iconic-dishes","noodles","prawns-shrimp"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bbdd82be973f', 'en', 'US', 'San Choy Bow (Chinese Lettuce Wraps)', 'Recipe video above. One of my favourite starters at Chinese restaurants, the ultimate (almost) carb free healthy dish of all time! It all comes down to the Sauce - with a great Sauce, you can change up the filling to your taste. I''ve copied the filling served by Chinese restaurants but feel free to substitute with other vegetables or make it entirely meat free (this is a great recipe to make vegetarian).', 'https://www.recipetineats.com/tachyon/2017/02/Lettuce-Wraps-2.jpg', 15, 5, 20, 3, '[{"id": "ing_cornstarch", "quantity": {"value": 0.016, "unit": "pack of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_corn", "quantity": {"value": 5.0, "unit": "can of 400g"}}, {"id": "ing_mushroom", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 160.0, "unit": "head"}}, {"id": "ing_peanuts", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 1/4 tsp cornflour / cornstarch","3 tbsp water, (separated)","1 1/2 tbsp light soy sauce (Note 1)","1 tsp dark soy sauce (Note 1)","2 tbsp oyster sauce","1 tsp sesame oil","2 tbsp Chinese cooking wine (or sub Mirin or dry sherry, Note 2)","1 tsp white sugar (can omit)"],"purpose":"Sauce"},{"ingredients":["1 tbsp peanut oil","1 clove large garlic, (minced)","1/2 tsp ginger, (minced)","300g / 10oz pork mince (ground pork) (Note 3)","1/2 onion, (finely chopped)","1 small carrot, (finely chopped)","100g/ 3.5oz canned water chestnuts, (drained and finely chopped (Note 4))","5 baby corn, (canned or fresh, finely chopped (Note 4))","5 mushrooms, (finely chopped(shiitake is best, I used Swiss Brown))"],"purpose":"Filling (Note 6)"},{"ingredients":["8 leaves large or 16 - 20 small lettuce, preferably soft (Note 5)","Crushed peanuts","Finely sliced scallions / shallots"],"purpose":"Serving"}]', '[{"description":"Mix cornflour with 1 tbsp water until lump free. Then add remaining Sauce ingredients and mix.","images":[],"step":1},{"description":"Heat oil in a wok or large skillet over high heat. Add garlic and ginger, give it a quick stir then add onion.","images":[],"step":2},{"description":"Cook for 1 minute then add pork. Cook pork until it turns white.","duration":1,"images":[],"step":3},{"description":"Add all the vegetables. Cook for 2 minutes until the carrot is softened and pork is cooked through.","duration":2,"images":[],"step":4},{"description":"Add Sauce and cook for 1 1/2 minutes or until it thickens and glossy, coating the Filling.","images":[],"step":5},{"description":"Transfer Filling into serving bowl. Lay out lettuce leaves, peanuts and scallions on the side.","images":[],"step":6},{"description":"To serve, spoon some Filling into a lettuce leaf. Top with peanuts and scallions, bundle it up and enjoy!","images":[],"step":7}]', '["gluten","peanuts","sesame","soy"]', '["low_calorie"]', '{"mealType":["snack","dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chicken-mince-recipes","chicken-recipes","chinese-recipes","dietary","dinner-tonight","low-calorie-recipes","main-dishes","pork-recipes","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_aeeea4463c87', 'en', 'US', 'Chinese dumplings (Potstickers!)', 'Recipe video above. Time to get your dumpling game on! Don''t fret about perfect pleats - if it''s all too hard, just press the seams together without pleating, plenty of Chinese restaurants do this. This recipe has a pork and cabbage filling, which is traditional and common. After a Vegetable filling? Here it is!', 'https://www.recipetineats.com/tachyon/2018/03/Potstickers_6a.jpg', 30, 25, 55, 30, '[{"id": "ing_shiitake_mushrooms", "quantity": {"value": 5.0, "unit": "pack of 150g"}}, {"id": "ing_cabbage", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_wine", "quantity": {"value": 0.01, "unit": "bottle of 750ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_round_dumpling_wrappers", "quantity": {"value": 30.0, "unit": "unit"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 4.0, "unit": "L"}}]', '[{"ingredients":["5 - 6 dried shiitake mushrooms (Note 1)","1 ½ cups finely chopped Chinese cabbage (Napa cabbage)","½ tsp salt","250 g / 0.5 lb fatty pork mince (20 - 30% fat ideal - Note 2)","¼ cup garlic chives (, finely chopped*)","2 tsp light soy sauce (light or dark soy also ok)","1 1/2 tsp Chinese wine (Note 4)","½ tsp sesame oil*","¼ tsp white pepper (black also ok)","1 garlic clove (, minced)","½ tsp grated fresh ginger*"]},{"ingredients":["30 - 35 round dumpling wrappers (Note 5)","1/2 cup water per batch","4 - 6 tsp vegetable oil"],"purpose":"To cook:"}]', '[{"title":"Shiitake Mushroom","description":"Place the mushrooms in a bowl and pour over plenty of boiled water. Leave for 20 minutes or until rehydrated. Squeeze out excess water, then finely chop.","duration":20,"images":[],"step":1},{"title":"Cabbage","description":"Place cabbage in a bowl with salt. Toss with fingers, then set aside for 15 minutes. Squeeze out excess liquid from cabbage using hands.","duration":15,"images":[],"step":2},{"title":"Filling","description":"Place cabbage, mushrooms and remaining Filling ingredients in a bowl. Mix with your hands until well combined.","images":[],"step":3},{"description":"Make Dumplings (watch video + see photos in post):","images":[],"step":4},{"description":"Peel one wrapper off and place on the palm of your left hand (if right handed). Dip your finger in water and run it along half the edge of the wrapper.","images":[],"step":5},{"description":"Place 1 heaped tablespoon of Filling in the centre. Fold wrapper over, then pleat to seal. Alternatively, just press together with no pleats.","images":[],"step":6},{"description":"Finish so the dumpling is curved slightly, see photos in post, with the pleats on the top.","images":[],"step":7},{"description":"Place on tray. Cover with cling wrap or wet tea towel (important). Repeat with remaining dumplings. Should make 30, if yours are extremely plump you may only make 25.","images":[],"step":8},{"description":"Cooking:","images":[],"step":9},{"description":"Make sure your pan has a lid that fits it half decently (Note 6).","images":[],"step":10},{"description":"Heat 2 tsp oil in a non stick pan over medium high heat. Add dumplings, pressing down firmly to flatten the base onto the pan. Cook around 8 to 10 per batch.","images":[],"step":11},{"description":"When the base is golden brown (check them), add 1/2 cup of water into the pan.","images":[],"step":12},{"description":"Immediately clamp the lid on, then leave for 7 minutes (any less and the pleats won''t be cooked through so if your water dries out, add a bit more).","duration":7,"images":[],"step":13},{"title":"Remove lid","description":"most of the water should be evaporated, the pleats should be cooked through. Leave the pan on the stove until the base dries and the underside of the dumplings are once again crisp.","images":[],"step":14},{"description":"Remove dumplings from pan and transfer to serving plate. Repeat with remaining Dumplings.","images":[],"step":15},{"description":"Serve with Dipping Sauces of choice. (Note 7)","images":[],"step":16}]', '["gluten","sesame","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","dumplings","iconic-dishes","pork-recipes","yum-cha-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3d463492b257', 'en', 'US', 'Thai Red Curry with Chicken', 'Recipe VIDEO above. A Thai Red Curry with Chicken is one of the world''s most popular curries! Make this with store bought curry paste (we give it a freshness boost) OR homemade red curry paste (the fresh flavour can''t be beaten!). SPICE Level: Mild to hot BUT if using store bought paste, depends on what brand you use (Note 5).', 'https://www.recipetineats.com/tachyon/2018/02/Thai-Red-Curry-Chicken-1.jpg', 5, 20, 25, 4, '[{"id": "ing_thai_red_curry_paste", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_quantity_homemade_thai_red_curry_paste", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 666.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_lemongrass", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_lime", "quantity": {"value": 6.0, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_pumpkin", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_green_beans", "quantity": {"value": 120.0, "unit": "pack"}}, {"id": "ing_basil", "quantity": {"value": 12.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["5 - 6 tbsp Thai Red Curry Paste (store bought, Maesri best) (Note 1)","1 quantity homemade Thai Red Curry Paste"],"purpose":"Red Curry Paste – choose ONE:"},{"ingredients":["2 large garlic cloves (, minced)","2 tsp fresh ginger (, finely grated )","1 tbsp lemongrass paste (or finely chopped fresh (Note 3))"],"purpose":"Extras – only for jar curry paste (Note 2)"},{"ingredients":["3 tbsp vegetable oil (or canola or peanut)","1 cup (250 ml) chicken broth/stock (, low sodium)","400 ml / 14 oz coconut milk (full fat!)","6 kaffir lime leaves (Note 4)","1 tbsp sugar (white, brown or palm)","2 tsp fish sauce (, plus more to taste)","350g / 12 oz chicken thighs (boneless and skinless), cut into 0.75 / 1/3\" thick slices (Note 5)","150g / 5 oz pumpkin or butternut squash, ( cut into 1.5cm / 3/5\" cubes (~1 heaped cup))","120g / 4oz green beans (, trimmed and cut into 5cm/2\" pieces)","12 Thai basil leaves (Note 6)"],"purpose":"Thai Red Curry"},{"ingredients":["Fresh red chilli slices (small chilli - spicy, large = less spicy)","Fresh coriander / cilantro leaves","Steamed jasmine rice"],"purpose":"Garnishes (optional) & serving:"}]', '[{"description":"Heat oil in a large heavy based skillet over medium high heat.","images":[],"step":1},{"description":"Add curry paste and Extras (if using jar paste) and cook for about 2 minutes so it \"dries out\" (See video)","images":[],"step":2},{"description":"Add chicken broth and stir to dissolve paste. Simmer rapidly for 3 minutes or until liquid reduces by half.","duration":3,"images":[],"step":3},{"description":"Add coconut milk, lime leaves, sugar and fish sauce. Stir, then add chicken.","images":[],"step":4},{"description":"Spread chicken out, bring to simmer, then turn heat down to medium. Simmer for about 8- 10 minutes or until Sauce reduces, the chicken is cooked and the sauce is almost at the thickness you want.","images":[],"step":5},{"description":"Do a taste test. Add more fish sauce (or even shrimp paste) to add more saltiness, sugar for sweetness.","images":[],"step":6},{"description":"Add pumpkin and beans, stir. Cook for 3 minutes or until pumpkin is just cooked through and Sauce is thickened - see video for Sauce thickness.","duration":3,"images":[],"step":7},{"description":"Remove from heat. Stir through a handful of Thai basil leaves.","images":[],"step":8},{"description":"Serve over jasmine rice, garnished with fresh red chilli slices and fresh coriander/cilantro leaves, if desired.","images":[],"step":9}]', '["fish","peanuts"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","cuisines","curry-recipes","dietary","gluten-free-recipes","iconic-dishes","main-dishes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3001269a9630', 'en', 'US', 'Sesame Crusted Salmon', 'Recipe VIDEO above. Just roll salmon in sesame seeds and bake - you''ll be amazed how well it sticks! Served over soba and Asian greens with a fabulous Asian dressing, this is a great quick salmon recipe.', 'https://www.recipetineats.com/tachyon/2018/02/Sesame-Crusted-Salmon_3.jpg', 5, 15, 20, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.75, "unit": "pack of 100g"}}, {"id": "ing_oil", "quantity": {"value": 20.0, "unit": "bottle"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_es_baby_buk_choi", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_mirin", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}]', '[{"ingredients":["4 x 150-200g / 5-7 oz skinless boneless salmon or trout fillets (Note 1)","Salt and pepper","75g/ 1/2 cup white sesame seeds","4 tsp vegetable or canola oil (or other neutral oil, not olive oil)","Sliced shallots / scallions (, optional garnish)"]},{"ingredients":["250 g / 8 oz dried soba noodles (Note 2)","2 bunches baby buk choi (, or other greens of choice (Note 3))"],"purpose":"Soba and greens:"},{"ingredients":["1 1/2 tbsp soy sauce (, light or ordinary (Note 4))","2 1/2 tbsp vegetable or canola oil (or other neutral oil, not olive)","3 tbsp rice vinegar (Note 2)","1 tbsp Mirin (Note 2)","2 tsp sugar (any, I use white)","2 tsp fresh ginger (, minced)","1 clove garlic (, minced)"],"purpose":"Asian Dressing:"}]', '[{"description":"Take salmon out of fridge 20 minutes before cooking.","images":[],"step":1},{"description":"Preheat oven to 220C/430F (standard) or 200C/390F (fan). Place shelf about 20cm/8\" from the broiler heat source at the top of the oven.","images":[],"step":2},{"description":"Sprinkle both sides of the salmon with salt and pepper.","images":[],"step":3},{"description":"Place sesame in shallow dish. Press salmon into sesame seeds to coat on all sides. Place on tray.","images":[],"step":4},{"description":"Drizzle top with oil.","images":[],"step":5},{"title":"Bake for 10 minutes. Flick to broiler on high","description":"broil / grill for 3 minutes until the top is a bit golden (or bake for 5 minutes, but won''t be as golden). (Note 5)","duration":10,"images":[],"step":6},{"description":"Remove from oven, rest 3 minutes. Serve with soba and greens, garnished with scallions (optional) and drizzled with Dressing.","images":[],"step":7},{"description":"Soba and greens:","images":[],"step":8},{"description":"Bring a large pot of water to the boil.","images":[],"step":9},{"description":"Cook soba per packet directions. Add greens for the last 1 minute of cooking.","images":[],"step":10},{"description":"Drain then divide between bowls.","images":[],"step":11},{"description":"Place ingredients in jar and shake. Set aside for 5 minutes.","duration":5,"images":[],"step":12}]', '["fish","gluten","sesame","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Asian influence"],"categories":["asian-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_04c12d065cdc', 'en', 'US', 'Thai Chicken Salad', 'Recipe VIDEO above. A chicken salad with a fantastic Thai chilli lime dressing with a great tangy-sweet-salty-spicy balance that South East Asian food is known for. Using Chilli Garlic Sauce is a great way to thicken dressing as well as adding more layers of flavour. Serves 2 as a main, 4 as a side.', 'https://www.recipetineats.com/tachyon/2017/11/Thai-Chicken-Salad-1.jpg', 15, 20, 35, 2, '[{"id": "ing_chicken_breast", "quantity": {"value": 180.0, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 0.25, "unit": "pack of 1kg"}}, {"id": "ing_chilli", "quantity": {"value": 5.0, "unit": "pack of 100g"}}, {"id": "ing_roasted_cashews", "quantity": {"value": 75.0, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 5.0, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 2.5, "unit": "pack of 3 heads"}}, {"id": "ing_lime", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}]', '[{"ingredients":["180 - 220 g / 6 -7oz chicken breast"]},{"ingredients":["150 g / 5 oz mixed lettuce leaves (or other of choice)","1 cup cherry or grape tomatoes (, halved)","1 small cucumber (, sliced)","1/4 red onion (, finely sliced)","1/2 large red chilli (, deseeded and very finely sliced (Note 1))","1/2 cup roasted cashews (, unsalted preferred)","1/4 cup coriander / cilantro leaves"],"purpose":"Salad:"},{"ingredients":["1 tbsp finely chopped coriander/cilantro stems (see video)","1 1/2 tsp Chilli Garlic Sauce (Note 2)","1 small garlic (, minced)","1 1/2 tbsp fresh lime juice (or rice vinegar)","2 tsp fish sauce (Note 3)","1 tbsp canola oil (or vegetable, grapeseed or other neutral oil)","1 1/2 tsp sugar (any, I use white)"],"purpose":"Thai Chilli Lime Dressing:"}]', '[{"description":"Take the chicken out of the fridge 30 minutes before cooking.","images":[],"step":1},{"description":"Boil water in a saucepan. Add chicken, put the lid on, let the water come back up to a simmer, then remove from stove. Set aside for 20 minutes (even up to 45 min is fine). (Note 4)","duration":20,"images":[],"step":2},{"description":"Remove chicken from water and shred, then cool.","images":[],"step":3},{"description":"Place ingredients in a jar. Shake well. Taste and adjust as required. It should be a balance of tangy / sweet / salty / hint of spice. (Note 5)","images":[],"step":4},{"description":"Place Salad ingredients in a large bowl. Drizzle over most of the Dressing, toss. Serve immediately, drizzled with remaining Dressing.","images":[],"step":5}]', '["fish"]', '["gluten_free"]', '{"mealType":["dinner","lunch"],"cuisine":["Thai"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","cuisines","dietary","dinner-tonight","gluten-free-recipes","low-calorie-recipes","main-dishes","quick-and-easy","salad-recipes-main-course","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_47e0d48a8e4a', 'en', 'US', 'Thai Meatballs', 'Recipe video above. The beautiful, fresh Thai flavour in these meatballs are amazing! Truly like something you''d get at those posh Thai restaurants. These aren''t authentic Thai, as far as I know there really aren''t meatballs in Thai cuisine (at least, not like this, they have them in soups), but all the flavourings in this are real-deal-Thai.', 'https://www.recipetineats.com/tachyon/2017/10/Thai-Meatballs.jpg', 20, 25, 45, 4, '[{"id": "ing_pork_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_lemongrass", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_lime", "quantity": {"value": 3.0, "unit": "net of 500g"}}, {"id": "ing_chilli", "quantity": {"value": 3.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 0.141, "unit": "loaf"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_chilli", "quantity": {"value": 3.0, "unit": "pack of 100g"}}, {"id": "ing_lime", "quantity": {"value": 3.0, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["500 g / 1 lb pork mince (ground pork, or chicken)","1 tbsp lemongrass paste (or finely chopped fresh) (Note 1)","1 tsp grated ginger","3 cloves garlic (, minced)","3 kaffir lime leaves, stem removed and very finely shredded, optional extra (Note 2)","3 Thai or birds eye chillies (, seeds removed and finely chopped (Note 3))","1/4 cup coriander/cilantro (, leaves and stem finely chopped (Note 4))","1 tsp sugar (any)","1 tbsp fish sauce (can sub with soy sauce if required)","3/4 cup panko breadcrumbs (+ extra 1/4 cup if needed)","1 small egg","Oil spray"],"purpose":"Meatballs:"},{"ingredients":["1/2 cup / 125 ml sweet chilli sauce (, store bought (Note 5))","1 garlic clove (, minced)","2 tbsp lime juice (, plus more to taste)"],"purpose":"Sweet Chilli Dipping Sauce:"},{"ingredients":["Coriander/cilantro leaves (, finely sliced large red chillies)","Steamed jasmine rice"],"purpose":"Optional garnishes & serving:"}]', '[{"description":"Preheat oven to 220C/430F (standard) or 200C/390F (fan / convection).","images":[],"step":1},{"description":"Place a rack on a tray (optional, rack keeps balls slightly rounder).","images":[],"step":2},{"description":"Place Meatball ingredients in a bowl (except oil spray), mix well with your hands. Only use extra breadcrumbs if necessary - sometimes, chicken mince can be quite wet. Scoop up 1 slightly heaped tablespoon and roll into a ball (about 3cm / 1.25\" diameter). (Note 6 for my way)","images":[],"step":3},{"description":"Spray rack well with oil and place the meatballs on the rack.","images":[],"step":4},{"description":"Spray meatballs generously with oil, then bake for 20 - 25 minutes or until a bit browned. They should be beautifully soft - see video!","duration":22.5,"images":[],"step":5},{"description":"Serve warm with Sauce, garnished with coriander and chillies if desired.","images":[],"step":6},{"description":"Place ingredients in a bowl and mix. Set aside for at least 10 minutes before using.","images":[],"step":7}]', '["egg","fish","gluten","soy"]', '[]', '{"mealType":["dinner","snack"],"cuisine":["Thai"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-mince-recipes","chicken-recipes","cuisines","finger-food","meatball-recipes","pork-recipes","super-bowl-party-food","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_20b1481b67eb', 'en', 'US', 'Vietnamese Coconut Caramel Chicken', 'The chicken version of the wildly popular Vietnamese Caramel Pork! It''s saucier and made with coconut milk so it has a gorgeous coconut fragrance. It''s sweet with savoury undertones, looks thoroughly unimpressive while cooking but then magically transforms in the last 5 minutes. Recipe VIDEO below.', 'https://www.recipetineats.com/tachyon/2017/10/Vietnamese-Coconut-Caramel-Chicken.jpg', 5, 55, 60, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.15, "unit": "bottle of 250ml"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 10.0, "unit": "pack of 100g"}}]', '[{"ingredients":["4 large / 5 small chicken thighs (, bone in skin on (Note 1))","1/2 cup / 80 g brown sugar (, loosely packed)","1 tbsp water","400 g / 14 oz coconut milk (, low fat (1 can) (Note 2))","1 1/2 tbsp fish sauce (Note 3)","2 1/2 tbsp rice vinegar (or cider vinegar)","2 garlic cloves (, minced)","1 eschallot / French onion (, finely sliced (Note 4))","1/4 tsp white pepper (or black)"]},{"ingredients":["1 shallot (, finely sliced (green onion / scallion))","1 large red chilli (, finely sliced)"],"purpose":"Garnishes (optional):"}]', '[{"description":"Place sugar and water in a skillet over medium heat. Stir, then when it bubbles and the sugar is melted (it looks like caramel), add the rest of the ingredients except chicken.","images":[],"step":1},{"description":"Stir, then put the chicken in SKIN SIDE DOWN.","images":[],"step":2},{"description":"Adjust the heat so it is simmering energetically. Not rapidly, not a slow simmer (I use medium high heat on a weak stove, medium on a strong stove).","images":[],"step":3},{"description":"After 25 minutes, turn the chicken.","images":[],"step":4},{"description":"After another 25 minutes, the fat should separate from the sauce and turn a pale brown (see video).","images":[],"step":5},{"description":"Turn chicken so the skin side is down. Move it around so the sauce doesn''t catch on the bottom of the skillet and to brown the skin.","images":[],"step":6},{"description":"Once sauce and skin is brown, remove from heat.","images":[],"step":7},{"description":"Place chicken on serving plates, spoon over some sauce (don''t need much, chicken is infused with flavour + sauce is strong).","images":[],"step":8},{"description":"Garnish with shallots and chilli, if using. Serve with rice.","images":[],"step":9}]', '["fish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","quick-and-easy","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e4dad176b9ea', 'en', 'US', 'Vietnamese Caramel Pork', 'Recipe VIDEO above. "Thit Kho To" - Tender pork in a sweet savoury glaze that has quite an intense flavour. Though made using coconut water as the broth, but it doesn''t have a coconut flavour at all! It looks so unimpressive right up until the end when it magically transforms into sticky caramelised pork pieces!', 'https://www.recipetineats.com/tachyon/2017/10/Vietnamese-Caramel-Pork_-4.jpg', 10, 90, 100, 4, '[{"id": "ing_brown_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_pork_shoulder", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1/2 cup / 100g brown sugar, tightly packed","1 tbsp water","1 kg / 2 lb pork shoulder (butt) or boneless skinless pork belly, cut into 3 cm / 1.2\" pieces (Note 1a)","1.5 cups / 375 ml coconut water (Note 1b)","1 eschallot / shallot (, very finely sliced (Note 2))","2 garlic cloves (, minced)","1 1/2 tbsp fish sauce","1/4 tsp white pepper"]},{"ingredients":["Red chilli and finely sliced shallots/green onions"],"purpose":"Garnishes:"}]', '[{"description":"Place sugar and water in a large pot over medium heat. Stir, then when it bubbles and the sugar is melted (it looks like caramel), add the rest of the ingredients.","images":[],"step":1},{"description":"Stir, then adjust the heat so it is simmering fairly energetically. Not rapidly, not a slow simmer (I use medium heat on a weak stove, between medium and low on a strong stove).","images":[],"step":2},{"description":"Simmer for 1.5 hours, uncovered. Stir once or twice while cooking.","images":[],"step":3},{"description":"At around 1.5 hours, when the liquid has reduced down and the pork is tender, (see Note 3 if pork is not yet tender), the fat will separate (see video).","images":[],"step":4},{"description":"Stir and the pork will brown and caramelise in the fat.","images":[],"step":5},{"description":"Once the liquid is all gone and it''s now stuck on the pork pieces, it''s ready.","images":[],"step":6},{"description":"Serve over rice, garnished with fresh chilli and shallots. Simple pickled vegetables are ideal for a side because the fresh acidity pairs well with the rich pork.","images":[],"step":7}]', '["fish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["asian-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","pork-recipes","quick-and-easy","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_44febe8729e9', 'en', 'US', 'Quick Satay Peanut Stir Fry (any protein)', 'VIDEO below. A gem of a recipe given to me by a reader, this is a brilliant QUICK Satay Stir Fry that tastes like Chinese style satay that you get from Chinese restaurants here in Australia. Make this with your choice of protein - great with beef (pictured), chicken, pork, shrimp or tofu. Use shredded shaped vegetables - ideal for this sauce which is not the saucy type.', 'https://www.recipetineats.com/tachyon/2017/07/Quick-Satay-Stir-Fry.jpg', 10, 7, 17, 3, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.06, "unit": "jar of 375g"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_beef", "quantity": {"value": 300.0, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 75.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.5, "unit": "bunch"}}, {"id": "ing_peanuts", "quantity": {"value": 0.094, "unit": "jar"}}]', '[{"ingredients":["1 1/2 tbsp fish sauce (Note 1)","1 1/2 tsp sugar","2 tsp cornflour / cornstarch","1 garlic clove (, minced)","1 tsp grated ginger","1 tsp curry powder (any - I use hot!)","1 1/2 tbsp crunchy peanut butter (smooth also ok)","2 tbsp water"],"purpose":"Sauce:"},{"ingredients":["300 - 350 g / 10 - 12 oz beef (, chicken or pork thinly sliced (or peeled prawns/shrimp) (Note 2))","2 tbsp oil","1 garlic (, finely chopped (Note 3))","1 large onion (, sliced)","1 large carrot (, julienned (Note 4))","1 big handful bean sprouts (~1 1/2 cups packed)","1/2 cup finely sliced shallots / green onions (plus more for garnish)","1/4 cup crushed peanuts (, plus more for garnish (optional))"],"purpose":"Stir Fry:"}]', '[{"description":"Mix Sauce ingredients EXCEPT WATER together in a small bowl. Then mix in water (easier to combine).","images":[],"step":1},{"description":"Place beef in a bowl, add 1 tbsp Sauce. Mix, set aside 10 minutes.","images":[],"step":2},{"description":"Heat oil in a wok or large heavy based skillet over high heat. Add garlic and stir until golden (~10 sec) then add onion. Cook for 1 minute.","duration":1,"images":[],"step":3},{"description":"Add beef. Cook for 1 1/2 minutes or until it mostly turns brown (some red spots ok). If using pork, chicken or prawns, cook until almost cooked through.","images":[],"step":4},{"description":"Add carrots, bean sprouts and Sauce. Cook until veggies are wilted.","images":[],"step":5},{"description":"Add peanuts and shallots, stir.","images":[],"step":6},{"description":"Serve immediately with rice or noodles, garnished with extra shallots and peanuts if desired. (For a low carb, low cal option, try Cauliflower Rice!)","images":[],"step":7}]', '["fish","peanuts","shellfish"]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","beef-recipes","chicken-breast-recipes","chicken-recipes","chinese-recipes","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5a26e2bb87e7', 'en', 'US', 'Teriyaki Chicken Meatballs', 'Recipe video above. Soft, plump, juicy meatballs smothered in a homemade Teriyaki sauce! The sauce for this recipe is based my mother''s authentic Teriyaki Chicken recipe. Serve these as a meal or pass them around at a party.', 'https://www.recipetineats.com/tachyon/2017/07/Teriyaki-Chicken-Meatballs.jpg', 20, 15, 35, 4, '[{"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.25, "unit": "bottle of 250ml"}}, {"id": "ing_cooking_sake", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_mirin", "quantity": {"value": 0.25, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.18, "unit": "L"}}, {"id": "ing_chicken_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_cooking_sake", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 tbsp cornflour / cornstarch","1/4 cup / 65ml soy sauce (, all purpose / ordinary (Note 1))","1/4 cup / 65ml cooking sake (, or sub with Chinese cooking wine or dry sherry (Note 2))","1/4 cup / 65ml Mirin (Note 2)","1 tbsp white sugar (brown also ok)","¾ cup / 180 ml water"],"purpose":"Teriyaki Sauce:"},{"ingredients":["500 g / 1 lb chicken mince (ground chicken) (or pork or turkey)","1 egg (preferably small 50g / 1.4 oz)","1 cup panko breadcrumbs (or ¾ cup normal breadcrumbs)","1 garlic clove (, minced)","1 ½ tsp cooking sake (, or sub with Chinese cooking wine or dry sherry (Note 2))","½ tsp salt"],"purpose":"Meatballs:"},{"ingredients":["1 tbsp oil","Sliced green onions / scallions (, for garnish (optional))","Sesame seeds (, for garnish (optional))"],"purpose":"Cooking:"}]', '[{"description":"Place Meatball ingredients in a bowl.","images":[],"step":1},{"description":"Place cornflour in a bowl with 1 tbsp of the water, then mix until lump free. Then add the soy sauce, sake, mirin and sugar, mix.","images":[],"step":2},{"description":"Add 2 tsp of Teriyaki Sauce into the Meatball bowl.","images":[],"step":3},{"description":"Add remaining water into the Sauce and mix. Set aside.","images":[],"step":4},{"description":"Mix Meatball mixture with your hands. Measure out 1 heaped tablespoon and roll into balls. See Note 3 for tips if mixture is too sticky.","images":[],"step":5},{"description":"Heat oil in a large skillet over medium high heat. Add all the meatballs and cook, rolling to brown all over, for 5 minutes. They will still be a bit raw inside.","duration":5,"images":[],"step":6},{"description":"Turn heat down. Give the Sauce a quick mix then add it into the pan. Bring to a simmer then cook for 2 - 3 minutes or until it thickens into a glossy sauce that coats the meatballs.","duration":2.5,"images":[],"step":7},{"description":"Serve over rice, garnished with green onions and sesame seeds if desired.","images":[],"step":8}]', '["egg","gluten","sesame","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Asian","Japanese","Western"],"categories":["asian-recipes","chicken-mince-recipes","chicken-recipes","dinner-tonight","main-dishes","meatball-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1769dff5dbb3', 'en', 'US', 'Chinese BBQ Chicken', 'The marinade for this chicken is based on the famous Chinese BBQ Pork (Char Siu), a very popular recipe on my blog! It’s sweet, savoury, sticky, laced with Chinese Five Spice. Add your own touch like ginger and chilli for a kick! The red food colouring is optional – it gives the chicken the reddish tinge that Char Siu is known for. Recipe VIDEO below, MARINATING TIME: 3 - 24 hrs.', 'https://www.recipetineats.com/tachyon/2017/06/Chinese-BBQ-Chicken-2.jpg', 5, 20, 25, 4, '[{"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_honey", "quantity": {"value": 0.045, "unit": "jar of 500g"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_few_drops_red_food_colouring", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_skewers", "quantity": {"value": 10.0, "unit": "pack of 50"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 garlic cloves (, minced)","2 tsp brown sugar","1 1/2 tbsp honey","1 1/2 tbsp hoisin sauce","2 tsp oyster sauce","1 ½ tbsp light soy sauce (or all purpose)","1/2 tsp Chinese five spice powder (Note 1)","1/2 tsp sesame oil (not critical)","Few drops red food colouring (, optional)"],"purpose":"Marinade:"},{"ingredients":["750 g / 1.5lb chicken thigh fillets (, skinless boneless (or breast))","1 tbsp vegetable oil","10 – 12 bamboo skewers (, soaked in water for 1 hour (optional))","Green onions / scallions (, finely sliced, for garnish (optional))"],"purpose":"Chicken:"}]', '[{"description":"Place Marinade ingredients in a ziplock bag or bowl and mix to combine.","images":[],"step":1},{"title":"Add chicken and mix to coat. Marinade for 3","description":"24 hours.","images":[],"step":2},{"title":"Optional","description":"Cut chicken into bite size or large pieces and thread onto skewers. Use 1 skewer for small pieces, 2 for large, like pictured in post.","images":[],"step":3},{"description":"Heat half the oil in a heavy based skillet over medium high heat, or BBQ on medium (if using grill side, brush oil on bars).","images":[],"step":4},{"description":"Remove chicken from marinade (RESERVE for basting) and place in the skillet - cook in 2 batches, don''t crowd the pan. Cook for 4 minutes then turn.","duration":4,"images":[],"step":5},{"description":"Use the Marinade to baste the cooked side of the chicken. After 3 minutes, turn the chicken over so the basted side is now cooking again - cook for 1 minute.","duration":1,"images":[],"step":6},{"description":"Baste the chicken, then turn again and cook for 45 sec - 1 min.","duration":0.75,"images":[],"step":7},{"description":"Transfer chicken to a plate, cover loosely with foil and rest for 5 minutes.","duration":5,"images":[],"step":8},{"description":"Serve, garnished with green onions / scallions if using!","images":[],"step":9}]', '["gluten","sesame","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","chinese-recipes","grilling-ideas-and-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b0e6e7ac26e5', 'en', 'US', 'Thai Coconut Marinated Chicken', 'Recipe video above. Chicken infused in a gorgeous Thai coconut marinade which infuses with flavour and adds buttery richness from the coconut milk. MARINATING TIME: 24 - 48 hours.', 'https://www.recipetineats.com/tachyon/2017/05/Thai-Coconut-Marinated-Chicken-4.jpg', 15, 10, 25, 5, '[{"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_lemongrass", "quantity": {"value": 20.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_turmeric", "quantity": {"value": 0.007, "unit": "jar"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.469, "unit": "can of 400ml"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.04, "unit": "jar of 375g"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_ime_juice", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 0.045, "unit": "net of 500g"}}]', '[{"ingredients":["1 tsp garlic (, minced)","1 tsp ginger (, minced)","1 tsp chilli (, finely chopped (or paste is fine), adjust quantity to taste (Note 2))","1 lemongrass (OR paste) (, white part only, finely chopped(Note 3))","1 1/2 tsp coriander powder","3/4 tsp tumeric powder","1/2 tsp curry powder (any is fine)","1 tbsp brown sugar","2 1/2 tbsp fish sauce (sub soy)","3/4 cup coconut milk (full fat please!)"],"purpose":"Marinade (Note 1):"},{"ingredients":["750 g - 1 kg / 1.5 - 2 lb chicken thigh fillets (, skinless and boneless (Note 4))","Oil for cooking"],"purpose":"Chicken:"},{"ingredients":["1/2 cup coconut milk","1 tbsp peanut butter, smooth","2 tbsp Hoisin Sauce","1 1/2 tbsp lime juice","1 garlic clove (, minced)","1/2 tsp chilli paste or fresh chilli (, adjust to taste)"],"purpose":"Coconut Peanut Sauce:"},{"ingredients":["Finely chopped coriander / cilantro and more chilli (, for garnish)","Lime wedges (highly recommended)"],"purpose":"Garnish (optional):"}]', '[{"description":"Mix marinade in a large bowl. Add chicken and mix. Cover with cling wrap and marinate in the fridge for 24 - 48 hours (can''t skip marinating for this recipe).","images":[],"step":1},{"description":"Brush BBQ with oil, or heat 1 tbsp in a skillet (I used a skillet). Use Medium heat - or Medium Low if your stove/BBQ runs hot (otherwise marinade may burn).","images":[],"step":2},{"description":"Remove chicken from marinade, shaking off excess. Cook the first side for around 5 minutes or until caramelised and golden. Turn then cook the other side for 4 minutes until caramelised.","duration":4,"images":[],"step":3},{"title":"BAKING","description":"See Note 4.","images":[],"step":4},{"description":"Transfer chicken to serving plate, cover loosely with foil and rest for 5 minutes. Garnish with coriander / chilli if desired, and serve with lime wedges and Sauce.","duration":5,"images":[],"step":5},{"description":"Place ingredients in a bowl and mix a bit. Microwave for 30 seconds, then mix until smooth. Bring to room temperature or serve warm (it thickens a bit when cooled).","duration":0.5,"images":[],"step":6}]', '["fish","peanuts","soy"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","cuisines","dietary","gluten-free-recipes","grilling-ideas-and-recipes","quick-and-easy","thai-recipes","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5a34a1ade631', 'en', 'US', 'Sticky Chicken Drumsticks in Chinese Plum Sauce', 'A fantastic one for midweek and a crowd pleaser! These sticky chicken drumsticks are baked in the oven until tender, and basted with an incredible Chinese plum sauce which is sweet with a touch of tang and the beautiful fragrance of plum. See notes for skipping the marinating time!', 'https://www.recipetineats.com/tachyon/2017/02/Sticky-Baked-Chicken-Drumsticks-in-Plum-Sauce-4.jpg', 5, 50, 55, 4, '[{"id": "ing_chicken", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_fountain_plum_sauce", "quantity": {"value": 112.5, "unit": "bottle"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.25, "unit": "bottle of 250ml"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1.2kg / 2.4lb large chicken drumsticks (8 drumsticks)"]},{"ingredients":["3/4 cup / 185ml Fountain Plum Sauce (Note 1)","1/3 cup brown sugar (can reduce to 1/4 cup)","1/4 cup soy sauce (all purpose or light, not dark soy sauce)","2 tbsp Hoisin Sauce","2 cloves garlic, (minced)","1/2 tsp ginger, (minced)","1/2 tsp Chinese Five Spice Powder (Note 2)"],"purpose":"Plum Marinade / Glaze"},{"ingredients":["Sesame seeds","Finely chopped scallions"],"purpose":"Garnish (optional)"}]', '[{"description":"Place Marinade ingredients in a ziplock bag (or bowl) and mix. Add chicken and massage to coat in the Marinade. Refrigerate for 1 hour (see Note 3 for skipping this).","images":[],"step":1},{"description":"Preheat oven to 180C/350F (all types).","images":[],"step":2},{"description":"Line a tray with baking paper / parchment paper (or foil then spray with oil).","images":[],"step":3},{"description":"Transfer chicken to tray, shaking off excess marinade. RESERVE Marinade.","images":[],"step":4},{"title":"Baking & Basting (Total bake time","description":"50 min)","images":[],"step":5},{"description":"Bake chicken for 20 minutes.","duration":20,"images":[],"step":6},{"description":"Remove from oven. Spoon / slather / brush with reserve marinade (generously!) (Note 4). Bake for 10 minutes.","duration":10,"images":[],"step":7},{"description":"Remove from oven and TURN chicken. Baste again using tray juices and reserved marinade. Bake for 10 minutes.","duration":10,"images":[],"step":8},{"description":"Remove from oven and baste again (very generously!) using tray juices and reserved marinade. Bake for 10 minutes.","duration":10,"images":[],"step":9},{"description":"Remove chicken from oven and scrape/brush tray juices onto chicken (don''t waste free flavour!).","images":[],"step":10},{"description":"Sprinkle with sesame seeds and shallots/scallions if using. I served it with rice and steamed broccolini.","images":[],"step":11}]', '["gluten","sesame","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Asian-esque"],"categories":["asian-recipes","chicken-drumstick-recipes","chicken-recipes","dinner-tonight","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_39ecd939f19a', 'en', 'US', 'Chinese Satay Chicken Stir Fry', '{Video below} My homemade copycat of the Chinese takeout favourite - chicken satay stir fry! The coconut and peanut flavour is not as intense as Malaysian and Thai satay sauce, and the satay seasoning flavour is stronger. The chicken is tenderised the way Chinese restaurants do - perfect to make breast nice and juicy. This step is optional, but I think it''s worth it for a true Chinese restaurant experience! MARINATING TIME: 20 minutes for tenderising, 10 minutes for seasoning, both optional.', 'https://www.recipetineats.com/tachyon/2017/02/Chicken-in-Satay-Sauce-3.jpg', 15, 5, 20, 2, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.227, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.019, "unit": "tub of 200g"}}, {"id": "ing_coriander", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_turmeric", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_chilli", "quantity": {"value": 0.013, "unit": "pack of 100g"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.06, "unit": "jar of 375g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_sriracha", "quantity": {"value": 0.025, "unit": "bottle of 400ml"}}, {"id": "ing_lemongrass", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.208, "unit": "can of 400ml"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["8 oz / 250g chicken breast","3/4 tsp baking soda (bi carb soda) (optional)"],"purpose":"Tenderised Chicken, optional (Note 5)"},{"ingredients":["1/2 tsp coriander powder","1/2 tsp cumin powder","1/4 tsp turmeric powder","1/4 tsp chilli powder (Not US Chilli powder! See Note 1)","1 1/2 tsp Curry Powder (Note 2)","1/2 tsp salt","1/4 tsp white pepper"],"purpose":"Satay Seasoning"},{"ingredients":["1 1/2 tbsp smooth peanut butter","2 tsp brown sugar","1 tsp light soy sauce (Note 3)","2 tsp rice vinegar","2 tsp Sriracha (or other hot sauce)","1/2 tsp lemongrass paste (Note 4)","1/3 cup coconut milk (full fat)","1/4 cup water"],"purpose":"Satay Sauce"},{"ingredients":["1 tbsp peanut oil (or other plain oil)","1 onion (, finely chopped)","2 garlic cloves (, minced)","Shallots/scallions (, sliced (optional garnish))"],"purpose":"Stir Fry"}]', '[{"description":"Tenderise Chicken (optional)","images":[],"step":1},{"description":"Cut chicken in half length wise then slice thinly. Place in a bowl with baking soda, use fingers to coat. Set aside for 20 minutes.","duration":20,"images":[],"step":2},{"description":"Rinse well, pat dry with paper towel then place in a bowl.","images":[],"step":3},{"description":"Seasoning","images":[],"step":4},{"description":"Mix together Seasoning.","images":[],"step":5},{"description":"Sprinkle 1 tsp of Seasoning over chicken. Mix to coat then set aside for 10 minutes (not critical, can skip this).","duration":10,"images":[],"step":6},{"description":"Place all ingredients except water in a bowl. Add remaining Seasoning. Mix, then add water and mix.","images":[],"step":7},{"description":"Heat oil in wok or skillet over high heat. Add onion and garlic, stir fry for 1 minute.","duration":1,"images":[],"step":8},{"description":"Add chicken and stir fry for 2 minutes until just cooked through and a bit browned.","duration":2,"images":[],"step":9},{"description":"Lower heat slightly, then add Sauce. Stir fry until it reduce down and becomes thicker - 1 to 1 1/2 minutes.","images":[],"step":10},{"title":"Serve immediately with rice","description":"or for a low carb, low cal option, try Cauliflower Rice! Garnish with sliced shallots/scallions if desired.","images":[],"step":11}]', '["gluten","peanuts","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","chinese-recipes","dinner-tonight","main-dishes","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bc482fdc5f3e', 'en', 'US', 'Chinese Steamed Fish with Ginger Shallot Sauce', 'Steamed Chinese Fish with a Ginger and Shallot Sauce! Love the drama as the hot oil is poured over the fresh ginger and shallots, cooking it and creating the gorgeous sauce. This recipe is one of those true treasures that are simple yet taste so incredible, and it''s healthy too! The fish can be steamed or baked - refer photos in post or video below recipe.', 'https://www.recipetineats.com/tachyon/2016/11/Chinese-Fish-Ginger-Shallot-Sauce-9.jpg', 5, 15, 20, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_ginger", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_japanese_cooking_sake", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_salt", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_oil", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["2 x 350 - 400g / 12 - 13 oz bream or snapper fish (, gutted, scaled and cleaned (Note 1))","2 stems of shallots ((scallions / green onions), diagonally julienned to 5cm/2\" length)","4 x 3cm / 1 x 2\" piece of ginger julienned","2 tbsp Japanese cooking sake (Note 2)","2 pinches of salt","3 tsp soy sauce (Note 3)","2 tsp sesame oil","4 tbsp oil (vegetable, canola or peanut oil)"]},{"ingredients":["Red chilli julienned (Note 4)"],"purpose":"Garnish (optional)"}]', '[{"description":"Cut 2 slashes on each side of the fish. Cut through to the bone.","images":[],"step":1},{"description":"Drizzle 1 tbsp of sake onto each fish.","images":[],"step":2},{"description":"Steam fish using method of choice, or bake (see directions below).","images":[],"step":3},{"description":"Meanwhile, heat oil over medium high heat until hot.","images":[],"step":4},{"description":"Transfer fish onto serving plates. Top with shallots and ginger.","images":[],"step":5},{"description":"Sprinkle with salt, drizzle over soy sauce and sesame oil.","images":[],"step":6},{"title":"Pour oil over fish","description":"enjoy the drama as it bubbles!","images":[],"step":7},{"description":"Sprinkle with red chilli if using and serve with rice and steamed Asian Greens.","images":[],"step":8},{"description":"Bamboo steamers in wok (see video)","images":[],"step":9},{"description":"Place fish on a plate and put plate in bamboo steamer. Repeat with other fish. Stack bamboo steamers and put lid on.","images":[],"step":10},{"description":"Fill wok with water, ensuring it doesn''t touch the bottom of the steamer. Bring water to boil over high heat, then place bamboo steamer on wok.","images":[],"step":11},{"description":"Steam for 10 minutes. Carefully transfer fish onto serving places.","duration":10,"images":[],"step":12},{"description":"Wrap each fish in foil, place on tray. Bake at 180C/350F for 15 minutes. Open foil and carefully transfer fish onto serving plates.","duration":15,"images":[],"step":13},{"description":"Steamer fitted inside a large pot, or a microwave steamer.","images":[],"step":14}]', '["fish","gluten","peanuts","sesame","soy"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","chinese-recipes","dietary","dinner-tonight","fish-recipes","gluten-free-recipes","main-dishes","seafood-recipes","yum-cha-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d07ba27a9a33', 'en', 'US', 'Foolproof Poached Chicken with Ginger Shallot Sauce', 'A foolproof method for poaching chicken breast with guaranteed juicy chicken every single time. Served with a Ginger Shallot (Scallion) Sauce that is so good, you will want to put it on everything! Also accompanied with a quick chilli sauce (optional). This is like a (much) faster, healthier midweek version of the famous Hainanese Chicken & Rice. Also see cooking video below recipe - don''t miss the Dozer cameo at the end! HIGH ALTITUDE locations - please see note 4', 'https://www.recipetineats.com/tachyon/2016/10/Foolproof-Poached-Chicken-Ginger-Shallot-Sauce-2.jpg', 10, 25, 35, 3, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_ginger", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_sriracha", "quantity": {"value": 0.037, "unit": "bottle of 400ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}]', '[{"ingredients":["2 chicken breasts (, boneless skinless, 250g/8.5 oz each (Note 1))"]},{"ingredients":["3 - 4 shallots / scallions (, green and white part thinly sliced (1 heaped cup))","2 tbsp finely grated ginger","1/4 tsp salt","5 tbsp vegetable oil (or peanut or grapeseed oil)"],"purpose":"Ginger Shallot Sauce"},{"ingredients":["1 tbsp chilli paste","1 tbsp Sriracha","1 tsp soy sauce","1 tsp sugar","1 garlic clove","1 tsp grated ginger"],"purpose":"Quick Chilli Sauce"}]', '[{"description":"Take chicken out of the fridge 30 minutes before cooking.","images":[],"step":1},{"description":"Fill a saucepan with water so the chicken breast will be well submerged with at least 2\" / 5cm of water above it.","images":[],"step":2},{"description":"Bring water to boil. Place chicken breast in water, place lid on, bring back up to the boil. Remove saucepan from stove and set aside for 20 minutes (it''s fine up to 45 min, won''t overcook).","duration":20,"images":[],"step":3},{"description":"Remove chicken from water and slice. Serve with Sauces (below) and rice.","images":[],"step":4},{"description":"Ginger Shallot Sauce","images":[],"step":5},{"description":"Combine and mix ingredients in a bowl. Set side for 20 minutes. It will sweat and become more liquidy.","duration":20,"images":[],"step":6},{"description":"Mix ingredients in a bowl. Set aside for 15 minutes.","duration":15,"images":[],"step":7}]', '["gluten","peanuts","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","chinese-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f29906a3807d', 'en', 'US', 'Sweet and Sour Chicken Stir Fry', 'This bright and colourful stir fry is made with a classic Sweet & Sour Sauce which is truly like what you get at good Chinese restaurants. This is not made by deep frying the chicken - it''s tasty enough as it is without adding more calories!! Also see Baked version of the fried Sweet & Sour Chicken - recipe here. I know 1/2 cup of sugar sounds like a lot, but it works out at 1 1/2 tbsp per serving, which isn''t too bad!', 'https://www.recipetineats.com/tachyon/2016/09/Sweet-and-Sour-Chicken-Stir-Fry-8.jpg', 10, 10, 20, 4, '[{"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.167, "unit": "bottle of 500ml"}}, {"id": "ing_pineapple", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_ketchup", "quantity": {"value": 0.09, "unit": "bottle of 500g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_pineapple", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1/2 cup white sugar (Note 1)","1/3 cup apple cider vinegar","3 tbsp pineapple juice (from the canned pineapple pieces)","3 tbsp ketchup (Australia: tomato sauce)","1 tsp Worcestershire sauce (Note 2)","1 tsp soy sauce (, light or all purpose (Note 2))","1 tsp Oyster Sauce (Note 2)","1/4 tsp salt"],"purpose":"Sauce"},{"ingredients":["1 tbsp cornflour / corn starch + 2 tbsp water (, mixed together)"],"purpose":"Thickener"},{"ingredients":["1 1/2 tbsp peanut oil (or vegetable)","1 garlic clove (, minced or finely chopped)","1 onion (, halved and sliced (brown, yellow or white) (see photo in post))","400 g / 13 oz chicken thigh fillets (, cut into bite size pieces (Note 3))","1 red capsicum / bell pepper (, cut into bite size pieces)","1 green or yellow capsicum / bell pepper (, cut into bite size pieces)","1 can ((8oz/250g) canned pineapple pieces in natural juice. Separate pineapple from juice.)","Sliced shallots / scallions (, for garnish)"],"purpose":"Stir Fry"}]', '[{"description":"Mix together Sauce ingredients. Mix together Thickener in a separate small bowl.","images":[],"step":1},{"description":"Heat oil in a wok or skillet over high heat. Add garlic and onion, cook for 1 minute.","duration":1,"images":[],"step":2},{"description":"Add chicken and stir fry until it it is white all over but still pink inside.","images":[],"step":3},{"description":"Add capsicum and stir fry for 2 minutes.","duration":2,"images":[],"step":4},{"description":"Add Sauce ingredients. Stir until sugar has dissolved and the sauce begins to bubble.","images":[],"step":5},{"description":"Add Thickener. Bring to simmer, stirring constantly. Then cook until it thickens to a syrup consistency - about 3 minutes.","images":[],"step":6},{"description":"Stir through pineapple pieces (just to warm) and remove from stove.","images":[],"step":7},{"title":"Serve immediately with rice","description":"or for a low carb, low cal option, try Cauliflower Rice! Garnish with shallots if desired.","images":[],"step":8}]', '["gluten","peanuts","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","chinese-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","most-popular","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_242962313501', 'en', 'US', 'Asian Chicken (Asian marinade)', 'A great all rounder Asian Marinade that infuses chicken with sweet/savoury flavours. This Asian chicken can be grilled, baked or cooked on the stove! MINIMUM MARINADE TIME: 1 hour (or overnight)', 'https://www.recipetineats.com/tachyon/2016/06/Asian-Marinated-Chicken_Hero.jpg', 10, 10, 20, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.045, "unit": "bottle of 500ml"}}, {"id": "ing_sriracha", "quantity": {"value": 1.0, "unit": "bottle of 400ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.01, "unit": "pack of 100g"}}, {"id": "ing_oil", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 - 1.5 lb / 500 - 750g chicken thigh fillets (, skinless boneless)"]},{"ingredients":["3 cloves garlic (, minced)","2 tsp ginger (, freshly grated)","2 tbsp soy sauce","2 tbsp tomato ketchup","2 tbsp Oyster sauce","1 1/2 tbsp Chinese cooking wine OR Mirin (Note 1)","1 - 3 tbsp Sriracha (adjust spiciness to taste)","2 tbsp brown sugar","1 tsp sesame oil"],"purpose":"Asian Marinade (see notes for subs)"},{"ingredients":["2 tsp oil","Sesame seeds","Finely sliced shallots / green onions","Finely sliced red chilies"],"purpose":"Cooking / Garnishes (optional)"}]', '[{"description":"Mix Marinade ingredients together. Add chicken and mix to coat. Marinade in the fridge for a minimum of 1 hour or up to overnight.","images":[],"step":1},{"description":"Heat oil in a large non stick skillet or BBQ over medium high heat. (See notes for other cooking methods) Add chicken and cook until each side is dark golden brown and chicken is cooked through (about 3 minutes each side). Transfer to plate, cover loosely with foil and rest for 3 minutes.","duration":3,"images":[],"step":2},{"description":"Garnish with chillies, shallots and sesame seeds if desired. Serve with white rice and slices of cucumber.","images":[],"step":3}]', '["gluten","sesame","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b4e91c0f7a18', 'en', 'US', 'Chinese Fried Rice with Shrimp / Prawns', 'This is a simple, traditional Chinese Fried Rice recipe by Kylie Kwong, Australia''s most well known Chinese Chef. The key to an authentic tasting fried rice like you get at proper Chinese restaurants is the Sauce, using day old or cold fresh cooked rice and ensuring you don''t overcrowd the wok, causing the rice to stew instead of stir fry! Feel free to add more vegetables (not too much otherwise the sauce will thin out) or substitute the prawns with other proteins.', 'https://www.recipetineats.com/tachyon/2016/05/Chinese-Fried-Rice_2.jpg', 10, 10, 20, 3, '[{"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_bacon", "quantity": {"value": 0.562, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_shrimp", "quantity": {"value": 0.142, "unit": "kg"}}, {"id": "ing_white_rice", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.025, "unit": "pack of 100g"}}]', '[{"ingredients":["3 tbsp peanut oil ((or vegetable), separated)","2 eggs (, lightly beaten)","3/4 cup bacon (, excess fat trimmed, chopped (or 1/2 cup Chinese Sausage) (Note 1))","2 garlic cloves (, minced)","3 tsp ginger (, minced or very finely chopped)","1/2 onion (, finely chopped (about 3/4 cup) (brown, white or yellow))","1 tbsp Chinese cooking wine or dry sherry (or sake, Japanese cooking wine) (Note 2)","1/2 tsp sugar","5 oz/150g small shrimp/prawns (, cooked and peeled (Note 3))","3 cups cooked long grain white rice (, refrigerated overnight (Note 4))","3 scallions (, thinly sliced)"]},{"ingredients":["1 tbsp Oyster Sauce","1 1/2 tbsp soy sauce (all purpose or light) (Note 3)","1/2 tsp sesame oil (roasted - i.e. dark colour)"],"purpose":"Sauce"}]', '[{"description":"Mix together Sauce ingredients, set aside.","images":[],"step":1},{"description":"Heat 1 tbsp oil in a wok (or heavy based skillet/fry pan) over medium heat. Add eggs and cook until scrambled, then remove onto plate.","images":[],"step":2},{"description":"Increase heat to high and add bacon. Cook until golden, then remove onto plate with egg - about 2 minutes.","images":[],"step":3},{"description":"Drain off excess bacon fat.","images":[],"step":4},{"description":"Add remaining 2 tbsp oil, garlic and ginger. (Note 5) Return wok to stove on high heat. Stir fry as it comes up to heat, don’t let it burn. When garlic starts to sizzle, add onion and stir fry for 2 minutes until golden.","duration":2,"images":[],"step":5},{"description":"Add Chinese wine and sugar and let it simmer rapidly, stirring, for 20 seconds, until mostly evaporated.","duration":0.3333333333333333,"images":[],"step":6},{"description":"Add prawns/shrimp and stir fry for 1 minute to heat through (if pre-cooked, cook longer to cook if raw).","duration":1,"images":[],"step":7},{"description":"Add rice, Sauce, eggs, bacon and all but 2 tbsp of shallots/scallions. Stir fry for 2 minutes until rice is hot - around 2 minutes.","duration":2,"images":[],"step":8},{"description":"Transfer to serving plate, sprinkle with remaining scallions and serve.","images":[],"step":9}]', '["egg","gluten","peanuts","sesame","shellfish","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","dietary","dinner-tonight","fried-rice","gluten-free-recipes","main-dishes","prawns-shrimp","quick-and-easy","rice-recipes","rice-side-dishes","side-dishes","yum-cha-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_01f73ac4f487', 'en', 'US', 'Thai Mango Chicken Curry', 'The secrets to making a GREAT curry using store bought curry paste are: saute the paste with onion, garlic and chilli, simmer the sauce with kaffir lime leaves (KEY TIP!) and using fish sauce for seasoning. This curry is made using mango puree which is a miracle way to make a thick saucy curry but with 1/3 less calories than just using coconut milk (mangoes have 1/5th of the calories of coconut milk!). Read more in Note 2. If you don''t have mangoes, you can make this with just coconut milk which is just as tasty but has more calories - see Note 3.', 'https://www.recipetineats.com/tachyon/2016/02/Mango-Thai-Red-Curry-with-Chicken_2.jpg', 15, 20, 35, 3, '[{"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.5, "unit": "pack of 100g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.544, "unit": "kg"}}, {"id": "ing_thai_red_curry_paste", "quantity": {"value": 4.0, "unit": "bottle"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.544, "unit": "kg"}}, {"id": "ing_mango", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.544, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_chilli", "quantity": {"value": 0.5, "unit": "pack of 100g"}}]', '[{"ingredients":["1 tbsp oil (vegetable, canola, grape seed)","3 garlic cloves (, minced)","1/2 tsp ginger (, minced (not critical))","1/2 - 1 tsp red chilli (, minced (Optional. I used 1 tsp.))","1 small onion (, sliced (brown, white, yellow) or 3 eschallots)","1.2 lb / 600g chicken thigh fillets ((or breast), cut into bite size pieces)","4 - 5 tbsp Thai Red Curry Paste (Note 1)","1 can (400ml/13oz) coconut milk (full fat is better but low fat is ok too)","3/4 cup chicken broth","1 cup mango puree (, preferably fresh (1 large mango) (Note 2))","1 tbsp fish sauce","2 kaffir lime leaves"]},{"ingredients":["Steamed jasmine rice","Coriander/cilantro leaves","Lime wedges","Fresh red chili (, sliced)"],"purpose":"To Serve"}]', '[{"description":"Heat oil in a skillet over medium high heat.","images":[],"step":1},{"description":"Add garlic, ginger, chilli (if using) and onion and saute until the onion is starting to soften.","images":[],"step":2},{"description":"Add chicken and cook until white all over but still raw inside.","images":[],"step":3},{"description":"Add curry paste and saute for 2 minutes until fragrant.","duration":2,"images":[],"step":4},{"description":"Add coconut milk and chicken broth. Bring to simmer, stirring to dissolve the curry paste into the liquid. Then add the mango, fish sauce and kaffir lime leaves.","images":[],"step":5},{"title":"Turn heat down to medium and simmer for 12","description":"15 minutes, stirring occasionally, until the sauce is thickened. Adjust saltiness using fish sauce.","duration":13.5,"images":[],"step":6},{"description":"Serve over jasmine rice, garnished with coriander/cilantro, wedges of lime and slices of red chilli, if desired.","images":[],"step":7}]', '["fish"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","cuisines","curry-recipes","dietary","gluten-free-recipes","main-dishes","most-popular","thai-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8746b85a91e6', 'en', 'US', 'Easy Chinese Honey Sesame Chicken', 'Crispy oven baked chicken chicken with a sesame crust tossed in a sticky sauce. Really easy and absolutely irresistible! If you can''t find sesame paste or tahini, substitute with peanut butter. Seriously! (Refer to Note 2)', 'https://www.recipetineats.com/tachyon/2016/02/Chinese-Honey-Sesame-Chicken_3.jpg', 10, 20, 30, 3, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.225, "unit": "pack of 100g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.225, "unit": "pack of 100g"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_honey", "quantity": {"value": 0.105, "unit": "jar of 500g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.225, "unit": "pack of 100g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.056, "unit": "pack of 400g"}}, {"id": "ing_oil", "quantity": {"value": 0.04, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 lb / 500g chicken thighs (, cut into 1.2cm/ 1/2\" slices (Note 1))","1/2 tsp salt","2 tsp sesame paste OR tahini (Note 2)","2 tsp soy sauce","1 1/2 tbsp sesame seeds (, toasted)","1/2 cup plain flour","Oil spray"],"purpose":"Chicken"},{"ingredients":["1 tbsp Chinese cooking wine (Shaoshing / Shaoxing wine) or sherry (or use chicken broth/stock)","3/4 cup chicken broth / stock","1 tsp rice wine vinegar or Chinese black vinegar (or ordinary white vinegar)","3 1/2 tbsp honey","1 1/2 tbsp soy sauce (, all purpose ordinary (Note 3))","2 tsp sesame oil"],"purpose":"Sauce"},{"ingredients":["1 1/2 tbsp cornstarch / cornflour mixed with 2 tbsp water"],"purpose":"Cornstarch"},{"ingredients":["2 tsp oil (vegetable, canola, peanut)","2 garlic cloves (, minced)"],"purpose":"To Cook"},{"ingredients":["1 scallion/shallot stem (, sliced)","1 1/2 tbsp sesame seeds (, toasted)"],"purpose":"Garnish"}]', '[{"description":"Preheat oven to 200C/430F with shelf placed on the highest level. Spray baking tray with oil.","images":[],"step":1},{"description":"Mix sesame paste and soy sauce in a bowl (to loosen it up, easier to coat chicken). Add chicken, salt and sesame seeds.","images":[],"step":2},{"description":"Place flour in a separate bowl and coat chicken in flour, shaking off excess. Place chicken on baking tray.","images":[],"step":3},{"description":"Bake for 12 minutes. Remove from oven.","duration":12,"images":[],"step":4},{"description":"Flick to broiler/grill as high as it will go with shelf about 15cm/6\" from the heat source.","images":[],"step":5},{"description":"Turn chicken. Broiler/grill for 5 minutes until golden and quite crispy (Note 4), then remove.","duration":5,"images":[],"step":6},{"description":"Meanwhile, mix together Sauce in one bowl and Cornstarch in another.","images":[],"step":7},{"description":"Heat oil in a wok or skillet (I used a skillet) over medium heat. Add garlic and cook for 30 seconds until fragrant but not browned.","duration":0.5,"images":[],"step":8},{"description":"Add Sauce and bring to bubble. Add Cornstarch and cook for 30 seconds until it thickens into a thick syrup.","duration":0.5,"images":[],"step":9},{"description":"Remove the Sauce immediately from the stove and pour over the chicken.","images":[],"step":10},{"description":"Toss chicken in Sauce then sprinkle over Sesame Seeds and Shallots/Scallions to serve. Serve with rice.","images":[],"step":11}]', '["gluten","peanuts","sesame","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","chinese-recipes","dinner-tonight","main-dishes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c20ebf4893bf', 'en', 'US', 'Coconut Shrimp / Prawns with Spicy THAI Mango Sauce', 'Crunchy coconut shrimp / prawns with a spicy Thai inspired Mango Sauce! These are shallow fried, not deep fried and the prawns cook VERY fast. These reheat really well! Refer to Note 6 for make ahead instructions. I made the sauce using Keitt mangoes because I think the slight tang is perfect for this recipe, but you can use any mangoes you want.', 'https://www.recipetineats.com/tachyon/2016/02/Coconut-Shrimp-Mango-Sauce_2.jpg', 20, 10, 30, 4, '[{"id": "ing_shrimp", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_bread", "quantity": {"value": 0.094, "unit": "loaf"}}, {"id": "ing_desiccated_coconut", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_mango", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_onion", "quantity": {"value": 30.0, "unit": "pack of 1kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_sriracha", "quantity": {"value": 0.037, "unit": "bottle of 400ml"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 2.0, "unit": "can of 400ml"}}]', '[{"ingredients":["1 lb / 500 g whole prawns OR 12oz/350g peeled fresh prawns (Note 1)","1/4 tsp salt","Black pepper","1 egg","1/2 cup panko breadcrumbs","1/2 cup desiccated coconut (Note 2)","Oil (, for frying)"],"purpose":"Shrimp / Prawns"},{"ingredients":["1 cup (packed) fresh mango. roughly diced","2 tbsp cilantro/coriander (, leaves and stems, roughly chopped)","2 tbsp red onion or eschallots (, finely chopped)","1 tbsp fish sauce (or substitute with light or ordinary soy sauce)","1 tbsp sriracha (Note 3)","1 tsp red chilli (, finely chopped (adjust to taste))","2 - 3 tbsp coconut milk (adjust for desired sauce consistency)"],"purpose":"Mango Sauce"}]', '[{"title":"Mango Sauce","description":"Place ingredients in a small food processor (or blender or use a blender stick). Whizz until smooth. Adjust salt and spice to taste. Use coconut milk to adjust the consistency.","images":[],"step":1},{"description":"Peel and devein the shrimp / prawns. Sprinkle with salt and pepper.","images":[],"step":2},{"description":"Whisk egg in a small bowl. Mix panko and coconut in another bowl.","images":[],"step":3},{"description":"Dip a prawn in the egg mixture then coat with panko. Repeat with remaining prawns.","images":[],"step":4},{"description":"Heat oil in a skillet (Note 4) over medium high heat. Toss in a clotted lump of panko/egg to test for heat - if it sizzles right away and floats to the top, then the oil is hot enough.","images":[],"step":5},{"description":"Working in batches, carefully place prawns in the hot oil. Cook for just 45 seconds (Note 5) until golden brown - start counting when you slide the first prawn in and remove the prawns from the oil in the order that you put them in.","images":[],"step":6},{"description":"Remove onto a paper towel lined tray to drain.","images":[],"step":7},{"description":"Serve warm with Spicy Mango Dipping Sauce!","images":[],"step":8}]', '["egg","fish","gluten","soy"]', '[]', '{"mealType":["snack","dinner"],"cuisine":[],"categories":["asian-recipes","cuisines","deep-fried-recipes","finger-food","most-popular","prawns-shrimp","seafood-recipes","super-bowl-party-food","thai-recipes","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_485d509b3234', 'en', 'US', 'Satay Chicken Noodle Salad', 'Chicken satay tossed in a noodle salad loaded with plenty of veggies with a creamy peanut satay dressing! Serve this warm or at room temperature.', 'https://www.recipetineats.com/tachyon/2016/01/Satay-Chicken-Noodle-Salad_1.jpg', 15, 5, 20, 3, '[{"id": "ing_peanut_butter", "quantity": {"value": 0.003, "unit": "jar of 375g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_sriracha", "quantity": {"value": 0.056, "unit": "bottle of 400ml"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.225, "unit": "can of 400ml"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.567, "unit": "pack of 500g"}}, {"id": "ing_red_cabbage", "quantity": {"value": 6.0, "unit": "head"}}, {"id": "ing_cabbage", "quantity": {"value": 6.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 10.0, "unit": "pack of 100g"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.34, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_peanuts", "quantity": {"value": 0.113, "unit": "jar"}}]', '[{"ingredients":["¼ cup peanut butter (preferably smooth)","1 garlic clove (, minced)","1 tbsp sesame oil","2 tbsp soy sauce","2 tsp brown sugar","1 1/2 tbsp sriracha (, or 2 tsp chili paste/sauce + 2 tsp vinegar)","2 tbsp lime juice","6 tbsp coconut milk (I used low fat)","2 tbsp water","1/4 tsp salt"],"purpose":"Dressing"},{"ingredients":["10 oz/300g fresh egg noodles (Note 1)","2 cups red cabbage (, shredded)","2 cups green cabbage (, shredded)","2 carrots (, finely chopped)","1/4 tsp salt","2 scallion/shallot stems (, finely sliced on the diagonal)","1 large red chilli (not very spicy), deseeded and finely sliced (Note 2)"],"purpose":"Salad"},{"ingredients":["12 oz / 350g chicken breast (, cut in half vertically and thinly sliced)","Salt and pepper","1 1/2 tsp curry powder","2 tsp sweet soy sauce/ kecap manis (Note 3)","1 tbsp cooking oil"],"purpose":"Satay Chicken"},{"ingredients":["3 tbsp peanuts (, roughly chopped)"],"purpose":"Garnish"}]', '[{"description":"Mix dressing ingredients in a bowl until smooth.","images":[],"step":1},{"description":"Prepare noodles according to packet instructions.","images":[],"step":2},{"description":"Place both cabbages and carrots in a bowl, add 1/4 tsp salt, toss to combine and set aside for 5-10 minutes to wilt lightly.","duration":7.5,"images":[],"step":3},{"description":"Place the Satay Chicken ingredients EXCEPT the oil in a bowl and toss to coat.","images":[],"step":4},{"description":"Heat oil in a non stick fry pan over high heat. Add the chicken and cook for 3 minutes until golden, then transfer to a plate.","duration":3,"images":[],"step":5},{"description":"Toss noodles and remaining salad ingredients with chicken and Dressing, then serve. Serve at room temperature or warm.","images":[],"step":6}]', '["egg","gluten","peanuts","sesame","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner","lunch"],"cuisine":[],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","most-popular","noodles"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d078b09c4553', 'en', 'US', 'Honey Sriracha Chicken Skewers', 'Spice Level: MediumJust 5 ingredients is all you need to make a marinade that doubles as a fantastic glaze for these skewers! Just 20 minutes of marinating time required. A great balance of sweet, spicy and savoury.', 'https://www.recipetineats.com/tachyon/2016/01/Honey-Sriracha-Glazed-Chicken-Skewers_1.jpg', 15, 10, 25, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_honey", "quantity": {"value": 0.167, "unit": "jar of 500g"}}, {"id": "ing_mustard", "quantity": {"value": 0.15, "unit": "jar of 200g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.24, "unit": "bottle of 250ml"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_hot_sauce", "quantity": {"value": 2.0, "unit": "bottle of 150ml"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}]', '[{"ingredients":["1.5 lb / 750g lb / 750g chicken thigh fillets (Note 1)"]},{"ingredients":["1/3 cup honey","2 tbsp Dijon mustard (Note 2)","4 tbsp soy sauce","2 garlic cloves (, crushed)","2 - 3 tbsp sriracha OR any other hot sauce ((e.g. Frank''s), adjust amount to your taste)","1/4 tsp salt"],"purpose":"Marinade Glaze"},{"ingredients":["1 1/2 tbsp oil (I used vegetable)"],"purpose":"To cook"}]', '[{"description":"Cut the chicken into 2cm / 4/5\" cubes.","images":[],"step":1},{"description":"Mix Marinade ingredients together in a bowl until smooth.","images":[],"step":2},{"description":"Transfer 4 tablespoons of the Marinade into a small bowl (\"Reserved Marinade\", to use for basting).","images":[],"step":3},{"description":"Add chicken into the bowl with the remaining Marinade. Mix to coat and set aside for 20 minutes to marinade (up to overnight). (Note 3)","duration":20,"images":[],"step":4},{"description":"Thread chicken onto skewers, discard marinade in the bowl. I used 14 small ones about 18cm/7\" long, 4 pieces of chicken on each.","images":[],"step":5},{"description":"Heat oil on a BBQ or skillet over medium heat. Place skewers on the BBQ and cook the first side for 2 1/2 minutes, then turn the skewers.","images":[],"step":6},{"description":"Baste the COOKED side that is now facing up generously with the reserved Reserved Marinade. After 2 1/2 minutes, turn the skewers and quickly baste the other side generously with the Reserved Marinade. Turn immediately. Cook for just a few seconds, then transfer to a plate. (Note 4)","images":[],"step":7},{"description":"Baste the skewers on the plate one more time with the Reserved Marinade, then serve.","images":[],"step":8},{"description":"I served mine with Cilantro/Coriander Lime Rice (Note 5)","images":[],"step":9}]', '["gluten","mustard","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian-syle"],"categories":["asian-recipes","australia-day","chicken-breast-recipes","chicken-recipes","dinner-tonight","grilling-ideas-and-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0b9d90963e47', 'en', 'US', 'Japanese Miso Salmon Side (BBQ or bake)', 'Recipe video below. My mother''s recipe for Miso Marinated Salmon. The flavour infused in the salmon is incredible. An authentic Japanese recipe, make this on the barbecue or even in the oven! You can get all the ingredients for this at Woolworths supermarket in Australia, including the side of salmon.', 'https://www.recipetineats.com/tachyon/2015/12/Miso-Marinated-Salmon-Side_2a.jpg', 10, 5, 15, 5, '[{"id": "ing_salmon_fillets", "quantity": {"value": 1.6, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_miso_paste", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_sake", "quantity": {"value": 25.0, "unit": "bottle"}}, {"id": "ing_mirin", "quantity": {"value": 0.1, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1.6 - 2.4 lb / 0.8 - 1.2kg side of salmon (, skin on (Note 1))","Oil (, for barbecue)"]},{"ingredients":["5 tbsp miso paste (Note 2)","2 tbsp white sugar","1 2/3 tbsp sake (Japanese rice wine)","1 2/3 tbsp mirin (Japanese sweet rice wine)"],"purpose":"Marinade"},{"ingredients":["Sesame seeds","Scallions/shallots (, finely sliced)"],"purpose":"Garnishes"}]', '[{"description":"Mix together the marinade ingredients in a small bowl until smooth.","images":[],"step":1},{"description":"Place the salmon skin side up on a work surface and slather with just under half the marinade.","images":[],"step":2},{"description":"Turn the salmon so it is skin side down onto a large piece of cling wrap. Slather the remaining marinade on the flesh side.","images":[],"step":3},{"description":"Wrap the salmon in cling wrap. Marinade for 24 to 48 hours.","images":[],"step":4},{"description":"Scrape the marinade off (do not rinse with water) and leave the salmon to come to room temperature <- KEY for perfectly cooked salmon.","images":[],"step":5},{"description":"Preheat barbecue plate side on MEDIUM LOW. Leave it to heat up for a good 10 to 15 minutes - another tip for cooking salmon perfectly.","images":[],"step":6},{"description":"Add oil just before cooking. Place the salmon on the BBQ skin side down. Cook for 3 minutes, then use two spatulas to turn it. Cook the flesh side for 2 - 3 minutes or until caramelised, then flip it again so the skin side is down then transfer to a tray.","duration":3,"images":[],"step":7},{"description":"Cover loosely with foil to rest for 5 minutes before serving. It will continue cooking while resting.","duration":5,"images":[],"step":8},{"description":"Garnish with sesame seeds and finely sliced shallots.","images":[],"step":9}]', '["fish","sesame"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Japanese","Modern Asian"],"categories":["asian-recipes","australia-day","dietary","easter-mains-fish-seafood","fish-recipes","gluten-free-recipes","grilling-ideas-and-recipes","modern-asian","quick-and-easy","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a0a97af3fc6c', 'en', 'US', 'Asian Grilled Shrimp / Prawns', 'Whether you make these on your BBQ or in a fry pan, this is a simple but magical combination of ingredients that tastes like something you''d get at a fancy restaurant! Actually, this is a copy of a great dish I had at a restaurant in Sydney called Esther.The nutty flavour of the browned butter pairs perfectly with a drizzle of sweet soy sauce and the freshness of lime. Add a sprinkle of chili for heat! Keep some bread on hand to mop up the glorious juices.', 'https://www.recipetineats.com/tachyon/2015/12/Asian-Barbecue-Prawns_31.jpg', 10, 5, 15, 2, '[{"id": "ing_shrimp", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 0.333, "unit": "block of 250g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.75, "unit": "bottle of 250ml"}}, {"id": "ing_ime", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 lb / 500 g shrimp / prawns (fresh), peeled and deveined (Note 1)","2 garlic cloves (, crushed)","2 tbsp vegetable oil","1/3 cup salted butter (or 1/3 cup unsalted butter + big pinch of salt)","3/4 to 1 tsp tsp sweet soy sauce / kecap manis (Note 2)","1 lime (, large)"]},{"ingredients":["1 red birds eye chilli (, deseeded and finely sliced or chopped)","Cilantro / coriander leaves"],"purpose":"Garnishes (all optional)"}]', '[{"description":"Combine shrimp / prawns, garlic and oil in a small bowl, use your fingers to coat then set aside for 15 minutes.","duration":15,"images":[],"step":1},{"description":"Browned Butter","images":[],"step":2},{"description":"Meanwhile, melt butter in a small silver fry pan or saucepan over medium heat. (Note 3)","images":[],"step":3},{"description":"Heat until it starts to foam, then swirl the pan occasionally to distribute heat evenly.","images":[],"step":4},{"description":"Cook until the butter turns golden, smells nutty and there are brown specks at the bottom (you might need a teaspoon to push the foam aside).","images":[],"step":5},{"description":"Remove from heat immediately. Pour into a jug, leaving behind most of the bitter brown specks (I strained it - because I was making an effort!).","images":[],"step":6},{"description":"Set aside until required.","images":[],"step":7},{"description":"Prawns / Shrimp","images":[],"step":8},{"description":"Heat the BBQ or fry pan over high heat (no oil).","images":[],"step":9},{"description":"Add prawns / shrimp and cook until each side is lightly golden brown, but be sure not to overcook! (Note 4)","images":[],"step":10},{"description":"Serve","images":[],"step":11},{"description":"Place prawns in a bowl. Grate over the zest of a lime, then cut the lime in half and squeeze over about 1 tbsp of lime juice. Drizzle with 1 tbsp of browned butter, toss gently.","images":[],"step":12},{"description":"Transfer to a plate. Drizzle with 2 tbsp of browned butter then lastly, drizzle over kecap manis, using as thin a stream as you can.","images":[],"step":13},{"description":"Serve immediately, garnished with chilli and cilantro/coriander, if using.","images":[],"step":14}]', '["gluten","milk","shellfish","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","australia-day","dinner-tonight","grilling-ideas-and-recipes","main-dishes","modern-asian","most-popular","prawns-shrimp","quick-and-easy","seafood-recipes","side-dishes","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_198a454d0c8a', 'en', 'US', 'Pot Roasted Coconut Chicken', 'Chicken in a fragrant coconut broth with an intensity of flavour that belies the few ingredients this recipe uses! The broth is so good that you will want to drink it straight. And the chicken stays beautifully moist by roasting it in the broth/stock. This is a clean-eating recipe that you would never think of as "clean"!', 'https://www.recipetineats.com/tachyon/2015/11/Fragrant-Coconut-Pot-Roasted-Chicken_1_600px.jpg', 15, 75, 90, 5, '[{"id": "ing_chilli", "quantity": {"value": 20.0, "unit": "pack of 100g"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_chicken", "quantity": {"value": 1.361, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 1.361, "unit": "kg"}}, {"id": "ing_lemongrass", "quantity": {"value": 20.0, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.992, "unit": "can of 400ml"}}, {"id": "ing_potato", "quantity": {"value": 0.8, "unit": "bag of 2kg"}}, {"id": "ing_ime", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.015, "unit": "kg"}}]', '[{"ingredients":["2 long red chilies (Note 1)","1 tsp freshly grated ginger","2 garlic cloves (, crushed)","1 tbsp coconut oil (or substitute with olive oil)","1/2 tsp salt","Black pepper","1 cup finely chopped cilantro/coriander leaves","3 lb /1.6kg whole chicken (, preferably organic/free range)","2 cups / 500 ml chicken broth/stock (preferably reduced salt)","1 lemongrass (, white part only, bruised (Note 2))","2 kaffir lime leaves (Note 3)","14 oz /400ml light coconut milk (1 can)","0.8 lb / 400g baby potatoes (, scrubbed clean)","1 lime","2 tsp coconut sugar (or substitute with brown sugar)","1 tbsp fish sauce"]}]', '[{"description":"Preheat oven to 390F/200C.","images":[],"step":1},{"description":"Finely mince ONE red chili (~1 tbsp). Combine chili, ginger, garlic, oil, 1/2 cup cilantro/coriander, salt and pepper in a small bowl and set aside.","images":[],"step":2},{"description":"Rinse and pat the chicken dry (inside and out) with paper towels. Starting from the neck end of the chicken, use a teaspoon upside down to loosen the skin from the meat across the surface of the chicken (i.e. not the legs or wings). Just go as far as you can.","images":[],"step":3},{"description":"Spoon the cilantro/mixture between the meat and the skin near neck. Use the spoon to spread it a bit, then to finish it off, use your finger/hands ON the skin to spread the mixture as far and evenly as you can. Doesn''t need to be perfect! :)","images":[],"step":4},{"description":"Place the chicken stock/broth, kaffir lime leaves, lemongrass and the whole red chili into a dutch oven or baking tray. (Note 4)","images":[],"step":5},{"description":"Place the chicken in the broth, cover with a lid and roast for 45 minutes. Remove the lid, add the coconut milk and potatoes then roast for a further 30 minutes, or until juices run clear when pierced.","duration":45,"images":[],"step":6},{"description":"Remove the chicken from the broth and cover loosely with foil to rest for 5 minutes.","duration":5,"images":[],"step":7},{"title":"Skim excess fat off the surface of the broth","description":"I usually get about 5 tbsp of fat off.","images":[],"step":8},{"description":"Add the juice from the lime, sugar and fish sauce. Stir until the sugar is dissolved. Add remaining cilantro/coriander.","images":[],"step":9},{"description":"Serve the chicken with the broth in a pouring jug, or cut up the chicken and serve it in the broth.","images":[],"step":10}]', '["fish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Modern Asian"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","dietary","easter-mains","easter-recipes","gluten-free-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ca14a5a12d86', 'en', 'US', 'Asian Glazed Salmon', 'Recipe video above. This salmon is marinated for just 30 minutes in a simple but super tasty Asian marinade and then broiled/grilled to produce a gorgeous caramelisation. Just a really fantastic, quick and delicious way to cook salmon using pantry staples.', 'https://www.recipetineats.com/tachyon/2015/10/Asian-Glazed-Salmon-take-3_4-2-1.jpg', 5, 10, 15, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_sweet_chili_sauce", "quantity": {"value": 0.08, "unit": "bottle of 375ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_steamed_asian_greens", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["2 x 180g / 6oz salmon fillets (, skinless (Note 1))","Oil spray (olive oil, canola oil etc)"]},{"ingredients":["1 tsp fresh ginger (, finely grated)","1 garlic clove (, crushed)","1 tbsp soy sauce","2 tbsp oyster sauce","2 tbsp sweet chili sauce (Note 2)"],"purpose":"Marinade"},{"ingredients":["Sesame seeds","Scallions/shallots (, finely sliced)","Steamed Asian Greens","Rice"],"purpose":"To Serve (optional)"}]', '[{"title":"Marinade salmon","description":"Combine the Marinade ingredients in a shallow bowl. Add salmon and turn to coat. Cover and marinate for 30 minutes or up to overnight.","duration":30,"images":[],"step":1},{"description":"Preheat grill/broiler on high. Place the rack 25 cm / 10\" from the heat source.","images":[],"step":2},{"title":"Glaze","description":"Place salmon on baking tray (no oil required, no paper - it will burn). Dab glaze onto the salmon, whatever will stick. Don''t pour excess glaze on, it will pool around the salmon and burn.","images":[],"step":3},{"title":"Cook","description":"Grill/broil for 7 minutes. Remove, spray the surface generously with oil. Grill/broil for another 1 to 3 minutes until the surface is caramelised at the salmon is cooked - the flesh should flake. (Internal temperature 50°C/122°F for medium rare - see Note 3) . Be careful not to overcook the salmon!","duration":7,"images":[],"step":4},{"description":"Serve salmon sprinkled with sesame seeds, scallions/shallots with rice and steamed Asian greens on the side.","images":[],"step":5}]', '["fish","gluten","sesame","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","dinner-tonight","fish-recipes","main-dishes","modern-asian","most-popular","quick-and-easy","salmon-recipes","seafood-recipes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e5df44e2a467', 'en', 'US', 'Korean Bulgogi Beef Stir Fry', 'This is a very classic, traditional dish from Korea. It is becoming increasingly popular in Western countries as more and more people are discovering not only how delicious it is, but how easy it is to make with ingredients you can get from the supermarket! The beef has a lovely balance of sweet and salty. The use of grated apple and onion is classic Korean and it makes all the difference! Bulgogi is traditionally cooked over charcoal or a tabletop BBQ, however, I''ve made this in stir fry form which is also a way it''s used.This recipe makes enough for 2 to 3 people, served with rice as a main.', 'https://www.recipetineats.com/tachyon/2015/08/Korean-Beef-Bowl_Featured-Image.jpg', 15, 5, 20, 2, '[{"id": "ing_beef", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_onion", "quantity": {"value": 500.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.075, "unit": "pack of 100g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_mirin", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.075, "unit": "pack of 100g"}}, {"id": "ing_onion", "quantity": {"value": 500.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_apples", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["14 oz / 400 g thinly sliced beef (, any good quality tender cut suitable for grilling (Note 1))","1 scallion/shallot stem (, green and white part separated, both finely sliced (Note 2))","1/2 large onion ((brown, yellow or white), peeled and thinly sliced)","1/2 medium carrot (, peeled, cut vertically then cut into thin slices on the diagonal)","1 tbsp cooking oil (I use peanut or vegetable oil)","1/2 tbsp sesame seeds"],"purpose":"Beef"},{"ingredients":["3 tbsp ordinary soy sauce (I use Kikkoman)","1 1/2 tbsp brown sugar","1 tbsp mirin (Note 3)","1/2 tbsp sesame oil","2 tbsp grated onion (brown, white or yellow)","2 cloves garlic (, minced)","3 tbsp grated red apple ((not green - they are too tart) OR nashi pears)","1/2 tsp minced ginger","Black pepper"],"purpose":"Marinade"}]', '[{"description":"Blot the beef dry using a paper towel then place into a bowl.","images":[],"step":1},{"description":"Mix together the Marinade ingredients in a small bowl, then add the beef. Stir gently to coat the beef, cover with cling wrap and set aside to marinate for at least 1 hour, preferably overnight. Because the meat is thin, you still get good flavour even with 1 hour of marinating.","images":[],"step":2},{"description":"Heat the oil in a wok or large fry pan over high heat.","images":[],"step":3},{"description":"Add the onion and white part of the scallion/shallots. Cook for 1 minute.","duration":1,"images":[],"step":4},{"description":"Then add the beef, including the Marinade, and carrots. Cook for around 3 to 5 minutes, stirring constantly, until the beef is just cooked.","images":[],"step":5},{"description":"Remove from heat, then toss through the sesame seeds.","images":[],"step":6},{"title":"Serve immediately with rice","description":"or for a low carb, low cal option, try Cauliflower Rice! Sprinkle with extra sesame seeds and the reserved green part of the scallions.","images":[],"step":7}]', '["gluten","peanuts","sesame","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Korean"],"categories":["asian-recipes","beef-recipes","dietary","dinner-tonight","gluten-free-recipes","korean-recipes","main-dishes","most-popular","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6304c26db9ab', 'en', 'US', 'Slow Cooker Beef and Broccoli', 'This slow cooker version of Beef & Broccoli is made using the same ingredients as the authentic way of making this but the quantities have been adjusted to make it suitable for slow cooking. Making this in a slow cooker means you can use a budget cut of beef and it makes it meltingly tender. AND it''s freezer friendly!', 'https://www.recipetineats.com/tachyon/2014/09/Slow-Cooker-Beef-Broccoli-2.jpg', 10, 180, 190, 4, '[{"id": "ing_beef_steak", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_broccoli", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_ginger", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.04, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 4.0, "unit": "jar of 50g"}}]', '[{"ingredients":["500 g / 16 oz chuck steak or other beef cut suitable for slow cooking","300 g / 16 oz broccoli florets (about 6 cups, 1 giant broccoli or 2 medium)","2 tbsp corn flour (corn starch)","1 cup water (see note 2)"]},{"ingredients":["2 tbsp oil","2 tbsp finely sliced fresh ginger (note 1)","3 tbsp soy sauce (normal dark soy sauce)","2 tbsp oyster sauce","4 tsp Chinese cooking wine (rice wine) or dry sherry (note 5)","1 tsp sesame oil (optional)","1 tsp sugar","4 dashes white pepper"],"purpose":"Sauce"}]', '[{"description":"Cut the beef into thin slices against the grain (which means at 90 degrees to the direction of the fibres in the meat).","images":[],"step":1},{"description":"Place beef in slow cooker.","images":[],"step":2},{"description":"Mix the corn flour with the water, then add to the slow cooker.","images":[],"step":3},{"description":"Add the Sauce ingredients to the slow cooker.","images":[],"step":4},{"description":"Cook on HIGH for 3 hours (or pressure cook on high for 40 minutes).","images":[],"step":5},{"description":"To Serve Immediately","images":[],"step":6},{"description":"Steam or boil broccoli until \"tender crisp\" (just cooked, still bright green and still crisp).","images":[],"step":7},{"description":"Add to beef and sauce, toss to combine. Serve over rice.","images":[],"step":8},{"description":"To Make Ahead to Freeze (2 months) or Refrigerate (2 days)","images":[],"step":9},{"description":"Let the beef and sauce cool.","images":[],"step":10},{"description":"Meanwhile, blanch the broccoli very briefly, then run under cold water or plunge into ice water to stop from cooking further.","images":[],"step":11},{"description":"Drain broccoli, then combine with the beef and sauce.","images":[],"step":12},{"description":"Place into ziplock bags or airtight containers and freeze or refrigerate.","images":[],"step":13},{"description":"To cook, thaw then reheat in the microwave, covered. Be careful not to heat for too long because otherwise the broccoli will overcook.","images":[],"step":14},{"description":"Serve with rice.","images":[],"step":15}]', '["gluten","sesame","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","beef-recipes","broccoli-recipes","chinese-recipes","main-dishes","quick-and-easy","slow-cooker-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_38cbd41f053d', 'en', 'US', 'Momofuku Marinated Beef Skirt Steak Ssam', '"Ssam" refers to Korean dishes in which leafy vegetables, usually lettuce, are wrapped around meat. This is a recipe by the much celebrated chef David Chang, from his famous New York restaurant Momofuku. The marinade for the beef is a classic Korean marinade and infuses the meat with enough flavour that they can be eaten as is, without a sauce. The sauces are simple to make once you get your hands on the ingredients. Excluding the marinating time, this is really fast and easy to make.', 'https://www.recipetineats.com/tachyon/2014/07/Momofuku-Marinated-Skirt-Steak-Ssam-3.jpg', 20, 10, 30, 4, '[{"id": "ing_beef_steak", "quantity": {"value": 0.907, "unit": "kg"}}, {"id": "ing_apples", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 4.536, "unit": "bunch"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_grapes", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 2.0, "unit": "bottle of 250ml"}}, {"id": "ing_vinegar", "quantity": {"value": 0.004, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_ssamjang", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_kochujang", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_oil", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_lettuce", "quantity": {"value": 3.0, "unit": "head"}}]', '[{"ingredients":["2 lb / 1 kg skirt / flank / hanger steak (Note 1)","2 cups apple juice","½ cup light soy sauce","5 garlic cloves (, minced)","1/2 brown onion","1 tsp sesame oil","1 tsp freshly ground black pepper"],"purpose":"Beef and Marinade"},{"ingredients":["8 oz / 250 g shallots/scallions (, thinly sliced)","5 g fresh ginger (, finely chopped or minced)","4 tbsp grape seed oil (or another neutral oil)","1 1/2 tsp light soy sauce","3/4 tsp sherry vinegar","3/4 tsp salt (adjust to taste)"],"purpose":"Ginger Spring Onion Sauce"},{"ingredients":["1 tbsp ssamjang (Korean fermented bean-and- chili paste, available in many Asian stores)","1/2 tbsp kochujang (Korean chili paste, available in many Asian stores)","1/4 cup sherry vinegar","1/4 cup grape seed oil (or another neutral oil)"],"purpose":"Ssam Sauce"},{"ingredients":["3 small heads of Bib Lettuce (, leaves removed, washed and dried)"],"purpose":"To Serve"}]', '[{"description":"Combine Beef with Marinade and marinade at least overnight, up to 24 hours.","images":[],"step":1},{"description":"Remove beef from marinade. Preheat outdoor grill or heavy based skillet on stove on very high heat. You want it to be screaming hot. Cook the beef to your liking (see notes for guide).","images":[],"step":2},{"description":"When done, remove from heat, cover loosely with foil and let them rest for 5 to 10 minutes.","duration":7.5,"images":[],"step":3},{"description":"Make the Ginger Spring Onion Sauce by combining the ingredients and mixing to combine.","images":[],"step":4},{"description":"Make the Ssam Sauce by combining the ingredients and mixing well until smooth.","images":[],"step":5},{"description":"Slice the beef into 0.5cm / 0.2 inch thick slices, against the grain.","images":[],"step":6},{"description":"Serve with lettuce, Ginger Spring Onion Sauce and Ssam Sauce on the side.","images":[],"step":7},{"description":"To eat, place a piece of beef in a lettuce leaf, top with some of each sauce, then fold over lettuce, eat and be happy.","images":[],"step":8}]', '["gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie","vegan","vegetarian"]', '{"mealType":["snack","dinner"],"cuisine":["Asian","Fusion","Korean"],"categories":["asian-recipes","australia-day","beef-recipes","grilling-ideas-and-recipes","korean-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3ce3afb0cf8b', 'en', 'US', 'Vietnamese Chicken Pho soup (Pho Ga)', 'Recipe video above. Chicken Pho (Pho Ga) - the little sister of famous Beef Pho, equally delicious but much easier to make! I call it the Vietnamese version of homemade chicken noodle soup made from scratch. Except - dare I say it - so much more exciting!You won''t use all the chicken, but it''s infused with lovely flavour so there''s loads of uses - see Note 7.', 'https://www.recipetineats.com/tachyon/2020/05/Chicken-Pho_2.jpg', 10, 90, 100, 4, '[{"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_ginger", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_star_anise_pods", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_s", "quantity": {"value": 4.0, "unit": "pack"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.04, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_rice_noodles", "quantity": {"value": 0.96, "unit": "pack of 375g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 3.0, "unit": "bag of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_imes", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_sriracha", "quantity": {"value": 1.0, "unit": "bottle of 400ml"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 tbsp oil (, vegetable or canola (or other plain oil))","2 onions (, halved (skin on fine))","5cm/ 2\" piece of ginger (, sliced 0.75cm / 1/3\" thick (unpeeled))"],"purpose":"Charred aromatics:"},{"ingredients":["2 litres / 2 quarts water","1.5 kg / 3 lb chicken thighs, bone in skin on (Note 1)","1 small bunch coriander/cilantro (Note 2)","5 star anise pods (was short in photo & video!)","1 cinnamon stick","4 cloves","2 tsp fennel seeds","2 tsp coriander seeds","8 tsp fish sauce","6 tsp white sugar","3/4 tsp salt (Cooking/kosher salt, or 1/2 tsp table salt)"],"purpose":"Pho Soup Broth:"},{"ingredients":["360g / 13 oz dried rice noodles (, thin flat (or 600g fresh))","2 green onions stems (, finely sliced)"],"purpose":"Noodle Bowls:"},{"ingredients":["3 cups bean sprouts (Note 3)","1 small bunch EACH Thai Basil, min, coriander/cilantro (Note 4)","2 limes (, cut into 4 wedges)","Hoisin sauce","Sriracha","Red chillies (, finely sliced (optional))"],"purpose":"Toppings – help yourself"}]', '[{"title":"Char onion & ginger","description":"Heat oil in a 6 litre / 6 quart pot (Note 5) over high heat. Place ginger and onion facedown, leave undisturbed for 2 minutes until they blacken. Turn and leave for another 2 minutes.","duration":2,"images":[],"step":1},{"title":"Put everything in pot","description":"Add water and remaining Broth ingredients EXCEPT salt. Bring it a simmer, then lower heat so it''s simmering VERY gently with the lid on, but open a crack (Note 6).","images":[],"step":2},{"description":"Simmer gently 1.5 hours. Scoop off scum (dirty foam) that rises to surface once or twice during the simmering.","images":[],"step":3},{"title":"Strain & measure","description":"Remove chicken, then strain broth into a clean pot - you should have 1.5 litres / 1.5 quarts. If you have more, simmer to reduce. If less, top it up with water.","images":[],"step":4},{"title":"Salt broth","description":"Add salt, bring broth to a gentle simmer. Broth should be slightly on the salty side - it dilutes when you add the noodles.","images":[],"step":5},{"description":"Keep broth warm until ready to serve","images":[],"step":6},{"description":"Shred chicken meat, discard bones and skin. (Note 6 Leftover Chicken ideas)","images":[],"step":7},{"description":"Place Toppings out on the table.","images":[],"step":8},{"description":"Reheat chicken (can briefly dunk in broth!).","images":[],"step":9},{"description":"Prepare noodles per packet directions, just prior to serving. Drain very well (excess water dilutes broth).","images":[],"step":10},{"description":"Place noodle in bowls. Top with chicken, ladle over 375ml / 1.5 cups broth. Sprinkle with green onion.","images":[],"step":11},{"description":"Pile on Toppings of choice, add a squeeze of lime into the broth. Consume immediately!","images":[],"step":12}]', '["fish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["asian-soups","iconic-dishes","soup-recipes","vietnamese-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_309a5dcc98d0', 'en', 'US', 'Chinese Orange Chicken', 'Recipe video above. This is a recipe for Chinese Orange Chicken that makes impressively crispy chicken pieces without deep frying. The sauce has great orange flavour, it''s not too sweet, and I love the background hint of ginger!The chicken does lose crispiness once tossed with sauce, but you''ll still get crispy bits. It''s not a flaw, it''s the way it is! More importantly though, the sauce really clings to the surface of the chicken so you get a good amount of that lovey orange sauce with every bite.Source: Loosely based on the Orange Chicken by Woks of Life, though I used my no-deep-fry method and tweaked the sauce to my taste.', 'https://www.recipetineats.com/tachyon/2026/06/Orange-chicken-0.jpg', 20, 15, 35, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_ginger", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.075, "unit": "pack of 400g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_oranges", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_oranges", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_white_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["600g/1.2 lb boneless skinless chicken thighs or breast (, cut into 2.5cm / 1\" pieces)","2 tbsp light soy sauce (, or all-purpose soy (not dark soy - Note 1))","1/2 tsp finely grated ginger (, optional)","1/8 tsp white pepper (substitute black pepper)","2 tbsp cornflour / cornstarch (- for mixing)","3/4 cup cornflour / cornstarch (- for crispy coating)","3/4 - 1 cup vegetable oil (, or other plain oil (1/2 cm / 0.2\" depth))"]},{"ingredients":["2 tsp orange zest (, from 1 orange)","1 cup orange juice (, either squeeze oranges or use fresh bottled OJ (or use the orange then top up with bottle))","1 1/2 tbsp cornflour / cornstarch","2 tbsp Chinese cooking wine (/Shaoxing wine (Note 2))","2 tbsp rice vinegar (substitute white vinegar)","1/3 cup + 2 tbsp white sugar","2 tbsp light soy sauce ( or all-purpose soy sauce (not dark soy - Note 1))","1/4 tsp cooking salt / kosher salt (halve for table salt, double for flakes)","1 tsp ginger (, finely grated)","2 garlic cloves (, finely minced with a knife)"],"purpose":"Orange sauce:"},{"ingredients":["White rice (, or other plain rice of choice)","1 green onion (, finely sliced - optional garnish)","White sesame seeds - optional garnish"],"purpose":"For serving:"}]', '[{"description":"Mix chicken with soy, ginger, pepper and 2 tbsp cornflour, then coat in remaining cornflour. Clench few pieces in fist, shake off excess cornflour in colander. Shallow-fry until deep golden. Remove oil, sauté garlic, simmer sauce 2 min until thickened. Add zest, toss chicken, serve!","images":[],"step":1},{"title":"Orange sauce","description":"Whisk the cornflour and soy sauce in a large jug or medium bowl until lump free. Then whisk in everything else except garlic and orange zest. Set aside.","images":[],"step":2},{"title":"Coat chicken","description":"Mix the chicken pieces with the soy sauce, ginger, pepper and the 2 tablespoons of cornflour in a large bowl. Mix well - the coating becomes a bit sticky and acts as a glue. Add the 3/4 cup cornflour and toss to coat each piece, separating as needed (they stick together a bit).","images":[],"step":3},{"title":"Press and shake off","description":"Pick up a few pieces and enclose in your fist, to really press the cornflour on. Place in a colander, then repeat with remaining chicken. Shake colander so excess cornflour falls through the holes. This press-and-shake method is highly effective crispy no-fry technique! (Note 3)","images":[],"step":4},{"title":"Shallow-fry until crispy","description":"Heat the oil on high heat in a large deep non-stick pan (mine is 30cm/12\"). The chicken should sizzle straight away when you dip it. Spread half the chicken out (or as much as you can, without crowding), and cook for 1 1/2 minutes on each side, using tongs to turn, until deep golden and crispy. Remove onto a paper towel lined tray and repeat with remaining chicken.","images":[],"step":5},{"title":"Sauté","description":"Pour out all but 2 tablespoons of the oil, and scrape out any loose crispy bits. Return the pan to medium high heat. Sauté garlic until light golden, about 20 - 30 seconds.","images":[],"step":6},{"title":"Thicken sauce","description":"Give the sauce a whisk (to mix cornflour settled on the base) then pour it in the pan. Simmer for 1 to 2 minutes until it thickens into a thick, glossy syrup (honey consistency). Stir in zest.","duration":1.5,"images":[],"step":7},{"title":"Toss","description":"Put the chicken back into the pan and toss quickly to coat in the sauce. Serve over rice, garnished with green onion.","images":[],"step":8}]', '["gluten","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Chinese","Chinese American"],"categories":["asian-takeout","chicken-recipes","chinese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a612eb324787', 'en', 'US', 'Greek Zucchini Tots', 'Recipe video above. These tasty bites are from the Greek Island of Alonnisos, adapted from the Courgette / Zucchini Rissoles recipe in The Food and Cooking of Greece cookbook. Such a great way to use the humble zucchini to make something fabulous that''s meal worthy and great to pass around at a party!Traditionally they''re deep fried but I like to make them in the oven (handy, healthier) and make them tater-tot (potato gem) shapes. But you can make them any shape you want!', 'https://www.recipetineats.com/tachyon/2015/10/Greek-zucchini-tots_0-1.jpg', 20, 30, 80, 30, '[{"id": "ing_zucchini", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_green_onion", "quantity": {"value": 2.25, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_cheese", "quantity": {"value": 0.5, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.225, "unit": "tub of 500g"}}, {"id": "ing_mint", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["1 lb / 500 g zucchinis (courgettes)","1/4 tsp cooking salt / kosher salt"],"purpose":"Zucchini"},{"ingredients":["1/2 cup plain flour ((all-purpose flour), can sub gluten-free flour)","1 cup panko breadcrumbs ((Note 1), can sub gluten-free flour)","2 eggs","3/4 cup green onion (, finely sliced (white and pale green parts only))","1/2 cup parmesan cheese (, finely grated (I use store bought sandy type), can also use shredded cheddar or tasty cheese)","1 tbsp dried oregano (or 2 teaspoon other dried herbs)","2 garlic cloves (, minced)","1/4 tsp cooking salt / kosher salt","150 g / 5 oz Greek feta cheese (, crumbled)"],"purpose":"Batter"},{"ingredients":["Olive oil spray","Lemon wedges and oregano leaves (, optional garnishes)"],"purpose":"Cooking and serving"},{"ingredients":["3/4 cup plain Greek yoghurt (, or any plain unsweetened yogurt)","1 tbsp fresh mint (, finely chopped)","1/2 tbsp lemon juice","1/2 tbsp extra virgin olive oil (or more)","1/4 tsp each salt and pepper"],"purpose":"Minted Yoghurt (optional)"}]', '[{"description":"Preheat oven to 200°C/390°F (180°C fan-forced)","images":[],"step":1},{"title":"Sweat zucchini","description":"Grate the zucchini using a standard box grater. Place into a large colander, sprinkle with the salt, toss with your fingers and leave to sweat for 30 minutes.","duration":30,"images":[],"step":2},{"title":"Squeeze out liquid","description":"Working a handful at a time, squeeze out the excess water (as much as you can) and place the zucchini in a bowl.","images":[],"step":3},{"title":"Tots batter","description":"Add the Batter ingredients except the feta and mix well to combine. Add the feta and gently stir through.","images":[],"step":4},{"title":"Form tots","description":"Dollop heaped tablespoons 2 trays lined with baking paper / parchment paper (I get 29 in total). Then use your fingers to shape them into cylinder \"tater-tot / potato gem\" shapes.","images":[],"step":5},{"title":"Bake","description":"Spray generously with oil. Bake for 30 minutes, swapping the trays at around 20 minutes (for extra golden, spray again with oil), or until golden brown and a crunchy crust forms on the surface. The tray on the bottom might need a few extra minutes.","duration":30,"images":[],"step":6},{"description":"Serve with Minted Yogurt, lemon wedges and sprinkled with fresh oregano leaves if using.","images":[],"step":7},{"description":"Mix together ingredients and set aside for at least 10 minutes before serving.","images":[],"step":8}]', '["egg","gluten","milk"]', '["keto_friendly","low_calorie","vegetarian"]', '{"mealType":["snack","breakfast","dinner","lunch"],"cuisine":["Greek"],"categories":["australia-day","finger-food","fritters-tots-and-similar","greek-recipes","mediterranean-recipes","side-dishes","super-bowl-party-food","vegetarian-recipes","zucchini-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6a8ca80c1883', 'en', 'US', 'Nando''s Peri Peri Chicken Burgers', 'Recipe video above. This is my copycat of Nando''s famous Peri Peri Chicken Burgers! Chicken marinated in a homemade Peri Peri sauce, seared for an authentic char, piled onto warm buns and slathered with a homemade "Perinaise" (Peri Peri Mayonnaise sauce). This is moreish, burger perfection, better than take-out!Serve with French fries or wedges for a real-deal Nando''s experience at home. Excellent for gatherings - marinade large batches of chicken, cook on the BBQ, set up a DIY burger station!', 'https://www.recipetineats.com/tachyon/2015/11/Nandos-Peri-Peri-Chicken-Burger_9.jpg', 15, 15, 210, 4, '[{"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_vinegar", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.75, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_drops_red_food_colouring", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_peri_peri_sauce", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.188, "unit": "jar of 400g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.15, "unit": "tub of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_chicken_breast", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}]', '[{"ingredients":["1 - 3 birds eye red chilies (1 is very mild, 3 is mildly spicy) (Note 1)","1 medium red capsicum / bell pepper (, roughly cut into 1.5cm / 1/2\" pieces)","5 garlic cloves (, peeled, whole)","3 tbsp vegetable or canola oil (, or other plain flavoured oil)","4 tbsp malt vinegar (Note 2)","2 tbsp smoked paprika (substitute regular / sweet paprika)","1 tbsp dried oregano","2 tsp onion powder (substitute garlic powder)","1 1/2 tsp white sugar","1 1/2 tsp cooking salt / kosher salt","3 drops red food colouring (optional, Note 3)"],"purpose":"Peri Peri Sauce/Marinade"},{"ingredients":["3 tbsp Peri Peri Sauce (above)","1/2 cup whole egg mayonnaise (or other mayonnaise)","1/4 cup sour cream (or yoghurt)"],"purpose":"Perinaise"},{"ingredients":["2 tbsp olive oil","4 chicken breasts or chicken thigh fillets (, skinless boneless (each large enough for a burger))","4 soft rolls (, split and lightly toasted (if desired))","2 tomatoes (, sliced)","Lettuce of choice"],"purpose":"Burgers"}]', '[{"title":"Prepare chicken breast","description":"If using breast, pound to 1 cm / 0.4\" even thickness (cover with go-between or freezer bags, use a meat mallet or rolling pin). Then trim each chicken piece so it is a bit larger than the buns (factor in 20% shrinkage when it cooks).","images":[],"step":1},{"title":"Peri Peri Sauce","description":"Put the Per Peri Sauce ingredients in a jug and blitz until smooth using a stick blender, or other appliance of choice (food processor, blender, NutriBullet).","images":[],"step":2},{"title":"Marinade chicken","description":"Pour 1/2 cup of the sauce into a bowl or ziplock bag. Add the chicken and turn to coat. Marinate for at least 3 hours, or up to 24 hours, in the fridge.","images":[],"step":3},{"title":"Perinaise","description":"Mix together the Perinaise ingredients. Set aside.","images":[],"step":4},{"title":"Cook chicken","description":"Heat 1 tablespoon of olive oil in a fry pan over medium / medium-high heat, OR brush BBQ grill with oil then heat. Cook breast for 3 minutes on each side, thighs for 4 minutes (in batches, if they won''t fit in the pan), lowering the heat as needed if they are charring too much (char = legit!).","duration":3,"images":[],"step":5},{"title":"Rest","description":"Remove the chicken onto a plate, loosely cover with foil and rest for 5 minutes. (Meanwhile, toast the rolls)","duration":5,"images":[],"step":6},{"title":"Assemble","description":"To make the burgers, spread the base of a roll with Peri-naise. Top with lettuce, tomato then chicken, then top with more Peri-naise and extra Peri Peri sauce if desired!","images":[],"step":7}]', '["egg","milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Portuguese"],"categories":["australia-day","burger-recipes","chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","mediterranean-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2b84323b4311', 'en', 'US', 'Moroccan lamb backstrap', 'Recipe video above. Love lamb backstrap - beautifully tender with a relatively mild lamb flavour. Pairs 100% perfectly with a bold, earthy Moroccan Ras el hanout spice blend. Cook this lean, delicate meat gently - keep it blushing pink for optimum juiciness!Serve on a bed of Pearl couscous salad or traditional couscous for a fabulous share platter. Cook on the stove or BBQ on warm summer days!', 'https://www.recipetineats.com/tachyon/2023/01/Moroccan-lamb-backstraps_1-1.jpg', 10, 10, 20, 4, '[{"id": "ing_lamb", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_cumin", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_ginger", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.025, "unit": "bunch"}}, {"id": "ing_powder", "quantity": {"value": 3.75, "unit": "jar"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.225, "unit": "tub of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_paprika", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_pears", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_couscous", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_more_side_suggestions_in_post", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["2 x 250g/8oz lamb backstraps (Note 1)","1 tbsp extra virgin olive oil (rubbing)","1 1/2 tbsp extra virgin olive oil (cooking)"]},{"ingredients":["1 1/2 tsp cooking/kosher salt","3/4 tsp cumin powder","3/4 tsp ground ginger","3/4 tsp black pepper","1/2 tsp allspice powder","1/4 tsp cinnamon powder","1/4 tsp coriander powder","1/8 tsp clove powder"],"purpose":"Moroccan spice mix (ras el hanout, Note 2):"},{"ingredients":["3/4 cup Greek yoghurt","1 tbsp lemon juice","1 tbsp olive oil (, plus extra swish for drizzling)","1/4 tsp each salt and pepper","Pinch of sumac or paprika (, optional garnish)"],"purpose":"Yogurt sauce (for serving):"},{"ingredients":["Pearl couscous salad (pictured in post)","Classic couscous","More side suggestions in post"],"purpose":"Sides (optional):"}]', '[{"title":"Yogurt sauce","description":"Mix ingredients. Refrigerate until required.","images":[],"step":1},{"title":"Moroccan spice mix","description":"Mix the spices in a small bowl.","images":[],"step":2},{"title":"Coat backstrap","description":"Pat the backstraps dry with a paper towel then rub all over with 1 tbsp olive oil. Sprinkle the spice mix on the lamb backstraps - use it all! Set aside for 1 hour to marinate (if time permits, can skip).","images":[],"step":3},{"title":"Cook","description":"Heat 1 1/2 tablespoons olive oil in a large skillet over medium high heat. Cook the lamb backstops for 4 minutes on each side, or until the core temperature is 59°C/138°F.","duration":4,"images":[],"step":4},{"title":"Rest","description":"Transfer onto a rack set over a tray (or just a plate) to rest for 3 minutes. Cut into 0.75 - 1 cm / 1/4 - 1/3\" thick slices. Serve with yogurt sauce!","duration":3,"images":[],"step":5}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern","Moroccan"],"categories":["australia-day","easter-mains","easter-recipes","lamb","lamb-recipes","mains","moroccan"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_eba234227723', 'en', 'US', 'Greek Butterflied Lamb Leg', 'Recipe video above. This is a terrific, bold Greek marinade for lamb that both tenderises and infuses it with garlicky, herby, lemon flavours. Butterflied lamb leg is a fantastic way to enjoy lamb because the flattened shape means it can be cooked relatively quickly compared to roasting a whole leg. In fact, I think that butterflied lamb leg is one of the best cuts of lamb for the BBQ!', 'https://www.recipetineats.com/tachyon/2021/01/Butterflied-Lamb-Leg_0.jpg', 5, 25, 30, 8, '[{"id": "ing_lamb", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1000.0, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 0.1, "unit": "net of 500g"}}, {"id": "ing_zest", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 0.1, "unit": "net of 500g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_greek_salad", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_tzatziki", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_more_ideas_listed_in_post", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["1.5 - 1.8kg / 3 - 3.6 lb butterflied (ie. boneless) lamb leg (Note 1)"]},{"ingredients":["1 tbsp dried oregano","3 large garlic cloves (, minced using garlic press)","2 tsp salt","1 tsp black pepper","1/3 cup fresh lemon juice","1 tbsp zest (= zest of 1 lemon)","1/2 cup olive oil"],"purpose":"Marinade:"},{"ingredients":["1 tbsp oil (for brushing BBQ or for stove sear)"],"purpose":"For cooking:"},{"ingredients":["Lemon (, for garnish)","Oregano leaves (, optional garnish as pictured)","Flatbreads or store bought pita breads","Greek Salad","Flatbreads or store bought pita breads","More ideas listed in post"],"purpose":"Serving options:"}]', '[{"description":"Mix marinade ingredients in a large ziplock bag.","images":[],"step":1},{"description":"Add lamb, massage bag well to get the marinade into all the meat cracks and crevices.","images":[],"step":2},{"description":"Seal bag and marinate for 24 hours (3 hours minimum).","images":[],"step":3},{"description":"Remove lamb from the fridge 1 hour prior to cooking (to take fridge chill out for more even cooking).","images":[],"step":4},{"description":"Brush grates with oil then preheat BBQ until very hot. (Takes a good 15 minutes, lid closed, with my basic gas BBQ).","images":[],"step":5},{"description":"Remove lamb from marinade and place on the grill, fat side down.","images":[],"step":6},{"description":"Cook for 12 minutes, then turn and cook the flesh side for 8 minutes, or until the internal temperature in the thickest part registers 57°C / 135°F for medium-rare or desired pull temperature (see Note 3).","duration":12,"images":[],"step":7},{"description":"Loosely cover with foil, and rest for 10 minutes before serving.","duration":10,"images":[],"step":8},{"description":"Stove/Oven (Note 2):","images":[],"step":9},{"description":"Preheat oven to 180°C/350°F (all oven types). Place a rack on a tray.","images":[],"step":10},{"description":"Cut lamb into 2 or 3 large pieces so it fits in your skillet.","images":[],"step":11},{"description":"Heat oil in skillet over medium-high heat. Sear until golden brown on both sides, around 2 - 3 minutes each side. (Note: It will not colour much more in the oven)","images":[],"step":12},{"title":"Roast for 22","description":"25 minutes, or until the thickest part registers 57°C / 135°F for medium-rare or desired pull temperature (see Note 3).","duration":23.5,"images":[],"step":13},{"description":"Remove from oven, loosely cover with foil, and rest for 10 minutes before serving.","duration":10,"images":[],"step":14},{"description":"Either slice it at the table, or slice prior to serving and pile onto a platter. Fabulous served with Greek Salad, Tzatziki and flatbreads, as pictured in post.","images":[],"step":15},{"title":"More side suggestions","description":"Lemon Rice, Mediterranean Rice Salad, Greek Chickpea Salad, Lemon Orzo Salad.","images":[],"step":16}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["australia-day","easter-mains","easter-recipes","grilling-ideas-and-recipes","lamb","lamb-recipes","mains","roast-lamb","roasts"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b49cd69460b4', 'en', 'US', 'Homemade Rotisserie Doner Kebab Meat - beef or lamb!', 'Recipe video above. This is a homemade version of the giant punching bag size Doner kebab meats rotating on vertical rotisseries in kebab shops! It might be small, but what it lacks in size it makes up for in authenticity and flavour. Prepare to be amazed - it tastes JUST like the real deal (and your house will smell like a kebab shop!)Excellent food for gatherings - make ahead, wow factor, DIY wraps and economical.', 'https://www.recipetineats.com/tachyon/2020/07/Carving-Doner-Kebab-Meat-1.jpg', 20, 120, 140, 8, '[{"id": "ing_beef_mince", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cinnamon", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 8.0, "unit": "loaf"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 6.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_hummus", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_tomato", "quantity": {"value": 6.0, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}]', '[{"ingredients":["1 kg / 2 lb lamb or beef mince (ground meat) (, preferably 15% fat (Note 1))","200g / 7oz streaky bacon (, roughly diced (Note 2))","1 onion (, diced (brown, yellow, white))","2 clove garlic (, roughly chopped)","1 tbsp vegetable oil (or olive oil (for frying))"]},{"ingredients":["1 tsp dried oregano","2 tsp ground cumin","2 tsp ground coriander","1/2 tsp cinnamon","3 tsp salt (, kosher/cooking salt (Note 3))","1 tsp black pepper"],"purpose":"Seasoning Spices:"},{"ingredients":["8 flatbreads (Lebanese bread authentic!)","1 iceberg lettuce (, finely shredded)","6 tomatoes (, halved and sliced)","2 red onions (, finely sliced)","Hummus","Yogurt sauce (, optional (recipe Note 8))","More Sauce options: chilli sauce/Sriracha (I use this), BBQ, sweet chilli, tomato sauce/ketchup","Extra options: tabbouleh, shredded cheese"],"purpose":"Doner Kebabs:"}]', '[{"title":"Mix beef or lamb with all the Spices","description":"mix well using your hands.","images":[],"step":1},{"description":"Cover and refrigerate 2 hours minimum, or up to 24 hours.","images":[],"step":2},{"description":"Preheat oven to 170°C/ 325°F (150°C fan).","images":[],"step":3},{"description":"Line baking pan with foil.","images":[],"step":4},{"description":"Check to ensure skewers are long enough to prop on the sides of the pan. (Note 5)","images":[],"step":5},{"description":"Place onion, bacon and garlic in a 8 cup/2L+ food processor. Blitz until it becomes a paste (video at 29 sec),~30 sec on high, scraping down sides as you go.","images":[],"step":6},{"description":"Add meat and blitz on low until it becomes a paste (video at 42 sec), scraping down sides (~1 min for powerful food processors, 2 min for less powerful). (Note 4)","images":[],"step":7},{"description":"Shape Doner Kebab Meat:","images":[],"step":8},{"description":"Turn meat out onto work surface. Wet hands with water, then shape into an even block 20cm/8\" long.","images":[],"step":9},{"description":"Place 2 x 60cm / 2 feet long pieces of foil overlapping each other by 1/3. (Note 6)","images":[],"step":10},{"description":"Place meat on the end of the foil, then roll it up, tightly wrapping it in the foil.","images":[],"step":11},{"description":"Twist the ends firmly to form a log 25cm/10\" long, then snip off excess foil. Roll into even log.","images":[],"step":12},{"description":"Thread skewers through the log.","images":[],"step":13},{"description":"Place log elevated in pan by propping skewers on the edge of the pan. (Note 7)","images":[],"step":14},{"description":"Cooking:","images":[],"step":15},{"description":"Cook for 1 1/2 hours, turning once after 1 hour, until the log reaches 70°C/160°F (up to 80°C/175°F is fine). The log is cooked at this point. (Note 9)","images":[],"step":16},{"description":"Remove foil from log but leave skewers in place.","images":[],"step":17},{"description":"Increase oven heat to 250°C/480°F, or as high as your oven can go if it can''t reach this.","images":[],"step":18},{"description":"Bake for 10 to 15 minutes, rotating once, until browned all over.","duration":12.5,"images":[],"step":19},{"description":"Shaving / pan frying (kebab shop style!):","images":[],"step":20},{"description":"Remove skewers then stand the meat upright.","images":[],"step":21},{"title":"Shave meat thinly","description":"carve as much as you intend to use.","images":[],"step":22},{"description":"Heat oil in a skillet over medium high heat. Cook shaved meat lightly coloured but still \"floppy\" (not crisped). Use immediately for Doner Kebabs!","images":[],"step":23},{"description":"Smear hummus on warmed flatbread. Top with lettuce, tomato, and onion.","images":[],"step":24},{"description":"Pile on Doner Kebab Meat. Drizzle with sauce(s) of choice.","images":[],"step":25},{"description":"Roll up tightly, wrap in foil if desired (to hold together). Grab and devour!","images":[],"step":26}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Turkish"],"categories":["australia-day","beef-mince-recipes","beef-recipes","cuisines","grilling-ideas-and-recipes","iconic-dishes","lamb-recipes","main-dishes","mains","middle-eastern-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8b91a54343e0', 'en', 'US', 'Greek Chicken Gyros with Tzaziki', 'Recipe video above. The marinade for the chicken is so sensational that I use it even when I''m not making Gyros! This is fantastic for entertaining because you can just lay it all out for guests to help themselves. The smell when the chicken is cooking is incredible - you can really smell the oregano and garlic!Recipe includes a Tzatziki, you can also use a Lemon Yogurt Sauce for a quicker option (make a double batch).', 'https://www.recipetineats.com/tachyon/2015/06/Greek-Chicken-Gyros_original-pics__8.jpg', 20, 6, 26, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.907, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1000.0, "unit": "pack of 3 heads"}}, {"id": "ing_vinegar", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.375, "unit": "tub of 500g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.375, "unit": "tub of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 1000.0, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}]', '[{"ingredients":["2 lb / 1 kg chicken thigh fillets (, boneless skinless)"]},{"ingredients":["3 large garlic cloves (, minced (~ 3 tsp))","1 tbsp white wine vinegar (or red wine or apple cider vinegar)","3 tbsp lemon juice","1 tbsp extra virgin olive oil","3 tbsp Greek yogurt (, preferably full fat)","1 1/2 tbsp dried oregano","1 tsp salt","Black pepper"],"purpose":"Marinade"},{"ingredients":["2 cucumbers (to make about 1/2 - 3/4 cup grated cucumber after squeezing out juice)","1 1/4 cups Greek yoghurt (, preferably full fat)","1 tbsp lemon juice","1 tbsp extra virgin olive oil (or more if you want richer)","1 garlic clove (, minced)","1/4 tsp salt","Black pepper"],"purpose":"Tzatziki"},{"ingredients":["3 tomatoes (, desseeded and diced)","3 cucumbers (, diced)","1/2 red spanish onion (, peeled and finely chopped)","1/4 cup fresh parsley leaves (optional)","Salt and pepper"],"purpose":"Salad"},{"ingredients":["4 to 6 pita breads or flat breads"],"purpose":"To Serve"}]', '[{"description":"Place the Marinade ingredients in a ziplock bag and massage to mix. Add the chicken into the ziplock bag and massage to cover all the chicken in the Marinade. Marinate for at least 2 hours, preferably 3 hours, ideally 12 hours and no longer than 24 hours.","images":[],"step":1},{"description":"Make the Tzatziki","images":[],"step":2},{"description":"Cut the cucumber in half lengthwise. Use a teaspoon to scrape the watery seeds out. Coarsely grate the cucumber using a box grater. Then wrap in paper towels or a tea towel and squeeze to remove excess liquid.","images":[],"step":3},{"description":"Place cucumber in a bowl. Add remaining ingredients then mix to combine. Set aside for at least 20 minutes for the flavours to meld.","images":[],"step":4},{"description":"Combine ingredients in a bowl.","images":[],"step":5},{"description":"Cook Chicken","images":[],"step":6},{"description":"Brush the outdoor grill with oil, then preheat on medium high. Or heat 1 tbsp of oil in a fry pan over medium high heat.","images":[],"step":7},{"description":"Remove chicken from Marinade. Cook the chicken for 2 to 3 minutes on each side, until golden brown and cooked through (cooking time depends on size of chicken).","duration":2.5,"images":[],"step":8},{"description":"Remove the chicken from the grill / fry pan onto a plate. Cover loosely with foil and allow to rest for 5 minutes before serving.","duration":5,"images":[],"step":9},{"description":"If your chicken thighs are large, you may need to cut them. Mine were small.","images":[],"step":10},{"description":"Get a pita bread or flatbread (preferably warmed) and place it on a piece of parchment (baking) paper (or you could use foil). Place some Salad down the middle of the bread, then top with chicken and Tzatziki.","images":[],"step":11},{"description":"Roll the wrap up, enclosing it with the parchment paper. Twist the end with the excess parchment paper to secure it and cut if desired.","images":[],"step":12},{"description":"I prefer to lay everything out on a table and let everyone help themselves.","images":[],"step":13}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner","lunch"],"cuisine":["Greek"],"categories":["australia-day","chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","greek-recipes","grilling-ideas-and-recipes","mediterranean-recipes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_14689a674677', 'en', 'US', 'Oven Pork Ribs with Barbecue Sauce', 'Recipe video above. Barbecue pork ribs made in the oven! It''s easy, the ribs are meltingly tender and it''s packed full of flavour from the rub, braising the ribs in cider (see Note 1 for subs!) and the homemade barbecue sauce glaze! (Note: BBQ Sauce ingredients not consistet with the video!! Editing blunder - use ingredients listed in recipe below. Need to fix video!!)', 'https://www.recipetineats.com/tachyon/2016/01/Oven-Pork-Ribs-with-Barbecue-Sauce_4.jpg', 15, 135, 150, 6, '[{"id": "ing_paprika", "quantity": {"value": 0.312, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_beef_steak", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_apples", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.25, "unit": "bottle of 500ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_molasses", "quantity": {"value": 22.5, "unit": "jar"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}]', '[{"ingredients":["2.5 tsp paprika powder","2 tsp garlic powder (sub with onion powder)","1.5 tsp onion powder (sub with garlic powder)","1 tsp cayenne pepper (omit for not spicy)","1.5 tsp dried thyme","1.5 tsp dried oregano","1.5 tsp salt","0.5 tsp black pepper"],"purpose":"Barbecue Rub for Ribs:"},{"ingredients":["2 - 2.5kg / 4 - 5lb pork ribs (2 racks)","3/4 cup sweet alcoholic apple cider (hard cider) (, or apple juice (Note 2))","1 tbsp olive oil"],"purpose":"Ribs"},{"ingredients":["1/2 cup apple cider vinegar (Note 3)","1 1/2 cups tomato ketchup (or Aussie tomato sauce)","1/2 cup water (or use remaining apple cider!)","1 1/2 tbsp molasses (, orginal (not blackstrap, Note 4))","1/3 cup brown sugar","2 tsp mustard powder","1 1/2 tsp garlic powder","2 tsp Worcestershire sauce","1 tsp salt","1 tsp black pepper","1 tsp Tabasco or cayenne pepper (optional, for spiciness)"],"purpose":"Homemade Barbecue Sauce"}]', '[{"description":"Combine the Rub ingredients and rub onto both sides of the ribs (most on meaty side). Set aside to marinate for 20 minutes (or overnight).","duration":20,"images":[],"step":1},{"description":"Preheat oven to 160°C/320°F (all oven types).","images":[],"step":2},{"description":"Place ribs on a tray in a single layer. Pour apple cider underneath the ribs, cover with foil then bake for 1 hour 30 minutes or until the meat is pretty tender (Note 5).","images":[],"step":3},{"description":"Remove from oven, turn up to 180°C/350°F. Remove foil, drizzle with olive oil, then return ribs to oven for 15 minutes or until rub becomes nice and crusty.","duration":15,"images":[],"step":4},{"description":"Line a new tray with foil then baking / parchment paper (you''ll thank me later).","images":[],"step":5},{"description":"Remove ribs from oven, transfer to lined tray. Pour any juices from tray over the ribs.","images":[],"step":6},{"description":"Flip ribs so the bonier side is up. Slather with Barbecue Sauce, then bake 10 minutes.","images":[],"step":7},{"description":"Remove from oven, then turn ribs over so the meaty side is up. Slather with Barbecue Sauce, bake 5 minutes. Repeat 2 or 3 more times until you''ve got a thick glaze on the ribs.","images":[],"step":8},{"description":"Cut ribs into individual or multiple rib portions and serve with remaining Barbcue Sauce!","images":[],"step":9},{"description":"Place all ingredients in a saucepan and simmer over medium heat, stirring occasionally, for 45 minutes or until thickened.","duration":45,"images":[],"step":10},{"title":"Adjust to taste","description":"sweetness with brown sugar / honey, salt and sour with vinegar. Use for glazing ribs and as a sauce for serving.","images":[],"step":11}]', '["mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["American"],"categories":["australia-day","grilling-ideas-and-recipes","iconic-dishes","most-popular","pork-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ff3cad72a151', 'en', 'US', 'Aussie Meat Pie recipe', 'Recipe video above. The great Australian meat pie - made at home! Buttery shortcrust base filled with slow cooked fall apart chunky beef smothered in a rich gravy, topped with puff pastry. Legendary! {See notes for beef mince version}Also see the Family Size Meat Pie, mini Party Pies and Sausage Rolls!', 'https://www.recipetineats.com/tachyon/2019/04/Meat-Pies_3.jpg', 40, 220, 260, 6, '[{"id": "ing_batches_homemade_shortcrust_pastry", "quantity": {"value": 1.5, "unit": "pack"}}, {"id": "ing_frozen_shortcrust_pastry_sheets_thawed", "quantity": {"value": 3.0, "unit": "pack"}}, {"id": "ing_refrigerated_pie_crusts", "quantity": {"value": 2.0, "unit": "pack"}}, {"id": "ing_frozen_puff_pastry_sheets_just_thawed", "quantity": {"value": 3.0, "unit": "pack"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_beef", "quantity": {"value": 1.25, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.2, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.2, "unit": "jar of 50g"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}]', '[{"ingredients":["1 1/2 batches homemade shortcrust pastry","3 frozen shortcrust pastry sheets, thawed (300g/10oz)","2 refrigerated pie crusts (US/Can)"],"purpose":"Pie Base – Choose ONE (Note 1):"},{"ingredients":["3 frozen puff pastry sheets, just thawed (300g/10oz) (Note 2)","1 egg (, lightly whisked)"],"purpose":"Pie Lid:"},{"ingredients":["1.25 kg / 2.5lb beef chuck (, 2.5cm/1\" cubes (Note 3))","1/2 tsp each salt & pepper","2 - 3 tbsp olive oil","1 onion (, diced)","4 garlic cloves (, minced)","5 tbsp flour (, plain/all purpose)","1 1/4 cups (315 ml) beef stock, low sodium (Note 4)","3 cups (750 ml) red wine (, dry full bodied (Note 5))","2 tbsp tomato paste","1 tsp Worcestershire sauce","2 tsp black pepper (, coarsely ground)","2 bay leaves"],"purpose":"Filling:"}]', '[{"description":"Sprinkle beef with 1/2 tsp salt and pepper.","images":[],"step":1},{"description":"Heat 1 tbsp oil in a large heavy based pot over high heat. Add 1/3 of the beef and brown aggressively all over, then remove. Repeat with remaining beef, adding more oil if needed.","images":[],"step":2},{"description":"Turn stove down to medium high. Add garlic and onion, cook 3 minutes.","images":[],"step":3},{"description":"Add flour, stir through.","images":[],"step":4},{"description":"Slowly add beef stock while stirring constantly. Once flour is dissolved, add wine, tomato paste, Worcestershire, pepper and bay leaves.","images":[],"step":5},{"description":"Return beef into pot, cover with lid, adjust heat so it''s simmering gently.","images":[],"step":6},{"description":"Simmer 1 hr 45 minutes. Remove lid, increase heat slightly and simmer 30 - 45 minutes, stirring regularly, or until beef is fork tender and liquid reduces down to a thickish gravy, just about covering beef (see video). Do not reduce liquid too much - thickens more as it cools & in pie.","images":[],"step":7},{"description":"Remove from stove, cover and cool filling (I usually leave overnight).","images":[],"step":8},{"description":"Preheat oven to 180C/350F.","images":[],"step":9},{"description":"Cut out 6 rounds from the shortcrust pastry, then drape pastry into pie tins - don''t stretch and pull pastry, causes shrinkage. (Notes 1 & 6)","images":[],"step":10},{"description":"Place pies on tray. Top each pie with large sheets of parchment / baking paper and fill with pie weights (Note 7).","images":[],"step":11},{"description":"Bake 20 minutes, remove, then use paper overhang to carefully remove pie weights.","images":[],"step":12},{"description":"Return crusts into oven for 5 minutes or until base is light golden and dry (can skip, Note 8). Remove from oven.","duration":5,"images":[],"step":13},{"description":"Fill pies with cooled filling, push down to fill. Should be slightly mounded.","images":[],"step":14},{"title":"Cut rounds from partially thawed puff pastry","description":"cut them slightly larger than the edge of the cooked pastry bases.","images":[],"step":15},{"description":"Brush edge of pie crusts with egg, then place lid on filling, pressing edges to seal puff pastry to the shortcrust pastry.","images":[],"step":16},{"description":"Brush lids with egg, then cut a 1cm / 0.5\" incision in the middle using a small knife.","images":[],"step":17},{"description":"Bake 30 minutes or until deep golden and puffed.","images":[],"step":18},{"description":"Devour hot and fresh, topped with tomato sauce or ketchup if desired!","images":[],"step":19}]', '["egg","gluten"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Australian"],"categories":["australia-day","beef-recipes","iconic-dishes","quiches-tart-and-pie-recipes","slow-cooked-fall-apart"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8cbd643628e5', 'en', 'US', 'Prawn Mango Avocado Summer Salad with Lime Dressing', 'Recipe video above (useful tips for chopping mango and avo). Prawns, Mango and Avocado are a magical combination! This summer salad is fresh and healthy, yet satisfying to have as a meal or great for sharing! Make this with: rice, quinoa, risoni/orzo or pearl couscous.', 'https://www.recipetineats.com/tachyon/2019/01/Prawn-Avocado-Mango-Salad-with-Lime-Dressing_2.jpg', 15, 10, 25, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.75, "unit": "pack of 500g"}}, {"id": "ing_shrimp", "quantity": {"value": 300.0, "unit": "kg"}}, {"id": "ing_mango", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_rocket_arugula", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["2.5 cups cooked risoni/orzo or similar (Note 1)","300 – 400g / 10 – 12 oz cooked peeled prawns / shrimp (~750g unpeeled whole cooked)","1 large mango (, cut 1.5cm / ½” pieces)","1 large ripe avocado (, cut 1.5cm / ½” pieces )","75 g / 2.5 oz rocket / arugula (, roughly chopped (Note 2))","250 g / 8oz cherry tomatoes (, halved)","1/2 red onion (, finely sliced)","1/4 cup coriander / cilantro leaves (, finely chopped (Note 2))"],"purpose":"Salad:"},{"ingredients":["4 tbsp (60 ml) extra virgin olive oil","2 tbsp (30 ml) lime juice ((fresh), plus more to taste)","1 small garlic clove (, minced)","1/2 tsp salt","1/4 tsp black pepper"],"purpose":"Lime Dressing:"}]', '[{"description":"Shake Dressing in a jar.","images":[],"step":1},{"title":"Chop prawns into 1.75","description":"2 cm / 2/3” pieces.","images":[],"step":2},{"description":"Place all Salad Ingredients in a bowl, pour over dressing. Toss very gently using rubber spatula. Adjust to taste with more lime if desired. Serve immediately!","images":[],"step":3}]', '["shellfish"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["australia-day","dietary","dinner-tonight","easter-brunch-recipes","easter-sides-fresh-light","gluten-free-recipes","main-dishes","mains","no-cook-food","pasta-salads-and-rice-salads","prawns-shrimp","quick-and-easy","salad-recipes-main-course","seafood-recipes","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_36772bb70b27', 'en', 'US', 'Marinated Beef Kebabs', 'Recipe video above. Using a marinade infuses the beef with flavour as well as tenderising so you''ll have juicy steak pieces even if you opt for a more economical cut of beef. Use the reserved marinade to baste the kebabs as they cook for extra flavour! Buy the beef in a block so you can cut them into large cubes. Marinading time - 24 hours will give you the best results (most tender beef), though even 3 hours is better than not marinating at all. Makes 8 skewers.', 'https://www.recipetineats.com/tachyon/2018/07/Beef-Kabobs_2.jpg', 15, 8, 23, 8, '[{"id": "ing_beef_steak", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_mushroom", "quantity": {"value": 16.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.15, "unit": "bottle of 250ml"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_skewers", "quantity": {"value": 16.0, "unit": "pack of 50"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_pink_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}]', '[{"ingredients":["750g / 1.5 lb rump (picanha), beef tri-tip, sirloin steak or other steak cut (suitable for quick cooking (Note 1))","3 capsicum / bell peppers (red, yellow green)","1 large red onion","16 small mushrooms (, 3.25cm / 1.3\" wide)"]},{"ingredients":["1 tsp minced garlic (2 large garlic clove)","1 tsp onion powder (or sub with garlic powder)","2 1/2 tbsp soy sauce (Note 2)","2 tbsp Worcestershire sauce","2 tbsp balsamic vinegar","1 tbsp vegetable oil (or other neutral flavoured oil)","1/4 tsp black pepper"],"purpose":"Marinade:"},{"ingredients":["16 flat metal skewers (, 25 - 30cm / 10 - 12\" (Note 3))","Olive oil (, for drizzling and cooking)","Finely chopped parsley (, garnish (optional))"],"purpose":"Cooking:"},{"ingredients":["Pink sauce (, pictured in post - Note 4)","Lemon Yogurt Sauce (this goes well with the flavours here)"],"purpose":"Optional sauce:"}]', '[{"description":"Cut the beef into 3.25cm / 1.3\" wide cubes.","images":[],"step":1},{"title":"Marinade","description":"Mix Marinade in a bowl. Add beef. Marinate for 3 - 24 hours.","images":[],"step":2},{"description":"Making the kebab skewers","images":[],"step":3},{"description":"Cut capsicum and onion into 3.25cm / 1.3\" wide squares.","images":[],"step":4},{"description":"Thread beef (reserve Marinade), vegetables and mushrooms on each skewer. I use 2 pieces of vegetables between each piece of beef. Thread loosely - don''t smush together tightly (helps even cooking).","images":[],"step":5},{"description":"Brush kebabs lightly with Reserved Marinade (including vegetables), then drizzle with olive oil.","images":[],"step":6},{"title":"Cook and baste","description":"Heat BBQ or large skillet over high heat. Add 1 tbsp oil, then when smoking, cook kebabs in batches for 2 minutes on each side until slightly charred (4 sides = 8 minutes in total), basting with Reserved Marinade as you go.","duration":2,"images":[],"step":7},{"title":"Rest and serve","description":"Transfer to plate, cover loosely with foil and rest for 3 minutes before serving. Garnish with parsley if desired. See note for pictured Pink Dipping Sauce.","duration":3,"images":[],"step":8}]', '["gluten","milk","soy"]', '["high_protein","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mediterranean","Western"],"categories":["australia-day","beef","beef-recipes","grilling-ideas-and-recipes","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b8ee823f83ca', 'en', 'US', 'Hamburger Recipe', 'Recipe video above. All you need for great beef hamburgers is decent beef and lots of salt and pepper. This is the way it''s done by all the grilling masters like Bobby Flay, and your favourite diners!', 'https://www.recipetineats.com/tachyon/2016/02/Beef-Hamburgers_7-2.jpg', 15, 20, 35, 4, '[{"id": "ing_beef", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 3.0, "unit": "pack of 1kg"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_cheese", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.005, "unit": "jar of 200g"}}, {"id": "ing_french_fries", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["800g - 1kg / 1.6 - 2 lb ground beef (mince), 20%+ fat (Note 1)","Salt and pepper","3 onions, peeled and sliced into rings","2 tbsp oil","4 - 8 slices cheese of choice, I use Swiss (optional)"],"purpose":"Hamburger Pattie"},{"ingredients":["4 soft hamburger buns, lightly toasted","Lettuce, tomato slices","Ketchup, mustard, relish, sliced pickles"],"purpose":"Hamburger"},{"ingredients":["French fries","Baked potato wedges"],"purpose":"On the side"}]', '[{"description":"Separate beef into 4 equal portions. Use hands to lightly form into patties the size of your buns (mine are about 10 cm / 4\") - don''t press hard, light fingers = soft juicy patties (see video for how I do this).","images":[],"step":1},{"description":"Season generously with salt and pepper on both sides. Make a dent on one side (stop burger from become dome shape and shrinking when cooking).","images":[],"step":2},{"description":"Heat 1 tbsp oil in a heavy based skillet or BBQ over high heat. Add onion and cook until wilted and caramelised. Season with salt and pepper, then remove.","images":[],"step":3},{"description":"Heat 1 tbsp oil until smoking. Add patties and cook for 2 minutes until deep golden with a great crust. Do not press! Flip carefully, cook for 1 minute then top with cheese (if using). Cover with lid and cook for further 1 minute until cheese is melted.","duration":2,"images":[],"step":4},{"description":"Meanwhile, toast the cut side of the buns lightly.","images":[],"step":5},{"title":"To serve","description":"Spread base of buns with sauce / condiment of choice. Top with lettuce then tomato, then hamburger patty. Pile over onions, sliced pickles, then more sauce/condiments. Top with lid of bun. Serve immediately.","images":[],"step":6}]', '["milk","mustard"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["australia-day","beef-mince-recipes","beef-recipes","burger-recipes","dietary","dinner-tonight","gluten-free-recipes","grilling-ideas-and-recipes","main-dishes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1ad0e830bdbe', 'en', 'US', 'Slow Cooker Beef Brisket with BBQ Sauce', 'Video above. Beef brisket slow cooked until tender, then finished in the oven to get that gorgeous caramelisation, basted with a homemade BBQ Sauce that the brisket is cooked in. Slice it and serve as part of a hearty Southern style supper or pile it up high on sliders!', 'https://www.recipetineats.com/tachyon/2017/07/Slow-Cooker-BBQ-Beef-Brisket-1-1.jpg', 15, 600, 615, 8, '[{"id": "ing_beef_brisket", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.019, "unit": "jar of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.25, "unit": "bottle of 500ml"}}, {"id": "ing_ketchup", "quantity": {"value": 0.45, "unit": "bottle of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 15.0, "unit": "bottle"}}]', '[{"ingredients":["1.5 – 2 kg / 3 – 4 lb beef brisket (Note 1)","1 tbsp olive oil (or a neutral oil like vegetable, canola)"]},{"ingredients":["1 tbsp brown sugar","2 tsp paprika powder","1 tsp onion powder","1 tsp garlic powder","1/2 tsp cumin powder","3/4 tsp mustard powder","1 tsp salt","1/2 tsp black pepper"],"purpose":"Rub:"},{"ingredients":["2 garlic cloves (, minced)","1/2 cup / 125 ml apple cider vinegar","1 1/2 cups / 375 ml ketchup","1/2 cup / 110g brown sugar (, packed)","2 tsp EACH black pepper, onion powder, mustard powder","1 tsp cayenne pepper (adjust to taste re: spiciness)","1 tbsp Worcestershire sauce"],"purpose":"BBQ Sauce:"}]', '[{"description":"Mix Rub ingredients. Rub all over brisket. If time permits, leave for 30 minutes – 24 hours in the fridge, but I rarely do this.","duration":30,"images":[],"step":1},{"description":"Combine BBQ Sauce ingredients in a slow cooker. Mix then add the brisket – squish it in if needed, like I did (see video).","images":[],"step":2},{"description":"Slow cook in slow cooker for 8 hours (1.5 kg / 3 lb) to 10 hours (2 kg / 4 lb). (Note 2 for pressure cooker and click here for oven)","images":[],"step":3},{"description":"Remove brisket onto a tray.","images":[],"step":4},{"description":"Pour liquid in slow cooker into a saucepan. Bring to simmer over medium high heat and reduce until it thickens to a syrup consistency (it thickens more as it cools).","images":[],"step":5},{"description":"Meanwhile, drizzle brisket with oil then roast in a 200C/390F oven for 15 minutes until brown spots appear. Remove then baste generously with Sauce, then return to oven for 5 minutes. Remove and baste again, then return to oven for 5 – 10 minutes until it caramelises and looks like the photos. (See note for BBQ option)","duration":15,"images":[],"step":6},{"title":"TO SERVE","description":"Slice brisket thinly across the grain and serve with remaining BBQ Sauce. This is terrific served as a meal with sides or piled high onto rolls with Coleslaw as sliders. See Note 3 for more ideas.","images":[],"step":7}]', '["mustard"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["American","Southern"],"categories":["australia-day","beef","beef-recipes","iconic-dishes","main-dishes","mains","quick-and-easy","sandwiches-and-sliders","slow-cooked-fall-apart","slow-cooker-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_37eb94fd3e20', 'en', 'US', 'Slow Cooked Lamb Shawarma', 'This meltingly tender Slow Cooked Shawarma is the stuff food dreams are made of!! Slathered in a deceptively simple shawarma spice rub then slow cooked until fall apart, the flavour and fragrance of this lamb is absolutely heavenly. Make this Middle Eastern speciality with lamb shoulder or lamb leg. Finishing on the BBQ is optional - ideal for reheating if making ahead / summer BBQ''s! SLOW COOKER directions added in notes. Recipe VIDEO below.', 'https://www.recipetineats.com/tachyon/2018/01/Lamb-Shawarma_4.jpg', 10, 210, 220, 6, '[{"id": "ing_lamb", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cardamon", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}]', '[{"ingredients":["2kg / 4 lb lamb shoulder (bone in) or 1.7 kg / 3.5 lb butterflied lamb leg (Note 1)"]},{"ingredients":["3 garlic cloves (, minced)","1 tbsp ground coriander","1 tbsp ground cumin","1 tbsp ground cardamon","1 tsp cayenne pepper (1/2 tsp = not spicy)","2 tsp smoked paprika (ordinary also ok)","1 1/2 tsp salt","1/2 tsp black pepper","1/4 cup / 65 ml extra virgin olive oil","2 - 3 tbsp / 40 - 60 ml lemon juice"],"purpose":"Shawarma Paste:"},{"ingredients":["2 cups / 500 ml water"],"purpose":"Cooking:"}]', '[{"description":"Preheat oven to 180C/350F (standard) or 160C/320F (fan forced / convection).","images":[],"step":1},{"description":"Place Paste ingredients in a bowl, starting with 2 tbsp lemon juice, and mix. It should be a wet paste that can be slathered onto the lamb (see video).","images":[],"step":2},{"description":"Place lamb in a large roasting pan. Slather all over with paste. Optional: Marinate 24 hours (not mandatory, I usually skip).","images":[],"step":3},{"description":"Position the lamb with the fat side up. Pour water around, cover tightly with foil.","images":[],"step":4},{"title":"Roast 3 hours, removing from the oven 2","description":"3 times to spoon over pan juices (ie baste).","images":[],"step":5},{"title":"Remove foil. Meat should be tender","description":"check with 2 forks.","images":[],"step":6},{"description":"Baste again, then return to oven for 30 minutes to get a nice crust.","duration":30,"images":[],"step":7},{"title":"Remove lamb from roasting pan","description":"reserve juices.","images":[],"step":8},{"description":"Finish on BBQ, Optional (Note 2):","images":[],"step":9},{"description":"Cool the lamb for 20 minutes or so (so it firms up slightly, easier to handle).","duration":20,"images":[],"step":10},{"description":"If you used shoulder, pull the meat off the bone in 4 or 5 chunks (see video).","images":[],"step":11},{"description":"Preheat BBQ to medium and oil if required.","images":[],"step":12},{"description":"Coat lamb in pan juices. Sear on both sides until deep golden and a crust forms. Dab with pan juices on both sides.","images":[],"step":13},{"description":"Slice or shred lamb, as desired. Drizzle with plenty of juices.","images":[],"step":14},{"description":"Make Lamb Shawarma wraps by serving with shredded lettuce, tomatoes and minted yoghurt (Note 3) or pile over Lemon Herbed Couscous (Note 4) and garnish with pomegranate seeds and parsley or chopped coriander/cilantro (if desired). Both pictured in post.","images":[],"step":15}]', '[]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern"],"categories":["australia-day","cuisines","dietary","easter-mains","easter-recipes","gluten-free-recipes","grilling-ideas-and-recipes","iconic-dishes","lamb-recipes","main-dishes","middle-eastern-recipes","quick-and-easy","roast-lamb","roasts","slow-cooked-fall-apart","slow-cooker-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9d63ee5aedd4', 'en', 'US', 'Doner Kebab recipe', 'Recipe VIDEO above. A homemade version of the chicken kebab rolls you get at your favourite kebab shop! It tastes remarkably similar to the kebab shop chicken meat. I oven bake it, but imagine it rotisserie style over the BBQ or charcoal! You will need 4 long metal skewers for this, around 30cm / 12" long.', 'https://www.recipetineats.com/tachyon/2017/11/Chicken-Doner-Kebab-1.jpg', 20, 55, 1515, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_hummus", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_tabbouleh", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 7.5, "unit": "pack of 1kg"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_mejadra_for_kebab_plate", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["1 kg / 2 lb chicken thighs (, skinless and boneless (Note 1))","Olive oil (, for drizzling)"]},{"ingredients":["1 cup plain yoghurt (, unsweetened (I use Greek))","3 garlic cloves minced","1 1/2 tsp coriander powder","2 tsp cumin powder","2 tsp paprika","1 tsp cayenne pepper (, optional)","1 1/2 tsp onion powder","1/2 tsp black pepper","2 1/2 tbsp tomato paste","1 1/2 tsp cooking salt / kosher salt","1 tbsp lemon juice (substitute apple cider vinegar)","2 tbsp olive oil"],"purpose":"Marinade:"},{"ingredients":["Lebanese bread / flatbreads / pita bread (, warmed)","Finely sliced iceberg lettuce","Tomato slices","Hummus (or Note 2 for simple Yoghurt Sauce)","Tabbouleh (optional, Note 3)","Red onion slices","Shredded cheese","Chilli Sauce (I use Sriracha, it''s perfect)","Mejadra ((Middle Eastern Rice with Lentils), for Kebab Plate)"],"purpose":"For Serving (choose):"}]', '[{"title":"Marinade","description":"Mix Marinade in a large bowl. Add chicken and mix to coat well. Cover and marinate in the fridge for a minimum of 3 hours, 24 hours is ideal. If only 3 hours, add an extra 1/2 tsp salt.","images":[],"step":1},{"description":"Preheat oven to 220°C / 430°F (200°C fan-forced).","images":[],"step":2},{"description":"Choose a pan of a size such that the skewers will stay propped up on the pan walls (see photos in post or video) and the chicken will be elevated off the base. Line with foil.","images":[],"step":3},{"title":"Thread onto skewers","description":"Remove chicken from fridge. Divide the chicken into 2 piles. Take one piece of chicken, fold in half then thread onto two skewers (see video). Repeat and push the chicken snugly up against each other. Repeat with other skewer.","images":[],"step":4},{"description":"Prop the 2 skewers on the edges of the baking pan. Drizzle surface with oil.","images":[],"step":5},{"description":"Bake for 35 minutes or until the surface is golden with some charred bits (char is good!). Spoon the pan juices over the chicken. Turn, drizzle with oil and bake for a further 20 minutes. If you want more colour, oven grill/broil for a few minutes on high (I don''t do this).","duration":35,"images":[],"step":6},{"title":"Rest 5 minutes","description":"Baste again with pan juices and stand for 5 minutes.","duration":5,"images":[],"step":7},{"title":"Carving","description":"Stand the skewers upright or on an angle, and slice meat fairly thinly. Use to make Doner Kebabs or Kebab Plates.","images":[],"step":8},{"description":"Making Doner Kebabs rolls:","images":[],"step":9},{"description":"Place a lebanese bread (or pita bread or other flatbread) on a piece of foil. Spread with a generous dollop of Hummus (or yoghurt sauce - Note 2). Top with shredded lettuce, slices of tomato, Tabbouleh (for a truly authentic experience! Note 3), cheese (I usually go this) and Chicken. Drizzle with chilli sauce if desired (I use Sriracha, it''s perfect).","images":[],"step":10},{"description":"Roll up tightly and wrap in foil. Consume and be happy!","images":[],"step":11},{"description":"Serve chicken with Mejadra (Middle Eastern Spiced Rice with Lentils), shredded lettuce, tomatoes, slices of red onion, tabbouleh, dollop of hummus. Optional to serve flatbread / lebanese bread on the side.","images":[],"step":12}]', '["gluten","milk"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Turkish"],"categories":["australia-day","chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","mediterranean-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e45e5e8ae8a5', 'en', 'US', 'Ripper Beef Nachos', 'The nachos cheese sauce takes 5 minutes to make and will take your nachos to the next level, ensuring even coverage of cheese goodness over every chip! You can substitute the homemade Nachos Seasoning with 1 packet store bought taco seasoning.', 'https://www.recipetineats.com/tachyon/2016/01/Beef-Nachos_2b.jpg', 20, 15, 35, 8, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_beef", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_corn", "quantity": {"value": 0.992, "unit": "can of 400g"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_quantity_proper_guacamole", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_quantity_pico_de_gallo", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}]', '[{"ingredients":["1 tbsp olive oil","2 garlic cloves","1/2 onion (, finely chopped)","1 lb / 500g ground beef (mince)","2 tbsp tomato paste","2 tbsp water"],"purpose":"Beef"},{"ingredients":["1 tsp each onion powder ((Note 1), dried oregano, salt)","2 tsp each dried cumin powder (, paprika)","1/4 tsp cayenne pepper (, or to taste)"],"purpose":"Nachos Seasoning"},{"ingredients":["14 oz / 400g corn chips (, good quality (Note 2))","2 cups grated cheese (cheddar, tasty, gruyere, Monterey Jack)","1 quantity Nachos Cheese Sauce (, warm (Note 3))"],"purpose":"Nachos"},{"ingredients":["Sliced scallions / shallots","1 quantity Proper Guacamole (, Restaurant Style)","1 quantity Pico de Gallo (Note 4)","Sour cream"],"purpose":"Sides/Garnish"}]', '[{"title":"Beef","description":"Heat oil in a skillet over high heat. Add garlic and onion, cook until translucent. Add beef and cook, breaking it up as you go. Once beef is cooked, add Nachos Seasoning, tomato paste and water. Cook for a further 2 minutes, then set aside.","images":[],"step":1},{"description":"Preheat oven to 180C/350F.","images":[],"step":2},{"description":"Spread half the corn chips in a single layer on a baking tray. Drizzle over about 1 cup Nachos Cheese Sauce (see KEY TIPS in Note 3), top with 1/2 the Beef and 1/2 the grated cheese ensuring most of the Cheese Sauce is covered.","images":[],"step":3},{"description":"Spread over remaining corn chips, drizzle over remaining Nachos Cheese Sauce, Beef and grated cheese, again ensuring all the Cheese Sauce is covered.","images":[],"step":4},{"description":"Bake for 15 minutes or until cheese is melted.","duration":15,"images":[],"step":5},{"description":"Serve immediately, garnished with sliced scallions/shallots if using and with Guacamole, Pico de Galloand Sour Cream on the side.","images":[],"step":6}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Tex-Mex"],"categories":["australia-day","beef-mince-recipes","beef-recipes","dietary","gluten-free-recipes","mexican-recipes","nachos-recipes","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_97f611fadbd2', 'en', 'US', 'Coconut Marinated Chicken (Grill or Stove)', 'Coconut milk is a fantastic marinade which tenderises the chicken and infuses it with rich flavour. The added bonus is that the marinade doubles as a scrumptious sauce! Cook this on your BBQ or stovetop.', 'https://www.recipetineats.com/tachyon/2015/08/Coconut-Marinated-Chicken_2-Featured.jpg', 10, 15, 25, 4, '[{"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_imes_all_the_zest_3_tbsp_of_juice", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_hot_sauce", "quantity": {"value": 0.2, "unit": "bottle of 150ml"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 can coconut milk (preferably full fat, but light is ok) (14oz/400g)","2 limes - all the zest + 3 tbsp of juice","1 tbsp mild curry powder","2 tsp paprika","1 tbsp fresh ginger (, finely grated)","3 garlic cloves (, crushed)","2 tbsp Frank''s classic hot sauce (, or other hot sauce of choice (adjust to taste) (Note 2))","3/4 tsp salt","Black pepper"],"purpose":"Marinade"},{"ingredients":["1.5 lb / 750g chicken thigh fillets (, skinless and boneless)","1 tbsp oil (for cooking)","3/4 cup water"],"purpose":"Chicken"},{"ingredients":["Fresh coriander leaves"],"purpose":"Garnish (optional)"}]', '[{"description":"Combine the Marinade ingredients in a ziplock bag. Add the chicken and set aside to marinate for at least 3 hours, preferably overnight.","images":[],"step":1},{"description":"Remove the chicken from the Marinade, shaking off the excess. Keep the Marinade for the Sauce (below).","images":[],"step":2},{"description":"Brush the BBQ with oil and heat to medium high, or heat the oil in a skillet over medium high heat.","images":[],"step":3},{"description":"Cook the chicken for around 7 minutes on the first side and 5 minutes on the second side, or until cooked through.","images":[],"step":4},{"description":"Transfer the chicken to a plate, cover loosely with foil and rest for 5 minutes.","duration":5,"images":[],"step":5},{"description":"Serve with Sauce and garnished with fresh cilantro leaves, if using.","images":[],"step":6},{"description":"Pour the marinade into a small saucepan over medium heat.","images":[],"step":7},{"description":"Add the water and bring to a simmer. Cook for at least 10 minutes, or until thickened to desired consistency. (Note 1) Transfer to a sauce bowl.","images":[],"step":8}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Tropical!"],"categories":["australia-day","chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","most-popular","quick-and-easy","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4ff74e7abbe8', 'en', 'US', 'Salmon Quiche', 'Recipe video above. The most amazing salmon quiche made with smoked salmon!! When cooked, it''s looks just like cooked normal salmon - but with better seasoning in every bite. This fills a deep dish quiche tin 23cm / 9″ diameter, 3.5 cm / 1.5″ deep. Scale down for smaller tins and prepared pie shells - see Note 1.', 'https://www.recipetineats.com/tachyon/2019/04/Salmon-Quiche_6.jpg', 20, 90, 110, 8, '[{"id": "ing_homemade_quiche_crust", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_sheets_frozen_shortcrust_pastry", "quantity": {"value": 2.0, "unit": "pack"}}, {"id": "ing_x_9_refrigerated_pie_crust", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_ready_made_pie_shell", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_butter", "quantity": {"value": 15.0, "unit": "block of 250g"}}, {"id": "ing_eek", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_pears", "quantity": {"value": 8.0, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 5.0, "unit": "carton of 12"}}, {"id": "ing_cream", "quantity": {"value": 1.5, "unit": "carton of 250ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_dill", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_salmon_fillets", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_gruyere_cheese", "quantity": {"value": 0.75, "unit": "block of 200g"}}, {"id": "ing_salmon_fillets", "quantity": {"value": 0.2, "unit": "kg"}}]', '[{"ingredients":["1 homemade quiche crust (shortcrust pastry)","2 sheets frozen shortcrust pastry","1 x 9\" refrigerated pie crust (, fitted in a 9\" pie dish or tart tin)","1 ready made pie shell (23cm / 9\", fridge or frozen)"],"purpose":"Quiche Crust – choose one (Note 1):"},{"ingredients":["15g / 1 tbsp butter (, unsalted)","1 leek (, white part only halved and finely sliced (Note 2))","2 garlic cloves (, minced)","8 - 10 asparagus spears","5 eggs (~55 - 60g / 2oz each)","1 1/2 cups (375ml) cream (, full fat (Note 3))","1/4 tsp salt + pinch pepper","2 tbsp fresh dill (, roughly chopped (Note 4))","200g / 7 oz smoked salmon (, cut into 4cm / 1.7\" pieces (Note 5))","3/4 cup (75g) gruyere cheese (, grated (Note 6))"],"purpose":"Quiche Filling:"},{"ingredients":["Dill sprigs and extra smoked salmon"],"purpose":"Decorations (optional)"}]', '[{"description":"Quiche Crust (Note 1):","images":[],"step":1},{"title":"Homemade quiche crust or frozen shortcrust pastry","description":"prepare and bake the crust per Quiche Crust recipe.","images":[],"step":2},{"title":"Refrigerated pie crust","description":"unroll, fit into a 9\" pie dish or tart tin. Bake per packet directions.","images":[],"step":3},{"title":"Prepared pie shell (ie comes in foil dish)","description":"bake per packet directions, scale Filling down to 4 eggs (Note 1).","images":[],"step":4},{"description":"Preheat oven to 180C/350F (160C/320F fan forced).","images":[],"step":5},{"description":"Place cooked quiche crust on a tray.","images":[],"step":6},{"title":"Asparagus","description":"break woody ends off (Note 7). Cut into 3.5cm / 1.5\" pieces, separate tips from stems (tips for decorating).","images":[],"step":7},{"description":"Melt butter in a skillet over medium heat. Add leeks and garlic, saute for 2 minutes or until leeks are translucent, don''t let them go golden.","duration":2,"images":[],"step":8},{"description":"Stir in asparagus stems (don''t cook), then remove from stove.","images":[],"step":9},{"description":"Cool slightly then scatter across base of quiche crust.","images":[],"step":10},{"description":"Whisk together eggs, cream, dill, salt, pepper in a bowl.","images":[],"step":11},{"description":"Scatter 2/3 of the salmon across quiche, folding/twisting pieces rather than laying flat.","images":[],"step":12},{"description":"Top with cheese, pour over egg mixture.","images":[],"step":13},{"description":"Top with remaining salmon and asparagus tips.","images":[],"step":14},{"description":"Bake for 40 minutes or until top is light golden and centre is set but still slightly jiggly when you poke it.","duration":40,"images":[],"step":15},{"description":"Rest for 10 minutes before carefully removing from tin and slicing.","duration":10,"images":[],"step":16}]', '["egg","fish","milk"]', '["gluten_free"]', '{"mealType":["breakfast","dinner"],"cuisine":["Western"],"categories":["baking-recipes","easter-brunch-recipes","easter-recipes","egg-recipes","fish-recipes","quiches-tart-and-pie-recipes","salmon-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d6966578a8fb', 'en', 'US', 'Quiche Crust / Shortcrust Pastry for Pies', 'Recipe video above. This is a recipe for quiche and pie crusts, both of which are made using shortcrust pastry. This is a great, EASY classic quiche crust. Quiche crusts are just made with shortcrust pastry. Made using a food processor, very slightly adapted from this recipe by Emeril Lagasse.Inactive chill time: 1 hour. This is the recipe I''ve been using for years and years, and it has never failed me! Makes pastry for 1 x 23cm / 9" pie dish or tart tin (serves 8 - 12 people).', 'https://www.recipetineats.com/tachyon/2019/04/Quiche-Crust_4.jpg', 15, 35, 50, 8, '[{"id": "ing_flour", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}]', '[{"ingredients":["1 1/4 cups (185g / 5.6 oz) plain white flour (all purpose flour)","1/2 tsp salt","100g / 7 tbsp unsalted butter, cold, cut into 1cm/ 1/3\" cubes","3 tbsp ice cold water (+ more as required)"]}]', '[{"description":"Place flour, salt and butter in a food processor.","images":[],"step":1},{"description":"Pulse 10 times or until it looks like breadcrumbs.","images":[],"step":2},{"description":"With the motor running on low, pour 2.5 tbsp of water into the tube feeder.","images":[],"step":3},{"description":"Turn up to high and blitz for 30 seconds or until it turns into a ball of dough. Initially it will look like breadcrumbs, then it will turn into a ball of soft dough - some random escaped bits is fine. If it doesn''t look like its coming together at 20 seconds, add another 1/2 tbsp of water. Don''t blitz longer than 30 seconds at most.","duration":0.5,"images":[],"step":4},{"description":"Form a disc, wrap in cling wrap. If there are escaped crumble bits, that''s fine - just press them in. Refrigerate for 1 - 3 hours.","images":[],"step":5},{"description":"Preheat oven to 200C/390F (standard) or 180C/350F (fan forced)","images":[],"step":6},{"description":"Sprinkle work surface with flour, unwrap dough and place on the flour. Sprinkle top with flour, then roll out into a 27cm/11\" round.","images":[],"step":7},{"description":"Gently roll the pastry so it wraps around the rolling pin.","images":[],"step":8},{"title":"Unroll it over the quiche pan or pie dish","description":"23cm / 9\".","images":[],"step":9},{"description":"Press the pastry into the edges of the quiche pan, patching up edges if required (if pastry doesn''t quite reach top of rim).","images":[],"step":10},{"description":"Roll the rolling pin across the top to cut off the excess pastry.","images":[],"step":11},{"title":"Optional extra \"safe measure\" refrigeration","description":"15 minutes. See (Note 2).","images":[],"step":12},{"description":"Place a large piece of parchment paper over the pastry, then fill with baking beads or lots of rice or dried beans to weigh it down. (Note 3)","images":[],"step":13},{"description":"Bake for 20 minutes, then remove from oven.","duration":20,"images":[],"step":14},{"description":"Turn oven DOWN to 180C/350F (or 160C/320F fan).","images":[],"step":15},{"description":"Use excess paper to CAREFULLY remove hot beads, then return to oven for 10 minutes or until base is light golden.","duration":10,"images":[],"step":16},{"description":"Remove from oven and fill with chosen Quiche Filling. Quiche Lorraine, Salmon Quiche, Italian Sausage or your other filling of choice.","images":[],"step":17},{"description":"The pastry will not be 100% cooked, it finishes cooking with the filling. It''s cooked enough so the crust will not go soggy.","images":[],"step":18}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["baking-recipes","quiches-tart-and-pie-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7c446c04df7a', 'en', 'US', 'Crispy Pork Belly Banh Mi', 'Recipe video above. The crispy pork belly version of the famous Vietnamese sandwich, inspired by Ca Com in Melbourne, a famous banh mi shop. Hands down one of the best sandwiches I have ever made in my life, and my favourite type of banh mi (all my recipes here). Excellent food for sharing with friends and Sunday lunches.The Special Sauce is a copycat of the Ca Com sauce and it''s an excellent match for crispy pork - thicker so it clings and doesn''t soak and soften the skin or bread.PS The recipe for the crispy skin pork belly is based on the much-loved Crispy Pork Belly recipe. So you can have confidence that your pork WILL have perfect crispy crackling!', 'https://www.recipetineats.com/tachyon/2024/03/Crispy-pork-belly-banh-mi_3.jpg', 15, 180, 195, 5, '[{"id": "ing_pork", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 60.0, "unit": "bottle"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.113, "unit": "can of 400ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.01, "unit": "bottle of 250ml"}}, {"id": "ing_bread", "quantity": {"value": 5.0, "unit": "loaf"}}, {"id": "ing_chicken", "quantity": {"value": 0.12, "unit": "kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.225, "unit": "jar of 400g"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.06, "unit": "bunch"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 1.2, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 3.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.06, "unit": "bunch"}}]', '[{"ingredients":["1kg / 2 lb pork belly with skin on","1 1/2 tsp canola or vegetable oil (, divided)","1/2 tsp Chinese Five Spice (, optional (you won''t miss it))","1 tsp cooking/kosher salt (, divided)","1/4 tsp black pepper (or white pepper)"],"purpose":"Crispy pork belly for banh mi"},{"ingredients":["4 tbsp Hoisin sauce","3 tbsp coconut milk (, full fat)","1/2 tsp dark soy sauce (mainly for colour, sub light or regular soy)"],"purpose":"Special banh mi sauce (Ca Com copy!)"},{"ingredients":["5 crusty white rolls (lightly oven toast to crisp if crust is softened)","120g/ 4 oz chicken pate (Note 2)","6 tbsp whole-egg mayonnaise (or Kewpie)","1 batch Vietnamese pickled carrots and daikon ()","3 green onion stems (, cut to length of rolls (2 to 3 pieces per roll))","2 cucumbers (, finely sliced using vegetable peeled or knife)","2 cups coriander/cilantro leaves (and small sprigs)","3 Birds Eye or Thai chillis (, finely sliced)","8 tbsp crispy fried shallots (, store bought (Note 3))"],"purpose":"To make the banh mi (5 rolls)"}]', '[{"description":"Crispy pork belly for banh mi","images":[],"step":1},{"title":"Dry skin overnight","description":"Place pork belly on a plate. Pat skin dry with paper towels. Leave uncovered in fridge overnight to dry out the skin. (If you don''t have time, pat the skin dry as best you can).","images":[],"step":2},{"description":"Preheat oven to 140°C/285°F (both fan and standard ovens).","images":[],"step":3},{"title":"Season flesh","description":"Drizzle flesh side with 1 tsp oil. Sprinkle over 1/2 tsp salt, and all the pepper and Chinese five spice. Rub all over the flesh, including on the sides.","images":[],"step":4},{"title":"Foil boat","description":"Place 2 pieces of foil on a work surface. Put the belly in middle of foil, skin side up. Fold the sides in to enclose the belly, forming an open box, pinching corners to seal tightly and make it as snug as possible. Place meat on a tray.","images":[],"step":5},{"title":"Season skin","description":"Pat skin dry with paper towels. Rub with 1/2 tsp oil then sprinkle remaining 1/2 tsp salt evenly all over the skin surface, from edge to edge.","images":[],"step":6},{"title":"Slow roast 2 hours","description":"Place in the oven and roast for 2 hours, tightening the foil around the pork after 1 hour (the pork will shrink). This protects the flesh from drying out.","images":[],"step":7},{"title":"Increase heat","description":"Remove pork from oven, then increase heat to 240°C/465°F (all oven types).","images":[],"step":8},{"title":"Level pork","description":"Remove pork from foil, discard fat and foil. Place pork on a rack set over a tray. Use scrunched up balls of foil stuffed under pork to prop it up so the skin surface is as level and horizontal as possible (see photos in post).","images":[],"step":9},{"description":"30 minutes blast! Place the pork back in the oven for 30 minutes, rotating after 15 minutes as needed, until the crackling is deep golden, puffy and crispy all over. If some patches are browning faster, protect with foil patches.","duration":30,"images":[],"step":10},{"title":"Rest 10 minutes","description":"Remove pork from oven. Rest for 10 minutes before slicing.","duration":10,"images":[],"step":11},{"description":"Making the banh mi","images":[],"step":12},{"title":"Sauce","description":"Mix the ingredients in a bowl then set aside. This will keep for 5 days in the fridge .","images":[],"step":13},{"title":"Chop pork","description":"Cut the pork into 1 1/2 cm / 0.6\" thick slices, then each slide into 1 1/2 cm / 0.6\" chunks.","images":[],"step":14},{"title":"Split & spread","description":"Split the roll in half down the side, keeping the lid attached. Smear the base with 1 1/2 tbsp of pate, then 1 1/2 tbsp of mayonnaise (on top of the pate)","images":[],"step":15},{"title":"Stuff","description":"Pile about 1/3 cup pickled vegetables on the mayonnaise. Lay 2 slices of cucumber and 2 green onions against the lid. Pile pork on top. Drizzle pork with 1 tbsp of sauce. Stuff coriander/cilantro down the side, sprinkle with chilli then2 tablespoons of crispy shallots as you want (if using).","images":[],"step":16},{"title":"Serving","description":"Eat immediately! Banh mi is definitely one of those foods best eaten freshly made!","images":[],"step":17}]', '["egg","gluten","soy"]', '["high_protein","keto_friendly"]', '{"mealType":["dinner","lunch"],"cuisine":["Vietnamese"],"categories":["banh-mi","iconic-dishes","modern-asian","sandwiches-and-sliders","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_db37fc0765e7', 'en', 'US', 'Charcoal Chicken Shop Chicken Skewers', 'Recipe video above. This is my copycat of those tasty Chicken Skewers sold at charcoal chicken shops all across Australia. They''re so heavily flavoured they are practically crusted with seasoning, in the best possible way! Great on the BBQ (also, you can cook them all in one go), but honestly just as good on the stove.You can cook them straight away though if you’ve got the time, an overnight marinade will take the flavour to another level.PS See Note 1 if you think this looks good but you''re feeling too lazy to skewer. :)', 'https://www.recipetineats.com/tachyon/2026/03/Kebab-shop-chicken-skewers_4.jpg', 15, 20, 35, 10, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.562, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_sauce_options", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_onion", "quantity": {"value": 15.0, "unit": "pack of 1kg"}}]', '[{"ingredients":["800g / 1.6 lb boneless chicken thighs (, cut into large 2.5cm / 1\" squares, I cut each thigh into ~6 to 8 pieces. (Note 1))","3 - 4 tbsp olive oil (, for cooking)"]},{"ingredients":["1 1/2 tbsp garlic powder (or 2 garlic cloves finely grated using microplane)","1 tbsp onion powder (or more garlic powder)","1 tbsp paprika (, regular/sweet (not spicy), smoked great too)","1 tsp mustard power (sub 1 tsp dijon or yellow mustard, not spicy)","1 tsp dried oregano (or thyme)","1/2 tsp curry powder *secret ingredient* (regular grocery stores ones, I use Clives)","1 1/4 tsp cooking salt / kosher salt (halve for table salt, +50% for flakes)","1/2 tsp black pepper","3 tbsp extra virgin olive oil","2 tbsp lemon juice (or white wine/red wine vinegar, or similar)"],"purpose":"Chicken marinade:"},{"ingredients":["Sauce options -","Flatbreads","Shredded lettuce, tomato slices (2 - 3 whole), finely sliced red onion","Shredded lettuce, tomato slices (2 - 3 whole), finely sliced red onion"],"purpose":"For serving – options"}]', '[{"title":"Mix marinade, marinate chicken 12","description":"24 hrs (if you can), skewer, cook 3 minutes on each side on medium high.","images":[],"step":1},{"title":"Marinade","description":"Mix the Marinade ingredients in a bowl, it should be like a paste. Add chicken pieces and toss well to coat every piece well.","images":[],"step":2},{"description":"Marinate for 12 to 24 hours (even 3 hours helps) though they are still tasty cooked straight away!","images":[],"step":3},{"title":"Skewer","description":"Thread the chicken pieces onto skewers. I usually do 10 to 12, with 3 to 4 pieces on each. (You could also skewer then leave skewered for marinating time, do it whichever way suits!)","images":[],"step":4},{"title":"Stove cook","description":"Heat a large non stick pan on medium high with enough oil to lightly coat the base. Cook the skewers in batches for 3 minutes on each side, controlling the heat as needed so the spices don''t burn. Transfer onto a plate, loosely cover with foil to keep warm. Wipe black bits out of the pan using a paper towel, add more oil and continue cooking.","duration":3,"images":[],"step":5},{"title":"BBQ option","description":"Brush the grills or flat plate lightly with oil. Heat on medium (or medium high, if your BBQ is not that strong). Cook skewers for 3 - 4 minutes on each side, adjusting the heat as needed so the spices don''t burn.","duration":3.5,"images":[],"step":6},{"description":"Serve the skewers with flatbreads or pita pockets, shredded lettuce, tomato and onion slices with sauce of choice (see ingredients section for options). Or make plates with a side of seasoned rice (see options above), a fresh Greek Salad and sauce of choice.","images":[],"step":7}]', '["mustard"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Aussie","Western"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","grilling-ideas-and-recipes","mains"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4592bdfe7ef9', 'en', 'US', 'Lamb Souvlaki', 'Recipe video above. The bold garlic-oregano Greek marinade works wonders to tenderise and infuse incredible flavour into the lamb! The flavour when this is cooking is out of this world. Eat them straight off the skewer while still hot or bundle up into warm pita bread with fixings.', 'https://www.recipetineats.com/tachyon/2023/11/Lamb-souvlaki_7.jpg', 20, 10, 30, 12, '[{"id": "ing_lamb", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_skewers", "quantity": {"value": 8.0, "unit": "pack of 50"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 0.15, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.15, "unit": "net of 500g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_vinegar", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_batch_tzatziki", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.15, "unit": "net of 500g"}}]', '[{"ingredients":["1.2 kg/ 2.4 lb boneless lamb leg (, fat trimmed, cut into 2.5cm/1” cubes (~900g / 1.8lb after trimming) (Note 1))","1 tsp cooking / kosher salt","1/2 tsp black pepper","1 tbsp extra virgin olive oil","8 - 12 skewers (, wooden or bamboo)"]},{"ingredients":["5 garlic cloves (, finely minced)","5 tbsp lemon juice","2 tsp lemon zest","2 tsp dried oregano","3 fresh bay leaves (, crushed in hand (or 2 dried kept whole))","1/3 cup white wine vinegar","3 tbsp extra virgin olive oil","1 tsp cooking / kosher salt"],"purpose":"Lamb souvlaki marinade:"},{"ingredients":["4 - 6 pita bread","1 batch Tzatziki","Greek salad ((chop small for stuffing) or shredded lettuce and tomato slices)","Greek lemon rice (to make plates instead of wraps)"],"purpose":"To serve – stuffed or make plates:"}]', '[{"description":"Mix marinade ingredients in a bowl. Add lamb and toss to coat.","images":[],"step":1},{"title":"Marinate in fridge for 12","description":"24 hours.","images":[],"step":2},{"description":"Skewer & cook:","images":[],"step":3},{"title":"Skewer","description":"Remove meat from marinade and thread 3 to 4 pieces on each to make 12 skewers, or 5 to make 8 larger skewers (pictured in post).","images":[],"step":4},{"description":"Sprinkle the meat with the salt and pepper. (This really makes a difference to the finished dish, better than just in the marinade).","images":[],"step":5},{"title":"Cook","description":"Heat 1 tbsp olive oil in a large non-stick pan over high heat. Cook half the skewers for 3 minutes, turn then cook the other side for 3 minutes until nicely seared (target internal temp 60°C/140°F for medium rare, optimum juiciness).","duration":3,"images":[],"step":6},{"description":"Transfer to a plate and loosely cover with foil to keep warm while you cook the remaining skewers.","images":[],"step":7},{"description":"BBQ cooking (Note 2):","images":[],"step":8},{"title":"Soak skewers","description":"Soak wood/bamboo skewers in water for 30 minutes if planning to cook on the BBQ (prevents burning). My skewers are 18cm/7” which fit in a pan (stove cooking).","duration":30,"images":[],"step":9},{"description":"Preheat BBQ to medium high. Flat iron hot plate is safer for wooden skewers (so they don''t catch fire) else use metal skewers on the grill side.","images":[],"step":10},{"title":"Skewer, oil & season","description":"Skewer per above. Drizzle with the oil (so it doesn''t stick to the BBQ) then sprinkle both sides with the salt and pepper.","images":[],"step":11},{"description":"BBQ cook for 3 minutes on each side.","duration":3,"images":[],"step":12},{"description":"Serve:","images":[],"step":13},{"description":"Pile Souvlaki onto a serving platter for DIY wraps with tzatziki (from this recipe), toasted pita bread and Greek salad (chopped small), or shredded lettuce and tomato slices. Else, make plates with lemon rice and a Greek Salad!","images":[],"step":14}]', '["gluten"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["greek-recipes","grilling-ideas-and-recipes","lamb","lamb-recipes","mains","mediterranean-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_122983ed27af', 'en', 'US', 'Vietnamese Lemongrass Pork steaks (tenderised!)', 'Recipe video above. Pork infused with a Vietnamese lemongrass marinade, then cooked over high heat for an authentic char-grill like you get at Vietnamese street stalls! Economical pork shoulder is a tough cut of meat that''s tenderised using a touch of baking soda. Even if you overcook these pork steaks, they are still tender inside!Use to make the popular Vietnamese rice noodle salad, Bún thịt nướng, or serve with coconut or jasmine rice and Asian slaw for a lovely dinner.', 'https://www.recipetineats.com/tachyon/2023/04/Vietnamese-noodles-lemongrass-pork-1.jpg', 15, 6, 21, 4, '[{"id": "ing_pork_shoulder", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_lemongrass", "quantity": {"value": 40.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_lime", "quantity": {"value": 0.12, "unit": "net of 500g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.019, "unit": "tub of 200g"}}]', '[{"ingredients":["500g/1 lb pork shoulder (, skinless and boneless, or pork scotch (roast or steaks) (Note 1))","3 tbsp canola oil"]},{"ingredients":["2 lemongrass stalks (, white part only, bruised, cut into 1 cm / 0.4\" slices on angle (Note 2))","4 garlic cloves (, finely minced)","4 tbsp lime juice","3 tbsp fish sauce","1 tbsp soy sauce (all purpose or light, NOT dark soy, Note 3)","4 tbsp brown sugar (tightly packed tablespoons)","3 tbsp oil (canola, vegetable, peanut)","3/4 tsp baking soda/bi-carb (, for tenderising (Note 4))"],"purpose":"Marinade:"}]', '[{"title":"Cut pork","description":"Cut into 8 equal, thinnish slices of pork. I find it easiest using the knife on a 45° angle, but if you have the right shape piece you can just cut straight down.","images":[],"step":1},{"description":"Pound each steak to 5mm / 0.2\" thickness using the scary side of a meat mallet (jagged, not flat), using go-between (Note 5) or a freezer bag to avoid damaging the meat. (You can use baking paper for rolling pin or the flat side of the mallet.)","images":[],"step":2},{"title":"Marinade","description":"Mix the marinade ingredients in a bowl, it will fizz when the baking soda is added! Add pork then toss well to coat using tongs. Transfer to a ziplock bag and marinate for 24 hours.","images":[],"step":3},{"description":"Remove pork from the marinade and brush off the lemongrass pieces. Discard marinade - it''s done its job!","images":[],"step":4},{"title":"Cook","description":"Heat a cast iron skillet over high heat until you see wisps of smoke. Add 1 1/2 tbsp oil, then cook half the pork for 1 1/2 minutes on one side and 1 minute on the other side until nicely charred. Remove onto a plate. Scrape pan clean of loose black bits then cook the remaining pork.","images":[],"step":5},{"description":"Serve! Make Pork Noodle Bowls (bun thit nuong) or serve with rice and a side salad - see note 6 and in post for suggestions!","images":[],"step":6},{"title":"NOTE","description":"The thin pork steaks are beyond well done in 2 1/2 minutes but it doesn''t matter because the baking soda keeps them tender. It will be blushing pink inside due to the baking soda (same happens with beef). You could cook them for another 5 minutes and they will still be tender inside. Miracle!","images":[],"step":7}]', '["fish","gluten","peanuts","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["grilling-ideas-and-recipes","mains","pork","pork-recipes","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2cbbce58a9c1', 'en', 'US', 'Marinated Vegetarian Pasta Salad', 'Recipe video above! How do you make the best ever vegetable pasta salad? MARINATE the veggies. Roast or BBQ any veg you want, then toss in a marinade so they absorb the flavour while hot before mixing through pasta. This is a big, fat JUICY flavour loaded pasta salad that lasts for days and days - see PRO TIP for keeping pasta salads juicy!', 'https://www.recipetineats.com/tachyon/2019/07/Marinated-Vegetable-Pasta-Salad_6.jpg', 15, 30, 75, 8, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.8, "unit": "pack of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_feta_cheese", "quantity": {"value": 120.0, "unit": "block of 200g"}}, {"id": "ing_capsicum", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_asparagus", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 0.1, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.5, "unit": "pack of 100g"}}]', '[{"ingredients":["400g / 14oz curly pasta (, dried (or other of choice))","1/4 cup parsley (, roughly chopped (or chives))","120g / 4oz feta (, crumbled into big chunks)"]},{"ingredients":["2 capsicum/bell peppers ((1 red, 1 yellow), cut into 2.5cm / 1\" pieces)","1 red onion (, cut into wedges)","1 eggplant (, halved lengthwise, then 1.25cm/ 0.5\" thick semi circles)","2 zucchini (, cut into 1.5cm / 2/3\" chunks (see video))","200g/ 7oz button mushrooms (, halved (large ones quartered))","1 bunch asparagus (, ends trimmed, cut into 5cm/2\" lengths)"],"purpose":"Vegetables (Note 1):"},{"ingredients":["1/4 cup (65ml) extra virgin olive oil","1 tsp each salt and pepper","3 cloves garlic (, minced)"],"purpose":"Roasting:"},{"ingredients":["1/3 cup (85ml) lemon juice","1/3 cup (85ml) extra virgin olive oil","2 tsp white sugar","2 garlic cloves (, minced)","1/2 tsp each salt and pepper","1/2 tsp each dried basil, parsley, oregano, thyme (Note 2)","1/2 - 1 tsp chilli flakes (adjust spice to taste, Note 3)"],"purpose":"Marinade / Dressing:"}]', '[{"description":"Marinade/Dressing:","images":[],"step":1},{"description":"Place ingredients in a jar and shake well. Set aside 10 minutes+.","images":[],"step":2},{"description":"Roasted Vegetables:","images":[],"step":3},{"title":"Preheat oven to 250°C/480°F (230°F fan)","description":"super high heat replicates BBQ charred edges.","images":[],"step":4},{"title":"Toss veggies in oil","description":"Place all vegetables other than asparagus in a large bowl. Drizzle with oil, sprinkle with salt, pepper and garlic, toss.","images":[],"step":5},{"description":"Spread vegetables on 2 trays (fill one less than the other). Roast 25 minutes, tossing once.","images":[],"step":6},{"title":"Add asparagus","description":"Drizzle asparagus with oil and pinch of salt and pepper. Add into oven for last 5 minutes.","images":[],"step":7},{"title":"BBQ Option","description":"See Marinated BBQ Vegetables for directions.","images":[],"step":8},{"title":"Marinate veggies","description":"Transfer vegetables into large bowl, pour over 1/2 the Dressing. Toss, then leave to marinate for 30 minutes to 3 hours.","duration":30,"images":[],"step":9},{"title":"Cook pasta + 2 minutes","description":"In large pot of salted water, cook pasta per packet directions but ADD 2 minutes to the cook time (Note 5 for why). Drain and return pasta into pot.","images":[],"step":10},{"description":"Add vegetables, including veg juices, into the pasta pot. Add remaining Dressing and parsley, then toss. Set aside for 15 minutes to cool slightly.","duration":15,"images":[],"step":11},{"title":"Serve! Sprinkle with feta and serve! Keeps 4","description":"5 days, serve at room temp.","images":[],"step":12},{"description":"Make ahead PRO TIP (Note 4):","images":[],"step":13},{"description":"SCOOP OUT a mug of pasta cooking water just before draining. Add 3 tbsp water to reserved Dressing (after marinating veg), shake well. Use this Dressing per above, but reserve 3 tbsp to freshen up pasta salad on Day 2 onwards.","images":[],"step":14},{"title":"Freshen up pasta salad","description":"Bring to room temp or briefly microwave (cold pasta = dry) to warm gently. Toss with Reserved Dressing then serve.","images":[],"step":15}]', '["gluten"]', '["vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["grilling-ideas-and-recipes","pasta-recipes","pasta-salads-and-rice-salads","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9f489d640e96', 'en', 'US', 'Slow cooked Beef Ribs with barbecue sauce (beef short ribs)', 'Recipe video above. Beef ribs slow braised in a silky, shiny homemade barbecue sauce until the meat is fall apart and ridiculously juicy inside, and the outside is bronzed and sticky. Also known as beef short ribs, this is one of the best cuts for slow cooking, far superior to beef chuck because there''s more marbling. Beef chuck always has some dry patches!100% perfect for make ahead and freezing.', 'https://www.recipetineats.com/tachyon/2020/09/Beef-Short-Ribs.jpg', 15, 240, 255, 6, '[{"id": "ing_beef_steak", "quantity": {"value": 6.0, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.019, "unit": "jar of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.25, "unit": "bottle of 500ml"}}, {"id": "ing_ketchup", "quantity": {"value": 0.45, "unit": "bottle of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["6 x 300 - 350g / 10 - 12 oz beef ribs ((aka beef short ribs) (Note 1), patted dry)"]},{"ingredients":["1 tbsp brown sugar (sub white)","2 tsp paprika","1 tsp garlic powder (sub 1 tsp fresh garlic)","1 tsp onion powder (sub garlic powder)","1/2 tsp cumin powder","3/4 tsp mustard powder (Note 2)","1 tsp cooking salt / kosher salt (reduce by 25% for table salt, increase 50% for salt flakes)","1/2 tsp black pepper"],"purpose":"RUB:"},{"ingredients":["2 garlic cloves (, minced (sub 2 tsp powder))","1/2 cup apple cider vinegar (Note 2 subs)","1 1/2 cups ketchup (, or Aussie tomato sauce)","1/2 cup brown sugar (, loosely packed (ie don''t pack it tight)(sub white))","2 tsp EACH black pepper, onion powder, mustard powder (Note 2)","1 tsp cayenne pepper (adjust to taste re: spiciness)","1 tbsp Worcestershire sauce (sub soy sauce)","2 cups water"],"purpose":"Barbecue SAUCE:"},{"ingredients":["Parsley or chives (, chopped)"],"purpose":"Optional garnish:"}]', '[{"description":"Coat ribs in rub, mix sauce except water in pan, then add water. Bake ribs in sauce covered 3.5 hrs at 160°C/320°F, turn, then 30 min uncovered. Serve!","images":[],"step":1},{"description":"Preheat oven to 160°C/320°F (both fan & standard).","images":[],"step":2},{"title":"Rub","description":"Mix Rub in a small bowl large, enough to fit one rib. Press beef ribs into the rub, coating all sides. Shake off excess.","images":[],"step":3},{"title":"BBQ Sauce","description":"Mix Barbecue Sauce ingredients, except water, in a baking pan. Then mix in water.","images":[],"step":4},{"title":"Coat","description":"Place ribs in sauce, turning to coat. Arrange meat side down in the sauce, bone side exposed (sauce won''t cover completely, that''s ok).","images":[],"step":5},{"title":"Bake 3.5 hours","description":"Cover tightly with foil or lid, bake 3 1/2 hours. Remove from oven, remove foil. Turn ribs (some may have fall over, that''s ok, just turn them). Spoon over sauce.","images":[],"step":6},{"title":"Bake 30 min","description":"Bake 30 minutes uncovered, spooning over sauce again halfway through, until surface is caramelised and sticky. Check to ensure ribs are tender - pry a bit apart using two forks. (If not, cover and return to oven, but after 4 hrs they certainly should be!)","images":[],"step":7},{"title":"Serve","description":"Remove ribs onto serving plate (use a spoon as meat will barely be attached to bone, if at all). Mix sauce to bring together (Note 3 on adjustments). Serve with ribs! (See below for serving suggestions)","images":[],"step":8}]', '["gluten","mustard","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Southern","Western"],"categories":["beef","beef-recipes","grilling-ideas-and-recipes","mains","slow-cooked-fall-apart","slow-cooker-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d3952a77e07a', 'en', 'US', 'Spanish Paella', 'Recipe video above. The most famous Spanish dish of them all! Paella is meant to be a fun relaxed dish, so don''t get hung up about having the exact same seafood I''ve used - see Notes. And don''t be scared of making paella - it is actually very forgiving if you have the right liquid/rice ratios and follow the order in which I cook things!Note on Chorizo - NOT in traditional Spanish Paella recipes however, it''s widely used in Spanish restaurants outside of Spain. Australia would faint if I excluded it. So it''s in!', 'https://www.recipetineats.com/tachyon/2016/08/Paella-8.jpg', 15, 30, 45, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_chorizo", "quantity": {"value": 0.198, "unit": "kg"}}, {"id": "ing_squid", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_rice", "quantity": {"value": 225.0, "unit": "pack"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_saffron_threads", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_shrimp", "quantity": {"value": 12.0, "unit": "kg"}}, {"id": "ing_2_lbs_mussels", "quantity": {"value": 12.0, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 4.0, "unit": "net of 500g"}}]', '[{"ingredients":["1 - 2 tbsp olive oil","7 oz / 200g chorizo (2 pieces) (, sliced 1/2 cm / 1/5\" thick (Note 1))","200g / 6 oz squid (calamari) (, cut into 7mm / 1/4\" thick rings (Note 2))","1 onion (, diced (brown, white, yellow))","3 garlic cloves (, minced)","1 red capsicum / bell pepper (, diced)","1 1/2 cups paella rice (\"Bomba\", \"Valencia\" or \"Calasparra\" rice) (Note 3)","2 juicy ripe tomatoes, peeled and diced (OR 3/4 cup canned crushed tomato (Note 4))","300g / 10 oz chicken thigh fillets (, cut into 1.5\" / 3.5cm pieces)","3 1/2 cups chicken broth/stock (not low sodium) ( or homemade seafood broth (Note 5))","1 tsp saffron threads (or 1/4 tsp ground saffron, Note 6)","1 cup frozen peas","12- 16 medium / large prawns (, whole (shell on) (Note 7))","12 large mussels (, cleaned & check freshness (Note 8))"]},{"ingredients":["Fresh parsley (, chopped)","2 Lemons (, cut into wedges)"],"purpose":"Garnish"}]', '[{"title":"Chorizo","description":"Heat 1 tbsp oil in a 30cm / 10\" paella pan or large skillet over high heat (Note 9). Add chorizo and cook until browned on each side (~ 3 minutes). Remove with a slotted spoon and set aside.","images":[],"step":1},{"title":"Squid","description":"Add squid and cook for 45 seconds on each side, then remove and set aside.","duration":0.75,"images":[],"step":2},{"title":"Garlic, onion, capsicum","description":"Add remaining oil (if needed). Add garlic and onion, cook for 2 minutes. Add capsicum, cook for 1 minute.","duration":2,"images":[],"step":3},{"title":"Chicken","description":"Add chicken. Cook for 2 minutes until lightly browned but still raw inside.","duration":2,"images":[],"step":4},{"title":"Add Rice","description":"Add rice and mix until the grains are coated in oil.","images":[],"step":5},{"title":"Cooking broth","description":"Add in most of the chorizo (reserve 1/4 for garnish), chicken stock, fresh or crushed tomato and saffron. Stir.","images":[],"step":6},{"title":"Simmer 1","description":"Bring it to a simmer then adjust heat so it''s simmering fairly gently (not super rapidly, will burn rice). Simmer for 10 minutes - no stirring! At this stage, a bit of rice should be poking through to the surface but there should still be plenty of liquid.","duration":10,"images":[],"step":7},{"title":"Add peas, prawns and mussels","description":"Scatter over peas, squidge the prawns and mussels into the rice (partial submerge is fine).","images":[],"step":8},{"title":"Simmer 2","description":"Cook for 8 minutes (turn prawns halfway if you think it''s necessary) or until prawns are opaque, mussels are open, and most of the liquid has been absorbed but still a bit liquidy. Discard any mussels that do not open. Remove from stove.","duration":8,"images":[],"step":9},{"title":"Check rice","description":"Do a taste test to see if the rice is cooked - it should be firm but cooked. If it is too firm for your taste, no stress, just add a splash of hot water (not too much!) and keep cooking.","images":[],"step":10},{"title":"Rest","description":"Scatter over squid and reserved chorizo (residual heat will warm through), cover with lid then rest for 5 minutes (rice will absorb remainig liquid). Paella rice should now be tender but \"juicy\", not stodgy and thick (if it is, add splash of water to loosen it).","duration":5,"images":[],"step":11},{"title":"Garnish","description":"scatter with parsley and wedges of lemon. Take to table as is, then mix up rice with seafood before serving!","images":[],"step":12}]', '["shellfish"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Spanish"],"categories":["chicken-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","iconic-dishes","mediterranean-recipes","prawns-shrimp","quick-and-easy","seafood-recipes","spanish-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e36e6d0302c9', 'en', 'US', 'Huli Huli Chicken (Tropical Hawaiian chicken)', 'Recipe video above. There''s just no chance you make this without doing a little hula dance… swish those hips!!! Traditional Hawaiian recipe with in-your-face tropical flavours. Sweet, savoury, very sticky! Best 24 - 48 hr marinade, but you can get away with 3 hrs but baste extra generously.IMPORTANT: Do not use pureed fresh pineapple or fresh, pure pineapple juice from the fridge - it will over tenderise chicken, see Note 2. Use any pineapple juice sold in the aisles, not fridge - can, bottle or vac packed.', 'https://www.recipetineats.com/tachyon/2020/07/Hawaiian-Huli-Huli-Chicken_1.jpg', 10, 12, 22, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_pineapple", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_ginger", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 7.5, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.5, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.125, "unit": "bottle of 500ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_sriracha", "quantity": {"value": 0.037, "unit": "bottle of 400ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_pineapple", "quantity": {"value": 0.75, "unit": "unit"}}]', '[{"ingredients":["1.5 kg / 3 lb chicken thighs (or breast, Note 1)","1 tbsp vegetable oil"]},{"ingredients":["3/4 cup pineapple juice, canned or bottled (NOT FRESH!) (, unsweetened (Note 2))","1 1/2 tbsp ginger (, freshly grated (Note 3))","1 1/2 tbsp garlic (, freshly grated (Note 3))","1/2 cup tomato ketchup (or Aussie tomato sauce)","1/2 cup soy sauce","1/4 cup sherry or Chinese cooking wine (Note 4)","1/4 cup brown sugar","1 tbsp Sriracha","2 tbsp rice vinegar (or cider vinegar)","1 tbsp sesame oil (, toasted)"],"purpose":"Marinade:"},{"ingredients":["Sliced green onion","Pineapple slices (, grilled for 3 minutes on each side for lines)"],"purpose":"Garnishes, optional:"}]', '[{"description":"Mix marinade, set aside 3/4 cup (185 ml) for basting.","images":[],"step":1},{"description":"Pour the rest over the chicken in a glass or ceramic container (not metal or plastic), coat chicken then marinade 24 - 48 hours.","images":[],"step":2},{"description":"Cooking:","images":[],"step":3},{"description":"Brush BBQ grills with oil then preheat to medium high, or heat oil in a skillet over medium high heat.","images":[],"step":4},{"description":"Drain excess marinade from chicken, place on BBQ/skillet.","images":[],"step":5},{"title":"Cook the first side for 2","description":"3 minutes until golden (adjust heat if browning too fast), then flip and cook for 2 minutes.","duration":2.5,"images":[],"step":6},{"description":"Baste (dab) generously with reserved marinade, then flip and cook for 1 minute.","duration":1,"images":[],"step":7},{"description":"Repeat this every minute or so for a total cook time of 10 minutes, or until internal temp in the thickest part registers 75°C/167°F (for thigh) or 65°C / 150°F (for breast).","images":[],"step":8},{"description":"Transfer chicken to a plate, loosely cover with foil and rest for 3 minutes before serving, garnished with green onion if desired.","duration":3,"images":[],"step":9}]', '["gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Hawaiian","Tropical!"],"categories":["chicken-breast-recipes","chicken-recipes","grilling-ideas-and-recipes","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9bc75da5bbef', 'en', 'US', 'Honey Soy Chicken - Marinade and Sauce (excellent grilled!)', 'Recipe video above. This is my premium recipe for Honey Soy chicken, a step up from this quick Honey Garlic Chicken and easy Baked Honey Soy Chicken, neither of which call for marinating. One mixture is used as a marinade, for basting, and also to make a fabulous glossy sauce to drizzle over the chicken and everything on your plate. It''s especially good for grilling! (More BBQ recipes here) Pictured with Pineapple Fried Rice.Other chicken cuts - For wings, use the Honey Soy Wings recipe. For drumsticks and bone-in thighs, use the Honey Soy Baked Chicken recipe.', 'https://www.recipetineats.com/tachyon/2020/06/Honey-Soy-Chicken_4.jpg', 10, 20, 30, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.25, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.5, "unit": "bottle of 250ml"}}, {"id": "ing_honey", "quantity": {"value": 0.333, "unit": "jar of 500g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.125, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.03, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 7.5, "unit": "pack of 3 heads"}}, {"id": "ing_water", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.019, "unit": "pack of 400g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1.25 - 1.5 kg/ 2.5 - 3 lb skinless boneless chicken thighs OR breast (Note 1)","1 tbsp vegetable oil (, for cooking)"]},{"ingredients":["1/2 cup soy sauce (, all purpose or light (not dark, Note 2))","2/3 cup honey (sub maple syrup)","1/3 cup cider vinegar (or rice vinegar)","1/4 cup Chinese cooking wine or dry sherry (key ingredient, Note 3)","1 tbsp sesame oil (, toasted (Note 4))","1 1/2 tbsp garlic (, finely minced)"],"purpose":"Honey Soy Marinade Sauce:"},{"ingredients":["1/3 cup water","1 1/2 tsp cornflour/cornstarch"],"purpose":"Serving Sauce:"},{"ingredients":["Green onion (, finely sliced)","Sesame seeds"],"purpose":"Garnishes (optional):"}]', '[{"description":"Marinade Sauce:","images":[],"step":1},{"description":"Place ingredients in a jug and mix well until honey is completely dissolved.","images":[],"step":2},{"description":"Reserve 1/4 cup for Basting, refrigerate. (Note 5)","images":[],"step":3},{"description":"Reserve 2/3 cup for Serving Sauce, refrigerate.","images":[],"step":4},{"title":"Marinade Chicken","description":"Pour remaining marinade over chicken in a container. Coat chicken thoroughly. Cover, refrigerate 24 to 48 hours (minimum 3 hrs).","images":[],"step":5},{"description":"Serving Sauce (Makes 1 cup):","images":[],"step":6},{"description":"Place reserved sauce in a small saucepan. Mix cornflour and water, then add into saucepan.","images":[],"step":7},{"description":"Simmer over medium for 5 minutes, stirring regularly, until it thickens to a syrupy consistency. Set aside and keep warm. (If it gets too thick, just add a bit more water)","duration":5,"images":[],"step":8},{"description":"Cook:","images":[],"step":9},{"description":"Brush BBQ plate or grills with oil and heat to medium high. Or heat oil in a large skillet over medium high heat.","images":[],"step":10},{"title":"THIGHS","description":"Place chicken on BBQ. Cook the first side for 2 minutes, then flip and dab with reserved Basting Sauce. Cook for 2 minutes, flip and baste. Then flip/baste every 1 minute for total cook time of ~ 10 minutes or until a thermometer reads 75°C/165°F.","duration":2,"images":[],"step":11},{"title":"BREAST","description":"Cook first side 2 minutes, flip, baste. Cook 2 minutes, then flip and baste every 45 sec or so for total cook time of ~8 minutes (internal temp 66°C / 151°F).","images":[],"step":12},{"title":"REST","description":"Transfer to serving plate, cover loosely with foil and rest for 5 minutes.","duration":5,"images":[],"step":13},{"description":"SERVE chicken garnished with sesame seeds and green onion, with sauce on the side so people can help themselves.","images":[],"step":14}]', '["gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian-esque","Western"],"categories":["chicken-breast-recipes","chicken-recipes","grilling-ideas-and-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_946d7108572e', 'en', 'US', 'Sticky Grilled Chicken', 'Recipe video above. Sticky, savoury and sweet, this is the marinade I use for grilled chicken that I know is a guaranteed hit with everyone, kids and adults! It tastes like a country-style rub, and it''s finger licking'' good.', 'https://www.recipetineats.com/tachyon/2019/07/Sticky-Grilled-Chicken_7.jpg', 10, 10, 1460, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_ketchup", "quantity": {"value": 0.15, "unit": "bottle of 500g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.25, "unit": "bottle of 250ml"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 20.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}]', '[{"ingredients":["700g/ 1.4lb chicken thighs (, skinless boneless (Note 1))"]},{"ingredients":["1/2 cup ketchup","1/3 cup brown sugar (, packed)","1/4 cup soy sauce (, all purpose or light (NOT dark))","2 tbsp apple cider vinegar","2 tbsp olive oil","4 tsp Worcestershire Sauce","4 garlic cloves (, minced)"],"purpose":"Marinade / Glaze (Note 2 for subs):"}]', '[{"description":"Mix Marinade in a large bowl.","images":[],"step":1},{"description":"Scoop out 1/2 cup and reserve for basting (\"Glaze\").","images":[],"step":2},{"description":"Add chicken, turn to coat. Marinade overnight (minimum 3 hours, up to 48 hours, or freeze).","images":[],"step":3},{"description":"Brush BBQ with vegetable or canola oil, then preheat to medium.","images":[],"step":4},{"description":"Pick up chicken, allowing excess Marinade to drip off.","images":[],"step":5},{"description":"Place on BBQ, cook 4 minutes until nicely caramelised.","images":[],"step":6},{"description":"Turn chicken, then brush generously with Glaze. Cook 4 minutes.","images":[],"step":7},{"description":"Flip, brush with more Glaze, flip again and brush with Glaze.","images":[],"step":8},{"description":"Remove chicken onto plate, cover loosely with foil.","images":[],"step":9},{"description":"Rest 3 minutes before serving, sprinkled with parsley if using. Pictured in post with Macaroni Salad!","images":[],"step":10},{"title":"Stove","description":"follow up steps in a non stick pan, heated to medium high with 1 tbsp oil (cook in batches if needed).","images":[],"step":11},{"title":"Oven","description":"use this recipe: Sticky Baked Chicken","images":[],"step":12}]', '["gluten","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-recipes","grilling-ideas-and-recipes","main-dishes","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b0e8d796cad9', 'en', 'US', 'Beef Steak Marinade', 'Recipe video above. This is a marinade to transform good value steaks by making them juicier, more tender and adding a hint of flavour while not overpowering the flavour of the beef. With this marinade, you won''t need a sauce for the beef, though I can never resist some garlic butter!', 'https://www.recipetineats.com/tachyon/2016/07/Steak-Marinade_4.jpg', 5, 5, 730, 2, '[{"id": "ing_beef_steak", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["2 steaks (, economical (Note 1))"]},{"ingredients":["1 tsp Dijon mustard","1/2 tsp minced garlic (1 large garlic clove)","1/2 tsp onion powder (or sub with garlic powder)","1 tbsp soy sauce (Note 2)","1 tbsp oil (I use olive oil, but any oil is fine)","1 tbsp Worcestershire sauce","1 tbsp balsamic vinegar","Black pepper"],"purpose":"Marinade"}]', '[{"description":"Mix together mustard, garlic and onion powder. Then mix in remaining ingredients.","images":[],"step":1},{"description":"Place beef in a ziplock bag with Marinade and marinade overnight (12 - 24 hours).","images":[],"step":2},{"description":"Remove from the fridge 30 minutes before cooking to bring to room temperature - key for even cooking of steaks. Shake off excess marinade.","images":[],"step":3},{"description":"Brush BBQ Grills with oil, then heat on high heat until is really hot - you should see wisps of smoke. Or heat a heavy based skillet on high until very hot, then add oil - it will heat almost instantly.","images":[],"step":4},{"description":"Add steaks. For 2cm / 3/4\" thick steaks, cook the first side for 2 minutes, then turn and cook the other side for 2 minutes (medium rare 52°C/125°F, chart below for other doneness temps). (Note 3)","duration":2,"images":[],"step":5},{"description":"Remove from skillet onto a WARM plate, cover loosely with foil and set aside for 5 minutes.","duration":5,"images":[],"step":6},{"title":"Serve! I couldn''t resist garlic butter","description":"see recipe in notes.","images":[],"step":7}]', '["gluten","mustard","soy"]', '["high_protein","keto_friendly","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a2cffd800f15', 'en', 'US', 'Fish Tacos', 'Recipe video above. Fish marinated in classic Mexican fresh flavours, seared until golden, are perfect for tacos. The lightly pickled red cabbage is a perfect accompanied for the soft fish, a great texture contrast. A wonderful recipe for white fish fillets, you will NOT miss deep fried fish!', 'https://www.recipetineats.com/tachyon/2016/05/Fish-Tacos_4-1.jpg', 15, 10, 45, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.544, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_chipotle", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_jalapeno", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_red_cabbage", "quantity": {"value": 12.0, "unit": "head"}}, {"id": "ing_green_onion", "quantity": {"value": 0.06, "unit": "bunch"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.45, "unit": "tub of 250g"}}, {"id": "ing_sriracha", "quantity": {"value": 2.0, "unit": "bottle of 400ml"}}, {"id": "ing_tortillas", "quantity": {"value": 12.0, "unit": "pack of 8"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}]', '[{"ingredients":["1.2 lb / 600g firm white fish fillets (Note 1)","Zest of 1 lime","3 tbsp lime juice","1 tbsp chipotle powder (Note 2)","1 tbsp canned jalapeno (, finely chopped)","1/4 cup cilantro / coriander (, finely chopped)","2 garlic cloves (, minced)","3 tbsp olive oil","Salt and pepper"],"purpose":"Fish Marinade"},{"ingredients":["4 cups red cabbage (, finely shredded)","3 green onion stems (, finely sliced on the diagonal)","2 tbsp red wine vinegar (or white wine vinegar, cider vinegar)","1/2 tsp salt"],"purpose":"Quick Pickled cabbage"},{"ingredients":["3/4 cup sour cream (or yogurt)","2 - 3 tbsp sriracha (, adjust to taste (Note 3))"],"purpose":"Pink Taco Sauce"},{"ingredients":["1 tbsp olive oil","12 small tortillas ((corn or flour), warmed)","lime wedges","coriander/cilantro leaves"],"purpose":"To Cook & Serve"}]', '[{"title":"Marinade fish","description":"Combine Fish Marinade ingredients in a ziplock bag. Set aside for 20 minutes to marinate - no longer than 1 hour.","duration":20,"images":[],"step":1},{"title":"Pickled Cabbage","description":"Place Pickled Cabbage ingredients in a bowl. Toss to combine and set aside for 30 minutes. Drain excess liquid, scrunch cabbage with your hands (to help soften). Set aside.","duration":30,"images":[],"step":2},{"title":"Pink Sauce","description":"Mix to combine.","images":[],"step":3},{"title":"Cook fish","description":"Heat oil in a skillet over high heat. Cook fish for 2 minutes on each side, or until golden and cooked.","duration":2,"images":[],"step":4},{"description":"Remove fish onto plate then flake into large pieces.","images":[],"step":5},{"description":"To assemble tacos, top with cabbage then fish, a dollop of sour cream and a squeeze of lime juice. Fold tortilla over and enjoy!","images":[],"step":6}]', '["fish","gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["dietary","fish-recipes","gluten-free-recipes","grilling-ideas-and-recipes","low-calorie-recipes","mexican-recipes","most-popular","quick-and-easy","seafood-recipes","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_38731e98ea9b', 'en', 'US', 'Avocado Chicken Burgers', 'Recipe video above. Ground chicken burgers can be so bland and boring. Not these! Parmesan, garlic and a hint of dried sage adds great savoury flavour, and you’ll love how these cook up beautifully golden with crispy edges!', 'https://www.recipetineats.com/tachyon/2019/08/Avocado-Chicken-Burgers_9.jpg', 15, 10, 25, 4, '[{"id": "ing_chicken", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_sage", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_lettuce", "quantity": {"value": 1.2, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.003, "unit": "jar of 400g"}}, {"id": "ing_french_fries", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["500g/ 1.2 lb ground chicken (mince) (Note 1)","1 cup panko breadcrumbs","1 egg","3/4 cup parmesan (, finely grated (Note 2))","1 cup green onion (, finely sliced (~2 stems))","2 garlic cloves (, minced)","1/2 tsp dried sage (Note 3)","1/2 tsp salt and pepper (, each)"],"purpose":"Chicken Burger Patties:"},{"ingredients":["2 tbsp olive oil","4 soft burger buns or brioche buns","1 avocado (big!) (or 2 medium)","60g / 2 oz rocket / arugula or other lettuce of choice","2 tomatoes (, sliced)","4 slices Swiss cheese (or other cheese)","Mayonnaise, relish, ketchup or tomato sauce (to smear lid)"],"purpose":"Burgers:"},{"ingredients":["French fries","Baked potato wedges"],"purpose":"On the side"}]', '[{"description":"Chicken Burger Patties","images":[],"step":1},{"description":"Place Pattie ingredients in bowl, mix well with hands.","images":[],"step":2},{"description":"Form 4 patties, 1.5cm / 3/5\" thick, slightly larger than the buns (shrinks slightly). If mixture is super sticky (Note 4), either refrigerate mixture for 30 minutes, or wet hands or lightly spray hands with oil (I do this).","duration":30,"images":[],"step":3},{"description":"Heat oil in skillet over medium high heat. Add patties, working in batches. Cook for 2 minutes or until deep golden, then flip.","duration":2,"images":[],"step":4},{"description":"After 1 minute, top with a piece of cheese and place lid on to melt cheese.","images":[],"step":5},{"description":"Once cheese is melted, remove patties from skillet.","images":[],"step":6},{"description":"Split buns and lightly toast in oven or under broiler/grill.","images":[],"step":7},{"description":"Cut avocado in half, scoop out a generous amount then \"smash\" it on the base of the bun with a fork. Sprinkle with salt and pepper.","images":[],"step":8},{"description":"Top with Chicken Pattie, then rocket/arugula and tomato.","images":[],"step":9},{"description":"Smear the top bun with mayonnaise (or relish, ketchup, other condiment of choice) and place lid on bun.","images":[],"step":10},{"description":"Devour and be happy!","images":[],"step":11}]', '["egg","milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["burger-recipes","chicken-mince-recipes","chicken-recipes","dinner-tonight","grilling-ideas-and-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8e1a22cf6ea9', 'en', 'US', 'Chimichurri Steak', 'Recipe video above. An essential part of Argentinian cuisine, Chimichurri Sauce is steadily growing in popularly throughout the rest of the world - with good reason! It''s fresh, zingy with a bit of a bite, and pairs so perfectly with a simple grilled steak. It''s also fantastic with fish, chicken and pork!', 'https://www.recipetineats.com/tachyon/2016/08/Steak-with-Chimichurri-Sauce_1.jpg', 5, 10, 15, 4, '[{"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 cup parsley leaves (, tightly packed)","1 tbsp oregano leaves (, tightly packed (still lovely without))","4 garlic cloves (, minced)","0 - 2 tsp red pepper flakes (optional - adjust to taste)","1/4 cup (65 ml) red wine vinegar (Note 1)","1/2 tsp salt","Black pepper","1/2 cup (125 ml) extra virgin olive oil"],"purpose":"Chimichurri Sauce"},{"ingredients":["700g / 1.4lb flat iron, flank, skirt steak (or other steak of choice, at room temperature (Note 3))","Salt and pepper"],"purpose":"Steak"}]', '[{"description":"Chimichurri Sauce","images":[],"step":1},{"description":"Place all ingredients except oil in a food processor. Whizz until parsley is finely chopped, but not pureed - see video or photos. Alternatively chop parsley by hand.","images":[],"step":2},{"description":"Transfer into a small bowl. Add oil, gently stir. Set aside for 1 hour before use, overnight is even better!","images":[],"step":3},{"description":"Store in an airtight container in the refrigerator and use within 3 days (Note 3). Makes 3/4 cup.","images":[],"step":4},{"description":"Take steak out of the fridge 30 minutes prior to cooking.","images":[],"step":5},{"description":"Heat BBQ or heavy based skillet with 1 tbsp vegetable or canola oil over high heat until smoking.","images":[],"step":6},{"description":"Sprinkle each side of steak generously with salt and pepper.","images":[],"step":7},{"description":"Add steak and cook to your liking.","images":[],"step":8},{"title":"Cook times","description":"for steak 2cm / 4/5” thick, 2 min on each side for medium rare (until internal temp is 52C/125F, will rise to 54C/130F after resting) OR 2 1/2 min each side for medium (internal temp 57C/135F, will rise to 60C/140F).","images":[],"step":9},{"description":"Transfer to a plate, cover loosely with foil and rest for 5 - 10 minutes.","duration":7.5,"images":[],"step":10},{"description":"Cut thin slices against the grain (see photo below) and serve with Chimichurri Sauce on the side so people can help themselves.","images":[],"step":11}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Argentinian"],"categories":["beef-recipes","dietary","dinner-tonight","gluten-free-recipes","grilling-ideas-and-recipes","main-dishes","quick-and-easy","roast-beef","south-american-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f02244be45ca', 'en', 'US', 'A great Chicken Marinade (great grilled or pan seared!)', 'Recipe video above. This is a great everyday Chicken Marinade, one you make with things you''ve already got with plenty of sub options (see notes). It will make any cut of chicken extra juicy, infuse it with savoury flavour that''s a touch of sweet, with a hint of herby goodness. Especially good for chicken breast, and terrific for grilling!', 'https://www.recipetineats.com/tachyon/2019/06/Grilled-Chicken-Marinades-Cover-Graphic.jpg', 5, 10, 15, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.3, "unit": "bottle of 250ml"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}]', '[{"ingredients":["700g / 1.4 lb chicken breast, tenderloins or thigh (Note 1)"]},{"ingredients":["2 tbsp honey OR brown sugar","1 tbsp olive oil (or any oil)","5 tbsp soy sauce","2 tbsp lemon juice","2 tsp Worcestershire sauce","4 garlic cloves (, minced)","1 tsp dried oregano (or rosemary, thyme, minced herbs)","1/2 tsp black pepper (, ground)"],"purpose":"Chicken marinade (subs Note 3):"},{"ingredients":["Finely chopped parsley","Lemon slices"],"purpose":"Garnishes (optional)"}]', '[{"title":"Recommended","description":"Pound breast to even thickness using a meat pounder, rolling pin, or fist. OR cut large ones in half horizontally to form 2 cutlets (steaks) for each.","images":[],"step":1},{"description":"Mix marinade in a ziplock bag (or container in which chicken fits snugly). Add chicken.","images":[],"step":2},{"description":"Marinate 3 hours to overnight, though even 30 minutes is effective. (Note 2)","images":[],"step":3},{"description":"Heat 1 tbsp olive oil in a large skillet over medium high heat, and cook chicken per times below until deep golden (see video). If browning too quickly, lower heat.","images":[],"step":4},{"description":"Transfer to serving plate, cover loosely with foil and rest for 3 minutes before serving, garnished with parsley and lemon slices if desired.","duration":3,"images":[],"step":5},{"description":"Cook times:","images":[],"step":6},{"title":"Whole breast and boneless thighs: 3","description":"4 minutes each side (internal temp 165F/75C)","images":[],"step":7},{"title":"Cutlets and tenderloin","description":"2 minutes each side","images":[],"step":8}]', '["gluten","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","grilling-ideas-and-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d7ea4ab4ac20', 'en', 'US', 'Crispy Grilled Shrimp (Prawns) with Lemon Butter Sauce', 'Recipe video above. Seasoned and CRISPY on the outside, juicy on the inside, drizzled with a simple-yet-incredible lemon butter sauce, you''ll love the little crispy little golden garlic bits in the sauce! This is a recipe made for the BBQ, but works great on the stove too (Note 4).', 'https://www.recipetineats.com/tachyon/2019/06/Crispy-Grilled-Shrimp-Lemon-Butter-Sauce_2.jpg', 5, 10, 15, 4, '[{"id": "ing_butter", "quantity": {"value": 90.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_shrimp", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["90g / 6 tbsp butter (, unsalted)","1/4 tsp salt","3 tsp garlic (, very finely chopped (do not use mincer, Note 1))","1.5 tbsp lemon juice (, plus more to taste)"],"purpose":"Lemon Garlic Butter:"},{"ingredients":["500g/ 1 lb large shrimp / prawns (, raw, peeled and deveined (Note 2))","1 tsp garlic powder","1 tsp smoked paprika (plain or sweet ok too)","1/4 tsp cayenne pepper","1 tbsp lemon juice (skip if using stove)","2 tbsp olive oil","1/2 tsp salt","1/4 tsp pepper"],"purpose":"Shrimp/Prawns:"},{"ingredients":["1 lemon (, halved, grilled if desired)","Lemon wedges or slices","2 tbsp finely chopped parsley"],"purpose":"Serving (optional):"}]', '[{"description":"Brush BBQ grills with oil, then preheat on high until very hot.","images":[],"step":1},{"description":"If shrimp are small and might fall through grills, skewer them (use 2 skewers, Note 3)","images":[],"step":2},{"description":"Melt butter in a small saucepan over medium high heat.","images":[],"step":3},{"description":"Add garlic and salt. Stir until garlic is LIGHT golden brown, then immediately remove from stove (residual heat will make garlic golden & crispy).","images":[],"step":4},{"description":"Stir through lemon.","images":[],"step":5},{"title":"Shrimp/Prawns (Stove","description":"Note 4):","images":[],"step":6},{"description":"Pat shrimp dry with paper towels (to ensure crispiness!)","images":[],"step":7},{"description":"Just prior to cooking, place in bowl, sprinkle/drizzle over remaining ingredients. Toss gently to coat.","images":[],"step":8},{"description":"Working quickly, place shrimp on BBQ and cook each side for 2 minutes until golden and crusty.","duration":2,"images":[],"step":9},{"description":"Immediately remove shrimp onto serving plate.","images":[],"step":10},{"description":"Drizzle over all the Lemon Garlic Butter, sprinkle with parsley and serve immediately with fresh lemon.","images":[],"step":11},{"description":"Crusty bread to mop up the crazy delish butter on the plate is essential!","images":[],"step":12}]', '["milk","shellfish"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["grilling-ideas-and-recipes","prawns-shrimp","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6764a38a414b', 'en', 'US', 'Marinated Grilled Salmon', 'Recipe VIDEO above. Make your next grilled salmon AMAZING with a simple yet incredible Salmon Marinade that will infuse the salmon with extra flavour! It''s savoury with a touch of sweet and hint of garlic, and does double duty as a sauce for serving!', 'https://www.recipetineats.com/tachyon/2019/06/Marinated-Grilled-Salmon_8.jpg', 5, 12, 17, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.333, "unit": "bottle of 250ml"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_honey", "quantity": {"value": 0.09, "unit": "jar of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}]', '[{"ingredients":["4 salmon fillets (, skin on best (150-180g/5-6oz each, Note 1))","Olive oil (, for cooking)"]},{"ingredients":["1/3 cup (85 ml) soy sauce (, low sodium)","2 tbsp lemon juice","3 tbsp honey","2 tbsp olive oil","2 garlic cloves (, minced)"],"purpose":"Marinade (Sauce)- Note 2:"},{"ingredients":["Parsley, chives or green onion (, finely chopped)","Lemon slices"],"purpose":"Serving (optional)"}]', '[{"description":"Place marinade in a ziplock bag and mix to combine.","images":[],"step":1},{"title":"Add salmon and massage to coat. Marinate for 3","description":"24 hours (1 hr minimum).","images":[],"step":2},{"description":"Take out of fridge 30 minutes prior to cooking.","images":[],"step":3},{"description":"Remove salmon onto plate, allowing excess marinade to drain off.","images":[],"step":4},{"description":"Sauce (basting + serving):","images":[],"step":5},{"description":"Pour remaining marinade into a small saucepan and simmer over medium high for 3 to 5 minutes until syrupy.","duration":4,"images":[],"step":6},{"description":"Pour into bowl/jug (some used for basting, some for serving).","images":[],"step":7},{"description":"Brush BBQ grills with oil. Then preheat to medium (or medium low for strong BBQ''s).","images":[],"step":8},{"description":"Drizzle salmon with oil, the place onto the BBQ flesh side down (skin side up).","images":[],"step":9},{"description":"Cook for 3 minutes or until golden, then use tongs to carefully turn.","duration":3,"images":[],"step":10},{"description":"Brush the flesh with Sauce, then close BBQ lid.","images":[],"step":11},{"title":"Cook for 3","description":"4 minutes, basting one more time halfway through, or until the internal temperature is 50C/120F(medium rare) or 55C/130F (medium).","duration":3.5,"images":[],"step":12},{"description":"Transfer salmon to plate and serve with remaining Sauce.","images":[],"step":13}]', '["fish","gluten","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","fish-recipes","grilling-ideas-and-recipes","quick-and-easy","salmon-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9ccf041ee881', 'en', 'US', 'A great Chicken Marinade (great grilled or pan seared!)', 'Recipe video above. This is a great everyday Chicken Marinade, one you make with things you''ve already got with plenty of sub options (see notes). It will make any cut of chicken extra juicy, infuse it with savoury flavour that''s a touch of sweet, with a hint of herby goodness. Especially good for chicken breast, and terrific for grilling!', 'https://www.recipetineats.com/tachyon/2019/05/Chicken-Marinade_8-1.jpg', 5, 10, 15, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.3, "unit": "bottle of 250ml"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}]', '[{"ingredients":["700g / 1.4 lb chicken breast, tenderloins or thigh (Note 1)"]},{"ingredients":["2 tbsp honey OR brown sugar","1 tbsp olive oil (or any oil)","5 tbsp soy sauce","2 tbsp lemon juice","2 tsp Worcestershire sauce","4 garlic cloves (, minced)","1 tsp dried oregano (or rosemary, thyme, minced herbs)","1/2 tsp black pepper (, ground)"],"purpose":"Chicken marinade (subs Note 3):"},{"ingredients":["Finely chopped parsley","Lemon slices"],"purpose":"Garnishes (optional)"}]', '[{"title":"Recommended","description":"Pound breast to even thickness using a meat pounder, rolling pin, or fist. OR cut large ones in half horizontally to form 2 cutlets (steaks) for each.","images":[],"step":1},{"description":"Mix marinade in a ziplock bag (or container in which chicken fits snugly). Add chicken.","images":[],"step":2},{"description":"Marinate 3 hours to overnight, though even 30 minutes is effective. (Note 2)","images":[],"step":3},{"description":"Heat 1 tbsp olive oil in a large skillet over medium high heat, and cook chicken per times below until deep golden (see video). If browning too quickly, lower heat.","images":[],"step":4},{"description":"Transfer to serving plate, cover loosely with foil and rest for 3 minutes before serving, garnished with parsley and lemon slices if desired.","duration":3,"images":[],"step":5},{"description":"Cook times:","images":[],"step":6},{"title":"Whole breast and boneless thighs: 3","description":"4 minutes each side (internal temp 165F/75C)","images":[],"step":7},{"title":"Cutlets and tenderloin","description":"2 minutes each side","images":[],"step":8}]', '["gluten","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","grilling-ideas-and-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9e9bc63f23ec', 'en', 'US', 'A Great Pork Chop Marinade', 'Recipe video above. This marinade will make any pork chops or steak extra juicy as well as infusing it with great savoury flavour and a touch of sweet. Soy sauce is the secret ingredient - it does not taste the least bit "Asiany" or soy saucey. MINIMUM MARINADE TIME: 1 hr+ for thin chops, 3 hrs+ for thick.', 'https://www.recipetineats.com/tachyon/2017/08/Marinated-Pork-Chops-3A.jpg', 5, 10, 15, 4, '[{"id": "ing_pork", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.333, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["4 bone in pork chops, 2 cm / 4/5\" thick about 280g/9 oz each (Note 1)","1 tbsp oil"]},{"ingredients":["1/3 cup (85 ml) soy sauce (light or all purpose, not dark)","2 tbsp brown sugar","2 tsp Worcestershire sauce","1 tsp Dijon mustard","2 garlic cloves (, minced)","¼ tsp black pepper"],"purpose":"Marinade:"}]', '[{"description":"Place Marinade ingredients in a ziplock bag. Massage to combine.","images":[],"step":1},{"description":"Add chops. Massage to coat in the Marinade. Marinate for 1 – 24 hours. (Note 2)","images":[],"step":2},{"description":"Take the chops out of the fridge 20 minutes before cooking.","images":[],"step":3},{"description":"Brush BBQ grill or drizzle oil in pan, heat on medium high. Add pork and cook for 4 minutes or until the underside is caramelised and the pork releases from the grill, then turn the chops and cook for 3 minutes (Note 2 for thin chops).","duration":4,"images":[],"step":4},{"description":"Baste both sides with residual marinade in ziplock bag, then cook the basted side for 30 seconds before serving. The chops should have a great crust","duration":0.5,"images":[],"step":5},{"description":"Transfer chops to a plate, cover loosely with foil. Rest for 3 minutes before serving.","duration":3,"images":[],"step":6}]', '["gluten","mustard","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dinner-tonight","grilling-ideas-and-recipes","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2b021325e6d0', 'en', 'US', 'Bun Cha - Vietnamese Meatballs', 'Recipe video above. Everything you know and love about Vietnamese food - fresh, healthy and full of flavour! Bun Cha in Vietnam is served slightly differently (read in post), but here I''ve made noodle bowls which are more familiar to those outside of Vietnam. See Notes for what this tastes like!', 'https://www.recipetineats.com/tachyon/2019/01/Vietnamese-Pork-Meatballs_6.jpg', 20, 10, 30, 2, '[{"id": "ing_pork_mince", "quantity": {"value": 250.0, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_lemongrass", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_water", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.2, "unit": "pack of 500g"}}, {"id": "ing_big_handful_beansprouts", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["250 - 300 g/8 - 10 oz pork mince (ground pork)(Note 1)","1 tbsp fish sauce (Note 2)","2 tsp white sugar","1/3 cup finely chopped green onions / scallions","1 clove garlic (, minced)","Pinch of white pepper and salt","2 tsp lemongrass paste or fresh finely chopped (, optional (Note 4))","1 1/2 tbsp oil (, for cooking)"],"purpose":"Meatballs:"},{"ingredients":["3 tbsp white sugar","3 tbsp fish sauce (Note 2)","2 tbsp rice wine vinegar","2 tbsp lime juice","1/3 cup water","1 birds eye chilli (, seeded and finely chopped (Note 3))","3 cloves garlic (, finely chopped)"],"purpose":"Nuoc Cham (Vietnamese Dressing / Sauce – Note 2):"},{"ingredients":["100 g / 3.5 oz vermicelli noodles (, dried)","Big handful beansprouts","Few lettuce leaves (, folded or shredded)","Julienned carrot and white radish (daikon), optional quick pickle (Note 5)","Handful of coriander/cilantro sprigs (, mint)","Sliced red chilli (, lime wedges (optional))"],"purpose":"Serving (Note 4):"}]', '[{"title":"Sauce","description":"Mix ingredients. Set aside 10 minutes+.","images":[],"step":1},{"title":"Noodles","description":"Pour over boiling water and soak per packet directions. Drain, set aside.","images":[],"step":2},{"description":"Mix all ingredients except oil until combined.","images":[],"step":3},{"description":"Shape into 6 mini hamburger patties with your hands.","images":[],"step":4},{"description":"Heat oil in a skillet over medium high heat. Add patties and cook for 2 1/2 minutes or until golden. Flip, cook 2 minutes then remove.","images":[],"step":5},{"description":"Assemble Bowls:","images":[],"step":6},{"description":"Place noodles in bowl. Top with a handful of beansprouts, wedge in lettuce, carrots and radish in.","images":[],"step":7},{"description":"Place meatballs on top, top with coriander and mint.","images":[],"step":8},{"description":"Spoon over a generous amount of Sauce (it''s supposed to be like a soup broth), eat and be happy!","images":[],"step":9}]', '["fish"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["dinner-tonight","grilling-ideas-and-recipes","iconic-dishes","meatball-recipes","pork-recipes","quick-and-easy","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_eea72dc7c5d1', 'en', 'US', 'Lemon Garlic Marinated Grilled Pork Chops', 'Recipe VIDEO above. Nothing infuses pork chops with flavour like a good marinade! This one is ideal for grilling so the high heat sears the crust beautifully. But the pork chops can of course be cooked on the stove, or even bake them! Also use this marinade for the proteins - see notes.', 'https://www.recipetineats.com/tachyon/2018/01/Lemon-Garlic-Oregano-Pork-Chops-3.jpg', 5, 10, 15, 4, '[{"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.1, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.1, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_pork", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 37.5, "unit": "bottle"}}]', '[{"ingredients":["3 garlic cloves (, minced)","1 tbsp dried oregano (or other herbs, Note 1)","Zest of 1 lemon","1/3 cup (85 ml) lemon juice (1 large or 2 medium lemons)","1/4 cup (65 ml) olive oil","3/4 tsp salt","1/4 tsp black pepper"],"purpose":"Marinade:"},{"ingredients":["4 pork chops bone in (, 2cm / 4/5\" thick about 280g/9 oz each (Note 2))","Oil (, for cooking)"],"purpose":"Pork:"}]', '[{"description":"Whisk Marinade ingredients in a bowl (or ziplock bag). Add pork. Marinade for 1 hr minimum, 3 hours ideal, 12 hours max (Note 3).","duration":60,"images":[],"step":1},{"description":"Take the pork out of the fridge 20 minutes before cooking.","images":[],"step":2},{"description":"Shake excess marinade off (but don''t wipe dry) and cook using preferred method. Pictured in post served with Minted Yoghurt - see notes!","images":[],"step":3},{"description":"Brush grills / plate with oil and heat on high until smoking.","images":[],"step":4},{"description":"Place pork on grills and cook the first side for 4 minutes until it is nicely charred. Turn and cook the other side for 3 minutes. Turn the porks on their side to briefly sear the fat side (see video). Transfer to plate, rest for 3 - 5 minutes then serve.","duration":4,"images":[],"step":5},{"description":"Heat skillet with about 1 tbsp oil over high heat. Add pork and cook for 1 minute, then turn DOWN slightly to medium high. Cook for another 3 minutes, then turn and cook the other side for 3 minutes. Turn the porks on their side to briefly sear the fat side (see video).","duration":1,"images":[],"step":6},{"title":"Transfer to plate, rest for 3","description":"5 minutes then serve.","duration":4,"images":[],"step":7},{"description":"Preheat oven to 200C / 390F (fan forced / convection) or 220C / 430F (standard oven).","images":[],"step":8},{"description":"Place oven shelf in top 1/3 of oven.","images":[],"step":9},{"description":"Place pork on tray. Bake for 15 minutes, then flick to grill/broiler and grill on high for 5 minutes until the surface is nicely browned.","duration":15,"images":[],"step":10},{"title":"Transfer to plate, rest for 3","description":"5 minutes then serve.","duration":4,"images":[],"step":11}]', '[]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dietary","dinner-tonight","gluten-free-recipes","greek-recipes","grilling-ideas-and-recipes","main-dishes","mediterranean-recipes","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_15bee2208c90', 'en', 'US', 'Chicken Burger Recipe', 'Recipe video above. Crispy seasoned chicken breast, topped with a mandatory slice of melted cheese and piled onto soft rolls with onion, avocado, lettuce, tomato and garlic mayo. The key to juicy chicken is to cook it hard and fast! You can eyeball the Seasoning - it will be tasty as long as you use "around" the right amounts. :)Want to the chicken mince version? Here''s it is!', 'https://www.recipetineats.com/tachyon/2017/07/Chicken-Burgers-4.jpg', 15, 10, 25, 4, '[{"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_paprika", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 2000.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken_breast", "quantity": {"value": 400.0, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.003, "unit": "jar of 400g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_french_fries", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["1/3 cup /80g flour (any white)","1 tsp salt","½ tsp black pepper","¾ tsp paprika","1 tsp thyme","½ tsp garlic powder","½ tsp onion powder"],"purpose":"Seasoning:"},{"ingredients":["2 tbsp olive oil","2 large onions (, halved them sliced (white, brown or yellow))","400 - 500g / 14 oz - 1 lb chicken breast (2 pieces) (, cut in half horizontally into 2 thin steaks)","4 – 8 slices Swiss or other melting cheese slices (Note 1)","4 soft rolls (I used brioche burger buns)","1 avocado","Lettuce","2 large tomatoes"],"purpose":"Burgers:"},{"ingredients":["½ cup mayonnaise (I use whole egg)","1 large garlic clove (, minced)"],"purpose":"Garlic Mayo:"},{"ingredients":["French fries","Baked potato wedges"],"purpose":"On the side"}]', '[{"description":"Mix Garlic Mayo ingredients in a small bowl, set aside for 20+ minutes.","images":[],"step":1},{"description":"Mix Seasoning in a flat bowl / dish.","images":[],"step":2},{"description":"If required, pound chicken to about 1 cm / 2/5” thick. If wanting to be exact, trim to shape of rolls BUT ensure it is about 15% larger (it shrinks) (Note 2).","images":[],"step":3},{"description":"Heat 1 tbsp oil in a skillet over high heat (if doing on BBQ, drizzle flat plate).","images":[],"step":4},{"description":"Add onion and cook, turning regularly, for 5 minutes until golden. Season with salt and pepper, toss, then remove.","duration":5,"images":[],"step":5},{"description":"While cooking the onions, preheat oven to 160C/320F. Split rolls, then lightly toast / warm the rolls (if using BBQ, just toast the cut side until crispy). Leave in turned off oven with door ajar while you cook chicken.","images":[],"step":6},{"description":"Heat 1 tbsp oil into the same skillet, still on high heat.","images":[],"step":7},{"description":"Dredge chicken in Seasoning, shake off excess, then place in skillet. Repeat.","images":[],"step":8},{"description":"Cook for 2 ½ minutes until golden, then flip.","images":[],"step":9},{"description":"Top with cheese then leave for 1 1/2 minutes. When the underside is golden, if the cheese is not yet melted, place lid on for 15 seconds (or tray or foil).","duration":0.25,"images":[],"step":10},{"description":"Remove chicken from skillet onto plate. Cover loosely with foil while you start assembling the burgers.","images":[],"step":11},{"description":"Smear base of roll with avocado, sprinkle with salt and pepper. Top with chicken, onion, lettuce then tomato.","images":[],"step":12},{"description":"Smear lid of roll with Garlic Mayo, place on burger. Enjoy!","images":[],"step":13}]', '["egg","gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["burger-recipes","chicken-breast-recipes","chicken-recipes","dinner-tonight","grilling-ideas-and-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5e23c18c020d', 'en', 'US', 'Creamy Garlic Prawns / Shrimp and Cheesy Potatoes Foil Packet Recipe', 'Recipe video above. Juicy, perfectly cooked prawns/shrimp bathed in a creamy garlic sauce piled on top of cheesy potatoes with a side of steamed asparagus, all cooked in a foil packet! Grill these on the BBQ, bake them in the oven or even cook these on the stove!', 'https://www.recipetineats.com/tachyon/2017/06/Creamy-Prawn-Cheesy-Potatoes-Foil-Pack_1.jpg', 10, 10, 20, 4, '[{"id": "ing_potato", "quantity": {"value": 600.0, "unit": "bag of 2kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_shrimp", "quantity": {"value": 20.0, "unit": "kg"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.75, "unit": "pack of 125g"}}, {"id": "ing_es_asparagus", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["600 g / 1.2 lb potatoes (, peeled and cut into 1.5cm cubes)","1 tsp dried thyme leaves (optional)","Salt and pepper","3/4 cup thickened / heavy cream","30 - 50 g / 2 - 3 tbsp butter (more = richer!)","1 garlic clove (, minced)","20 - 24 prawns/shrimp (, peeled and deveined, tail on or off)","3/4 - 1 cup mozzarella or other melting cheese of choice","2 - 3 bunches asparagus (, trimmed then cut in half, fat ones vertically cut in half (Note 1))","Finely chopped parsley"]}]', '[{"description":"Bring a large pot of water to the boil. Add potatoes and cook for 5 minutes or until just cooked.","duration":5,"images":[],"step":1},{"description":"Drain potatoes, then sprinkle with salt, pepper and thyme. Toss to coat.","images":[],"step":2},{"description":"Meanwhile, place the cream, butter and garlic in a heatproof bowl. Microwave 30 - 40 seconds on high, until butter melts when stirred. If time permits, cool (place in fridge to speed up). (Note 1)","images":[],"step":3},{"description":"Preheat oven to 200C/390F (standard) or 180C/350F (fan/convection) or BBQ on medium high with hood down.","images":[],"step":4},{"description":"Tear 4 x 45cm/18\" pieces of heavy duty foil (Note 2).","images":[],"step":5},{"description":"Divide potatoes among foil sheets. Top with cheese, then prawns and asparagus, then drizzle over cream sauce.","images":[],"step":6},{"description":"Sprinkle with salt, pepper and parsley.","images":[],"step":7},{"description":"Bring the long ends of the foil together over the prawns, then fold down to seal, then fold in the sides (watch video, it''s easy!)","images":[],"step":8},{"description":"Place on a baking tray or BBQ and cook for 10 minutes (small prawns) - 12 minutes (medium prawns). (Note 4)","duration":10,"images":[],"step":9},{"title":"Serve immediately","description":"do not leave them sitting around inside the unopened packet, the prawns and asparagus will overcook and leech water, making the sauce watery.","images":[],"step":10}]', '["milk","shellfish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","grilling-ideas-and-recipes","main-dishes","one-pot-recipes","prawns-shrimp","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_49339ac0168c', 'en', 'US', 'Carne Asada', 'The famous Latin American grilled beef! Marinated in a wicked Carne Asada marinade that infuses and tenderises the beef, this is beautiful made with any cut of beef suitable for quick grilling but is traditionally made with flank and skirt steak. Use for tacos, burritos or serve on rice, or try a salad! This recipe serves 5 - 6, because it''s sliced thinly a bit goes a long way.', 'https://www.recipetineats.com/tachyon/2017/06/Carne-Asada-4.jpg', 10, 8, 18, 6, '[{"id": "ing_garlic", "quantity": {"value": 6.667, "unit": "pack of 3 heads"}}, {"id": "ing_oranges", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_ime_juice", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.25, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_jalapeno", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_1_2kg_1_5_2_5lb_skirt_of_flank", "quantity": {"value": 750.0, "unit": "unit"}}, {"id": "ing_tortillas", "quantity": {"value": 1.0, "unit": "pack of 8"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 0.075, "unit": "net of 500g"}}]', '[{"ingredients":["4 cloves garlic (, minced)","1/2 cup / 125 ml orange juice","1/4 cup / 65 ml lime juice (about 2 limes)","1 cup finely chopped coriander / cilantro","1/2 teaspoon salt","1/4 teaspoon black pepper","1/4 cup / 65 ml olive oil","1 jalapeno ((fresh), finely minced)","2 tbsp white vinegar (any clear or clear-ish vinegar will be ok here e.g. white wine vinegar, cider vinegar)"],"purpose":"Marinade:"},{"ingredients":["Oil","750 g - 1.2kg / 1.5 - 2.5lb skirt of flank (I used a 900g/1.8lb skirt) (Note 1)"],"purpose":"Cooking:"},{"ingredients":["Tortillas","Avocado Slices","Pico De Gallo or Tomato","Coriander/cilantro leaves","Lime wedges"],"purpose":"To Serve as Carne Asada Tacos:"}]', '[{"description":"Place the Marinade ingredients in a large ziplock bag and mix. Add beef and massage through the bag to coat evenly. Seal then marinate for 1- 8 hours (12 hours max, otherwise meat gets over marinated and can be mushy).","images":[],"step":1},{"title":"Take the skirt steak out of the fridge 20","description":"30 minutes before cooking to bring to room temperature.","images":[],"step":2},{"description":"Brush BBQ with oil and heat on high until smoking (or use a large skillet over high heat and turn the fan on!).","images":[],"step":3},{"description":"Cook skirt steak for 3 minutes each side for rare, 4 minutes for medium rare. For flank, cook for 4 minutes each side for rare and 5 minutes for medium rare. Don''t cook beyond medium - chewy beef!","duration":3,"images":[],"step":4},{"description":"Remove onto a plate and cover loosely with foil. Rest for 5 minutes then slice thinly against the grain (Note 2).","duration":5,"images":[],"step":5},{"description":"Serve with tacos, in burritos or on rice!","images":[],"step":6}]', '[]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["South American"],"categories":["beef-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","mexican-recipes","quick-and-easy","south-american-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_90eeed1c7626', 'en', 'US', 'Rosemary Garlic Grilled Lamb Chops', 'A tasty way to prepare economical cuts of lamb chops and steaks! Tenderise and infuse them with flavour with a delicious marinade then grill to perfection on the BBQ (or stove). Marinade for at least 2 hours, preferably overnight (no longer than 24 hours). Update: This is (was!) a tart marinade and following feedback from some readers by email and from a friend, I have tweaked the recipe slightly to take the edge off the vinegar. :) Resounding feedback all round!', 'https://www.recipetineats.com/tachyon/2016/12/Rosemary-Garlic-Marinated-Lamb-Chops-5.jpg', 5, 10, 15, 4, '[{"id": "ing_lamb", "quantity": {"value": 600.0, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_vinegar", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_honey", "quantity": {"value": 0.03, "unit": "jar of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_rosemary", "quantity": {"value": 0.125, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["600 - 800 g / 1.2 - 1.6lb lamb chops (4 - 8, depending on size)","Oil (, for cooking, if required)"]},{"ingredients":["2 1/2 tbsp red wine vinegar","1 tbsp extra virgin olive oil","1 tbsp honey","3 garlic cloves (, minced)","1 1/4 tsp finely chopped fresh rosemary (or 1 tsp dried rosemary)","1/2 tsp dried thyme","3/4 - 1 tsp sea salt","Black pepper"],"purpose":"Marinade"}]', '[{"description":"Mix Marinade ingredients in a bowl until salt dissolves. Add lamb, mix to coat, then marinate at least 2 hours, preferably overnight, up to 24 hours.","images":[],"step":1},{"description":"Brush BBQ bars with oil if required (Note 1) and heat to medium high (or heat 1/2 tbsp oil in skillet on stove on medium high).","images":[],"step":2},{"description":"Cook lamb to your taste. I had 4 x 150g/5oz lamb loin chops about 2cm/3/4\" thick and 3 minutes on each side = medium. I also cooked smashed garlic cloves and rosemary sprigs for garnish.","images":[],"step":3},{"description":"Transfer lamb to plate, cover loosely with foil and rest for 5 minutes.","duration":5,"images":[],"step":4},{"description":"Serve with sides of choice!","images":[],"step":5}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dietary","gluten-free-recipes","grilling-ideas-and-recipes","lamb-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_206b298a2d19', 'en', 'US', 'Chicken Souvlaki with Tzatziki', 'This Greek favourite is so easy to make at home! Loaded with classic Greek flavours of lemon, garlic and dried oregano. Fabulous for an outdoor BBQ!', 'https://www.recipetineats.com/tachyon/2016/07/Chicken-Souvlaki_1.jpg', 15, 10, 25, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.075, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.375, "unit": "tub of 500g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}]', '[{"ingredients":["1.5 lb / 750 g chicken thigh fillets ((or breast), cut into 1\"/2.5cm pieces)","2 tbsp olive oil","1/4 cup lemon juice","3 garlic cloves (, minced)","2 tbsp dried oregano","1/2 - 3/4 tsp salt","Black pepper"],"purpose":"Marinade"},{"ingredients":["1 tbsp olive oil","Flatbreads / wraps / pita bread","Lettuce","Tomato slices"],"purpose":"To Cook / Serve"},{"ingredients":["2 Lebanese cucumbers (to make about ½ cup grated cucumber after squeezing out juice)","1 1/4 cups / 300 g plain Greek yoghurt","2 tsp white wine vinegar (or red wine or apple cider vinegar)","1 tbsp lemon juice","1/2 garlic clove (, minced)","1 tbsp extra virgin olive oil (or more if you want richer)","1/2 tsp salt","Black pepper"],"purpose":"Tzatziki"}]', '[{"description":"Place chicken and Marinade into a bowl and set aside to marinate for at least 3 hours to overnight.","images":[],"step":1},{"description":"Thread chicken onto 8 skewers.","images":[],"step":2},{"description":"Heat oil in a large skillet over high heat (or BBQ). Cook skewers for 3 minutes on each side, or until cooked through.","duration":3,"images":[],"step":3},{"description":"Serve Chicken Souvlaki with tzatziki, flatbreads (make your own!), lettuce and tomato slices.","images":[],"step":4},{"description":"Cut the cucumber in half lengthwise. Use a teaspoon to scrape the watery seeds out. Coarsely grate the cucumber using a box grater. Then wrap in paper towels or a tea towel and squeeze to remove excess liquid.","images":[],"step":5},{"description":"Place cucumber in a bowl. Add remaining ingredients then mix to combine. Set aside for at least 20 minutes for the flavours to meld.","images":[],"step":6}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","greek-recipes","grilling-ideas-and-recipes","mediterranean-recipes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3aca52194d76', 'en', 'US', 'Pineapple Coconut Hawaiian Chicken Skewers', 'This recipe is based on the marinade of the Hawaiian street food chicken you can get from roadside stalls throughout Hawaii, except I added coconut. Coconut is a brilliant base for marinades because it adds richness into the flesh as well as infusing it with sweetness and coconut flavours. I served this with a Coconut Lime Rice (it uses the balance of coconut milk leftover after this recipe from a standard 14oz/400g can). MARINATING TIME: 3 hrs - overnight recommended, but even 20 minutes is enough.', 'https://www.recipetineats.com/tachyon/2016/05/Coconut-Pineapple-Chicken-Skewers_4.jpg', 15, 10, 25, 8, '[{"id": "ing_coconut_milk", "quantity": {"value": 0.469, "unit": "can of 400ml"}}, {"id": "ing_pineapple", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_lime", "quantity": {"value": 0.225, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.5, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_skewers", "quantity": {"value": 8.0, "unit": "pack of 50"}}]', '[{"ingredients":["3/4 cup coconut milk (from a 14oz/400g can, use leftovers for Coconut Lime Rice!)","1/2 cup pineapple juice (Note 1)","3 tbsp brown sugar","2 tbsp tomato sauce/ketchup","3 tbsp soy sauce","Zest and juice of 1 lime","2 garlic cloves (, minced)","1/2 tsp EACH onion powder (, cumin, paprika,)","1 tsp ginger powder (or 1/2 tsp grated fresh ginger)","1/2 - 1 tsp cayenne pepper (, optional)","1/2 tsp salt"],"purpose":"Marinade"},{"ingredients":["1.5 lb / 750g chicken thigh fillets (, cut into 1\"/2.5cm pieces)","1 tbsp olive or vegetable oil","8 skewers (, soaked in water for 30 minutes if cooking on outdoor BBQ)"],"purpose":"Skewers"}]', '[{"description":"Combine Marinade ingredients in a bowl. Remove 1/2 cup of Marinade (for basting) and set aside in fridge. Add chicken, cover and marinate in the fridge for at least 3 hours, preferably overnight. But even 20 minutes is enough - compensate with extra basting.","images":[],"step":1},{"description":"Drain and discard marinade. Thread chicken onto skewers.","images":[],"step":2},{"description":"Heat oil in a large skillet or on outdoor BBQ over medium high heat. Cook skewers, turning to cook all sides, and basting generously with reserved Marinade. (Note 1)","images":[],"step":3},{"description":"Serve with Coconut Lime Rice.","images":[],"step":4}]', '["gluten","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Hawaiian"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","most-popular","quick-and-easy","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e454613f7927', 'en', 'US', 'Mexican Grilled Chicken Tacos', 'Wonderfully authentic Mexican flavours, a homestyle version of Sinaloa chicken, a popular Mexican street food. Adapted from Bobby Flay''s "Mexican Red Chicken" recipe from his cookbook "Bobby Flay''s Barbecue Addiction". (Note 1)', 'https://www.recipetineats.com/tachyon/2016/04/Mexican-Grilled-Chicken-Tacos_1.jpg', 5, 10, 15, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_oranges", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_ime_juice", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_chipotle", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.016, "unit": "jar of 40g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_tortillas", "quantity": {"value": 1.0, "unit": "pack of 8"}}, {"id": "ing_pico_de_gallo", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 0.045, "unit": "net of 500g"}}]', '[{"ingredients":["1 - 1.5 lb / 500 - 750g chicken thigh fillets (Note 2)","1 tbsp olive oil"]},{"ingredients":["4 tbsp orange juice","2 tbsp apple cider vinegar (or rice vinegar)","1 1/2 tbsp lime juice","3 garlic cloves (, minced)","1 1/2 tbsp chipotle or ancho chile powder (Note 3)","2 tsp dried oregano","2 tsp smoked paprika powder (Note 4)","1/8 tsp All Spice","1/4 tsp cinnamon powder","1/4 - 1/2 tsp cayenne pepper (optional - for spiciness)","1 tsp salt","Black pepper"],"purpose":"Marinade"},{"ingredients":["Tortillas or taco shells","Pico de Gallo (tomato salsa)","Sour cream","Avocado","Fresh coriander / cilantro","Lime wedges"],"purpose":"Taco Fixings"}]', '[{"description":"Place Marinade ingredients in a ziplock bag. Add chicken, massage to coat then refrigerate to marinate for at least 3 hours, preferably overnight.","images":[],"step":1},{"description":"Remove chicken from Marinade, discard Marinade.","images":[],"step":2},{"description":"Heat oil in a skillet over medium high heat (or even better, do this on the BBQ on medium high). Cook chicken for 4 minutes on each side, until dark golden brown.","duration":4,"images":[],"step":3},{"description":"Remove chicken onto plate, cover loosely with foil and rest for 3 minutes.","duration":3,"images":[],"step":4},{"description":"Cut into strips and use for tacos. (See Note 5 for more serving options)","images":[],"step":5}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","mexican-recipes","quick-and-easy","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4a3c120e6ed8', 'en', 'US', 'Beef Steak Fajitas', 'Recipe video above. Beef Fajitas made extra juicy and extra tasty with a wicked marinade that tenderises and flavours the beef! But if you don''t have time to marinade, see Note 7 for a faster version. Adapted from this recipe by Tyler Florence (mine is easier and I think it is just as tasty!)', 'https://www.recipetineats.com/tachyon/2016/03/Beef-Fajitas_4.jpg', 15, 15, 30, 4, '[{"id": "ing_beef_steak", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_oranges", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_chipotle", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 2.0, "unit": "bottle"}}, {"id": "ing_capsicum", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 2.5, "unit": "pack of 1kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_tortillas", "quantity": {"value": 12.0, "unit": "pack of 8"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 lb / 500g beef steak (rump and skirt are ideal) (Note 1)","4 tbsp / 1/4 cup orange juice (, fresh (1 orange))","2 tbsp lime juice","2 garlic cloves (, minced)","1/2 tsp cumin powder","1/2 tsp coriander powder","1/2 tsp onion powder (optional)","1 tsp chipotle powder (Note 2)","1/2 tsp salt","Black pepper"],"purpose":"Marinated Beef"},{"ingredients":["2 - 3 tbsp oil","2 bell peppers/capsicum (, sliced (Note 3))","1 large onion (, halved and sliced (brown, yellow, white))","Salt and pepper"],"purpose":"Fajitas"},{"ingredients":["12 tortillas (, small)","Avocado","Cilantro/coriander","Sour cream","Lime wedges","Tomatoes (, sliced, or Pico de gallo)"],"purpose":"Fixings"}]', '[{"description":"Place the Marinated Beef ingredients in a ziplock bag, massage to coat then refrigerate for 2 hour to overnight.","images":[],"step":1},{"description":"Remove beef from marinade 30 minutes prior to cooking (to bring to room temperature) and pat dry with paper towels. Discard marinade.","images":[],"step":2},{"description":"Drizzle 1/2 tbsp of oil on each side of the beef (1 tbsp in total).","images":[],"step":3},{"description":"Heat the BBQ or a skillet on high heat. Cook beef to your liking. (Note 4)","images":[],"step":4},{"description":"Remove beef onto a plate and cover loosely with foil.","images":[],"step":5},{"description":"Return skillet to stove, still on high heat, and heat 1/2 tbsp oil. Add onions, sprinkle with salt and pepper, and cook until soft and charred. Remove onto serving plate.","images":[],"step":6},{"description":"Heat remaining 1/2 tbsp oil in the skillet. Add bell pepper/capsicum, sprinkle with salt and pepper, and cook until charred. Remove onto plate.","images":[],"step":7},{"description":"Slice beef thinly against the grain (Note 5).","images":[],"step":8},{"description":"Serve with warmed tortillas and fixings of choice. (Note 6)","images":[],"step":9}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["beef-recipes","dietary","fajitas","gluten-free-recipes","grilling-ideas-and-recipes","low-calorie-recipes","mexican-recipes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1ee599ec9dd5', 'en', 'US', 'Turkish Lamb Kofta Kebabs', 'A simple, exotic, fragrant midweek meal. 30 minutes, start to finish. Adapted from a recipe by Effendi restaurant in Balmain, Sydney, as shown in the Food Safari "Fire" TV series. See notes for changes made to the original recipe.', 'https://www.recipetineats.com/tachyon/2016/02/Turkish-Kebabs-1_3.jpg', 20, 10, 30, 4, '[{"id": "ing_lamb_mince", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_pistachio_nuts", "quantity": {"value": 37.5, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_yogurt", "quantity": {"value": 0.225, "unit": "tub of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}]', '[{"ingredients":["1 lb / 500g lamb mince (ground lamb) (or substitute with beef)","1 small onion (, grated or minced using a food processor - about 1/4 cup (white, brown or yellow) (Note 1))","1 garlic clove (, minced)","1/4 cup pistachio nuts (, ground (Optional. I use my food processor) (Note 2))","3/4 tsp cooking salt / kosher salt (halve for table salt, +50% for salt flakes)","1 tsp black pepper","1 tbsp cumin powder","1 tbsp red pepper flakes","1 tbsp olive oil"],"purpose":"Kebabs"},{"ingredients":["3/4 cup plain yoghurt (I use Greek)","1 tbsp lemon juice","1/2 garlic clove (, minced)","Salt and pepper"],"purpose":"Yoghurt Sauce"},{"ingredients":["Pita bread or lebanese flat bread (, warmed)","Lettuce leaves of choice","Sliced tomato","Sliced red onion"],"purpose":"To Serve"}]', '[{"description":"Mix together Yoghurt Sauce ingredients and place in the refrigerator to allow the flavours to develop.","images":[],"step":1},{"description":"Place the Kebab ingredients except the oil in a bowl and use your hands to just combine (don''t over mix).","images":[],"step":2},{"description":"Divide into 8 portions and mould onto skewers.","images":[],"step":3},{"description":"Heat oil in a large skillet over medium high heat. Add skewers (I could fit all in, placing them in alternating directions) and cook for 8 minutes, turning to brown all sides.","duration":8,"images":[],"step":4},{"description":"Meanwhile, slice tomatoes and red onion.","images":[],"step":5},{"description":"Serve kebabs with pita bread, lettuce, tomatoes, red onion and yoghurt sauce on the side. Wedges of lemon are also a great accompaniment.","images":[],"step":6}]', '["gluten","milk","nuts"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Turkish"],"categories":["cuisines","dietary","dinner-tonight","gluten-free-recipes","grilling-ideas-and-recipes","lamb-recipes","main-dishes","middle-eastern-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_58ce4d3da4a7', 'en', 'US', 'Peruvian Chicken with Garlic Butter Rice', 'Known as Peruvian Blackened Chicken ("Pollo a la Brasa"), this chicken is traditionally made on a rotisserie. As with every ethnic dish, there are many many versions but the common ingredients in all are soy sauce, garlic and paprika. I served this with a garlic butter rice on the side. The rice recipe makes enough for around 6 servings and you''ll be thankful for this because it''s so yummy, you will want leftovers for the next day!', 'https://www.recipetineats.com/tachyon/2015/12/Peruvian-Roast-Chicken_1.jpg', 10, 45, 55, 4, '[{"id": "ing_chicken", "quantity": {"value": 1.134, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.24, "unit": "bottle of 250ml"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_rice", "quantity": {"value": 300.0, "unit": "pack"}}, {"id": "ing_chicken", "quantity": {"value": 1.134, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["2.5 lb (1.2 kg) chicken pieces (Note 1)"]},{"ingredients":["1 tbsp garlic powder OR 3 garlic cloves (, minced)","2 tsp cumin powder","1 tbsp paprika powder (preferably smoked but plain is ok)","4 tbsp soy sauce (Note 2)","2 tbsp lime juice (, fresh (1 lime))","1 tbsp olive oil"],"purpose":"Marinade"},{"ingredients":["4 garlic cloves, minced","1/2 onion (, finely diced (white, brown, yellow))","1 tbsp olive oil","2 cups long grain rice (, uncooked)","2 cups chicken broth / stock","1 cup water","2 - 4 tbsp butter (Note 3)","Salt and pepper"],"purpose":"Garlic Butter Rice"}]', '[{"description":"Place the Marinade ingredients in a small bowl and mix until lump free.","images":[],"step":1},{"description":"Place the chicken in a ziplock bag (my preferred method) or non reactive bowl and coat with Marinade. Marinade for at least 3 hours, preferably overnight (24 hours) OR freeze it straight away, then it will marinade while it defrosts.","images":[],"step":2},{"description":"Preheat oven to 180C/350F. Place chicken in a baking dish, skin side up. Slather leftover marinade onto the skin. Roast for 45 minutes or until deep burnt-red golden brown in colour.","duration":45,"images":[],"step":3},{"description":"Rest for 5 minutes before serving with Garlic Butter Rice and a green salad.","duration":5,"images":[],"step":4},{"description":"Garlic Butter Rice","images":[],"step":5},{"description":"Heat oil in a saucepan over medium heat. Add garlic and onion and cook for 5 minutes until onion is translucent and sweet.","duration":5,"images":[],"step":6},{"description":"Add rice and stir so the rice becomes translucent. Add broth and water, then cover and turn heat down to medium low.","images":[],"step":7},{"description":"Cook for 12 to 15 minutes until the liquid has JUST evaporated, then remove from stove and allow to rest for 10 minutes.","duration":13.5,"images":[],"step":8},{"description":"After resting, add the butter and stir the rice to fluff it up and disperse the butter.","images":[],"step":9}]', '["gluten","milk","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Peruvian","South American"],"categories":["chicken-drumstick-recipes","chicken-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","quick-and-easy","rice-recipes","south-american-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_25c585b65bde', 'en', 'US', 'Blackened Fish Tacos', 'Fish cooked with a punchy spice rub of Cajun Flavours! Perfectly paired with a Avocado-Lime Slaw to make these irresistible tacos.', 'https://www.recipetineats.com/tachyon/2015/10/Blackened-Fish-Tacos1-Featured.jpg', 20, 6, 26, 8, '[{"id": "ing_greek_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_imes_zested_and_juiced", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_jalape_os", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_mint", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_red_cabbage", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_cabbage", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.094, "unit": "jar of 400g"}}, {"id": "ing_sriracha", "quantity": {"value": 0.013, "unit": "bottle of 400ml"}}, {"id": "ing_lime", "quantity": {"value": 4.0, "unit": "net of 500g"}}, {"id": "ing_paprika", "quantity": {"value": 0.75, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_tortillas", "quantity": {"value": 8.0, "unit": "pack of 8"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["½ cup greek yogurt","1 avocado","1 cup cilantro/coriander leaves","2 garlic cloves","2 limes zested and juiced","2 jalapeños","2 tbsp mint (, roughly chopped)","½ tsp Kosher salt","Freshly ground black pepper (, to taste)","1 cup red cabbage (, finely shredded*)","1 cup green cabbage (, finely shredded*)","2 carrots (, grated*)"],"purpose":"Avocado-Lime Slaw"},{"ingredients":["1/4 cup mayonnaise","1 tsp Sriracha","1 tbsp fresh lime juice"],"purpose":"Quick Sriracha Aioli"},{"ingredients":["2 tbsp paprika","2 tsp ground cumin","2 tsp onion powder","2 tsp garlic powder","2 tsp dried thyme","2 tsp dry mustard","1 1/4 tsp Kosher salt","1/4 tsp cayenne pepper","2 tbsp extra virgin olive oil","4 tilapia fillets"],"purpose":"Blackened Fish"},{"ingredients":["8 (6 inch) tortillas","2 jalapeños (, sliced)","1 small bunch cilantro"],"purpose":"To Serve"}]', '[{"description":"In the bowl of a food processor, add the yogurt, avocado, cilantro, garlic, lime zest, lime juice, jalapeños, mint, salt, and pepper. Puree until smooth and creamy. Taste and add more salt and pepper, if needed. Place the shredded cabbage and carrots in a large bowl. Add 1/2 a cup of the avocado-lime dressing from the food processor and stir to combine. Add more dressing if you would like a creamier slaw. If not, you can use the extra dressing to top the tacos later. Refrigerate until ready to use.","images":[],"step":1},{"description":"In a small bowl, combine the ingredients for the Sriracha Aioli. Refrigerate until ready to use.","images":[],"step":2},{"description":"If you would like to toast the tortillas (highly recommended if you are using corn tortillas)* heat a pan over medium-high heat. Once hot, warm each tortilla 1 to 2 minutes per side – you want to heat the tortillas just enough to slightly char and add a bit of crispness, but not so much that when you fold it, it cracks. Wrap the tortillas in a clean tea towel to keep warm and set aside.","images":[],"step":3},{"description":"On a large plate, combine all of the spices to make the blackened seasoning. Dredge both sides of each fish fillet in the spice mixture. In a large saute pan, heat the olive oil over medium-high heat. At the first wisp of smoke from the pan, add the fillets, working in batches if needed. Cook for 2 -3 minutes on each side. (Do not move the fish fillets around while they''re cooking. Leave them be until they''re ready to flip). Transfer the cooked fillets to a cutting board and slice each fillet in-half, vertically - making 8 pieces.","duration":2.5,"images":[],"step":4},{"description":"To serve, top each tortilla with the fish, avocado-lime slaw, jalapeños, cilantro, and drizzle with the Sriracha aioli. Serve with extra wedges of lime and enjoy!","images":[],"step":5}]', '["milk","mustard"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Fusion"],"categories":["dietary","dinner-tonight","fish-recipes","gluten-free-recipes","grilling-ideas-and-recipes","main-dishes","mexican-recipes","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5e4a72222a2c', 'en', 'US', 'One-pan baked sausage & lentils', 'Recipe video above. In this recipe where both lentils and sausages are baked together in the same pan, the lentils absorb the sausage juices as they cook, making the humble lentils tastier than you ever dreamed possible! The recipe starts on the stove sautéing aromatics right in the roasting pan. Any metal pan will work, and it doesn''t matter if your stove burner isn''t large enough for the roasting pan- mine certainly isn''t.Don''t skip the cumin seeds. It gives this a special touch!', 'https://www.recipetineats.com/tachyon/2023/03/Baked-sausage-with-lentils_9.jpg', 10, 50, 60, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 4.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_lentils", "quantity": {"value": 0.562, "unit": "can of 400g"}}, {"id": "ing_carrot", "quantity": {"value": 4.0, "unit": "pack of 1kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_chicken", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_sausages", "quantity": {"value": 8.0, "unit": "pack of 500g"}}]', '[{"ingredients":["3 tbsp extra virgin olive oil","4 eschallots/shallots (, peeled, halved, finely sliced (sub 1 large onion, Note 1))","3 garlic cloves (, finely minced)","1 tbsp cumin seeds (don''t skip this!)","1 1/2 cups puy lentils / French lentils (sub green/brown lentils, Note 3)","4 small carrots (, peeled, quartered, diced into 8mm/ 1/3\" cubes)","1 tsp cooking salt (kosher salt)","3/4 tsp black pepper","3 cups chicken broth/stock (, low sodium)","8 x 85g/3oz pork sausages (Note 3)"]}]', '[{"description":"Pre-heat oven to 200°C/400°F (180°C fan).","images":[],"step":1},{"title":"Cooking vessel","description":"Use a metal roasting pan ~23 x 33 cm / 9 x 13\". Fold a sheet of baking/parchment paper (large enough to cover pan) in half and cut 4 x ~10cm/4\" slits (steam vents! Note 4). Else, use foil - just tear steam vents.","images":[],"step":2},{"title":"Sauté aromatics","description":"Put the pan directly on the stove (really, it''s ok!) and heat the olive oil over medium high heat. Add eschallots and garlic, sauté for 3 minutes until soft. Add cumin seeds and stir for 1 minute.","duration":3,"images":[],"step":3},{"title":"Lentils & stock","description":"Add dried lentils, carrot, salt, pepper and stock. Bring to a simmer.","images":[],"step":4},{"title":"Sausages & paper","description":"Gently place the sausages on top (don''t press in). Cover with the paper, gently pressing so it \"sticks\" to the stock.","images":[],"step":5},{"description":"Bake for 25 minutes on the middle shelf. Remove paper and bake for 20 more minutes to brown the sausages.","duration":25,"images":[],"step":6},{"title":"Rest 5 min","description":"Remove from the oven. Rest for 5 minutes.","duration":5,"images":[],"step":7},{"description":"Serve the sausages with lentils. The flavour-loaded lentils are saucy so they act as the sauce for the sausages! Also pictured in post - baby spinach with Everyday Dressing.","images":[],"step":8}]', '[]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","lentil-recipes","quick-and-easy","sausage-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b1885916fa7d', 'en', 'US', 'Greek Marinated Chickpea Salad', 'Recipe video above. Chickpea salads can be so bland... but not this one! We''re marinating the chickpeas so they absorb the flavour of the lovely Greek dressing. Mediterranean flavours, bright and fresh,this works as a starch + veg side dish, or main course served with crusty bread or flatbreads for scooping!Serves 4 as a main course or 8 as a side.', 'https://www.recipetineats.com/tachyon/2020/06/Chickpea-Salad_0.jpg', 10, 0, 10, 4, '[{"id": "ing_chickpeas", "quantity": {"value": 2.0, "unit": "can of 400g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_spinach", "quantity": {"value": 3.0, "unit": "bag of 250g"}}, {"id": "ing_feta_cheese", "quantity": {"value": 100.0, "unit": "block of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}]', '[{"ingredients":["800g/ 14oz (2 cans) chickpeas, (well drained (Note 1))"]},{"ingredients":["2 tbsp red wine vinegar (Note 2)","5 tbsp extra virgin olive oil","1 garlic clove (, minced using garlic press)","2 tsp dried oregano","1/2 tsp dijon mustard (or other non spicy smooth mustard)","3/4 tsp EACH salt and pepper"],"purpose":"Dressing / Marinade:"},{"ingredients":["1/2 red onion (, finely sliced)","1/2 cup red wine vinegar (Note 2)","1 tsp white sugar","1/2 tsp salt"],"purpose":"Quick pickled onion (pickling optional, Note 3):"},{"ingredients":["250g/ 8oz cherry or grape tomatoes (, halved (or 2 normal tomatoes))","3 cups (packed) spinach, (sliced 1/2 cm / 1/5\" thick (Note 4))","100g/ 3oz feta","3/4 cup chargrilled peppers (, drained and sliced 1cm / 1/3\" thick (optional, Note 5))"],"purpose":"Salad:"}]', '[{"description":"Shake Dressing in a jar.","images":[],"step":1},{"description":"Marinated chickpeas:","images":[],"step":2},{"description":"Place chickpeas in a microwaveable bowl. Toss with half the Dressing.","images":[],"step":3},{"description":"Microwave 1 1/2 minutes, stirring every 30 seconds, until warmed through.","images":[],"step":4},{"description":"Set aside 20 minutes to marinate (warm chickpeas = absorbs flavour).","images":[],"step":5},{"description":"Quick Pickled Onion:","images":[],"step":6},{"description":"Mix ingredients in a bowl, set aside 30 minutes until onion is wilted. Drain.","images":[],"step":7},{"title":"Speedy option","description":"microwave for 2 minutes until hot, cool 10 minutes then use.","duration":2,"images":[],"step":8},{"description":"Assemble salad:","images":[],"step":9},{"description":"Place spinach in a big bowl, add marinated chickpeas (including all residual Dressing in the bowl). Add tomatoes, pickled onion and peppers, if using.","images":[],"step":10},{"description":"Pour over remaining Dressing, toss well. Transfer to serving plate, crumble over feta, serve!","images":[],"step":11}]', '["mustard"]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["dinner","lunch"],"cuisine":["Greek(ish)","Western"],"categories":["beans-lentils","lentil-recipes","quick-and-easy","salad-recipes-main-course","side-dishes","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7687065f7be2', 'en', 'US', 'Creamy Tomato Bean Soup', 'Recipe video above. This is a white bean soup with a thick, creamy broth that''s full of savoury flavour with a hint of tomato. It''s a fast way to turn bland beans into a really filling soup that so simple to make, yet so, so good! The flavour trick - blitzing up the sautéed onion, carrot and garlic with just a bit of the beans. Keep it meat free or see notes for how to add ham, bacon, chicken or sausage! This is VERY filling - and keeps you full for ages (thank you beans!)', 'https://www.recipetineats.com/tachyon/2020/04/Creamy-Tomato-Bean-Soup_0.jpg', 5, 20, 25, 4, '[{"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_italian_herb_mix", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_x_420g_cans_cannellini_or_any_white_beans_drained_rinsed", "quantity": {"value": 3.0, "unit": "pack"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 120.0, "unit": "bag of 250g"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}]', '[{"ingredients":["2 tbsp/ 30g butter (, unsalted)","1 onion (, finely chopped (brown, yellow, white))","2 garlic cloves (, finely chopped)","1 carrot (, large, peeled and finely chopped)","1 1/2 tsp Italian herb mix OR other dried herbs (oregano, thyme, parsley, basil, or mixed)","3/4 cup (170g) tomato paste (Note 1)","1/2 cup (125ml) dry white wine (, optional (can omit) )","4 cups (1 litre) stock/broth, chicken or veg (, low sodium)","3 x 420g/15oz cans cannellini or any white beans, drained & rinsed","1/2 cup (50g) parmesan (, grated)","1/2 tsp EACH salt and pepper","120g/4oz baby spinach (or 5 - 6 cups any other leafy greens OR 4 cups diced veg, Note 3)","3/4 cup (185ml) cream, heavy/thickened ((optional) OR more butter!)"]}]', '[{"description":"Melt butter in a pot over medium high heat. Cook garlic, onion and carrot for 5 minutes until carrot is soft and sweet.","duration":5,"images":[],"step":1},{"description":"About 3 minutes in, add the Italian herbs and cook with the onion (makes the herb flavour \"bloom\").","images":[],"step":2},{"description":"Turn heat up to high, add tomato paste. Cook for 2 minutes to remove the “raw” flavour.","duration":2,"images":[],"step":3},{"description":"Add white wine, cook for 3 minutes until the harsh “winey” smell is gone and mostly evaporates so you’re just left with tomato paste again.","duration":3,"images":[],"step":4},{"description":"Add 1/2 cup of beans (to thicken soup), stock, parmesan, salt and pepper. Stir, low heat, cover and simmer 3 minutes, stirring every now and then.","images":[],"step":5},{"description":"Use a stick blender to puree until smooth (or transfer to blender).","images":[],"step":6},{"description":"Add remaining beans, simmer 3 minutes. Stir in spinach until wilted, then stir in cream if using. Add more salt and pepper if needed (note: canned beans are already salted).","images":[],"step":7},{"description":"Serve with crusty bread for dunking!","images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","gluten-free-recipes","lentil-recipes","quick-and-easy","soup-recipes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9c910cef270e', 'en', 'US', 'Lentil Curry - mega flavour lentil recipe!', 'Recipe video above. This will be an eye opener for you - an incredible creamy coconut curry made with just TWO spices! Hugely economical, this is essentially a streamlined version of Indian Dahl, delivering a similar intoxicating curry flavour but a whole lot less complicated.', 'https://www.recipetineats.com/tachyon/2020/04/Lentil-Curry_9.jpg', 5, 55, 60, 5, '[{"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.6, "unit": "jar of 50g"}}, {"id": "ing_turmeric", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_lentils", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["50g (3 tbsp) butter (, unsalted (sub 2 tbsp neutral oil))","4 garlic cloves (, finely minced (Note 1))","1.5 tbsp ginger (, finely minced (Note 1))","1 onion (, finely chopped (white, yellow, brown))","2 tbsp curry powder (, mild or spicy (your choice!) (Note 2))","1/2 tsp tumeric powder","1/2 tsp cayenne pepper (, optional)","1 1/4 tsp salt","1/2 tsp black pepper","1 cup dried lentils (, green or brown (or any other dried lentils or split peas, Note 3))","400 ml / 14 oz coconut milk (, full fat)","400g/ 14 oz canned tomato (, crushed or diced)","3 cups (750 ml) water"]},{"ingredients":["1/2 cup coriander/cilantro (, finely chopped)","Yogurt (, optional)","Basmati rice (or other rice)"],"purpose":"Serving:"}]', '[{"title":"Saute onion","description":"Melt butter in a pot over medium heat. Add onion, garlic and ginger. Slowly cook, stirring every now and then, for 10 minutes until tinged with gold and the onion is sweet.","duration":10,"images":[],"step":1},{"title":"Cook off spices","description":"Turn heat up to high, add curry powder and turmeric, stir for 1 1/2 minutes.","images":[],"step":2},{"title":"Add everything else","description":"Add remaining ingredients and stir. Bring to simmer, then place lid on and adjust heat to low / medium low so it''s simmering gently.","images":[],"step":3},{"title":"Simmer","description":"Simmer for 30 minutes, then remove lid and simmer for a further 10 minutes to reduce the sauce. {Note 2 for cook times of other lentils}","duration":30,"images":[],"step":4},{"description":"Lentils should be soft, sauce should be thickened and creamy. Too thick, add water. Too thin, simmer with lid off - thickens quickly.","images":[],"step":5},{"title":"Coriander","description":"Stir through half the coriander, then taste and add more salt if needed.","images":[],"step":6},{"description":"Serve over basmati rice, sprinkled with more coriander and a dollop of yogurt. (Low carb option - cauliflower rice).","images":[],"step":7}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["coronavirus-food","curry-recipes","dinner-tonight","indian-recipes","lentil-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9f86eb812b83', 'en', 'US', 'Lentil Soup', 'Recipe VIDEO above. Don''t settle for a bland lentil soup. Make it right, and you''ll have everyone begging for seconds...and thirds! The touch of spices and finishing it off with lemon really lifts this soup to the next level.', 'https://www.recipetineats.com/tachyon/2017/03/Lentil-Soup-6.jpg', 10, 45, 55, 6, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_lentils", "quantity": {"value": 0.75, "unit": "can of 400g"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["2 tbsp olive oil","1 onion, chopped (white, brown, yellow)","2 garlic cloves, minced","1 large carrot (, chopped (about 1 1/4 cups))","2 celery ribs (, chopped (about 1 1/4 cups))","2 cups / 400g dried lentils (, green or brown, rinsed (Note 1))","400g / 14 oz crushed tomato","1.5 litres / 1.5 quarts (6 cups) vegetable or chicken (stock / broth, low sodium)","1/2 tsp each cumin and coriander powder","1 1/2 tsp paprika powder","2 dried bay leaves","1 lemon (zest + juice)","1/4 tsp salt and pepper, (each)"]},{"ingredients":["Chopped fresh parsley, for garnish","Warm bread, to serve"],"purpose":"To Serve"}]', '[{"description":"Heat oil in a large pot over medium heat. Add garlic and onion, cook for 2 minutes.","duration":2,"images":[],"step":1},{"title":"Add celery and carrot. Cook for 7","description":"10 minutes or until softened and the onion is sweet. Don''t rush this step, it is key to the flavour base of the soup.","duration":8.5,"images":[],"step":2},{"description":"Add all remaining ingredients except the lemon and salt. Stir.","images":[],"step":3},{"description":"Increase heat and bring to simmer. Scoop scum on the surface off and discard (do this again during cooking if required). Place lid on and turn heat down to medium low. Simmer for 35 - 40 minutes or until lentils are soft.","duration":37.5,"images":[],"step":4},{"description":"Remove bay leaves.","images":[],"step":5},{"title":"Thicken Soup","description":"Using a stick blender, do 2 or 3 quick whizzes to thicken the soup (see video below). Or transfer 2 cups to a blender, let it cool slightly, then hold lid with tea towel and blend then transfer back into pot.","images":[],"step":6},{"description":"Add a touch of water if you want to adjust soup consistency. Season to taste with salt and pepper. Grate over the zest of the lemon then add a squeeze of lemon juice just before serving. Garnish with parsley if desired and serve with warm crusty bread slathered liberally with butter!","images":[],"step":7}]', '["gluten"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["coronavirus-food","dinner-tonight","lentil-recipes","main-dishes","quick-and-easy","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d0c2f5002235', 'en', 'US', 'Brazilian Coconut Chickpea Curry', 'Recipe video above. A chickpea recipe that even carnivores think is worth making!! The sauce is from this traditional Brazilian Fish Stew. I call it a curry because it tastes distinctly curryish - except with a fraction of the ingredients!', 'https://www.recipetineats.com/tachyon/2020/02/Brazilian-Chickpea-Curry_2.jpg', 10, 15, 25, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_chickpeas", "quantity": {"value": 2.0, "unit": "can of 400g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.5, "unit": "jar of 40g"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_baby_spinach", "quantity": {"value": 50.0, "unit": "bag of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.9, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["1.5 tbsp olive oil","1 onion (, finely chopped)","2 garlic cloves (, minced)","1 red capsicum/bell peppers (, cut into 3 x 0.75cm / 1.25 x 1/3\"\" strips)","2 cans chickpeas (, drained (Note 1))","400ml/14oz coconut milk (, full fat for best flavour (Note 2))","400ml/14oz can crushed tomato","1 cup (250ml) chicken or vegetable stock/broth (, low sodium)","1 tbsp paprika","1 tbsp cumin","1/2 - 1 tsp cayenne pepper (adjust spiciness to taste)","1.5 tsp sugar (any type)","0.5 tsp salt","50g / 2oz baby spinach leaves (or kale)"],"purpose":"Chickpea Curry:"},{"ingredients":["3 tbsp coriander/cilantro (, roughly chopped, plus more for serving (Note 3))","1 tbsp lime juice (, plus extra wedges for serving)","Yogurt (optional)","Rice - or something to soak up the sauce (Note 4)"],"purpose":"Finishing & Serving:"}]', '[{"description":"Heat oil in a pot or large deep skillet over high heat. Add garlic and onion, cook for 1 minute.","duration":1,"images":[],"step":1},{"description":"Add capsicum, cook for 2 minutes until onion is translucent and slightly golden on edges.","duration":2,"images":[],"step":2},{"description":"Add remaining Curry ingredients except baby spinach. Stir, bring to simmer then lower to medium low so it''s simmering gently.","images":[],"step":3},{"title":"Simmer 12","description":"15 minutes until it changes from pale pink to an orangey red colour.","images":[],"step":4},{"description":"Stir in spinach until just wilted, then stir in coriander and lime juice. Add more salt it needed.","images":[],"step":5},{"description":"Serve over rice with a dollop of yogurt, extra sprinkle of coriander and squeeze of lime (don''t go overboard, I often do and it''s too sour!)","images":[],"step":6}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Brazilian","South American"],"categories":["curry-recipes","dietary","gluten-free-recipes","lentil-recipes","main-dishes","quick-and-easy","south-american-recipes","stews","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2ebeddbe4e0a', 'en', 'US', 'Easy Chickpea Curry with Potato (Chana Aloo Curry)', 'Recipe video above. Say goodbye to boring chickpea recipes! This vegetarian curry called Channa Aloo Curry, is a really great authentic Chickpea Curry that packs serious flavour, is easy, and no need to hunt down unusual spices - everything is from the local grocery shop. It''s a Caribbean curry from Trinidad that tastes very similar to tomato based Indian curries. Spiciness: Medium, from the cayenne pepper most, and bit from white pepper. Can reduce or omit (Note 3).', 'https://www.recipetineats.com/tachyon/2016/01/Chickpea-Curry_7.jpg', 15, 25, 40, 5, '[{"id": "ing_curry_powder", "quantity": {"value": 0.6, "unit": "jar of 50g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_nutmeg_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 666.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_potato", "quantity": {"value": 1.5, "unit": "bag of 2kg"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.985, "unit": "can of 400g"}}, {"id": "ing_tomato", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_white_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 tbsp curry powder (, mild - just regular grocery store brands like Clives, Keens(Note 2))","1 tsp All Spice powder","1 tsp nutmeg powder (or 1/2 tsp freshly grated)","1 1/2 tsp smoked paprika (or normal/sweet)","2 tsp dried thyme leaves (or 3 tsp fresh)","1 tsp cumin powder","3/4 tsp cayenne pepper (for spiciness - reduce or omit (Note 3))","1 tsp white pepper (or 1/2 tsp black pepper) (Note 3)"],"purpose":"Spices (Note 1):"},{"ingredients":["3 tbsp canola or coconut oil (any type) (, or any other oil for cooking)","2 large garlic cloves (, minced)","1 large onion (, diced (brown, white, yellow))","1 1/2 cups potatoes (, cut into 1.2cm / 1/2\" cubes (1 large, any type, peeled))","28 oz / 800g canned chickpeas (2 x 14oz/400g cans), drained (Note 3)","14 oz / 400g canned crushed tomatoes","2 cups vegetable or chicken broth/stock (, low sodium)","1 tsp cooking salt / kosher salt (, plus more to taste (halve for table salt))","2 green onion (, sliced (green & white part))","2 tbsp fresh parsley (, finely chopped (or coriander/cilantro) - optional)"],"purpose":"Curry"},{"ingredients":["1 tbsp coriander/cilantro leaves (, chopped - optional)","Dollop of yogurt (- recommended)","Basmati rice (OR)","White rice"],"purpose":"Serving – choose"}]', '[{"description":"Sauté garlic and onion, then toast Spices for 1 min. Stir in potatoes, then chickpeas, tomato, stock and salt. Simmer 15 min, stir in green onion and parsley, serve!","duration":1,"images":[],"step":1},{"title":"Sauté","description":"Heat oil in a large pot or very deep skillet over medium high heat. Add onion and garlic, cook for 3 minutes until onion is translucent.","duration":3,"images":[],"step":2},{"description":"Add Curry Spices and stir for 1 minute.","duration":1,"images":[],"step":3},{"description":"Add the potatoes and stir to coat in the Spices. If the spices start to stick to the bottom of the pot, add a tiny splash of water.","images":[],"step":4},{"title":"Simmer 15 minutes","description":"Add the chickpeas, tomatoes, veg or chicken broth and salt. Bring to simmer then turn down the heat to medium and simmer for 15 minutes, or until the potatoes are cooked and the sauce has thickened.","duration":15,"images":[],"step":5},{"title":"Adjust salt","description":"Taste and add more salt if needed. Stir through scallions/shallots and parsley.","images":[],"step":6},{"description":"Serve with rice with a dollop of yogurt and coriander/cilantro if desired. Basmati would be ideal, or Coconut Rice if you''re wanting to impress. To go all out, add some Easy Soft Flatbreads!","images":[],"step":7}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Caribbean","Trinidad"],"categories":["curry-recipes","dietary","dinner-tonight","gluten-free-recipes","indian-recipes","lentil-recipes","main-dishes","quick-and-easy","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_39547d7e90fb', 'en', 'US', 'Falafel', 'Recipe video above. Deep bronze and crispy on the outside, vivid green, moist and fluffy on the inside. Delicately spiced with a beautiful fresh herb flavour, these falafels are the perfect balance of flavour, texture and can''t-stop-eating-them delicious! Best served fresh out of the fryer. Recipe requires 12 hrs+ soaking time.', 'https://www.recipetineats.com/tachyon/2018/09/Falafel_4.jpg', 25, 10, 35, 20, '[{"id": "ing_chick_peas", "quantity": {"value": 225.0, "unit": "unit"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 6.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.017, "unit": "tub of 150g"}}, {"id": "ing_flour", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_tahini", "quantity": {"value": 60.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_tabbouleh", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_hummus", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}]', '[{"ingredients":["225 g / 8 oz dried chick peas (Note 1)","1 cup parsley leaves (, roughly chopped)","1 cup coriander/cilantro leaves (, roughly chopped)","6 scallions/shallots (, white and light green part only finely chopped (Note 2))","2 cloves of garlic (, minced)","1 tsp cumin","1/2 tsp coriander","1 1/2 tsp salt","1/2 tsp baking powder (Note 3)","4 tsp flour ((plain/all purpose) OR chickpea flour)","5 tbsp water"],"purpose":"Falafels:"},{"ingredients":["500 ml / 2 cups+ vegetable oil (Note 4)"],"purpose":"For frying:"},{"ingredients":["4 tbsp tahini","2 tbsp lemon juice","4 tbsp water","1/4 tsp salt (adjust to taste)"],"purpose":"Tahini Sauce (Other Sauces Note 5):"},{"ingredients":["Pita bread or other flatbreads","Tabbouleh (recipe below)","Hummus (optional extra)","Shredded lettuce, tomato slices, sliced red or white onion"],"purpose":"Serving (Note 6):"}]', '[{"description":"Place chickpeas in a large bowl and pour over plenty of cold water. Leave to soak 12 + hours (even 2 days is fine).","images":[],"step":1},{"description":"Drain chickpeas well. Place in food processor, add remaining Falafel ingredients.","images":[],"step":2},{"description":"Blitz for 2 to 3 minutes on high, scraping down sides as necessary, until the chickpeas are very small grains. Mixture should look like smooth guacamole from the outside (see video).","duration":2.5,"images":[],"step":3},{"description":"Scoop up heaped tablespoons and shape into balls (or dome, disc or torpedo), place on a tray. Should make around 20, about 2.5cm / 1\" wide.","images":[],"step":4},{"description":"Refrigerate for 30 minutes.","duration":30,"images":[],"step":5},{"title":"Pour oil in a skillet or large pot","description":"at least 1.7 cm / 2/3\" depth (Note 4). Heat on medium high to 180 - 190C / 355F (or drop a bit in, should sizzle energetically).","images":[],"step":6},{"description":"Place a ball in a large spoon (or tongs) and slide ball in. Cook in batches for around 4 minutes, using 2 forks to roll, until deep golden and super crusty on the outside.","images":[],"step":7},{"description":"Drain on paper towels. Repeat with remaining falafel.","images":[],"step":8},{"description":"Serve fresh out of the fryer with Sauce of choice! Make falafel wraps or plates with tabbouleh, tomato, onion, and Sauces of choice. See Notes 5 and 6.","images":[],"step":9},{"description":"Combine tahini and lemon juice, and mix well. The mixture will stiffen.","images":[],"step":10},{"description":"Stir in the water 1 tbsp at a time and it will loosen again. The final consistency should be like a thick drizzle sauce (see video). Season to taste with salt.","images":[],"step":11}]', '["gluten"]', '["keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern"],"categories":["cuisines","deep-fried-recipes","dietary","gluten-free-recipes","iconic-dishes","lentil-recipes","middle-eastern-recipes","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b9129fe3a95f', 'en', 'US', 'Easy Coconut Curry Sauce', 'Recipe video above. This 30 minute recipe is all about the sauce that has beautiful depth of flavour, tastes like an Indian curry but not quite as intense. Specifically created this using spices you can get from everyday grocery stores, rather than having to find speciality Indian spices, but without sacrificing flavour. It''s utterly addictive! I really love lentils and pumpkin with this creamy sauce, but feel free to use whatever you want, including proteins - see notes. Spiciness: Low, as long as your Curry Powder and Garam Masala are not spicy.', 'https://www.recipetineats.com/tachyon/2018/04/Coconut-Curry-with-Lentils-and-Pumpkin_0.jpg', 15, 15, 30, 5, '[{"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_lentils", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_pumpkin", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_baby_spinach", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_cashews", "quantity": {"value": 75.0, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_garam_masala", "quantity": {"value": 15.0, "unit": "jar"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.6, "unit": "jar of 50g"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_turmeric", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}]', '[{"ingredients":["2 tbsp coconut oil, ghee or any regular cooking oil (canola, olive oil etc)","4 garlic cloves (, minced)","2 tsp fresh ginger (, finely grated)","1/2 onion (, finely chopped (brown or yellow))","400ml/14oz can coconut milk (full fat)","1 cup chicken broth","1/2 cup tomato passata (tomato puree) (Note 1)","400 g/14 oz can brown lentils (, drained)","250 g / 8 oz pumpkin (~3 cups) (, cut into 2cm / 4/5\" cubes)","2 cups (tightly packed) baby spinach","1/2 cup cashews (, unsalted (roasted or raw) (Note 2))","1/2 tsp each cooking/kosher salt + black pepper"]},{"ingredients":["1 tbsp garam masala (Note 3)","2 tbsp curry powder (mild or spicy, your choice, Note 4)","2 tsp cumin","1 tsp coriander powder","1 tsp paprika (sweet, or hot for spice!)","1/2 tsp turmeric powder"],"purpose":"Spices:"},{"ingredients":["Coriander/cilantro leaves (, whole or chopped)","Chopped cashews (optional)"],"purpose":"Serving garnishes:"}]', '[{"title":"Sauté aromatics","description":"Heat oil in a deep skillet or pot over medium high heat. Add onion, garlic and ginger, cook for 2 minutes until onion is a bit tinged with gold.","duration":2,"images":[],"step":1},{"title":"Cook off spices","description":"Add Spices and stir for 1 minute. Don''t worry if it looks a bit dried out.","duration":1,"images":[],"step":2},{"title":"Coconut sauce","description":"Add coconut milk, passata and broth. Stir until incorporated. Add lentils and pumpkin. Bring to simmer then adjust heat so it''s simmering energetically.","images":[],"step":3},{"description":"Simmer for 10 minutes or until pumpkin is tender but not mushy, and sauce has thickened.","duration":10,"images":[],"step":4},{"description":"Stir through baby spinach until wilted, then cashew nuts. Add salt and pepper last, adding more if needed.","images":[],"step":5},{"description":"Serve over rice, sprinkled with coriander and extra cashews, if using.","images":[],"step":6}]', '[]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["curry-recipes","dietary","dinner-tonight","gluten-free-recipes","lentil-recipes","main-dishes","pumpkin","quick-and-easy","sunday-supper","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_986a091f1ab0', 'en', 'US', 'Chickpea Lamb Shawarma Soup', 'No such thing as bland chickpea soups in my world! Exploding with the flavours of your favourite Chicken Shawarma, except it’s in SOUP form with lamb and chickpeas! This is not spicy, the small amount of cayenne pepper gives it a tiny warm hum, so if you want it spicier, just add more at the end. Deceptively veggie loaded and is quick to make! Recipe VIDEO below.', 'https://www.recipetineats.com/tachyon/2017/12/Chickpea-Lamb-Shawarma-Soup-4.jpg', 10, 20, 30, 4, '[{"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cardamon", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_lamb_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_chickpeas", "quantity": {"value": 2.0, "unit": "can of 400g"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_spinach", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["2 tsp EACH cumin powder, coriander, paprika","1 tsp cardamon powder (can omit if you don’t have)","¼ tsp cinnamon powder","½ tsp cayenne pepper (adjust to taste)","1/2 tsp black pepper","1 tsp salt"],"purpose":"Spices:"},{"ingredients":["2 tbsp olive oil","2 garlic cloves (, minced)","1 onion (, finely chopped)","500 g / 1 lb lamb mince (ground lamb, or beef) (Note 1)","2 tbsp tomato paste","2 carrots (, peeled and chopped (about size of chickpeas))","600 g / 21 oz canned chickpeas (, drained and rinsed (1.5 standard cans, Note 2))","400 g / 14 oz can crushed tomato","3 cups / 750 ml chicken broth / stock","1 bunch spinach (, roughly chopped (about 4 packed cups) (wilts a lot))"],"purpose":"Soup:"},{"ingredients":["Plain yoghurt (or sour cream)","Chopped fresh coriander / cilantro"],"purpose":"Garnishes (highly recommended):"}]', '[{"description":"Heat oil in a large pot over high heat. Add garlic and onion, cook for 1 minute until starting to turn translucent.","duration":1,"images":[],"step":1},{"description":"Add lamb and cook, breaking it up as you go. When it has mostly turned from pink to light brown, add spices.","images":[],"step":2},{"description":"Cook for 1 minute, then add tomato paste and cook for another 1 minute. (It smells amazing!)","duration":1,"images":[],"step":3},{"description":"Add carrots, chickpeas, tomato and broth. Stir and bring to simmer.","images":[],"step":4},{"description":"Cover with lid, lower heat so it is bubbling energetically but not crazy rapidly. Cook for 10 minutes until carrot is tender but not super soft – I like it to have a bit of bite still, if you want super soft, keep cooking.","duration":10,"images":[],"step":5},{"description":"Stir through spinach. Once wilted, adjust salt, pepper and spiciness (cayenne) to taste, and water if you want more liquid.","images":[],"step":6},{"description":"Ladle into bowls, add a dollop of yoghurt and a generous sprinkling of coriander. Enjoy!","images":[],"step":7}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern"],"categories":["cuisines","dietary","gluten-free-recipes","lamb-recipes","lentil-recipes","main-dishes","middle-eastern-recipes","quick-and-easy","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e1af99f04c95', 'en', 'US', 'Cauliflower and Chickpea Curry', 'This homestyle traditional Indian curry has all the familiar complex, spicy flavours of curries you know and love, but is much healthier and lighter than the usual suspects you get from restaurants. No hunting down hard to find ingredients! I really recommend serving this with yoghurt - adds a touch of creaminess to this healthy tomato based curry. Adding the garam masala towards the end is a great tip - adds a fresh burst of curry flavour', 'https://www.recipetineats.com/tachyon/2016/09/Cauliflower-Chickpea-Curry_6.jpg', 10, 20, 30, 4, '[{"id": "ing_vegetable_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1000.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_turmeric", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_uncategorized", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_frozen_peas", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_garam_masala", "quantity": {"value": 15.0, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}]', '[{"ingredients":["4 tbsp vegetable oil","1 tbsp ginger (finely grated)","3 large garlic cloves (minced.)","1 large onion (chopped (brown, white, yellow))","3 tsp coriander powder","1/4 tsp tumeric powder","1 tsp cumin powder","2 tsp paprika","1 1/2 cups chicken stock","800 g / 28 oz can crushed tomato","300 g / 4 cups (packed cauliflower small florets (1 small / 1/2 large cauliflower))","400 g / 14 oz can chickpeas (drained)","Salt","1 tsp sugar - optional (Note 1)","3/4 cup frozen peas (75g)","3 tsp garam masala powder (Note 2)","1/4 cup coriander / cilantro leaves (chopped)","Yoghurt (to serve (highly recommended))"]}]', '[{"description":"Heat oil in a large deep skillet or pot over medium high heat. Add garlic and ginger, cook for 1 minute. Add onion and cook for 6 - 8 minutes or until golden and caramelised.","duration":1,"images":[],"step":1},{"description":"Add coriander, turmeric, cumin and paprika. Cook for 1 minute.","duration":1,"images":[],"step":2},{"description":"Add chicken stock and tomato. Stir to combine, bring to simmer and cook for 5 minutes.","duration":5,"images":[],"step":3},{"description":"Add cauliflower and chickpeas. Cook for 15 minutes or until cauliflower is soft and sauce has thickened. If sauce is thickening too quickly (Note 3), put the lid on. Adjust salt to taste, and add sugar if using.","duration":15,"images":[],"step":4},{"description":"Add peas and garam masala. Cook for 2 minutes, then remove from stove. Stir through most of the coriander.","duration":2,"images":[],"step":5},{"description":"Serve curry with basmati rice or plain white rice, garnished with reserved coriander and yoghurt on the side.","images":[],"step":6}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["curry-recipes","dietary","dinner-tonight","gluten-free-recipes","indian-recipes","lentil-recipes","main-dishes","most-popular","quick-and-easy","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_43603b3d94f8', 'en', 'US', 'Vegetarian Mexican Lasagna', 'Mexican flavours stacked in a lasagna-type form = Mexican Lasagna! Fresh, light and healthy yet packed full of flavour thanks to the gorgeous Enchilada sauce. The key is whizzing it up in a blender to get the punchy fresh flavours into the sauce! Feel free to swap out the veggies with whatever you want to use.', 'https://www.recipetineats.com/tachyon/2016/09/Vegetarian-Mexican-Casserole-Lasagna_2.jpg', 15, 30, 45, 5, '[{"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_black_beans", "quantity": {"value": 1.062, "unit": "can of 400g"}}, {"id": "ing_corn", "quantity": {"value": 0.562, "unit": "can of 400g"}}, {"id": "ing_tortillas", "quantity": {"value": 750.0, "unit": "pack of 8"}}, {"id": "ing_cheese", "quantity": {"value": 2.5, "unit": "block of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["800 g / 28oz crushed canned tomato","1 tbsp olive oil","1 clove garlic (, whole peeled)","1/2 red onion (, chopped)","1 cup fresh coriander / cilantro (, lightly packed)","1 tbsp EACH cumin (, oregano and paprika (any type))","1 tsp EACH salt (, garlic powder, cayenne pepper (optional) and sugar (any))","2 tsp coriander powder","Black pepper"],"purpose":"Enchilada Sauce"},{"ingredients":["1 tbsp olive oil","1 garlic clove (, minced)","1/2 red onion (, finely chopped)","1 large red capsicum / bell pepper (, chopped (~1 1/2 cups))","2 zucchinis (, chopped (~1 1/2 cups))"],"purpose":"Hot Filling"},{"ingredients":["425 g / 14 oz can black beans (, drained and rinsed)","1 1/2 cups frozen corn","6 large flour tortillas (approx 22 cm / 9\" wide) (2)","2 1/2 cups / 200g grated melting cheese (I used low fat cheddar)","Fresh coriander / cilantro leaves (, for garnish (optional))"],"purpose":"Assembling"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Place Enchilada Sauce ingredients in a blender and whizz until onion is whizzed in and no longer visible. (In my Vitamix, I started on 3 then cranked it to 8 and it took 15 seconds)","images":[],"step":2},{"description":"Heat oil in a large non stick skillet. Add garlic and onion, cook for 1 minute. Add capsicum, cook for 1 minute. Add zucchini and cook for 3 minutes until charred. Remove skillet from heat.","duration":1,"images":[],"step":3},{"description":"Smear a bit of Enchilada Sauce on the bottom of a casserole dish. Place 1 tortilla in the middle, then tear on in half and place on either side (see step photos or video).","images":[],"step":4},{"description":"Top with half the Hot Filling. Scatter over half the black beans, half the corn. Drizzle over 1 cup Enchilada Sauce and 3/4 cup grated cheese.","images":[],"step":5},{"description":"Repeat with another layer so you have 2 layers of filling. Then for the last layer, top with tortillas then cover 2 cups of Enchilada Sauce (Note 3) and scatter over remaining cheese.","images":[],"step":6},{"description":"Bake for 25 minutes or until cheese is bubbling and golden. Stand for 5 minutes, then garnish with fresh coriander and serve.","duration":25,"images":[],"step":7}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Tex-Mex"],"categories":["casseroles-and-cosy-bakes","dietary","gluten-free-recipes","lentil-recipes","low-calorie-recipes","quick-and-easy","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8099f73ff738', 'en', 'US', 'One Skillet Oven Baked Chicken Shawarma and Rice Pilaf', 'This combines two of my favourite Middle Eastern foods into one pot - Chicken Shawarma and Rice Pilaf. The Chicken Shawarma is the same recipe as the one I use for grilling (recipe here) with just quantities adjusted to suit using thigh cutlets cooked on the stove. The rice pilaf has been adapted from Yotam Ottolenghi''s Chicken with Cardamon Rice recipe from his cookbook "Jerusalem" (one of my all time favourite cookbooks!). Note that this is not an authentic way of preparing Chicken Shawarma! Real Shawarma is cooked on a rotisserie then shaved and served in a kebab. This is my one pot rice version - Shawarma flavours, made in one pot with rice!', 'https://www.recipetineats.com/tachyon/2015/08/One-Pot-Chicken-Shawarma-and-Rice_Hero.jpg', 15, 50, 65, 5, '[{"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_rice", "quantity": {"value": 225.0, "unit": "pack"}}, {"id": "ing_chicken", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_cardamon", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 2.0, "unit": "jar"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_raisins", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 large garlic clove (, minced (or 2 small cloves))","1 1/2 tsp ground coriander","1 1/2 tsp ground cumin","1 tsp ground cardamom","1 tsp smoked paprika (or ordinary is fine)","1 tsp cayenne pepper (optional)","1/2 tsp salt","Black pepper","3 tbsp lemon juice"],"purpose":"Spice Rub"},{"ingredients":["5 chicken thigh fillets (, bone in, skin on - about 2 lb / 1kg in total (Note 1))","1/2 tbsp olive oil","1 small onion (, finely diced)","2 garlic cloves (, minced)","1 1/2 cups long grain rice (, uncooked (Note 2))","1 1/2 cups chicken broth (or water)","2 cups water","3/4 - 1 tsp salt","Black pepper","1 1/2 tsp cardamon powder","2 cinnamon sticks (or 1/2 tsp cinnamon powder)","400g (14oz) can chickpeas (, drained (1 can))","1/4 cup raisins or sultanas (optional)"],"purpose":"Chicken and Rice"},{"ingredients":["Yoghurt (plain, unsweetened. Greek yoghurt is great)","Cilantro/coriander leaves (, roughly chopped)","Parsley leaves (, roughly chopped)"],"purpose":"Garnish (optional)"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Mix the Spice Rub ingredients together in a small bowl. Slather onto the chicken, covering both sides.","images":[],"step":2},{"title":"Optional","description":"Marinate for at least 1 hour, up to 24 hours. (Note 3)","images":[],"step":3},{"description":"Heat olive oil in a large skillet over medium high heat. Add the chicken, skin side down, and cook for 5 minutes on each side, or until light golden brown.","duration":5,"images":[],"step":4},{"description":"Remove chicken from skillet. Scrape off excess black bits stuck to the pan and discard, along with excess oil (but leave some to cook the onion).","images":[],"step":5},{"description":"Add garlic and onion. Cook for 2 minutes until translucent.","duration":2,"images":[],"step":6},{"description":"Add rice and stir so the grains are coated in oil and become a bit translucent.","images":[],"step":7},{"description":"Add remaining ingredients. Place the chicken on top - it should be half submerged with the skin above the surface. Pour in the juices from the plate as well.","images":[],"step":8},{"description":"Bring to simmer, then place a lid on (or cover with foil) and transfer to oven.","images":[],"step":9},{"description":"Bake for 35 minutes, then remove the lid and bake for a further 10 minutes.","duration":35,"images":[],"step":10},{"description":"Remove from the oven. Let it rest for 5 minutes.","duration":5,"images":[],"step":11},{"description":"Remove chicken from the rice and mix the rice quickly (to evenly distribute flavour).","images":[],"step":12},{"description":"Serve, garnished with cilantro/coriander and parsley if desired. I also like to serve it with a bit of plain yoghurt. (Note 4)","images":[],"step":13}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern"],"categories":["chicken-recipes","cuisines","dietary","dinner-tonight","gluten-free-recipes","lentil-recipes","main-dishes","middle-eastern-recipes","most-popular","one-pot-recipes","quick-and-easy","rice-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_600b1b4235e2', 'en', 'US', 'Easy slow cooker BBQ pulled beef', 'Recipe video above. Make this when you want a big batch of succulent pulled beef smothered in an incredible homemade barbecue sauce, made using the convenience of a slow cooker. Pile into sliders, heap onto plates, stuff into baked potatoes. So many ways to enjoy it!Adapted from my Easy Slow Cooker BBQ pulled pork recipe. I don''t sear the pork before slow cooking, but it''s really worth searing the beef. I tried without and it was still great, but it''s noticeably better when you do. :)Easy to scale up - I can do a double batch in my slow cooker.', 'https://www.recipetineats.com/tachyon/2026/06/Easy-slow-cooker-BBQ-shredded-beef-8.jpg', 30, 620, 650, 8, '[{"id": "ing_beef", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.5, "unit": "bottle of 500ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_molasses", "quantity": {"value": 45.0, "unit": "jar"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 20.0, "unit": "bottle"}}, {"id": "ing_tabasco", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_green_onion", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["1.5 kg / 3 lb chuck beef (, cut into 4 thick steaks (Note 1))","1 cup beer (anything other than dark stouts like Guinness), or beef stock/broth, low sodium (Note 2)","3 tbsp olive oil (or other neutral oil, for searing)"]},{"ingredients":["3 tbsp (tightly packed) brown sugar","1 tbsp paprika powder (regular/sweet or smoked)","1 tbsp garlic powder","2 tsp onion powder","2 tsp mustard powder","1 tsp cumin powder","2 tsp cooking salt / kosher salt","1 tsp black pepper"],"purpose":"RUB:"},{"ingredients":["1 cup apple cider vinegar (Note 3)","3 cups tomato ketchup (or Aussie tomato sauce)","3 tbsp molasses (, orginal (not blackstrap, Note 4))","2/3 cup brown sugar","4 tsp mustard powder","3 tsp garlic powder","4 tsp Worcestershire sauce","2 tsp cooking salt / kosher salt","2 tsp black pepper","2 tsp Tabasco ( or cayenne pepper (optional, very faint background spiciness))"],"purpose":"BBQ Sauce:"},{"ingredients":["2 tbsp green onion (, finely sliced)"],"purpose":"Option garnish (for serving in bowl)"}]', '[{"description":"Mix BBQ sauce in slow cooker. Coat beef in Rub, sear. Deglaze pan with beer. Arrange beef in slow cooker, add beer, slow cook 10 hours. Shred, reduce BBQ sauce on stove, toss half with beef, serve rest on the side.","images":[],"step":1},{"title":"BBQ Sauce","description":"Put all the ingredients in a slow cooker and whisk to combine.","images":[],"step":2},{"title":"Season beef","description":"Mix the Rub together in a medium bowl. Dredge the steak in the Rub to coat on both sides.","images":[],"step":3},{"title":"Sear","description":"Heat half the oil in a large non stick pan over medium high heat. Brown 2 steaks for 1 - 1 1/2 minutes on each side until deep golden but take care not to burn the spice rub. Place in the slow cooker. Wipe the pan clean of black bits, heat the remaining oil and repeat with remaining 2 steaks.","images":[],"step":4},{"title":"Deglaze pan with beer","description":"Add the beer into the pan and let it simmer rapidly, scraping the base as you go, until it is reduced down to about 1/4 cup - about 3 minutes. Pour into the slow cooker.","images":[],"step":5},{"title":"Slow cook 10 hours","description":"Arrange the beef so each piece is as submerged as much as possible. Slow cook on low for 10 hours. The beef should be tender enough to easily shred.","images":[],"step":6},{"title":"Shred","description":"Remove the beef into a pan and shred with 2 forks.","images":[],"step":7},{"title":"Reduce sauce","description":"Pour the sauce from the slow cooker into a pot or large deep fry pan. Simmer on medium high for 15 to 20 minutes until thickened to a BBQ sauce consistency. Stir regularly towards the end and lower heat as needed if it starts to splutter aggressively.","duration":17.5,"images":[],"step":8},{"title":"Toss","description":"Pour about 1/3 to 1/2 the sauce over the beef and toss (use enough to moisten and flavour, but not make it soggy).","images":[],"step":9},{"description":"Serve the beef with remaining BBQ sauce. Use for sliders and sandwiches with Coleslaw for classic southern sliders (pictured), make plates with Corn bread, Mac and Cheese and corn on the cob on the side, stuff into baked potatoes. You just can''t go wrong however you serve it!","images":[],"step":10}]', '["mustard"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["BBQ","Southern","Texas","Western"],"categories":["beef","beef-recipes","mains","sandwiches-and-sliders","slow-cooked-fall-apart","slow-cooker-recipes","stews"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_de90de965662', 'en', 'US', 'Beef Rump Cap Roast (Picanha)', 'Recipe video above. Rump cap is considered by many to be the best cut for roast beef - prime rib quality without the price tag! But cook it wrong and it’s a chewy disaster. This recipe uses a safe, straightforward method that ends with pure roast beef bliss - edge-to-edge medium rare and a golden, crackly fat cap. Bonus: two new steak sauce obsessions provided! Chimichurri Butter plus a Roasted Garlic Butter (links in ingredient list)', 'https://www.recipetineats.com/tachyon/2025/11/Rump-cap-roast-picanha_1.jpg', 10, 90, 100, 8, '[{"id": "ing_beef_steak", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 0.625, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_classic_chimichurri", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_bearnaise_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_cafe_de_paris", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_mushroom", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}]', '[{"ingredients":["2 kg/ 4 lb beef rump cap / picanha ((more names: sirloin cap, coulette), silver skin trimmed off)","5 tsp sea salt flakes (or 3 1/2 tsp cooking salt / kosher salt - Note 2)","1/2 tsp black pepper"]},{"ingredients":["Chimichurri butter (pictured, stellar!)","Roasted Garlic Butter (pictured, current obsession!)","Classic Chimichurri","Bearnaise sauce","Cowboy butter","Cafe de Paris","Creamy mushroom sauce","My favourite Blue Cheese Sauce (page 330 of Dinner)","Red wine sauce (page 327 of Dinner)","Dijon mustard, wholegrain mustard, horseradish cream (good ones!)"],"purpose":"Sauce options:"}]', '[{"description":"Score fat (cut right in), rub meat with 2 tsp salt, and 3 tsp on fat cap. Roast on rack at 140°C/285°F (120°C fan) until the internal temperature is 48°C / 118°F (~70 minutes - 1 1/2 hrs). Rest 30 minutes, brown fat cap quickly under very hot oven grill/broiler (3 min max). Serve immediately!","images":[],"step":1},{"description":"Preheat the oven to 140°C/285°F (120°C fan-forced).","images":[],"step":2},{"title":"Dry","description":"Pat excess moisture off the surface of the rump cap with paper towels.","images":[],"step":3},{"title":"Score the fat cap with 2.5cm / 1\" diamonds","description":"cut well into the fat but don''t cut into the meat. (But not a disaster if you do, unlike pork crackling!)","images":[],"step":4},{"title":"Rub salt","description":"Rub the meat surface with 2 teaspoons of the salt and half the pepper (ie underside and sides). Then rub the remaining 3 teaspoons of salt and pepper into the fat cap.","images":[],"step":5},{"title":"Meat thermometer","description":"Place the beef on a rack set on a tray. Insert an oven-safe meat thermometer into the middle of the thickest part of the beef, if using.","images":[],"step":6},{"title":"Slow-roast","description":"Roast until the internal temperature is 48°C / 118°F, between 70 to 90 minutes (it varies! Note 3)","images":[],"step":7},{"title":"Rest","description":"Remove from the oven and leave on the counter for 30 - 40 minutes to rest (do not cover). The internal temperature will climb to 56°C / 132.8°F which is perfect medium rare. (Note 4 for other doneness)","duration":35,"images":[],"step":8},{"description":"Brown fat cap:","images":[],"step":9},{"title":"Preheat","description":"Halfway through the resting time, preheat the oven grill / broiler as high as it will go. Arrange the shelf so the surface of the fat cap will be 12cm / 5\" from the heat element.","images":[],"step":10},{"title":"Brown","description":"Grill rump cap for 2 - 3 minutes until the fat cap is golden and a bit crisp. Keep a close eye on it, it can burn quickly, and remove after 3 minutes even if not golden enough else you risk a band of overcooked beef.","duration":2.5,"images":[],"step":11},{"title":"Ready! The beef is ready to serve","description":"there is no need to rest again.","images":[],"step":12},{"description":"Slicing to serve:","images":[],"step":13},{"description":"Cut the beef thinly into 8mm / 1/3\" slices and serve with sauce of choice (you can go up to 1.25cm / 1/2\" if you have wagyu). Don''t be tempted to cut thick slices, this beef cut is not suitable for that! (Note 5 about grain direction)","images":[],"step":14}]', '["milk","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef","beef-recipes","iconic-dishes","mains","roast-beef","roasts","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3c5b97ebc16f', 'en', 'US', 'Birria Tacos', 'Recipe video above. Birria Tacos - or Quesabirria - the legendary crispy red tacos stuffed with cheesy shredded beef dunked in rich consommé. This was a beast of a recipe to crack, so I’m thrilled we finally got there. What makes these special: specify chillies by weight not number, toss shredded beef in sauce, skim red-oil off to use for crisping tacos, and our consommé is not watery and thin, it''s a smidge thicker than usual so it clings better.These deliver big flavour with every single bite, the consommé is rich and full bodied with beefy chilli flavour, and wow the tacos are crisp! Important: Birria is very reliant on chillies for flavour. So if you don''t have scales for the chillies, deseed, chop, then measure using cups. Don''t rely on "2 anchos", they can vary so much in size.', 'https://www.recipetineats.com/tachyon/2025/09/Birria-tacos_4.jpg', 30, 180, 210, 22, '[{"id": "ing_chilli", "quantity": {"value": 0.25, "unit": "pack of 100g"}}, {"id": "ing_chilli", "quantity": {"value": 0.25, "unit": "pack of 100g"}}, {"id": "ing_chilli", "quantity": {"value": 0.25, "unit": "pack of 100g"}}, {"id": "ing_chilli", "quantity": {"value": 0.25, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_beef", "quantity": {"value": 1.3, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_bay_leaf", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_salt", "quantity": {"value": 0.013, "unit": "kg"}}, {"id": "ing_tortillas", "quantity": {"value": 20.0, "unit": "pack of 8"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cheese", "quantity": {"value": 3.5, "unit": "block of 250g"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_hot_sauce", "quantity": {"value": 1.0, "unit": "bottle of 150ml"}}]', '[{"ingredients":["25 g (0.9 oz) guajillo chillies, dried (~4 pieces, heaped 3/4 cup once chopped) (Note 1)","45 g (1.6 oz) ancho chillies, dried (~2-3 pieces, 1 cup once chopped) (Note 1)","6 g (0.2 oz) chillies de arbol, dried (~6 pieces, 2 tbsp once chopped) (Note 1)","1/2 cup chilli soaking water (reserve after simmering)","5 garlic cloves (, peeled)","1 small onion (, roughly sliced (~tennis ball size))","1 medium tomato (, roughly sliced (180g))","2 tsp dried oregano","1 tsp ground cumin","1/8 tsp black pepper"],"purpose":"Birria adobo (paste):"},{"ingredients":["5 tbsp vegetable oil (or canola oil) (Note 2)","1.3 kg/2.6 lb chuck beef (, cut into 6 large pieces (or boneless beef short ribs - 1.8kg/3.6 lb bone-in) (Note 3))","2 cups beef stock / broth (, low sodium)","10 cloves (or 1/4 tsp ground cloves)","1 cinnamon stick (substitute 1/4 tsp powder, but it''s not quite the same)","3 bay leaves (, preferably fresh else dried)","2 tbsp apple cider vinegar (or regular white vinegar, red or white wine vinegar)","2 1/2 tsp cooking salt / kosher salt (halve for table salt, +30% for flakes)"],"purpose":"Birria braising:"},{"ingredients":["1/2 tsp cooking salt / kosher salt"],"purpose":"Beef seasoning:"},{"ingredients":["20 - 25 corn tortillas (14.5cm/6\" wide) (Note 4)","1 white onion (, diced (Note 5))","1/2 cup finely chopped coriander / cilantro leaves","3 1/2 cups (350g) shredded Colby, Monterey Jack or (Oaxaca cheese (if you can get it) (Note 6))","Lime wedges (, optional)","Your favorite salsa or hot sauce (, optional)"],"purpose":"Birria Tacos:"}]', '[{"description":"Simmer chopped chillies 10 min. Strain, blitz Adobo paste. Brown beef, cook off adobo paste, slow-cook beef 2 1/2 hrs (lid on). Remove meat, shred, skim fat off braising liquid (\"Birria Oil\"). Toss beef in skillet with 1 cup braising liquid (aka Consomme). Heat 1 tsp Birria oil over low heat, wipe pan with tortilla, remove, repeat x2 with 1/2 tsp oil each. Top tortilla with cheese, beef, onion, coriander, fold over, pan fry until crisp. Serve with Birria Consomme for dunking!","images":[],"step":1},{"description":"Prepare chillis:","images":[],"step":2},{"description":"Use gloves if you''re sensitive to working with chilli!","images":[],"step":3},{"title":"Deseed","description":"Trim and discard stems. Cut lengthwise, remove and discard the seeds. Roughly chop into 1 - 1.5cm / 1/4\" pieces.","images":[],"step":4},{"title":"Simmer","description":"Put chillis in a large saucepan of boiling water. Simmer rapidly for 10 minutes to soften, until flesh is mushy (skin stays intact but softens).","duration":10,"images":[],"step":5},{"description":"Reserve 1/2 cup of chilli-simmering water. Drain chilli in a sieve, lightly press out residual liquid.","images":[],"step":6},{"title":"Birria Adobo (paste)","description":"Place cooked chillies, reserved 1/2 cup chilli water and remaining Adobo ingredients in a tall jug large enough to fit the head of a stick blender. Blitz for 20 seconds until as smooth as possible (it''s not completely smooth, see video). You can also do this in a small food processor, NutriBullet or blender (Note 7).","duration":0.3333333333333333,"images":[],"step":7},{"title":"Sear beef","description":"Heat the oil in a large heavy based pot over high heat (I use my 24cm / 9.6\" dutch oven). Add half the beef and sear each side aggressively until it''s dark golden brown (about 1 - 1 1/2 minutes each side). Remove to a bowl and repeat with remaining beef.","images":[],"step":8},{"title":"Cook off Adobo","description":"Add the paste to same pan and stir for 2 minutes in oil (lower heat if spitting aggressively).","duration":2,"images":[],"step":9},{"title":"Slow cook 2 1/2 hours","description":"Add all Birria braising ingredients, stir, then add the beef. Bring to a boil then lower heat until it''s simmering very gently (small gentle bubbles every now and then). Cover with a lid and cook for 2 1/2 hours, or until beef shreds easily (short ribs take 3 - 3.5 hrs). (Note 8 for slow cooker)","images":[],"step":10},{"title":"Shred","description":"Remove the beef to a clean pan and shred well. Add the 1/2 teaspoon of salt and toss meat to distribute.","images":[],"step":11},{"title":"Birria oil","description":"Skim off as much of the red oil floating on braising liquid surface as possible (ideally 6 tbsp+) and place in a separate bowl (this is the \"Birria Oil\"). Precious stuff!","images":[],"step":12},{"title":"Soak beef","description":"Pour 1 cup of the braising liquid (\"Birria Consommé\") into a large non-stick pan over medium-high heat. Let it simmer for 15 seconds, then add all the beef and toss in the sauce until it''s all absorbed by the beef, there should be almost none pooled in the pan. Move beef back into the shredding pan, scraping the non-stick pan clean.","duration":0.25,"images":[],"step":13},{"title":"Birria Consommé","description":"Taste and check for salt, add more if needed. It should be on the slightly salty side (because it''s used for dipping) but not too salty to drink a small cup like soup. Keep warm to use for dipping once tacos are done.","images":[],"step":14},{"title":"Red tortillas","description":"Heat 1 teaspoon Birria Oil in the same non-stick pan over medium-low heat. Put a tortilla in and \"wipe\" around to make the underside red. Once the tortilla is soft (no need to flip) - about 10 seconds - remove to a work surface red side down. Repeat twice more, heating 1/2 teaspoon Birria Oil for each tortilla.","images":[],"step":15},{"title":"Stuff","description":"Spread cheese on half of each tortilla, top with beef, then onion and coriander/cilantro.","images":[],"step":16},{"description":"Crisp! Fold over then pan-fry 3 Birria Tacos at a time (in the same pan) over medium-high heat for 2 minutes on each side, until golden-red and crispy.","duration":2,"images":[],"step":17},{"title":"Serve","description":"Remove and serve while hot with the Birria Consommé for dunking! (Drink leftover consommé, it might be the best soup broth you have this year).","images":[],"step":18}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["beef","beef-recipes","iconic-dishes","mains","mexican-recipes","slow-cooked-fall-apart","slow-cooker-recipes","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f1acfebb1ff2', 'en', 'US', 'Tomahawk Steak', 'Recipe video above. Don’t cook a tomahawk steak entirely on the BBQ - you’ll end up with a thick, overcooked band! The best way is to use the reverse-sear method: oven first, then BBQ. It''s stress free and you''ll have blushing pink meat from edge to edge with a killer crust - steak perfection! All credit to J Kenji Lopez-Alt for popularising this now world renowned method which can be used for all thick cut steaks.No BBQ? See note 5 for the oven-only method.PS Please a meat thermometer to nail the doneness - this is not the time to guess.PPS Even if you overshoot to 60°C/140°F, it still eats like medium-rare. Also - see FAQ above for making stacks for a tomahawk party!', 'https://www.recipetineats.com/tachyon/2025/05/Tomahawk-steak-shoot-3_6-1.jpg', 5, 60, 80, 2, '[{"id": "ing_beef_steak", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_bearnaise_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_cafe_de_paris", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_mushroom", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chimichurri_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_mustard", "quantity": {"value": 0.005, "unit": "jar of 200g"}}]', '[{"ingredients":["1 tomahawk steak (1.2 - 1.5kg / 2.4 - 3lb) (Note 1)","2 tsp cooking salt/kosher salt","3/4 tsp black pepper","1 tbsp olive oil"],"purpose":"Tomahawk Steak"},{"ingredients":["Cowboy butter (pictured in post - Tomahawk worthy!)","Bearnaise sauce","Cafe de Paris","Creamy mushroom sauce","Chimichurri sauce","Blue cheese sauce (page 330 of Dinner)","Blue cheese sauce (page 330 of Dinner)","Dijon or seeded mustard"],"purpose":"Steak sauce options"}]', '[{"description":"Season, slow-roast on rack at 140°C/285°F (120°C fan) for 40-45 minutes to 50°C/122°F. Rest 10 minutes. Preheat BBQ until screaming hot, drizzle steak with oil, lower BBQ to low/med low and sear on hot BBQ 3 - 4 minutes on each side (temp 55°C (128°F)). Rest 3 minutes (temp rises to 57°C/135°F = perfect medium rare 🙌🏻). Slice, serve with Cowboy Butter!","duration":42.5,"images":[],"step":1},{"description":"Oven slow-roast:","images":[],"step":2},{"title":"De-chill","description":"Take the steak out of the fridge 1 hour prior to cooking. Remove from packaging and pat the surface dry. (Do not salt).","images":[],"step":3},{"description":"Preheat the oven to 140°C/285°F (120°C fan-forced).","images":[],"step":4},{"title":"Season","description":"Sprinkle the steak meat with salt and pepper, then use your hands to rub it in.","images":[],"step":5},{"title":"Slow(ish) roast","description":"Put the steak on a rack and set it on a baking tray. (Note 2) Bake for 40 to 45 minutes, or until the internal temperature is 50°C/122°F (for medium rare, see Note 3 for other doneness).","duration":42.5,"images":[],"step":6},{"title":"Rest","description":"Take the tray out of the oven and leave the steak on the counter for 10 minutes. (Internal temperature should rise by 3 degrees).","duration":10,"images":[],"step":7},{"description":"Preheat the BBQ on high until it''s screaming hot. Use the flat plate side if you''re not a confident BBQ''er, or the grill side if you''re a BBQ master. (Note 4)","images":[],"step":8},{"title":"Oil","description":"Drizzle the oil on the steak and lightly pat to spread (don''t rub off the salt), using most of the surface area of the meaty part.","images":[],"step":9},{"title":"Turn BBQ DOWN","description":"If using the grill side, reduce to low (if yours is strong, mine is) or medium low (for weaker ones). If using the flat plate side, lower to medium. Do this just before putting the tomahawk on.","images":[],"step":10},{"title":"Edges first","description":"Using tongs, hold the steak upright and sear the edges and bone first (only if you''ve got meat on it), rotating and moving every minute or so to achieve this all the way around. ⚠️Flare-ups – If searing on the grill side, don’t walk away - flare-ups are inevitable. See Note 4 for managing.","images":[],"step":11},{"title":"Steak crust","description":"Then place the steak down on the grill and cook for 3 to 4 minutes on each side, or until the internal temperature is 55°C / 131°F. For classic X grill lines, rotate once 45° partway through.","duration":3.5,"images":[],"step":12},{"title":"Rest the steak on a rack for 3 minutes","description":"the internal temperature will rise to 57°C/135°F which is perfect medium rare.","duration":3,"images":[],"step":13},{"title":"Serve","description":"Cut into 1 cm / 0.4\" thick slices. Serve with steak sauce of choice! (Pictured: Cowboy Butter, highly recommend!).","images":[],"step":14}]', '["milk","mustard"]', '["gluten_free","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef","beef-recipes","iconic-dishes","mains"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0e4199cee174', 'en', 'US', 'Beef in black bean sauce', 'Recipe video above. This incredible Beef in Black Bean Sauce recipe is from Hannah, a chef at our food bank RecipeTin Meals who was born and raised in China, and comes from a long line of chefs. I''ll wager this recipe beats any Chinese restaurant you’ve tried - even “fancy” city ones - and it is far, far cheaper. Made from scratch, it leaves jarred sauces in the dust. Shockingly easy!', 'https://www.recipetineats.com/tachyon/2025/04/Beef-in-black-bean-sauce_8.jpg', 20, 10, 90, 4, '[{"id": "ing_black_beans", "quantity": {"value": 0.188, "unit": "can of 400g"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_oil", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.006, "unit": "tub of 200g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_white_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1/2 cup (75g) preserved black beans (salted black beans, fermented black beans, Note 1)","400g/14 oz beef rump steak (US: top sirloin) (, thinly sliced 3mm / 0.1\" (Note 2))","1 brown onion (, medium size, cut into 2.5cm/1\" squares)","1 green capsicum ((bell pepper), medium size, cut into 2.5cm/1\" squares)","1 tbsp garlic (, finely minced with a knife ~ 4 cloves (Note 3))","1/2 cup peanut oil (or vegetable, canola) (Note 4)","1 tbsp Chinese cooking wine (shaoxing wine) (Note 5)"]},{"ingredients":["1 tbsp light soy sauce (Note 6)","1 tsp dark soy sauce (Note 6)","1 tbsp oyster sauce","2 tsp cornflour / cornstarch","1/4 tsp baking soda (bi-carbonate) (Note 7)","1 tbsp sesame oil (toasted ie brown, not untoasted which is yellow)"],"purpose":"Tenderising beef marinade:"},{"ingredients":["1 tbsp light soy sauce (Note 6)","2 tsp white sugar","2 tbsp cornflour/cornstarch (20g)","1 cup water"],"purpose":"Sauce:"},{"ingredients":["White rice"],"purpose":"Serving:"}]', '[{"description":"Abbreviated recipe:","images":[],"step":1},{"description":"Marinade beef 1 hour, soak beans, mix sauce. Shallow fry beef 30 seconds, remove. Discard all but 3 tbsp oil. Add and cook in this order: black beans 20 seconds, garlic 10 seconds, onion + capsicum 1 minute, beef 1 minute, cooking wine 30 seconds, sauce 1 minute or until thickened. Serve!","images":[],"step":2},{"description":"Mix the marinade ingredients EXCEPT sesame oil in a bowl. Add beef, mix to coat. Add sesame oil, mix again.","images":[],"step":3},{"title":"Marinade","description":"Refrigerate to marinade for 1 hour.","images":[],"step":4},{"title":"Soak beans","description":"Put the salted black beans in a medium bowl and cover with water. Set aside for 30 minutes to 1 hour to soak, then drain.","duration":30,"images":[],"step":5},{"title":"Mix sauce","description":"Put the cornflour, soy sauce and sugar in a jug or small bowl. Mix until lump free then mix in the water. Set aside.","images":[],"step":6},{"description":"Cooking:","images":[],"step":7},{"title":"Cook beef","description":"Heat the oil in a wok (or non stick pan) over high heat. Add the beef and cook, tossing, for 30 seconds until it changes from red to brown. Remove with a slotted spoon onto a plate.","duration":0.5,"images":[],"step":8},{"description":"Discard most of the oil in the wok, keep just 3 tablespoons.","images":[],"step":9},{"title":"Aromatics","description":"Return the wok to high heat. Add the black beans and stir for 20 seconds, then add the garlic and stir for 10 seconds. Add the capsicum and onion, cook for 1 minute.","duration":0.3333333333333333,"images":[],"step":10},{"title":"Beef","description":"Add beef and any juices pooled on the plate, toss for 1 minute. Pour the Chinese cooking wine around the sides of the wok so it runs down into the beef then toss for 30 seconds (Note 8)","duration":1,"images":[],"step":11},{"title":"Sauce","description":"Pour the sauce in, then stir and let it bubble for 1 minute or until the sauce thickens, is shiny and coats the beef beautifully.","duration":1,"images":[],"step":12},{"title":"Serve","description":"Pour into a serving bowl and serve with rice!","images":[],"step":13}]', '["gluten","peanuts","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["beef","beef-recipes","chef-hannahs-recipes","chinese-recipes","iconic-dishes","mains"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_31cea54aec7d', 'en', 'US', 'Thai Sweet Chilli Beef Bowls', 'Recipe video above. This quick dinner using beef mince channels Thai Chilli Basil stir fry vibes (but, no basil and not spicy) with poke bowl versatility (but, no pricey raw fish!). I use bottled sweet chilli sauce for simplicity instead of fresh chilli, garlic, sugar and thickener, and it works a treat. Plus, it''s more kid friendly because you can barely taste the spice.The key is the Sweet Chilli Drizzle Sauce! It adds flavor to the beef, rice, and veggies (raw or cooked). Jumble it all up and dig in!', 'https://www.recipetineats.com/tachyon/2024/12/Thai-sweet-chilli-beef-bowls_0.jpg', 13, 7, 20, 4, '[{"id": "ing_roasted_cashews", "quantity": {"value": 50.0, "unit": "jar"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 0.9, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_steamed_or_veg", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["1/3 cup roasted cashews (, unsalted (or peanuts, Note 1))","1 tbsp canola oil (, or other plain cooking oil)","500 g / 1 lb beef mince (ground beef)","1 small onion (, finely chopped)","2 garlic cloves (, finely minced)","3 tbsp roughly chopped coriander/cilantro leaves (sub green onion)"]},{"ingredients":["2 tbsp sweet chilli sauce (I use Trident)","2 tbsp fish sauce (Note 2)","2 tbsp rice vinegar (sub cider vinegar)","1 tbsp oyster sauce (Note 3)","1 tbsp dark soy sauce (Note 3)"],"purpose":"Sweet chilli stir fry sauce:"},{"ingredients":["1 garlic clove (, minced using garlic crusher)","3 tbsp sweet chilli sauce","2 tbsp lime juice (sub rice vinegar when limes are crazy expensive)","2 tsp fish sauce (Note 2)"],"purpose":"Sweet chilli drizzle sauce:"},{"ingredients":["2 batches jasmine rice (or other plain rice of choice)","Steamed or fresh veg (Note 5) (pictured: chopped cucumber, coriander/cilantro, red onion finely sliced)"],"purpose":"Serving:"}]', '[{"description":"Abbreviated recipe","images":[],"step":1},{"description":"Mix each sauce. Toast cashews, sauté onion + garlic 1 min, then cook beef. Add sauce, cook until reduced/caramelised, serve over rice with veg on side. Spoon over drizzle sauce, top with cashews and coriander.","images":[],"step":2},{"title":"Drizzle sauce","description":"Mix the ingredients in a bowl, set aside.","images":[],"step":3},{"title":"Stir fry sauce","description":"Mix the ingredients in a separate bowl, set aside.","images":[],"step":4},{"title":"Toast cashews","description":"Heat a large non-stick pan over medium high heat. Add the cashews and toast for 2 minutes. Transfer to a cutting board then roughly chop once cool.","duration":2,"images":[],"step":5},{"title":"Cook beef","description":"Heat the oil in the same pan over high heat. Add the garlic and onion, cook for 1 minute. Add the beef and cook, breaking it up as you go, until you no longer see raw meat.","duration":1,"images":[],"step":6},{"description":"Sauce it! Add the cooking sauce and cook well, stirring, until it mostly reduces down so the sauce caramelises on the beef, about 3 - 4 minutes. (Don''t shortcut this step, it''s where the flavour is!)","images":[],"step":7},{"description":"Serve the beef over rice with a side of veg. Douse everything with the sauce, top with cashews and coriander (fresh chilli wouldn''t go astray either). To eat, jumble everything up then dig in!","images":[],"step":8}]', '["fish","gluten","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef","beef-mince-recipes","beef-recipes","dinner-tonight","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5732397bf16b', 'en', 'US', 'One Pot Cajun Beef Pasta with lots-of-veg', 'Recipe video above. A big bubbly beefy pasta in a Cajun flavoured tomato sauce, filled with lots of hidden vegetables, all made in one pot! Love that it''s a complete meal, and a great way to stretch 500g/1lb beef to serve more people with the bonus of a stack of "hidden" vegetables (carrot, zucchini ,zucchini, canned tomato and onion - yes, onion counts towards daily veg intake!).Leftovers are excellent! Fridge or freeze.', 'https://www.recipetineats.com/tachyon/2024/09/One-pot-Cajun-Beef-Pasta_0.jpg', 15, 25, 40, 7, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_zucchini", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_kidney_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.7, "unit": "pack of 500g"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.562, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}]', '[{"ingredients":["1 tbsp olive oil","2 garlic cloves (, finely minced)","1 onion (, chopped)","500g/ 1 lb beef mince (ground beef) (Note 1)","1 carrot (, medium, shredded using box grater (I keep skin on) )","1 zucchini (, medium, shredded using box grater (Note 2))","1 red capsicum (bell pepper), chopped (Note 2)","2 tbsp tomato paste","800g/ 28 oz canned crushed tomato","400g/ 14 oz kidney beans (, drained (or other beans of choice, can omit))","2 cups chicken stock/broth (, low sodium (sub beef stock))","2 cups water (just regular tap water!)","350g / 12 oz (3 cups) elbow pasta (macaroni) (, spirals, penne, ziti, small shells, rigatoni or similar size, uncooked (Note 3))","1 1/2 cups (tightly packed) colby cheese (or other melting cheese of choice, preferably freshly shredded (melts better))","1 green onion stem (, finely sliced (optional garnish))"],"purpose":"One-pot pasta:"},{"ingredients":["1 1/2 tsp dried thyme","1 1/2 tbsp paprika (sweet/regular, not smoked or spicy)","2 tsp garlic powder","2 tsp onion powder","1/2 tsp cayenne pepper (, optional (faintly spicy))","1/4 tsp black pepper","1 1/4 tsp cooking salt / kosher salt"],"purpose":"Cajun spices:"}]', '[{"description":"Heat the oil in a large heavy based pot with a lid over high heat.","images":[],"step":1},{"title":"Cook vegetables","description":"Cook the onion and garlic for 2 minutes. Add the beef and cook, breaking it up as you go, until you no longer see red meat. Add the carrot and zucchini, cook for 2 minutes until the water they release mostly evaporates. Add the capsicum and cook for 2 minutes.","duration":2,"images":[],"step":2},{"title":"Spices","description":"Add the tomato paste and Cajun Spices. Cook for 1 minute.","duration":1,"images":[],"step":3},{"title":"Pasta sauce","description":"Add the canned tomato, water (I swill the cans clean), stock and beans. Mix and bring to a simmer.","images":[],"step":4},{"description":"Add the pasta, stir, let it come back up to the simmer. Put the lid on and lower the heat slightly to medium so the liquid is simmering (not bubbling madly).","images":[],"step":5},{"description":"Cook for 15 minutes, stirring every few minutes so the base doesn''t catch. The pasta should be a bit firmer than you want in the middle, and still a bit soupy which is good! Liquid gets absorbed in the next step.","duration":15,"images":[],"step":6},{"title":"Melt cheese","description":"Give it a stir, smooth the surface, sprinkle with cheese. Put the lid on then turn the stove off (leave the pot on the stove). Leave for 3 minutes so the residual heat melts the cheese and the pasta finishes cooking.","duration":3,"images":[],"step":7},{"title":"Serve","description":"Remove from the stove, sprinkle with green onion if desired, then serve immediately while saucy and the cheese is gooey!","images":[],"step":8}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef","beef-mince-recipes","beef-recipes","mains","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ac5f1a0b1b90', 'en', 'US', 'Beef Tenderloin with Creamy Mushroom Sauce', 'Recipe video above. This recipe uses a simple but highly effective, low-risk slow-roasting technique for evenly cooked tenderloin that''s blushing pink from edge to edge. No thick overcooked band!A slather of garlic-thyme-butter gives the beef a tasty crust, and the drippings from roasting are used to make a magnificent creamy mushroom sauce. Marsala, an Italian fortified wine you can pick up cheaply, is the secret ingredient in the sauce for a luxurious edge of flavour. But if you need to be alcohol free, see recipe notes.Please get a meat thermometer to take the guess work out! It''s far cheaper than the beef. (Note 4)PRO TIP: Season the beef the night before for best results. (Note 5)', 'https://www.recipetineats.com/tachyon/2023/12/Beef-tenderloin-with-mushroom-sauce_3.jpg', 15, 60, 75, 4, '[{"id": "ing_beef", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 75.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_mushroom", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_marsala", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}]', '[{"ingredients":["1 - 1.25kg/ 2 - 2.5lb centre cut beef tenderloin (eye fillet), tied (Note 1)","1 1/2 tsp cooking / kosher salt","1/2 tsp black pepper","1 tbsp vegetable oil"],"purpose":"Beef:"},{"ingredients":["75g/ 5 tbsp unsalted butter (, softened)","1 tsp garlic (, finely grated or very finely minced with a knife)","1 tsp fresh thyme leaves (, finely chopped (Note 2))","1/4 tsp cooking/kosher salt","1/4 tsp black pepper"],"purpose":"Garlic-Thyme-Butter-Slather:"},{"ingredients":["150g/5 oz white mushrooms (, sliced 3mm thick)","1/2 tsp garlic (, finely minced)","1 thyme sprig (Note 2)","3/4 cup marsala (, Italian fortified wine (Note 3))","1/2 cup chicken stock (, low sodium)","3/4 cup thickened cream (heavy cream)","1/4 tsp black pepper"],"purpose":"Creamy mushroom sauce:"}]', '[{"title":"Prep beef","description":"Pat beef dry with paper towels, sprinkle with salt and pepper all over. Place the beef on a rack on a tray then refrigerate uncovered 12 to 24 hours. (Can skip, Note 5)","images":[],"step":1},{"title":"Butter Slather","description":"Mix Butter Slather ingredients in a bowl.","images":[],"step":2},{"title":"De-chill","description":"Remove the beef from the fridge 2 hours prior to cooking. This helps the beef cook evenly.","images":[],"step":3},{"title":"Sear","description":"Heat oil in an ovenproof heavy based pan over high heat until smoking. (Note 6) Brown the surface of the beef all over, aggressively and quickly. Then put the beef back on the rack to cool for 15 minutes (so the butter doesn''t instantly melt when you put it on).","duration":15,"images":[],"step":4},{"description":"Preheat oven to 120°C/250°F (both fan and standard ovens) (Note 7).","images":[],"step":5},{"title":"Butter","description":"Put beef back in cooled skillet. Slather 3/4 of the butter onto the beef - top and sides (not underside).","images":[],"step":6},{"title":"Roast 40","description":"50 minutes - Roast for 15 minutes. Remove, slather remaining butter onto the top and sides. Roast for a further 25 - 35 minutes or until the internal temperature is 53°C/127°F for medium rare (Note 8 for other levels of doneness).","duration":15,"images":[],"step":7},{"title":"Rest & serve","description":"Remove beef from the skillet onto a cutting board and rest for 10 minutes. The internal temperature will rise 56-58°C / 133-136°F (this is medium rare). Slice thickly and serve with Creamy Mushroom Sauce!","duration":10,"images":[],"step":8},{"description":"Creamy mushroom sauce","images":[],"step":9},{"title":"Roasting juices","description":"Pour all juices in skillet into a bowl or jug. The fat will rise to the surface. Pour off 1/4 cup (60ml) of the fat back into the skillet (reserve the rest for later).","images":[],"step":10},{"title":"Cook mushrooms","description":"Turn the stove onto high. Once the butter is hot, add mushrooms and cook until they start to sweat. Then add thyme and garlic, and cook for a further 2 minutes until the mushrooms are softened.","images":[],"step":11},{"title":"Sauce","description":"Add chicken stock/broth and reduce by half. Add marsala, cream, pepper and remaining reserved roasting juices. Simmer on medium / medium high for 5 minutes until it reduces by half and the sauce is thickened. Taste - it should be slightly on the salty side (which will seem just right with each mouthful of beef). Add more salt if needed. Serve with beef.","duration":5,"images":[],"step":12}]', '["fish","milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef","beef-recipes","mains","roast-beef","roasts","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_37e8be83e724', 'en', 'US', 'One pot creamy tomato beef pasta', 'Recipe video above. This is a beefy pasta cooked with Italian seasonings in a creamy tomato sauce. Epitome of homemade comfort food with the convenience of one-pot cooking! Love how the pasta absorbs the flavour of the sauce.For more, see the full One Pot Pasta recipe collection.', 'https://www.recipetineats.com/tachyon/2023/08/One-pot-creamy-tomato-beef-pasta_0.jpg', 10, 20, 30, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_italian_herbs", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.7, "unit": "pack of 500g"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 1/2 tbsp olive oil","2 garlic cloves (, finely minced)","1 onion (, finely chopped)","500g/ 1 lb beef mince / ground beef","2 tsp Italian herbs (Note 1)","2 tbsp tomato paste","400g/ 14 oz can crushed tomatoes (or tomato passata)","1/2 tsp red pepper flakes (chilli flakes, optional)","1 1/2 tsp cooking salt/kosher salt","1/2 tsp black pepper","4 cups (1 L) chicken stock/broth (, low sodium (Note 2))","350g/ 12oz fusilli, penne, elbow macaroni ( or other short pasta (Note 3))","3/4 cups thickened / heavy cream"]},{"ingredients":["Parmesan cheese (, finely grated)","Parsley (, finely chopped, optional)"],"purpose":"Serving:"}]', '[{"title":"Sauté","description":"Heat the oil on high heat in a large heavy-based pot. Cook garlic and onion for 1 1/2 minutes.","images":[],"step":1},{"title":"Cook beef & seasonings","description":"Add beef and cook, breaking it up as you go, until you can no longer see red meat. Add the Italian herbs and cook for 30 seconds, then add tomato paste and cook for 1 minute to cook out the raw flavour.","duration":0.5,"images":[],"step":2},{"title":"All in","description":"Add crushed tomato, chicken stock, salt, pepper and red pepper flakes, if using. Stir, then add the pasta.","images":[],"step":3},{"title":"Cook 15 min","description":"Bring the liquid to a simmer, then cook for 15 minutes, stirring every couple of minutes then more frequently towards the end (ensure pasta doesn''t stick to base) until the pasta is just about cooked.","duration":15,"images":[],"step":4},{"title":"Creamy","description":"Add cream, then simmer for a further 1 to 2 minutes. It will still be quite saucy - this is what you want! Pasta absorbs liquid quickly, so it will still be nice and oozy when you start eating.","images":[],"step":5},{"title":"Serve","description":"Remove from the stove. Give it a good stir then ladle into bowls. Serve with parmesan and parsley.","images":[],"step":6}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["beef","beef-mince-recipes","beef-recipes","dinner-tonight","mains","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5231f7ba1735', 'en', 'US', 'Crispy Lebanese Meat Stuffed Pita - Arayes', 'Recipe video above. Lebanese street food - pita bread stuffed with spiced kofta meat, pan fried until crispy! Think of these as Lebanese quesadillas or easy Gozleme. :) The unique method here is that it''s cooked with raw meat inside, so the tasty meat juices soaks into and flavours the pita bread as it cooks. It''s outrageously delicious. I bet you become as obsessed with these as I have!', 'https://www.recipetineats.com/tachyon/2023/07/Arayes_2-close-up.jpg', 15, 15, 30, 10, '[{"id": "ing_bread", "quantity": {"value": 5.0, "unit": "loaf"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_tahini", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}]', '[{"ingredients":["5 pita bread (, the thin pocket type, ~15cm/6\" diameter (250g/8oz pack), cut in half (Note 1))","Olive oil spray (or brush with olive oil)"]},{"ingredients":["1/2 brown onion","500g/ 1 lb lamb or beef mince (ground meat) (Note 2)","2 garlic cloves (, finely grated)","1 tbsp finely chopped parsley (, optional)","3 tsp ground coriander","3 tsp ground cumin","1 1/2 tsp smoked paprika (sub plain paprika)","3/4 tsp ground allspice (sub mixed spice)","1/2 tsp cayenne pepper (reduce/omit for less spicy - Note 4)","1 1/4 tsp cooking/kosher salt"],"purpose":"Spiced meat filling:"},{"ingredients":["1 cup plain yogurt","2 tbsp tahini (or Chinese sesame paste - Note 5)","1 tbsp lemon juice","1 garlic clove (, finely grated)","1/2 tsp cooking/kosher salt"],"purpose":"Whipped tahini yogurt sauce:"}]', '[{"description":"Spiced meat filling:","images":[],"step":1},{"description":"Grate the onion in a bowl using a standard box grater. We want the juices and all! (Note 4)","images":[],"step":2},{"title":"Meat filling","description":"Add remaining meat filling ingredients. Mix well with your hands.","images":[],"step":3},{"description":"Divide stuffing in 10 (about 55 to 60g per portion, 1/4 cup). Flatten into a semi-circle shape slightly smaller than the pita bread half.","images":[],"step":4},{"title":"Stuff","description":"Gently open a pita then place the meat inside. Close, then press to spread to the edge and make it fairly evenly flat. (Is your pita tearing? See Note 5 for tip!)","images":[],"step":5},{"description":"Cooking Arayes:","images":[],"step":6},{"description":"Preheat oven to 50C/120F. Place a rack on a tray. (To keep cooked Arayes warm.)","images":[],"step":7},{"title":"Cook","description":"Heat a large frying pan over medium high heat. Spray both sides of the pita with olive oil then place 2 or 3 pieces in the pan (whatever you can fit). Cook for about 2 minutes on each side, pressing down lightly with a spatula, until golden and crispy. The meat is spread so thin it cooks really quickly! {Sandwich press - Note 7}","images":[],"step":8},{"title":"Keep warm","description":"Transfer cooked Arayes onto the rack and put in the oven to keep warm. Cook remaining pita.","images":[],"step":9},{"title":"Serve","description":"Cut in half if desired (sometimes I do, sometimes I don''t!). Pile Arayes onto a serving platter. Serve with Whipped Tahini sauce. Enjoy!","images":[],"step":10},{"description":"Whipped tahini sauce:","images":[],"step":11},{"description":"Place ingredients in a heatproof bowl and whisk to combine. Microwave for 15 seconds on high. Whisk again - it should resemble soft whipped cream. Use slightly warm or at room temperature.","duration":0.25,"images":[],"step":12}]', '["gluten","milk","sesame"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["lebanese","Middle Eastern"],"categories":["beef","beef-mince-recipes","beef-recipes","cuisines","lamb","mains","middle-eastern-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c74153ab432e', 'en', 'US', 'Saltimbocca', 'Recipe video above. This rustic Italian classic is fabulously quick to make thanks to thin slices of veal that cook in 2 1/2 minutes flat. Traditionally made with veal, Saltimbocca is also excellent with chicken or beef. The trick to a great Saltimbocca sauce is to slowly melt in cubes of cold butter by swirling the pan off the heat. This thickens the sauce and makes it luxuriously silky. It''s a stunner! Serve with mashed potato, cauliflower mash or mop your plate clean with bread.', 'https://www.recipetineats.com/tachyon/2022/09/Veal-saltimbocca_6.jpg', 7, 5, 12, 2, '[{"id": "ing_beef_steak", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_sage", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_prosciutto", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_wine", "quantity": {"value": 0.083, "unit": "bottle of 750ml"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 x 80g / 3 oz thin veal steaks or boneless cutlets","1/4 tsp black pepper","4 large sage leaves","4 prosciutto slices (finely sliced, Note 2)","2 tbsp flour (plain/all-purpose)","2 tbsp olive oil"]},{"ingredients":["50 g / 3 tbsp COLD unsalted butter (, cut into 1cm / 1/3\" cubes (Note 3))","1/4 cup white wine (, pinot grigio or chardonnay (Note 4))","Small pinch of salt"],"purpose":"Saltimbocca Sauce:"}]', '[{"description":"Prepare saltimbocca:","images":[],"step":1},{"title":"Pound","description":"Place the veal between sheets of cling wrap or paper. Pound to an even 3mm thickness using a meat mallet (Note 5 for tips!) Cut each piece in half so you have 4 pieces in total, and sprinkle both sides with pepper.","images":[],"step":2},{"title":"Prosciutto and sage","description":"Fold a slice of prosciutto in half then place on one piece of veal (trim if needed so it''s not hanging off the sides too much). Place a sage leaf on top then secure with a toothpick, piercing from the underside (see step photos or video). Do the same with the other piece of veal.","images":[],"step":3},{"title":"Dust","description":"Spread flour on a plate. Press the non-prosciutto side of the veal into the flour, shaking off excess (do not flour the prosciutto side).","images":[],"step":4},{"description":"Cook:","images":[],"step":5},{"title":"First side 1 1/2 minutes","description":"Heat oil in a large fry pan over medium-high heat. Place veal slices in the pan, prosciutto-side down, and cook for 90 seconds until prosciutto is beautifully golden.","duration":1.5,"images":[],"step":6},{"description":"Other side 1 min:Turn veal and cook the other side for 1 minute. Remove to a warm plate.","duration":1,"images":[],"step":7},{"description":"Tip out excess oil (do not scrape pan clean however). Return skillet to stove, with heat still on.","images":[],"step":8},{"title":"Reduce wine","description":"Pour in wine (careful, it will be steamy!) plus pinch of salt. Bring to a simmer then let it cook for 20 to 30 seconds, stirring to scrape up the brown fond from the base of the pan, until wine is reduced by half.","duration":0.4166666666666667,"images":[],"step":9},{"title":"Swirl butter","description":"Keep the pan on the stove but turn the stove OFF. Scatter the butter in the pan then swirl (or stir) until it melts. The clear liquid will thicken magically into a luscious butter sauce!","images":[],"step":10},{"description":"Serve:","images":[],"step":11},{"description":"Divide veal between plates. Spoon over sauce. Devour! (Careful of the toothpick!)","images":[],"step":12}]', '["gluten","milk"]', '["high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["beef","chicken-breast-recipes","italian-recipes","mains","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_009c06f39fc0', 'en', 'US', 'Family Meat Pie', 'Recipe video above. Aussies love a good meat pie. We love the hand-held ones because we get the whole thing to ourselves. But when you''ve got sharing vibes, this Family-size Meat Pie is the one you pull out. Shortcrust base, slow cooked fall-apart chunks of beef smothered in a rich gravy with a golden puff pastry lid.It''s knee-shatteringly good comfort food!Workflow - I usually make the filling the day before, then refrigerate overnight. Then I do everything else on the day of serving.', 'https://www.recipetineats.com/tachyon/2021/09/Meat-Pie-Family-Size_39-new.jpg', 20, 240, 440, 6, '[{"id": "ing_beef", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.625, "unit": "pack of 200g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_guinness", "quantity": {"value": 330.0, "unit": "unit"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_quantity_shortcrust_pastry", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_sheet_puff_pastry", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["800g/ 1.6lb chuck beef (, 3.5cm/1.4\" cubes (Note 1))","3/4 tsp salt","1/2 tsp pepper","2 tbsp olive oil (, plus more as needed (or vegetable or canola))"],"purpose":"Beef:"},{"ingredients":["30g / 2tbsp unsalted butter","200g / 7 oz mushrooms (, smallish, halved (larger ones quartered))","125g / 4 oz streaky bacon (, cut into 1 x 1.5cm / 0.4 / 0.6\" cubes)","1 onion (, cut into 2cm / 0.8\" cubes)","2 garlic cloves (, minced)","1 celery (, cut into 1cm/0.4\" slices (split wide end of celery lengthwise, don’t want giant celery chunks))","1 carrot (, halved, 1cm/0.4\" slices (quarter very thick end if needed))","330ml / 11 oz Guinness (Note 2)","2 cups beef stock (, homemade or store bought low sodium (Note 3))","1 cup water","1/4 tsp salt","3/4 tsp coarsely crushed black pepper (, plus more as desired)"],"purpose":"Filling:"},{"ingredients":["4 tbsp flour","60g / 4 tbsp unsalted butter (, softened)"],"purpose":"Beurre Manié (sauce thickener, Note 4)"},{"ingredients":["1 quantity shortcrust pastry","1 sheet puff pastry (, for lid (Note 6))","1 egg (, lightly whisked)"],"purpose":"Pastry:"},{"ingredients":["Ketchup or Aussie Tomato Sauce (, for serving)"],"purpose":"Serving:"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan).","images":[],"step":1},{"title":"Brown beef","description":"Sprinkle beef with 3/4 tsp salt and 1/2 tsp pepper. Heat oil in a large heavy based pot over high heat. Brown beef aggressively in 2 to 3 batches (do not crowd pot, else it gets watery instead of browning). Then remove beef into a big bowl.","images":[],"step":2},{"title":"Wipe down pot","description":"Wipe pot clean of burnt bits, if needed.","images":[],"step":3},{"title":"Cook bacon","description":"Cool pot, add bacon. Place pot back onto medium heat. When you see some fat starting to melt, turn heat up to medium high and cook bacon until golden. Then remove into bowl with beef.","images":[],"step":4},{"title":"Cook mushrooms","description":"Melt 30g/ 2tbsp butter in the pot. Cook mushrooms until golden with a pinch of salt and pepper. Remove into separate bowl with slotted spoon.","images":[],"step":5},{"title":"Cook other vegetables","description":"Add onion, garlic, carrot and celery then cook for 5 minutes until onion is soft and sweet, not too golden. Add oil if needed, but bacon fat + residual butter should be enough.","duration":5,"images":[],"step":6},{"title":"Oven slow cook","description":"Add beef, bacon, Guinness, water, stock, 1/4 tsp salt and 3/4 tsp pepper. Stir then bring to simmer. Cover with lid, then transfer to oven for 1 hour.","images":[],"step":7},{"description":"Add mushrooms, then continue cooking in the oven for a further 1 hour. Meat should be starting to be tender at this stage.","images":[],"step":8},{"description":"Thicken Sauce and Cool:","images":[],"step":9},{"title":"Stove reduce","description":"Remove pot from oven. Remove lid, then simmer on low heat for 20 minutes to reduce sauce. Meat should now be \"fall-apart-tender\" but just holding form (not disintegrating).","duration":20,"images":[],"step":10},{"title":"Sauce thickener (Beurre Manié","description":"Note 4): Mix together butter and flour until smooth.","images":[],"step":11},{"title":"Thicken sauce","description":"Stir Beurre Manié into sauce. Once melted, leave on the stove for another 2 minutes. Sauce should be thicker than a normal stew, like a honey consistency. Sauce will not thicken any more in oven, so make it exactly what you want - Note 7. Also, there will be more sauce than you expect for a pie - some gets absorbed by pastry (but won''t make it soggy).","images":[],"step":12},{"title":"Cool","description":"Cover pot with lid, then let it cool completely, preferably overnight. (Note 8)","images":[],"step":13},{"description":"Assemble and bake:","images":[],"step":14},{"title":"Shortcrust base","description":"Make and blind bake Shortcrust Pastry per that recipe using a 23cm/9” pie dish, whether using homemade or store bought. Then let it cool for at least 15 minutes (stays crispier).","images":[],"step":15},{"title":"Preheat oven","description":"Turn oven up to 200°C/390°F (180°C fan).","images":[],"step":16},{"title":"Fill pie","description":"Bring filling to room temp, do not use fridge cold. (Note 9) Fill pie with filling (use it all, pack it in a level surface or have slight mound).","images":[],"step":17},{"title":"Puff pastry lid","description":"Partially thaw puff pastry (do not cut). Brush lip of pie crust base with egg, then top with puff pastry sheet. Trim excess with scissors, press to adhere to edges. Then press the tip of a fork around the edge to make little crimps (to further adhere + decorative).","images":[],"step":18},{"title":"Egg wash","description":"Brush top with remaining whisked egg, then make a 2.5cm / 1\" X incision in middle to allow steam to escape (stops lid doming).","images":[],"step":19},{"title":"Bake: Bake 45","description":"50 minutes until top is super golden. Rest 5 minutes. Brag in comments below that you made this magnificent pie. Save Nagi a slice. Then serve remainder with ketchup or Aussie tomato sauce!","images":[],"step":20}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Australian"],"categories":["beef","beef-recipes","casseroles-and-cosy-bakes","mains","quiches-tart-and-pie-recipes","slow-cooked-fall-apart","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a7e5f4b903d8', 'en', 'US', 'Café de Paris - Steak butter sauce', 'Recipe video above. Café de Paris is a butter for steak flavoured with a mix of herbs, spices and savoury condiments. Despite the name, it originates from Switzerland, popularised by a restaurant called "Café de Paris". Now a staple steak sauce around the world (including in Paris!), slices of this compound butter are placed on hot steaks so they melt to form a butter sauce. It''s so simple, yet so incredibly good!Makes enough for 4 to 6 steaks, depending on how much butter you want on your steaks. Keeps for 2 months in the fridge, also excellent over seafood, poultry and hot steamed veg!', 'https://www.recipetineats.com/tachyon/2021/08/Cafe-de-Paris-butter-for-steak_19.jpg', 10, 0, 10, 4, '[{"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_fish_fillets", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_tarragon", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}]', '[{"ingredients":["100g / 7 tbsp unsalted butter (, softened)","2 tbsp eschalot (small), very finely chopped (Note 1)","1 garlic (, finely minced)","3 anchovy fillets (, finely chopped (Note 2))","1 tsp lemon juice","1 tsp Worcestershire sauce","1 tsp Dijon mustard","1 tsp curry powder (mild, Note 3)","1/2 tsp paprika (plain or sweet, not smoked or spicy)","1 tsp kosher / cooking salt","2 tsp tarragon (, finely chopped (Note 4))","2 tsp parsley (, finely chopped)"]},{"ingredients":["Steaks of choice (Note 5)","1/2 tsp cooking/kosher salt per steak","1/4 tsp black pepper per steak","1 tbsp vegetable or canola oil"],"purpose":"Steak:"}]', '[{"description":"Café de Paris butter:","images":[],"step":1},{"description":"Place ingredients in a bowl and mix to combine.","images":[],"step":2},{"description":"Place on cling wrap and roughly shape into a 20cm / 8\" log using spatulas or butter knives.","images":[],"step":3},{"description":"Roll up, then twist ends tightly. As you tighten the ends, the butter will shape into a neat, firm log.","images":[],"step":4},{"description":"Tie ends if needed to keep the shape. Refrigerate for 3 hours or until firm.","images":[],"step":5},{"title":"To use","description":"Slice into 0.7cm (1/3\") slices, then let them soften to room temperature (so they melt easier). Place on hot steak so it melts - I use 2 slices each steak. Leftovers - fridge 3 days or freeze 2 months (pre sliced for ease of use).","images":[],"step":6},{"description":"Cooking Steak:","images":[],"step":7},{"description":"Cooking Steak:","images":[],"step":8},{"title":"Bring to room temp","description":"Take the steak out of the fridge 30 minutes prior to cooking.","images":[],"step":9},{"title":"Dry","description":"Pat steaks dry with paper towels.","images":[],"step":10},{"title":"Heat skillet","description":"Heat oil in a heavy based skillet over high heat until it is very hot - you should see smoke!","images":[],"step":11},{"title":"Season","description":"Sprinkle each side of the steak generously with salt and pepper, then immediately place in the skillet.","images":[],"step":12},{"title":"Cook steak to taste","description":"For 2cm (3/4\") thick steaks, cook the first side for 2 minutes, then turn and cook the other side for 2 minutes (medium rare 52°C/125°F, chart below for other doneness temps).","duration":2,"images":[],"step":13},{"title":"Rest","description":"Transfer steaks to a warm plate, cover loosely with foil and rest for 5 to 10 minutes, then serve.","duration":7.5,"images":[],"step":14},{"description":"Cooking Steak:","images":[],"step":15},{"title":"Leftovers","description":"fridge 3 days or freeze 2 months (pre sliced for ease of use).","images":[],"step":16}]', '["fish","milk","mustard"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["beef","beef-recipes","mains","quick-and-easy","sauces"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_751a5c03d295', 'en', 'US', 'Mexican Meatballs', 'Recipe video above. The best Mexican Meatballs are spiced with Mexican flavours and made with:1. crushed corn chips instead of breadcrumbs (more flavour!);2. a combination of beef AND pork (softer and tastier); and3. are browned in the oven then simmered in the chipotle tomato sauce for a winning flavour exchange: meatball juices leech into the sauce, and the meatballs absorb the sauce flavour. Win win!Spiciness: Chipotle powder and fresh jalapeno in meatballs gives it a warm buzz but definitely not spicy. Same for chipotle chilli in sauce. Feel free to reduce both and add a pinch of paprika in its place.', 'https://www.recipetineats.com/tachyon/2021/06/Mexican-Meatballs_5.jpg', 20, 25, 45, 4, '[{"id": "ing_beef_mince", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_corn", "quantity": {"value": 0.125, "unit": "can of 400g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_coriander", "quantity": {"value": 0.9, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.9, "unit": "bunch"}}, {"id": "ing_jalape_o", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_cumin", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_chipotle", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.9, "unit": "bunch"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_chipotle_from_a_can_of_chipotle_in_adobo", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_adobo_sauce_from_a_can_of_chipotle_in_adobo", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.9, "unit": "bunch"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_guacamole", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["250g / 8oz beef mince (ground beef)","250g / 8oz pork mince (ground pork), or more beef (Note 1)","1/2 red onion (, grated using a standard box grater)","50g / 1.75 oz plain corn chips (, sub breadcrumbs + 1/4 tsp salt (Note 2))","1 egg","3 tbsp coriander/cilantro (, finely chopped (sub chives or parsley))","3 tbsp parsley (, finely chopped (optional))","2 tsp fresh jalapeño (, seeds removed and finely minced (reduce/omit for not spicy))","Oil spray (preferably olive oil)"],"purpose":"Meatballs:"},{"ingredients":["1 1/2 tsp ground cumin","1 tsp chipotle powder (, sub more smoked paprika, reduce for less spicy (Note 3))","1 tsp coriander powder","1 tsp garlic powder (sub 1/2 fresh garlic clove, finely grated)","1/2 tsp paprika (, hot for spicy or sweet for not (or sub more Chipotle powder))","1 tsp salt","1/2 tsp black pepper"],"purpose":"Meatball Mexican Spices:"},{"ingredients":["2 tbsp olive oil","2 cloves garlic (, finely minced)","1 chipotle from a can of Chipotle in Adobo (, finely chopped - add another for extra flavour! (Note 4))","1 tsp Adobo Sauce from a can of Chipotle in Adobo (Note 4)","800g / 24 oz crushed tomato","1 tsp sugar","1 tbsp coriander/cilantro (, roughly chopped)"],"purpose":"Chipotle Sauce:"},{"ingredients":["Coriander/cilantro leaves (, whole)","Shredded cheese","Sour cream","Guacamole (or just diced, sliced or mashed plain avocado)","Rice, for serving ((Note )"],"purpose":"Toppings & garnishes (pick & choose):"}]', '[{"description":"Preheat oven to 220°C/390°F (200°C fan). Place a rack over a tray. Spray rack with oil.","images":[],"step":1},{"title":"Blitz corn chips","description":"Place corn chips in a Nutribullet or food processor. Blitz until they become fine crumbs. (Else put in a ziplock bag and bash!)","images":[],"step":2},{"title":"Meatball mixture","description":"Place meatball ingredients and meatball Mexican spices in a bowl and mix well with your hands.","images":[],"step":3},{"title":"Roll meatballs: Roll into 3","description":"3.5cm / 1.2 - 1.4\" balls. Place on rack. Should make around 20 - 24 meatballs.","images":[],"step":4},{"title":"Bake 10 minutes","description":"Spray meatballs generously with oil. Bake 10 minutes until browned (they will still be raw inside, we finish cooking them in the sauce).","images":[],"step":5},{"description":"While the meatballs are in the oven, start the sauce.","images":[],"step":6},{"title":"Sauté garlic and chipotle","description":"Heat oil over medium high heat in a large skillet. Add garlic and cook for 30 seconds. Add chopped Adobo Chile and sauté for 20 seconds.","duration":0.5,"images":[],"step":7},{"title":"Simmer 5 minutes","description":"Add tomato, Adobo sauce and sugar. Bring to simmer, then turn heat down to low and cook, stirring every now and then, for 5 minutes.","duration":5,"images":[],"step":8},{"description":"Finish Meatballs:","images":[],"step":9},{"title":"Cook meatballs in sauce","description":"Remove meatballs from oven and transfer into sauce. Continue to cook the sauce for another 10 minutes, rolling meatballs every now and then, until the sauce is thickened and the meatballs are cooked.","images":[],"step":10},{"title":"Fresh coriander","description":"Sprinkle with chopped coriander/cilantro.","images":[],"step":11},{"title":"Serving","description":"Serve over rice or stuff into tortillas with toppings of choice!","images":[],"step":12}]', '["egg","milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Mexican","Tex-Mex"],"categories":["beef","beef-mince-recipes","beef-recipes","mains","meatball-recipes","mexican-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c72d597383e7', 'en', 'US', 'Beef Bourguignon (Beef Burgundy)', 'Recipe video above. Considered by many to be the mother of all stews, Beef Bourguignon is a French dish made with beef, bacon lardons, carrots, onions and mushrooms slow-cooked in a rich red wine sauce. For the most magnificent stew of your life, start this 2 days before you plan to serve it, do not shortcut pan roasting ingredients individually, and use homemade beef stock if you can!', 'https://www.recipetineats.com/tachyon/2021/02/Beef-Bourguignon_7.jpg', 40, 150, 190, 5, '[{"id": "ing_beef", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 2000.0, "unit": "pack of 1kg"}}, {"id": "ing_onion", "quantity": {"value": 16.0, "unit": "pack of 1kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.75, "unit": "pack of 200g"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.09, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["800g/ 1.6 lb chuck beef (, cut in 4-5 cm / 2” cubes (Note 1))","2 large carrots ((~300g/10oz), cut on an angle into 4-5 cm / 2” pieces)","16 pearl onions or small, round pickling onions (Note 2)","1 bay leaf (, fresh (sub: dried))","3 sprigs thyme","750ml/ 25 oz pinot noir or other red wine (Note 3)"],"purpose":"Beef marinade:"},{"ingredients":["3 tbsp oil (, olive, canola or vegetable)","3/4 tsp salt","1/2 tsp pepper"],"purpose":"Browning beef:"},{"ingredients":["200g/ 7oz mushrooms (, halved (quarters if large))","150g/ 5oz bacon piece (, cut into 1cm / 1/2” thick batons (Note 4))","50g/3 tbsp unsalted butter","3 garlic cloves (, minced)","2 tbsp tomato paste","6 tbsp flour (, plain/all purpose)","3 cups beef stock (low sodium)","1/4 tsp salt","2 tbsp chopped parsley (, for garnish)"],"purpose":"Stew:"}]', '[{"title":"Marinate beef","description":"Place the Beef Marinade ingredients in a large, non-reactive ceramic dish or ziplock bag. Marinate overnight in the fridge (minimum 12 hours, maximum 24 hours).","images":[],"step":1},{"description":"Strain liquid into a bowl, reserve marinade. Separate the beef, carrots and onion.","images":[],"step":2},{"title":"Reduce wine","description":"Pour red wine into a saucepan and bring to a boil over medium high heat. Simmer vigorously, skimming off any impurities that rise to the surface, until reduced by half. Set aside.","images":[],"step":3},{"description":"Brown beef and vegetables:","images":[],"step":4},{"description":"Preheat oven to 180°C / 350°F (160°C fan).","images":[],"step":5},{"title":"Dry beef","description":"Line a tray with paper towels, spread beef out, then pat dry with paper towels.","images":[],"step":6},{"title":"Season beef","description":"Sprinkle beef with 3/4 tsp salt and 1/2 tsp black pepper.","images":[],"step":7},{"title":"Brown beef","description":"Heat 2 tbsp oil in a large, heavy-based, oven-proof pot over high heat. Add 1/3 beef and brown aggressively all over. Remove into bowl, then repeat with remaining beef, adding more oil if needed.","images":[],"step":8},{"title":"Fry bacon","description":"Add bacon and cook for 3 minutes until golden. Add to bowl with beef.","duration":3,"images":[],"step":9},{"title":"Sauté mushrooms","description":"Add mushrooms and cook for 5 minutes, or until golden. Remove into a new bowl.","duration":5,"images":[],"step":10},{"title":"Sauté onion","description":"Add a bit of extra oil if needed, then cook onions for 5 minutes or until there are nice golden patches. Add to bowl with mushrooms.","duration":5,"images":[],"step":11},{"title":"Sauté carrot","description":"Add butter into pot. Once melted, add carrot and cook for 3 - 4 minutes until there are golden patches. Add garlic and cook for a further 1 minute.","duration":3.5,"images":[],"step":12},{"title":"Tomato paste","description":"Add tomato paste and cook for 2 minutes.","duration":2,"images":[],"step":13},{"title":"Flour","description":"Add flour and cook for 2 minutes.","duration":2,"images":[],"step":14},{"title":"Add wine and stock","description":"While stirring, slowly pour in beef stock – this helps the flour dissolve lump-free into the stock. Then add wine and mix until flour mixture is dissolved and mostly lump-free (Note 6).","images":[],"step":15},{"title":"Add beef into pot","description":"Add beef, bacon, thyme, bay leaf, 1/4 tsp salt and pepper into the pot, then stir well.","images":[],"step":16},{"description":"Slow-cook:","images":[],"step":17},{"title":"Oven 1 hour","description":"Bring to a simmer, then cover and transfer to oven for 1 hour. (Note 7)","images":[],"step":18},{"title":"Mushrooms and onion","description":"Remove from oven, stir in mushrooms and onion.","images":[],"step":19},{"title":"Oven 1½ hours","description":"Cover with lid and return to oven for 1½ hours, or until beef is \"fall-apart tender\".","images":[],"step":20},{"title":"Adjust salt","description":"Remove from oven, taste sauce and add salt if needed. (Note 8 - important!)","images":[],"step":21},{"title":"Leave overnight (recommended)","description":"If time permits, leave the stew overnight before serving because as with all stews, it gets better with time! Reheat gently on a low stove.","images":[],"step":22},{"title":"Serve over mashed potato","description":"Essential for mopping up every drop of that amazing sauce!","images":[],"step":23}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["beef","beef-recipes","iconic-dishes","mains","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8d6676aa595a', 'en', 'US', 'Caramelised Vietnamese Shredded Beef', 'Recipe video above. A very quick, very tasty way to use up leftover cooked beef used in things like broth (see notes to start from raw). Created to use up leftover brisket from making Vietnamese Pho. Cooked is tossed in a Vietnamese lemongrass marinade then pan fried until golden. It''s INSANELY delicious!', 'https://www.recipetineats.com/tachyon/2019/04/Vietnamese-Shredded-Beef_2.jpg', 14, 6, 20, 3, '[{"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_lemongrass", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["500g / 1lb (3 cups) leftover cooked brisket or other beef (, shredded or chopped (Note 1))","1 - 2 tbsp oil (, for cooking)"]},{"ingredients":["2 garlic cloves (, minced)","2 tbsp lime juice","2 tbsp fish sauce","1 tbsp soy sauce (, light or all purpose)","2.5 tbsp (packed) brown sugar","1 tbsp vegetable oil","1 tbsp lemongrass paste (Note 2)"],"purpose":"Marinade:"},{"ingredients":["Rice or noodles","Lime wedges OR Nuoc Cham (Note 3)","Fresh coriander/cilantro leaves (and/or finely sliced green onions)","Finely sliced red chilli, sliced cucumber, crushed peanuts*"],"purpose":"Serving:"}]', '[{"description":"Mix Marinade in a bowl.","images":[],"step":1},{"description":"Add shredded beef and mix. Set aside 5 minutes.","images":[],"step":2},{"description":"Heat oil in a large skillet over high heat. Add about half the beef and spread out in single layer.","images":[],"step":3},{"description":"Leave undisturbed until golden (about 1 minute). Flip then cook the other side just briefly (about 30 seconds) just to heat and get a touch of golden, then remove.","images":[],"step":4},{"description":"Repeat with remaining beef.","images":[],"step":5},{"description":"Serve over rice, using either limes or Nuoc Cham as the sauce, and garnishes of choice (I used them all in the photos!)","images":[],"step":6}]', '["fish","gluten","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Modern Vietnamese"],"categories":["beef","beef-recipes","dietary","gluten-free-recipes","mains","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f99b03cb0544', 'en', 'US', 'Beef Stroganoff', 'RECIPE VIDEO ABOVE. Juicy strips of beef smothered in a sour cream mushroom gravy - a quick dinner everyone will love! KEY STEPS: Sear beef super quickly for maximum juiciness and use a large skillet (for quick sear + fast sauce reduction). Stroganoff calls for good beef but if you only have a budget cut, use this easy Chinese method to tenderise the beef (it''s called "velveting"). It''s life changing - and perfect for Stroganoff.', 'https://www.recipetineats.com/tachyon/2018/01/Beef-Stroganoff_2-1-1.jpg', 15, 15, 30, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 40.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.6, "unit": "tub of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 250.0, "unit": "pack of 500g"}}, {"id": "ing_chives", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["600 g / 1.2 lb scotch fillet steak / boneless rib eye (Note 1)","2 tbsp vegetable oil (, divided)","1 large onion ((or 2 small onions), sliced)","300 g / 10 oz mushrooms (, sliced (not too thin))","40 g / 3 tbsp butter","2 tbsp flour (Note 2)","2 cups / 500 ml beef broth (, preferably salt reduced)","1 tbsp Dijon mustard","150 ml / 2/3 cup sour cream","Salt and pepper"]},{"ingredients":["250 - 300 g / 8 - 10 oz pasta or egg noodles of choice (Note 3)","Chopped chives (, for garnish (optional))"],"purpose":"Serving:"}]', '[{"description":"Use your fist (or rolling pin or mallet) to flatten the steaks to about 3/4cm / 1/3\" thick. Slice into 5mm / 1/5\" strips (cut long ones in half), discarding excess fat.","images":[],"step":1},{"description":"Sprinkle with a pinch of salt and pepper.","images":[],"step":2},{"description":"Heat 1 tbsp oil in a large skillet over high heat. Scatter half the beef in the skillet, QUICKLY spread it with tongs. Leave untouched for 30 seconds until browned. Turn beef quickly (as best you can!). Leave untouched for 30 seconds to brown. Immediately remove onto a plate. Don''t worry about pink bits and that it will be raw inside.","duration":0.5,"images":[],"step":3},{"description":"Add remaining 1 tbsp oil and repeat with remaining beef.","images":[],"step":4},{"description":"Turn heat down to medium high. Add butter, melt. Then add onions, cook for 1 minute, then add mushrooms.","duration":1,"images":[],"step":5},{"description":"Cook mushrooms until golden. Scrape bottom of fry pan to get all the golden bits off (this is flavour!).","images":[],"step":6},{"description":"Add flour, cook, stirring, for 1 minute.","duration":1,"images":[],"step":7},{"description":"Add half the broth while stirring. Once incorporated, add remaining broth.","images":[],"step":8},{"description":"Stir, then add sour cream and mustard. Stir until incorporated (don''t worry if it looks split, sour cream will \"melt\" as it heats).","images":[],"step":9},{"description":"Bring to simmer ,then reduce heat to medium low. Once it thickens to the consistency of pouring cream (3 - 5 minutes), adjust salt and pepper to taste.","images":[],"step":10},{"description":"Add beef back in (including plate juices). Simmer for 1 minute, then remove from stove immediately. (Note 4)","duration":1,"images":[],"step":11},{"description":"Serve over pasta or egg noodles, sprinkled with chives if desired.","images":[],"step":12}]', '["egg","fish","gluten","milk","mustard"]', '["high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Russian","Western"],"categories":["beef","beef-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","mains","nagis-picks","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1ea0f9b2f17b', 'en', 'US', 'Sloppy Joes', 'Recipe video above. Everybody loves Sloppy Joes - and they''re easy to make from scratch! I like making it with crushed tomato and less ketchup, and skipping the flavoured canned tomato sauces. Ideal freezer food, and to scale up to make for gatherings. SWEETNESS: Sloppy Joes are typically quite sweet, this is less sweet than most. But if you want it with just a bit of sweetness, skip the brown sugar and add it in gradually towards the end, adjusting to taste.', 'https://www.recipetineats.com/tachyon/2018/10/Sloppy-Joes_3.jpg', 10, 40, 50, 5, '[{"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_ketchup", "quantity": {"value": 0.15, "unit": "bottle of 500g"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 5.0, "unit": "loaf"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_other_fixing_options_see_note_4", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["1 tbsp /15g butter","2 garlic cloves (, minced)","1 onion (, finely chopped)","1 green capsicum/bell pepper (, diced)","500 g/1lb ground beef (mince) (Note 1)","1 tbsp Dijon mustard (OR 1 tsp dry mustard)","1.5 tbsp brown sugar","1/2 cup ketchup","400 g/14oz crushed tomato (, canned)","2 tsp Worcestershire sauce","1 tbsp tomato paste","1 beef bouillon cube (, crumbled (Note 2))","1/4 tsp black pepper"]},{"ingredients":["5 to 6 soft rolls (Note 3)","Cheese slices (optional)","Other fixing options - see Note 4"],"purpose":"To serve:"}]', '[{"description":"Melt butter in a large pot over high heat.","images":[],"step":1},{"description":"Ad garlic and onion, cook for 2 minutes until onion is almost translucent.","duration":2,"images":[],"step":2},{"description":"Add capsicum and cook for 2 minutes until softened.","duration":2,"images":[],"step":3},{"description":"Add beef and cook, breaking it up as you go, until it changes from red to brown.","images":[],"step":4},{"description":"Add remaining ingredients. Mix well, then turn heat down to medium low (or low for strong stoves).","images":[],"step":5},{"description":"Cover and cook for 30 minutes, stirring once or twice to make sure it doesn''t catch on the base. (If in rush, cook 15 minutes without lid)","duration":30,"images":[],"step":6},{"description":"Remove lid and give it a good stir for a minute. Mixture should be thick, not runny and saucy (see video). Adjust salt to taste.","images":[],"step":7},{"description":"Toast rolls. Butter if desired (I don''t).","images":[],"step":8},{"description":"Pile on lots of filling, immediately top with cheese (heat should semi melt, otherwise pop under broiler/grill). Top with lid and serve immediately!","images":[],"step":9}]', '["milk","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef","beef-mince-recipes","dinner-tonight","mains","quick-and-easy","sandwiches-and-sliders","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_eee5a4909093', 'en', 'US', 'OSSO BUCO', 'Recipe VIDEO above. Meltingly tender veal shanks slow cooked in a tomato sauce, a classic Italian dish! This is traditionally served with Risotto Milanese (saffron risotto) but is also terrific over mashed potato, polenta and even pasta. Gremolata is also served with Osso Buco and it provides a fantastic freshness to contrast with the richness of this dish.', 'https://www.recipetineats.com/tachyon/2017/08/Osso-Buco-2.jpg', 15, 90, 105, 5, '[{"id": "ing_thick_veal_osso_bucco", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_kitchen_string", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}]', '[{"ingredients":["5 thick veal osso bucco (300 g / 10 oz each, 2.5cm / 1” thick) (or beef, Note 1)","Salt and pepper","Kitchen string (optional)","2 tbsp olive oil","1 small onion (, finely chopped)","3 garlic cloves (, minced)","1 small carrot (, finely chopped)","1 celery stick (, finely chopped)","800 g / 28 oz can crushed tomato","1 cup / 250 ml dry white wine ((not sweet, not fruity), or chicken broth)","1 cup / 250 ml chicken broth","1 chicken bouillon cube (optional, or use beef)","2 tbsp tomato paste","3 sprigs thyme or 1 ½ tsp dried thyme","2 bay leaves"]},{"ingredients":["1 cup parsley leaves (flat or curly), lightly packed","2 – 3 tsp lemon zest (, finely grated)","1 garlic clove (, minced)"],"purpose":"Gremolata:"},{"ingredients":["Risotto Milanese ((saffron risotto, recipe in notes), mashed potato or pasta)"],"purpose":"For Serving:"}]', '[{"description":"Sprinkle both sides of the veal very generously with salt and pepper.","images":[],"step":1},{"description":"Heat the oil in a large heavy based pot over high heat. Add beef and sear on both sides so it has a nice brown crust. Remove onto a plate, turn heat down to medium low.","images":[],"step":2},{"description":"If the pot is looking dry, add a splash of oil. Add garlic and onion, cook for 1 minute, then add carrot and celery. Cook on low heat for 8 minutes or until it is softened and sweet.","duration":1,"images":[],"step":3},{"title":"OPTIONAL","description":"Meanwhile, tie kitchen string around each piece of veal – holds it together for nice presentation (it falls apart once slow cooked).","images":[],"step":4},{"description":"Add tomato, wine, broth, bouillon cube (crumbled), tomato paste, thyme, and bay leaves. Mix, then return veal into pot, place lid on.","images":[],"step":5},{"title":"Adjust heat so the liquid is simmering gently","description":"about medium low. Cook until tender enough to be pried apart with forks – check at 1.5 hours then every 15 minutes after that.","images":[],"step":6},{"description":"Use slotted spoon to remove veal into bowl, cover to keep warm. Simmer liquid on medium for 5 – 15 minutes or until thickened to taste. Adjust salt & pepper at the end.","duration":10,"images":[],"step":7},{"description":"Traditionally served with Saffron Risotto (Risotto Milanese, recipe in notes), but is also terrific with mashed potato, creamy polenta or even pasta. Place a piece of Osso Buco on the serving plate, spoon over sauce, then top with Gremolata.","images":[],"step":8},{"description":"Place the parsley leaves on a cutting board. Top with garlic and lemon zest. Finely chop the parsley. Transfer to serving bowl and set aside for at least 20 minutes before use.","images":[],"step":9}]', '["gluten"]', '[]', '{"mealType":["dinner"],"cuisine":["American-Italian"],"categories":["beef","beef-recipes","dietary","gluten-free-recipes","italian-recipes","mains","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_42199f3a765f', 'en', 'US', 'One Pot Lasagna', 'Recipe video above. This is how to make an easy lasagna from scratch in one pan, complete with layers!! It''s such a great way to get a lasagna fix mid week when you don''t have the time to make a proper lasagna. Everyone will be so amazed when you tell them you made it in one pot! (Well, one pan...)This is a quick version so the meat sauce (essentially Spaghetti Bolognese) is cooked quickly, and you''ll love how we use one bottle of tomato passata for both the meat sauce and tomato topping. Make sure to use dried lasagna sheets, not fresh, which will be too soft here.Note: The carrot and celery are optional, as is the ricotta layer (but boy is it good when you use it!)', 'https://www.recipetineats.com/tachyon/2026/05/One-pot-lasagna-with-layers-5-1.jpg', 20, 50, 80, 5, '[{"id": "ing_tomato", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_italian_herb_mix", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_ricotta", "quantity": {"value": 0.6, "unit": "tub of 250g"}}, {"id": "ing_milk", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_sheets_lasagna", "quantity": {"value": 8.0, "unit": "pack"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.5, "unit": "pack of 125g"}}, {"id": "ing_parsley", "quantity": {"value": 0.1, "unit": "bunch"}}]', '[{"ingredients":["24 oz / 700g (1 bottle) tomato passata ((pureed tomato - Note 1), used for both the meat sauce and sauce topping)"]},{"ingredients":["2 tbsp olive oil","3 garlic cloves (, finely minced)","1 small onion (, diced)","1 small carrot (optional) (, peeled and shredded using a box grater)","1 celery stick (optional) (, shredded using a box grater (discard stringy bits remaining))","1 lb / 500g beef mince (ground beef)","2 tbsp tomato paste","2 beef bouillon stock cubes (, crumbled)","2 tsp Worcestershire sauce","1/2 tsp white sugar (Note 2)","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper","1/2 cup water"],"purpose":"Meat sauce:"},{"ingredients":["1 tsp dried Italian herb mix (, or equal parts dried basil, oregano and parsley)","1/2 tsp garlic powder (or 1 crushed garlic clove)","1/4 tsp white sugar (Note 2)","1/2 tsp cooking salt / kosher salt","1/4 cup water"],"purpose":"Topping Sauce flavourings"},{"ingredients":["1 cup good ricotta (I like Paesanella) or smooth ricotta (Note 3)","1 tbsp milk (, as needed (probably won''t need for smooth ricotta))","1/4 tsp cooking salt / kosher salt"],"purpose":"Creamy ricotta dollops (faux bechamel!) – optional"},{"ingredients":["8 sheets (250g / 8oz) dried lasagna (US: no-boil \"oven-ready\" lasagna) (, not fresh (Note 4))","1 1/2 tightly packed cups mozzarella cheese (, shredded)","2 tsp parsley (, finely chopped (optional))"],"purpose":"Lasagna"}]', '[{"title":"Meat sauce","description":"Sauté onion, garlic, celery and carrot, cook beef. Add 2/3 bottle of passata + remaining Meat Sauce ingredients, simmer 10 min. Topping Sauce - add everything into remaining passata in bottle, shake. Creamy ricotta - vigorously whisk until it''s like whipped cream. Layer - Remove half meat sauce from pan. Slide lasagna sheets under Meat Sauce (break as needed), then do 2 more layers using reserved meat sauce. Dollop with ricotta, cover with cheese, bake 30 min at 180C/350F (160C). Stand 10 min before cutting.","images":[],"step":1},{"title":"Sauté","description":"Heat olive oil in a deep skillet/pan over medium high heat. (Mine is 26cm/10.5\" wide, 5cm/2\" deep) (Note 5) Add garlic, onion, carrot and celery. Sauté until onion is translucent - about 3 minutes.","images":[],"step":2},{"title":"Cook beef","description":"Turn up heat to high. Add beef and cook, breaking it up with the spatula, until you no longer see red.","images":[],"step":3},{"title":"Sauce","description":"Add about 2/3 of the passata (keep rest for Sauce), and remaining Meat Sauce ingredients. Bring to rapid simmer, then turn down to medium/medium low. Simmer gently for 10 minutes.","duration":10,"images":[],"step":4},{"description":"Preheat oven to 180°C/350°F (160°C fan-forced).","images":[],"step":5},{"title":"Make sauce","description":"Add Sauce Flavourings into the tomato passata bottle and shake to combine.","images":[],"step":6},{"title":"Creamy ricotta (optional)","description":"Put the ingredients in a bowl. Start softening the ricotta using smearing motions with the back of a spoon, then switch to a whisk and give it a vigorous whisk for 20 - 30 seconds until it resembles whipped cream. (If using smooth ricotta, you''ll barely need to do this).","duration":0.4166666666666667,"images":[],"step":7},{"description":"Assemble lasagna (in-post step photos and video are helpful)","images":[],"step":8},{"title":"Remove half filling","description":"Remove the pan from the stove. Remove half the Meat Sauce into a bowl.","images":[],"step":9},{"title":"Base layer","description":"Slide one lasagna sheet, starting from the side, under the Meat Sauce - this will be the base of the lasagna. Break up pieces of lasagne and slide them in under the Meat Sauce around the sides of the pan (to form the remainder of the bottom layer). There is no need to be accurate with coverage here, you can overlap and have gaps. We are making a rustic quick lasagna, remember! Spread the Meat Sauce to cover all the lasagna sheets.","images":[],"step":10},{"title":"Layer 2","description":"Top with another layer of dried lasagna sheets. Then spread over the Meat Sauce in the bowl.","images":[],"step":11},{"title":"Layer 3","description":"Cover with a 3rd layer of lasagna sheets.","images":[],"step":12},{"title":"Toppings","description":"Pour over the Sauce and spread over the top. Do 12 - 15 dollops of ricotta across the surface (if using). Sprinkle with cheese.","images":[],"step":13},{"title":"Bake and rest","description":"Bake for 30 minutes uncovered, then set aside for 10 minutes to stabilise a bit.","duration":30,"images":[],"step":14},{"title":"Serve","description":"Sprinkle with parsley (if using), then cut and serve! Enjoy with a simple Balsamic Rocket Salad and Garlic Bread on the side.","images":[],"step":15}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian-esque","Western"],"categories":["beef-mince-recipes","beef-recipes","casseroles-and-cosy-bakes","italian-recipes","most-popular","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_80025a6e18b0', 'en', 'US', 'Pastel de Choclo (Chilean Beef and Corn Casserole)', 'Recipe video above. Meet my new favourite way to turn beef mince and a big bag of frozen corn into dinner! This is Pastel de Choclo, a classic Chilean casserole with a spiced onion beef filling and a thick corn topping that bakes up lightly caramelised, with surprise pockets of olives, raisins and boiled egg tucked inside. It''s like South America''s answer to Cottage Pie! Hearty, comforting, something a little difference, I love the combination of the sweet corn pudding with the savoury beef filling. PS Frozen corn is super convenient but gosh, imagine making it with fresh summer corn?Recipe credits: Inspired by a visit to La Paula, a wonderful Chilean establishment in Fairfield, Sydney, and developed with reference to a number of recipes, listed in the blue box above the video.', 'https://www.recipetineats.com/tachyon/2026/05/Pastel-de-choclo-0.jpg', 20, 75, 110, 8, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_beef_mince", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 3000.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 2000.0, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_cumin", "quantity": {"value": 0.562, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_corn", "quantity": {"value": 3.125, "unit": "can of 400g"}}, {"id": "ing_milk", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_basil", "quantity": {"value": 12.0, "unit": "bunch"}}, {"id": "ing_corn", "quantity": {"value": 3.125, "unit": "can of 400g"}}, {"id": "ing_pitted_black_olives_else_kalamata_is_fine", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_raisins", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}]', '[{"ingredients":["2 tbsp olive oil","1 kg / 2 lb beef mince (ground beef)","3 large onions (, diced (4 - 5 medium ones))","6 large garlic cloves (, finely minced)","1/4 cup plain flour (all-purpose flour)","1 1/2 cups beef stock/broth (, low sodium)"],"purpose":"Beef filling:"},{"ingredients":["1 1/2 tbsp cumin powder","1 tbsp paprika (regular/sweet, not spicy or smoked)","1 1/2 tsp cooking salt / kosher salt","1/2 tsp black pepper"],"purpose":"Beef spice mix:"},{"ingredients":["50g/ 3 tbsp unsalted butter (or olive oil)","1.25 kg/ 2.5 lb frozen corn (, still frozen is fine, or kernels cut off corn cobs (8 cups) (Note 1 on canned corn))","1 1/2 tsp cooking salt / kosher salt","1/2 cup milk (any fat %, non-dairy is ok too)","12 - 15 large basil leaves (, optional (Note 2))","2 tbsp fine cornmeal (or semolina (Note 3))"],"purpose":"Corn layer:"},{"ingredients":["1/4 cup pitted black olives (roughly chopped, Chilean or South American (if you can) else Kalamata is fine)","2 soft boiled eggs (, quartered (8 minutes lowered into boiling water))","2 tbsp raisins (or sultanas)","1 tbsp regular sugar (granulated sugar) (, not caster sugar / superfine sugar (Note 4))","Pinch paprika"],"purpose":"Assembling / baking:"}]', '[{"description":"Preheat oven to 200°C/390°C (180°C fan-forced).","images":[],"step":1},{"title":"Cook beef","description":"Heat the oil in a large 30cm/12\" pan over high heat. Add the beef and cook, breaking it up as you go, until you no longer see red. Cook for another couple of minutes, breaking up the beef into fine pieces. Remove beef from the pan using a slotted spoon, leaving the fat and juices behind.","images":[],"step":2},{"title":"Cook onion","description":"To the same pan, add the onion and garlic. Cook for 5 minutes, stirring regularly, until the onion is translucent.","duration":5,"images":[],"step":3},{"title":"Simmer and reduce","description":"Add the beef and mix through. Stir in the spices. Add the flour and mix until you no longer see flour. Add the stock and stir - it will thicken into a gravy quite quickly, coating the beef. Lower heat to medium and cook for 5 minutes, stirring regularly so the base doesn''t catch, until the mixture is thick enough so you can draw a path across the base of the pan and it stays.","duration":5,"images":[],"step":4},{"description":"Remove from stove and spread in a 23 x 33 cm (9 x 13\") pan, then set aside and let it cool while you make the corn.","images":[],"step":5},{"title":"Sauté","description":"Melt the butter in a pot over medium high heat. Add corn (still frozen is fine) and cook for 5 minutes, stirring regularly.","duration":5,"images":[],"step":6},{"title":"Blitz","description":"Add milk, salt and basil. Stir, then use a stick blender to blitz ~ 30 seconds (moving it around) or until you no longer see whole corn kernels. It won''t be complete smooth which is what you want.","images":[],"step":7},{"title":"Thicken","description":"Stir in cornmeal. Lower heat to medium or medium low so it''s not spitting. Cook for 5 minutes, stirring regularly so the base doesn''t catch. It should be thick enough to mound in a heap on the spoon, and when you draw a path across the base it should stay in place.","duration":5,"images":[],"step":8},{"description":"Assemble and bake:","images":[],"step":9},{"title":"Assemble","description":"Press the eggs into the beef, scatter with olives and raisins.","images":[],"step":10},{"title":"Corn topping","description":"Dollop the corn mixture across the surface then spread and smooth the surface. Sprinkle all over with the sugar, then paprika (sprinkle from a height for light coverage).","images":[],"step":11},{"title":"Bake for 40","description":"45 minutes until the surface is golden. Cool 15 minutes to let it set a bit so you can cut neat(ish) slices, then cut like lasagna and serve!","duration":42.5,"images":[],"step":12}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Chilean","South American"],"categories":["beef-mince-recipes","casseroles-and-cosy-bakes","south-american-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_da0ac6dc0fd6', 'en', 'US', 'Moroccan Spiral Meatball Zucchini Bake', 'Recipe video above. I love recipes like this - everyday ingredients used in a different way to make something new and interesting! Moroccan-spiced lamb meatballs are baked in a striking spiral arrangement with zucchini and capsicum in a bubbly garlicky tomato sauce. You will be impressed at how soft the meatballs are, and how the deceptively simple tomato sauce gets so much flavour as it bakes!Serve straight from the pan with flatbreads, couscous or basmati rice.Inspired by Özlem Warren''s Baked Aubergine Kebab with Meatballs from Özlem''s Turkish Table.', 'https://www.recipetineats.com/tachyon/2025/08/Moroccan-Meatball-Zucchini-Spiral-Bake_7.jpg', 25, 35, 60, 4, '[{"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_lamb_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["1/2 cup panko breadcrumbs (use GF if needed, can substitute regular breadcrumbs)","1/2 onion (, grated with a standard box grater)","500g / 1 lb lamb mince (ground lamb), or beef (Note 1)","1 egg","2 garlic cloves (, finely minced using a garlic crusher or knife)","1/4 cup pretty finely chopped parsley (, plus extra for garnish)"],"purpose":"Meatballs:"},{"ingredients":["1 tsp cumin powder","1 tsp coriander power","1 tsp paprika (sweet / regular, or smoky - not spicy)","1/4 tsp cinnamon powder (don''t skip this! Magical :) )","1/4 tsp cayenne pepper ((or black pepper), tiny amount so doesn''t make it spicy)","3/4 tsp cooking salt / kosher salt"],"purpose":"Moroccan spice mix:"},{"ingredients":["2 fat zucchinis / courgettes (5cm/2\" wide, 22cm/9\" long is ideal), cut into ~20 x 1.2 cm / 0.5\" thick rounds (Note 2)","1 large or 1 1/2 regular red capsicum (bell pepper), cut into ~20 x large-ish chunks 5 x 2.5cm / 1 x 2\" (Note 3)","1/2 tbsp extra virgin olive oil (, plus extra for drizzling to bake)","1/4 tsp each salt and pepper"],"purpose":"Vegetables:"},{"ingredients":["2 garlic cloves (, crushed using garlic press)","2 1/2 tbsp tomato paste","2 tbsp extra virgin olive oil","1/2 cup warm tap water","1/8 tsp each salt and pepper"],"purpose":"Garlic tomato sauce:"},{"ingredients":["Plain yogurt (, thinned with a little water to make it drizzle-able)","Flatbreads (, rice(basmati recommended), couscous, mash)"],"purpose":"Serving"}]', '[{"description":"Toss Vegetables, mix Sauce. Make meatball mixture, roll and squish 16 meatballs, wedge between zucchini rounds, tuck capsicum in. Pour over sauce, bake 35 minutes at 200°C/375°F (180°C fan).","images":[],"step":1},{"description":"Preheat oven to 200°C/375°F (180°C fan-forced).","images":[],"step":2},{"description":"Toss capsicum and zucchini with the oil, salt and pepper in a bowl, and set aside.","images":[],"step":3},{"title":"Sauce","description":"Mix the sauce ingredients in a small jug or bowl.","images":[],"step":4},{"title":"Meatball mixture","description":"Put the breadcrumbs in a bowl and grate the onion over. Toss with fingertips to wet the breadcrumbs with the onion juices. Then add remaining meatball ingredients and the Moroccan spice mix. Mix well with your hands.","images":[],"step":5},{"title":"Roll & squish","description":"Roll the mixture into 16 balls then squish slightly to 1.5cm / 0.6\" thickness (~2.5 tbsp/45g each), about the size of (or slightly larger than) the zucchini rounds.","images":[],"step":6},{"description":"Stand upright with a zucchini round wedged and arrange in a 26cm/10.5\" round cast-iron pan (or baking dish of similar size). I do them in a ring then use the rest to fill in the middle. Arrange loosely because next we wedge the capsicum in between wherever you can. Fill the whole pan so everything holds each other up, and use as much capsicum & zucchini as you can (you might have leftover). There are NO RULES with arrangement here, make this your own delicious artwork! :)","images":[],"step":7},{"description":"Pour sauce over everything, aiming to pour some over everything as best you can. Drizzle all over with about 1 tbsp olive oil.","images":[],"step":8},{"description":"Bake for 35 minutes until the surface of the meatballs are nicely browned.","duration":35,"images":[],"step":9},{"description":"Serve with flatbreads or garlic rice, being sure to spoon plenty of the delicious sauce over everything!","images":[],"step":10}]', '["egg","gluten","milk"]', '["high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern"],"categories":["beef-mince-recipes","cuisines","dietary","gluten-free-recipes","lamb","mains","meatball-recipes","middle-eastern-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7d36cbdc7d5e', 'en', 'US', 'Smothered rissoles', 'Recipe video above. Rissoles are great. Smothered rissoles are AWESOME!!! Especially when it’s mushroom gravy doing the smothering. :)They''re the softest rissoles you''ve ever had because we cook them in the gravy as it thickens. They come out so much softer than regular rissoles!Serve over buttery mash for cosy comfort food you''ll crave week after week.', 'https://www.recipetineats.com/tachyon/2025/07/Smothered-rissoles-overhead.jpg', 20, 15, 35, 4, '[{"id": "ing_onion", "quantity": {"value": 500.0, "unit": "pack of 1kg"}}, {"id": "ing_bread", "quantity": {"value": 0.094, "unit": "loaf"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_zucchini", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 500.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_mushroom", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.052, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["1/2 large onion (, grated using standard box grater (Note 1))","1/2 cup panko breadcrumbs (sub regular breadcrumbs, Note 2)","500g/ 1lb beef mince (ground beef)","1 small zucchini (, grated)","1 small carrot (, peeled and grated)","1 large egg","1 large garlic clove (, crushed using garlic press or finely grated)","1/2 tsp dried thyme (optional)","1/2 tsp oregano (optional)","1/4 tsp black pepper","3/4 tsp cooking salt / kosher salt (halve for table salt)","2 tsp Worcestershire sauce"],"purpose":"RISSOLES:"},{"ingredients":["2 tbsp olive oil (, for cooking)"],"purpose":"COOKING:"},{"ingredients":["30g/ 2 tbsp unsalted butter","1/2 onion (, sliced 5mm/0.2\" thick)","2 garlic cloves (, finely chopped)","200g/ 7 oz mushrooms (, sliced 5mm/0.2\" thick)","3 1/2 tbsp flour (plain / all-purpose)","2 cups beef stock / broth (, low sodium)","1/4 tsp cooking salt / kosher salt (halve for table salt)","1/4 tsp black pepper","1 tsp Worcestershire sauce"],"purpose":"MUSHROOM GRAVY"},{"ingredients":["Mashed potato (or other starchy vehicle of choice)"],"purpose":"TO SERVE"}]', '[{"description":"Mix rissole ingredients, form 12 patties, slightly indent one side. Cook in 2 batches until lightly browned but raw inside. Wipe pan clean, melt butter, cook onion, then mushrooms, add garlic towards end. Make roux then gravy. Cook rissoles in gravy as it thickens, 4 - 5 minutes, serve!","images":[],"step":1},{"description":"Grate the onion into a large bowl, add panko, toss to soak in the onion juices. Add remaining rissole ingredients and mix well with your hands.","images":[],"step":2},{"title":"Dented patties","description":"Form 12 patties (1/4 cup each) and make a slight indentation on one side (this prevents doming while cooking).","images":[],"step":3},{"title":"Lightly brown","description":"Heat 1 tablespoon of the oil in a large non-stick pan (30cm/12\") over medium high heat. Cook half the rissoles for 1 1/2 minutes on each side until lightly browned but still raw inside. Remove onto a plate. Add the remaining oil and repeat with remaining rissoles.","images":[],"step":4},{"description":"Mushroom gravy:","images":[],"step":5},{"title":"Clean pan","description":"Discard excess oil and give the pan a rough clean with paper towels, just to remove most of the black bits.","images":[],"step":6},{"title":"Cook mushrooms","description":"Melt the butter in the same pan, cook the onion for 1 minute, then add the mushrooms and cook for 3 - 4 minutes until they release water, soften, then become lightly browned. Add the garlic for the last 30 seconds.","duration":1,"images":[],"step":7},{"title":"Cook off flour","description":"Turn the heat down to medium, scatter flour across the surface and stir for 1 minute - it will be like a dry paste.","duration":1,"images":[],"step":8},{"title":"Half beef stock","description":"While stirring, pour in half the stock then keep mixing until the flour paste dissolves and thickens the liquid, and is lump free (about 30 seconds).","images":[],"step":9},{"title":"Simmer rissoles and thicken gravy","description":"Add remaining stock, Worcestershire sauce, salt and pepper. Stir, turn heat up slightly to medium high. When it starts simmering, gently place the rissoles in (including any juices pooled on the plate). Cook rissoles 4 - 5 minutes until the liquid thickens into a thin gravy (aim for thinner than you want, thickens as you serve).","images":[],"step":10},{"description":"Serve rissoles over mash with plenty of sauce! Add a sprinkle of parsley if you''re feeling fancy.","images":[],"step":11}]', '["egg","gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Aussie","Australian"],"categories":["beef-mince-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4e8dbcdfe4f9', 'en', 'US', 'Crispy oven baked beef quesadillas', 'Recipe video above. This is a super handy method to make 3, 4 or 8 quesadillas in the oven at the same time rather than cooking them one by one on the stove. They are impressively crispy (see photos and video for proof!) and very quick to make.Stuffed with my beef taco filling though you can switch with chicken, turkey, pork or lamb, or stuff with whatever your heart desires as long as it''s not too watery because this might affect how well the tortilla crisps in the oven.', 'https://www.recipetineats.com/tachyon/2024/07/Baked-Beef-Quasadillas-51259.jpg', 5, 20, 25, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 0.125, "unit": "can of 400g"}}, {"id": "ing_black_beans", "quantity": {"value": 0.125, "unit": "can of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_tortillas", "quantity": {"value": 4.0, "unit": "pack of 8"}}, {"id": "ing_cheese", "quantity": {"value": 1.25, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.016, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_pico_de_gallo", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_nothing", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["2 tsp olive oil","250g/ 8oz beef mince ((ground beef) - or chicken, turkey, pork, lamb)","1 tbsp tomato paste","1/3 cup corn kernels (canned, drain, or frozen)","1/3 cup black beans (caned, drained)","2 tbsp water"]},{"ingredients":["4 flour tortillas (20cm/8\"), Mission crisps best, Old El Paso the least (Note 1)","3 tsp olive oil","1 1/4 tightly packed cups shredded cheese ( - cheddar, colby, tasty cheese, Monterey jack (not mozzarella))"],"purpose":"Quesadillas:"},{"ingredients":["1/2 tsp EACH ground garlic (, onion, dried oregano)","1 tsp EACH cumin (, paprika powder)","1/8 tsp cayenne pepper (, optional)","1/4 tsp cooking salt / kosher salt"],"purpose":"Homemade taco seasoning:"},{"ingredients":["Avocado sauce ( or Guacamole)","Pico de Gallo","Sour cream","Nothing (I happily eat it plain!)"],"purpose":"Serving:"}]', '[{"title":"Filling","description":"Heat the oil in a non stick pan over high heat. Add the beef and cook, breaking it up as you go, until the red colour is mostly gone. Add the Taco Seasoning and cook for 1 minute. Add the tomato paste and cook for 30 seconds. Stir in the beans and corn, then add the water and stir. The filling should be juicy (not dry) but not watery (compromises crispiness!). Remove into a bowl and cool for at least 15 minutes.","duration":1,"images":[],"step":1},{"description":"Preheat the oven to 220°C / 425°F (200°C fan-forced). Grease a metal tray with 1 teaspoon of olive oil (I use my hand).","images":[],"step":2},{"title":"Assemble quesadillas","description":"Spread the filling on one side of the quesadilla. Top with cheese, fold to cover. Place on tray, repeat with remaining quesadillas.","images":[],"step":3},{"description":"Drizzle the top of each with 1/2 tsp olive oil then spread using your hands (top and sides, not underside). Press the quesadilla down to flatten the surface.","images":[],"step":4},{"description":"Bake for 8 minutes. Flip the quesadillas, bake for 5 minutes, flip again then bake for a further 2 minutes or until crispy. (Sometimes I spritz with oil to give it a helping hand)","duration":8,"images":[],"step":5},{"title":"Serve","description":"Cut each into half and serve immediately with dipping sauce/toppings of choice.","images":[],"step":6}]', '["gluten","milk"]', '["high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["beef-mince-recipes","mexican-recipes","quesadillas","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a5b8c424a45a', 'en', 'US', 'Qeema Indian Curried Beef', 'An authentic Indian spiced ground (minced) beef recipe known as Qeema (or keema or kheema). This is a gem of a recipe because it tastes incredible but unlike many Indian dishes, there are no hard-to-find spices in the ingredients. And it''s super fast - on the table in 20 minutes! Serve over basmati rice. Great with plain yogurt, even better with Mint Yogurt.', 'https://www.recipetineats.com/tachyon/2016/04/Queema-Indian-Curried-Beef-Mince_3.jpg', 5, 15, 20, 4, '[{"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_ginger", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1666.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_aram_masala", "quantity": {"value": 1.25, "unit": "unit"}}, {"id": "ing_cumin", "quantity": {"value": 0.156, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.125, "unit": "bunch"}}, {"id": "ing_turmeric", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.125, "unit": "bunch"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.006, "unit": "tub of 500g"}}, {"id": "ing_mint", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["3 tbsp vegetable or canola oil (, or other neutral oil)","4 tsp ginger (, finely mince)","5 large garlic cloves (, minced (about 4 tsp))","1 large onion (, finely diced)","500g / 1 lb beef mince (ground beef)","3/4 tsp cooking salt / kosher salt","1 tsp cayenne pepper (or chilli powder (pure, not US chili powder spice mix), omit for not spicy)","1 1/4 tsp garam masala (Note 1)","1 1/4 tsp cumin powder","1 1/4 tsp coriander powder","1/2 tsp turmeric powder","1 cup water"]},{"ingredients":["1 green cayenne pepper (, deseeded, finely sliced)","Cilantro/coriander leaves","Plain yogurt or Mint yogurt (below)"],"purpose":"Garnish"},{"ingredients":["3/4 cup plain yogurt","1/2 cup (lightly packed) mint leaves","1/4 tsp cooking salt / kosher salt"],"purpose":"Mint yogurt (optional, pictured in post)"}]', '[{"title":"Sauté","description":"Heat oil in a skillet over high heat. Add ginger and garlic and saute for 30 seconds until golden, don''t let it burn! Add onion and cook for 1 minute until it is starting to turn translucent.","duration":0.5,"images":[],"step":1},{"description":"Add beef and cook, breaking it up as you go, until it changes from pink to light brown. Add remaining ingredients EXCEPT water. Cook for a further 2 minutes to let the spices bloom.","images":[],"step":2},{"title":"Cook 10 minutes","description":"Add water, give it a stir, then put a lid on (or cover with a baking tray). Turn heat down to medium and let it simmer for 10 minutes or until most of the water has evaporated.","duration":10,"images":[],"step":3},{"description":"Serve over with basmati rice or plain white rice, garnished with extra chilli and coriander/cilantro, and lots of Mint Yogurt. Naan or flatbreads would make it even better, though if time is not your friend, try frozen roti (pictured in post, Note 3).","images":[],"step":4},{"title":"Blitz then stir","description":"Put just 1/4 cup of the yogurt with the mint leaves and salt in a jug just big enough to fit the head of a stick blender. Blitz until mint is very finely chopped. Then stir in remaining yogurt. (Note 4) Refrigerate until required.","images":[],"step":5}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["beef-mince-recipes","beef-recipes","curry-recipes","dietary","dinner-tonight","gluten-free-recipes","indian-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_595f731dc716', 'en', 'US', 'Easy Moroccan Stuffed Eggplant (beef or lamb)', 'Recipe video above. A delicious, unique, EASY way to serve up eggplant and minced / ground beef or lamb! Think of this as a midweek take on traditional Arabic stuffed eggplant that''s usually hollowed out.Don''t worry if you don''t have every single spice. There''s so many in this spice mix, it will still be tasty even if you''re missing one...or two, even three!Serves 2 as a main with a small side salad, or 4 as a meal with a starch (flatbread, couscous) and a substantial side (like this Pumpkin Salad, roast veg, chickpea salad), or 4 as a generous starter.', 'https://www.recipetineats.com/tachyon/2016/03/Moroccan-baked-eggplant-halves-with-beef-or-lamb_0.jpg', 15, 45, 90, 2, '[{"id": "ing_egg", "quantity": {"value": 0.167, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cinnamon", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_lamb_mince", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_pinenuts", "quantity": {"value": 30.0, "unit": "jar"}}]', '[{"ingredients":["2 x 250g/8oz eggplants (aubergines), ~17cm/7\" long (Note 1)","3/4 tsp cooking salt / kosher salt","1 tbsp extra virgin olive oil","1 tbsp lemon juice (or more oil)"],"purpose":"Eggplant"},{"ingredients":["1 1/2 tsp EACH coriander, paprika","1 tsp cumin","3/4 tsp all spice powder","1/2 tsp EACH garlic powder, ginger, turmeric powder","1/4 tsp cinnamon","1/4 tsp cayenne pepper"],"purpose":"Chermoula spice mix (Note 2)"},{"ingredients":["1 tbsp olive oil","1 garlic clove (, finely minced)","1/2 onion (, finely chopped)","250g / 8oz beef or lamb mince (, lean if you can (chicken, turkey, pork also ok))","1/2 tsp cooking/kosher salt","2 tsp tomato paste (Note 3)","1/4 cup water"],"purpose":"Spiced beef or Lamb topping"},{"ingredients":["Yoghurt (, plain)","2 tbsp coriander/cilantro leaves (, roughly chopped (sub parsley))","2 tbsp pinenuts (, toasted (Note 4))"],"purpose":"To Serve"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan).","images":[],"step":1},{"title":"Sweat eggplants (recommended, see Note 5 to skip)","description":"Cut eggplants in half then score with 2.5cm / 1\" diamonds. Rub surface with salt, getting some into the slits. Place face down in a colander and set aside for 30 minutes. Gently squeeze like a sponge to remove excess water, pat surface dry.","duration":30,"images":[],"step":2},{"description":"Mix Chermoula spice mix ingredients in a bowl. Remove 3 teaspoons for the meat and set aside. Add olive oil and lemon juice into the remaining spice mix and mix into a paste.","images":[],"step":3},{"title":"Roast eggplant","description":"Place eggplant on baking tray. Slather spice mix onto the surface. Roast for 45 minutes until softened.","duration":45,"images":[],"step":4},{"title":"Spiced topping","description":"Heat oil in a non stick skillet over medium high heat. Cook onion and garlic for 1 minute. Turn heat up to high, add lamb/beef and cook, breaking it up as you go, until you no longer see red. Add reserved spices and salt, then cook for a further 1 minute. Add tomato paste and cook for 1 minute. Stir in water, cook for 1 minute until it''s juicy but not watery.","duration":1,"images":[],"step":5},{"title":"Assemble","description":"Top eggplant with beef/lamb. Sprinkle over coriander, dollop with yogurt and pine nuts. Finish with an extra drizzle of extra virgin olive oil, if desired!","images":[],"step":6}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern"],"categories":["beef-mince-recipes","beef-recipes","cuisines","dietary","dinner-tonight","gluten-free-recipes","lamb-recipes","low-calorie-recipes","main-dishes","middle-eastern-recipes","moroccan","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_12984a900bda', 'en', 'US', 'Beef fried rice', 'Recipe video above. GREAT quick dinner to make with beef mince, complete with veg, protein and starch! The trick is using a strong savoury sauce and caramelise the beef well for extra delicious flavour.Frozen cooked rice is a staple in my house. Don''t have day-old-cooked rice? Don''t try this recipe - you''ll be disappointed with gummy rice! Make Baked Fried Rice instead (starts with uncooked rice, and it''s awesome!). Use the beef to make Asian Beef and serve together.', 'https://www.recipetineats.com/tachyon/2023/02/Beef-fried-rice_4.jpg', 10, 10, 20, 4, '[{"id": "ing_dark_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_oil", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 75.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 300.0, "unit": "pack of 1kg"}}, {"id": "ing_rice", "quantity": {"value": 450.0, "unit": "pack"}}, {"id": "ing_green_onion", "quantity": {"value": 1.5, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp dark soy sauce (Note 1)","2 tsp light soy sauce (Note 1)","2 tbsp oyster sauce (Note 2)","1 tbsp Chinese cooking wine (Note 3)","1/2 tsp white sugar","1/8 tsp white pepper (sub black)"],"purpose":"Sauce:"},{"ingredients":["1 tsp sesame oil","2 eggs (, lightly whisked)"],"purpose":"Scrambled eggs:"},{"ingredients":["2 tbsp oil (peanut, veg, canola or other neutral oil)","1/2 onion (, finely diced)","2 garlic cloves (, finely minced)","250g / 8 oz beef mince / ground beef (I use lean, Note 4)","2 cups frozen diced carrots, peas, corn ( (still frozen fine!) (or fresh diced veg))","3 cups day-old cooked rice (1c uncooked rice = 3c cooked, Note 5)","1/2 cup finely sliced green onions (1-2 stems)"],"purpose":"Fried rice:"}]', '[{"description":"Mix Sauce ingredients in a small bowl, then set aside.","images":[],"step":1},{"title":"Scramble eggs","description":"Heat sesame oil in a large wok or non-stick pan over medium high heat. Add egg and cook, stirring gently, so it is softly scrambled. Remove onto a plate.","images":[],"step":2},{"title":"Cook beef","description":"Heat vegetable oil in the same pan over high heat. Add onion and garlic, cook for 30 seconds. Add beef and cook, breaking it up as you go, for 2 minutes or until you no longer see raw beef. Add 2 tablespoons of sauce and cook for 1 minute.","duration":0.5,"images":[],"step":3},{"title":"Veg / caramelise beef","description":"Add frozen vegetables and cook for 2 minutes or until the beef gets nicely caramelised - this is the trick to great flavour so do not shortcut this!","duration":2,"images":[],"step":4},{"title":"Rice & sauce","description":"Add rice and remaining sauce. Toss for 2 minutes until the sauce is well dispersed throughout the rice and the rice grains start to caramelise a bit.","duration":2,"images":[],"step":5},{"title":"Egg & green onion","description":"Then add scrambled eggs and green onion, give it a quick toss to disperse then divide between bowls. EAT!","images":[],"step":6}]', '["egg","gluten","peanuts","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["beef-mince-recipes","fried-rice","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4f77c864ba2c', 'en', 'US', 'Cheeseburgers (double or single)', 'Recipe video above. This cheeseburger recipe assumes your bun is 10cm/4" wide. If it''s larger, you may want to scale up the beef so you don''t end up with wafer-thin patties or a burger patty that''s much smaller than your bun. Nobody likes biting into bread with no beef!!Slather with sauce of choice though for a really great burger experience, try my Special Burger Sauce (quick, no cook) or my Tomato Chutney for Burgers.', 'https://www.recipetineats.com/tachyon/2022/08/Stack-of-cheeseburgers.jpg', 10, 10, 20, 4, '[{"id": "ing_beef_mince", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 2.0, "unit": "bottle"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_cheese", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_lettuce", "quantity": {"value": 8.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_gherkins", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_special_burger_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_ketchup", "quantity": {"value": 1.0, "unit": "bottle of 500g"}}, {"id": "ing_mustard", "quantity": {"value": 0.005, "unit": "jar of 200g"}}, {"id": "ing_french_fries", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["600 g / 1.2 lb beef mince (ground beef) (, at least 20% fat (Note 1 for quality))"],"purpose":"Single Cheeseburgers:"},{"ingredients":["1.2 kg / 2.4 lb beef mince (ground beef) (, at least 20% fat (Note 1 for quality))"],"purpose":"Mighty Double Cheeseburgers:"},{"ingredients":["1/8 tsp each salt and pepper PER burger","2 - 3 tbsp canola oil"],"purpose":"Cooking:"},{"ingredients":["4 soft burger buns or rolls (, around 10cm/4\" wide (Note 2))","4 - 8 slices burger cheese (American) or other cheese or choice (Note 3)","8 cos/romaine lettuce leaves (, torn to size (or shredded iceberg))","2 large tomatoes (, cut into eight 7mm/ 1/4\" slices)","1 red onion (, finely sliced into rings (Note 4))","2 large gherkins (, finely sliced (Note 5))"],"purpose":"Everything else you need:"},{"ingredients":["Special Burger Sauce (creamy orangey/pink one, quick no cook)","Tomato chutney for burgers","Ketchup","Mustard"],"purpose":"Sauce options:"},{"ingredients":["French fries (and it''s epic!)"],"purpose":"On the side:"}]', '[{"title":"Patties","description":"Separate the beef into 4 equal portions, or 8 if making double cheeseburgers (do it!). Gently roll each portion into balls then press down into round patties that are slightly larger than your bun to allow for shrinkage (12 cm / 4.7\" wide, 1 cm / 0.4\" thick for a 10cm / 4\" burger bun).","images":[],"step":1},{"title":"Prepare","description":"Get all your burger bits and pieces out and ready to use. Don''t salt your beef until just before cooking (it toughens the meat).","images":[],"step":2},{"title":"Toast buns","description":"Preheat the grill to high. Place the bread cut face up on a tray and toast for 3 to 5 minutes until light golden. (If using BBQ, place cut face down on the grill). Set aside.","duration":4,"images":[],"step":3},{"title":"Dent patty","description":"Sprinkle one side of patties with half the salt and pepper. Flip, then press a dent into the middle of each patty. (Prevents patties doming when cooking and reduces shrinkage!). Sprinkle this dented side with the remaining salt and pepper.","images":[],"step":4},{"description":"Preheat 1 tablespoon oil in a large cast iron skillet over high heat until very hot - smoking hot! (Note 6)","images":[],"step":5},{"title":"Cook","description":"Cook 2 to 4 patties (whatever fits in the pan) for 1 1/2 minutes. Press down lightly with a spatula (not too hard else the meat juices squeeze out!). Flip, then immediately top with a slice of cheese. Cook for another 1 1/2 minutes (cheese will melt by itself!) then transfer burgers to a tray to rest for 3 minutes.","duration":3,"images":[],"step":6},{"title":"Preheat","description":"If your BBQ hot plate/grill is well seasoned (ie oiled), there is no need to oil before cooking. If not, lightly brush with vegetable or canola oil (or use scrunched up paper towel). Then preheat your BBQ on high until very hot and you see wisps of smoke.","images":[],"step":7},{"description":"Cook the burgers per above directions for 1 1/2 minutes on each side, topping with cheese as soon as you flip, then resting for 3 minutes. (You can also toast the buns on the grill (face down on the grills, 2 - 3 minutes.)","duration":3,"images":[],"step":8},{"description":"Slather the base of the bun with your sauce of choice. My order of assembly: lettuce, tomato, burger (x 2 for double!), gherkins, onion, sauce on bun lid, jam it on top of the stack.","images":[],"step":9},{"description":"DEVOUR with French Fries on the side.","images":[],"step":10}]', '["milk","mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef-mince-recipes","burger-recipes","dinner-tonight","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
